module fontROM #(
    parameter FONT_FILE = "font.list",
    parameter addr_width = 6,
    parameter data_width = 3
)(
    input wire clk,
    input wire [addr_width-1:0] addr,
    output reg [data_width-1:0] dout
);

    // Declare the memory array
    reg [data_width-1:0] mem [0:(2**addr_width)-1];

    // Initialize memory from file
    initial begin
        $readmemb(FONT_FILE, mem);
    end

    // Synchronous read operation
    always @(posedge clk) begin
        dout <= mem[addr];
    end

endmodule

module control_unit (
    input [5:0] opcode,
    input [9:0] xox,
    input [8:0] xoxo,
    input [1:0] xods,
    output reg RegRead,
    output reg RegWrite,
    output reg MemRead,
    output reg MemWrite,
    output reg Branch,
    output reg MemToReg,
    output reg ALUSrc,
    output reg PCSrc
);

always @(*) begin
    // Initialize all signals to 0
    RegRead = 0;
    RegWrite = 0;
    MemRead = 0;
    MemWrite = 0;
    Branch = 0;
    MemToReg = 0;
    ALUSrc = 0;
    PCSrc = 0;

    case(opcode)
        6'd31: begin // Register-type instructions
            RegRead = 1;
            RegWrite = 1;
        end

        6'd14, 6'd15, 6'd28, 6'd24, 6'd26: begin // Immediate arithmetic/logical operations
            RegRead = 1;
            RegWrite = 1;
            ALUSrc = 1;
        end

        6'd58, 6'd32, 6'd40, 6'd42, 6'd34: begin // Load instructions
            RegRead = 1;
            MemRead = 1;
            MemToReg = 1;
            ALUSrc = 1;
            RegWrite = 1;
        end

        6'd38, 6'd44, 6'd37, 6'd36, 6'd62: begin // Store instructions
            RegRead = 1;
            MemWrite = 1;
            ALUSrc = 1;
        end

        6'd18: begin // Unconditional branch
            Branch = 1;
            PCSrc = 1;
        end

        6'd19: begin // Conditional branch
            RegRead = 1;
            Branch = 1;
            PCSrc = 1;
        end

        default: begin
            // Default case: all signals remain 0
        end
    endcase
end

endmodule

