module system(
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    output wire [8:0] parity_out,
    output wire [15:0] bcd_out,
    output wire [7:0] sum_out
);

// Odd parity generator
reg parity_bit;
always @(*) begin
    parity_bit = ^data_in;
end
assign parity_out = {parity_bit, data_in};

// 4-digit BCD counter
reg [3:0] ones, tens, hundreds, thousands;
wire en_tens, en_hundreds, en_thousands;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        ones <= 4'd0;
        tens <= 4'd0;
        hundreds <= 4'd0;
        thousands <= 4'd0;
    end else begin
        if (ones == 4'd9) ones <= 4'd0;
        else ones <= ones + 1'd1;

        if (en_tens) begin
            if (tens == 4'd9) tens <= 4'd0;
            else tens <= tens + 1'd1;
        end

        if (en_hundreds) begin
            if (hundreds == 4'd9) hundreds <= 4'd0;
            else hundreds <= hundreds + 1'd1;
        end

        if (en_thousands) begin
            if (thousands == 4'd9) thousands <= 4'd0;
            else thousands <= thousands + 1'd1;
        end
    end
end

assign en_tens = (ones == 4'd9);
assign en_hundreds = en_tens && (tens == 4'd9);
assign en_thousands = en_hundreds && (hundreds == 4'd9);

assign bcd_out = {thousands, hundreds, tens, ones};

// Sum module
reg [7:0] sum;
always @(*) begin
    sum = parity_out[7:0] + {4'b0000, ones};
end
assign sum_out = sum;

endmodule

