module GameController (
    input wire clk, rst,
    input wire timeOutFlag, accessFlag, gameOverFlag, userIDfoundFlag,
    input wire startButton_s, chooseLevel_SW0, switch14,
    input wire [3:0] hisCurrentScore, hisMaxScore,
    output reg setTimeMaxFlag, startGameFlag, enableSetTimeFlag, enableSetUserIDFlag,
    output reg enableSetPassFlag, enableStartButtonFlag, clearFlag,
    output reg [2:0] setSpeed,
    output reg [3:0] scoreDisp
);

    // State encoding
    localparam INIT = 4'b0000;
    localparam CHECKPASS = 4'b0001;
    localparam SETTIME = 4'b0010;
    localparam GETREADY = 4'b0011;
    localparam START = 4'b0100;
    localparam RESULT = 4'b0101;
    localparam WAIT1 = 4'b0110;
    localparam WAIT2 = 4'b0111;

    reg [3:0] state, next_state;

    // State transition and output logic
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            state <= INIT;
            setTimeMaxFlag <= 0;
            startGameFlag <= 0;
            enableSetTimeFlag <= 0;
            enableSetUserIDFlag <= 0;
            enableSetPassFlag <= 0;
            enableStartButtonFlag <= 0;
            clearFlag <= 1;
            setSpeed <= 3'b000;
        end else begin
            state <= next_state;
            case (state)
                INIT: begin
                    enableSetUserIDFlag <= 1;
                    if (userIDfoundFlag) next_state <= WAIT1;
                    else next_state <= INIT;
                end
                WAIT1: begin
                    next_state <= CHECKPASS;
                end
                CHECKPASS: begin
                    enableSetPassFlag <= 1;
                    if (accessFlag) next_state <= WAIT2;
                    else next_state <= CHECKPASS;
                end
                WAIT2: begin
                    next_state <= SETTIME;
                end
                SETTIME: begin
                    enableSetTimeFlag <= 1;
                    setTimeMaxFlag <= 1;
                    enableStartButtonFlag <= 1;
                    if (startButton_s) next_state <= GETREADY;
                    else next_state <= SETTIME;
                end
                GETREADY: begin
                    setSpeed <= chooseLevel_SW0 ? 3'b010 : 3'b001;
                    next_state <= START;
                end
                START: begin
                    startGameFlag <= 1;
                    if (gameOverFlag || timeOutFlag) next_state <= RESULT;
                    else next_state <= START;
                end
                RESULT: begin
                    startGameFlag <= 0;
                    enableStartButtonFlag <= 1;
                    if (startButton_s) next_state <= SETTIME;
                    else next_state <= RESULT;
                end
                default: next_state <= INIT;
            endcase
        end
    end

    // Score display logic
    always @(posedge clk) begin
        scoreDisp <= switch14 ? hisMaxScore : hisCurrentScore;
    end

endmodule

