module cpu_branch (
    input wire clock,
    input wire reset,
    input wire [15:0] status_in,
    input wire [3:0] condition,
    output reg branch
);

    // Extract status bits
    wire carry_borrow_in = status_in[0];
    wire zero_in = status_in[1];
    wire sign_in = status_in[2];
    wire overflow_in = status_in[3];
    wire bit_in = status_in[4];

    // Branch condition codes
    localparam UNCONDITIONAL = 4'b0000;
    localparam EQUAL = 4'b0001;
    localparam NOT_EQUAL = 4'b0010;
    localparam BELOW = 4'b0011;
    localparam NOT_BELOW = 4'b0100;
    localparam NOT_ABOVE = 4'b0101;
    localparam ABOVE = 4'b0110;
    localparam LESS = 4'b0111;
    localparam LESS_EQUAL = 4'b1000;
    localparam GREATER = 4'b1001;
    localparam GREATER_EQUAL = 4'b1010;
    localparam BIT = 4'b1011;
    localparam NOT_BIT = 4'b1100;

    // Branch condition evaluation
    always @(*) begin
        case (condition)
            UNCONDITIONAL: branch = 1'b1;
            EQUAL: branch = zero_in;
            NOT_EQUAL: branch = ~zero_in;
            BELOW: branch = carry_borrow_in;
            NOT_BELOW: branch = ~carry_borrow_in;
            NOT_ABOVE: branch = carry_borrow_in | zero_in;
            ABOVE: branch = ~(carry_borrow_in | zero_in);
            LESS: branch = sign_in ^ overflow_in;
            LESS_EQUAL: branch = (sign_in ^ overflow_in) | zero_in;
            GREATER: branch = ~((sign_in ^ overflow_in) | zero_in);
            GREATER_EQUAL: branch = ~(sign_in ^ overflow_in);
            BIT: branch = bit_in;
            NOT_BIT: branch = ~bit_in;
            default: branch = 1'b0;
        endcase
    end

endmodule

module debounce (
    input  logic        reset_in,
    input  logic        clock_in,
    input  logic        noisy_in,
    output logic        clean_out
);

    parameter DEBOUNCE_COUNT = 1000000;

    logic [23:0] count;
    logic        new_input;

    always_ff @(posedge clock_in or posedge reset_in) begin
        if (reset_in) begin
            clean_out <= noisy_in;
            new_input <= noisy_in;
            count     <= 24'd0;
        end else begin
            if (noisy_in != new_input) begin
                new_input <= noisy_in;
                count     <= 24'd0;
            end else if (count == DEBOUNCE_COUNT - 1) begin
                clean_out <= new_input;
            end else begin
                count     <= count + 1'b1;
            end
        end
    end

endmodule

