module booth_multiplier_4bit(
    input [3:0] A,
    input [3:0] B,
    output [7:0] P
);

reg [8:0] acc;
reg [3:0] Q;
reg Q_1;
reg [2:0] count;

wire [4:0] A_ext = {A[3], A};

always @(*) begin
    acc = 9'b0;
    Q = B;
    Q_1 = 1'b0;
    count = 3'd4;

    while (count != 0) begin
        case ({Q[0], Q_1})
            2'b01: acc[8:4] = acc[8:4] + A_ext;
            2'b10: acc[8:4] = acc[8:4] - A_ext;
            default: ; // Do nothing for 00 or 11
        endcase

        // Arithmetic right shift
        {acc, Q, Q_1} = {acc[8], acc, Q};
        count = count - 1;
    end
end

assign P = {acc[7:0]};

endmodule

