module carry_select_adder(
    input [99:0] a,
    input [99:0] b,
    input cin,
    output [99:0] sum,
    output cout
);

    wire [99:0] sum0, sum1;
    wire cout0, cout1;

    // Two 100-bit ripple carry adders
    ripple_carry_adder rca0(
        .a(a),
        .b(b),
        .cin(1'b0),
        .sum(sum0),
        .cout(cout0)
    );

    ripple_carry_adder rca1(
        .a(a),
        .b(b),
        .cin(1'b1),
        .sum(sum1),
        .cout(cout1)
    );

    // Multiplexer for selecting the correct sum and carry-out
    assign sum = cin ? sum1 : sum0;
    assign cout = cin ? cout1 : cout0;

endmodule

