module baudRateDownCounter(
    input clk,
    input rst,
    input loadCounter,
    input [15:0] divisor,
    output reg counterZero,
    output reg [15:0] count
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 16'h0000;
            counterZero <= 1'b0;
        end
        else if (loadCounter) begin
            count <= divisor;
            counterZero <= 1'b0;
        end
        else if (count == 16'h0001) begin
            count <= 16'h0000;
            counterZero <= 1'b1;
        end
        else begin
            count <= count - 16'h0001;
            counterZero <= 1'b0;
        end
    end

endmodule

