always @(negedge RST or posedge CLK) begin
    if (!RST) begin
        tmpCount <= 23'd0;
        dividedCLK <= 1'b0;
    end else begin
        if (tmpCount == DIVIDE) begin
            tmpCount <= 23'd0;
            dividedCLK <= ~dividedCLK;
        end else begin
            tmpCount <= tmpCount + 1'b1;
        end
    end
end

endmodule

