module car_simulator(
    input clk_100mhz,
    input rst,
    input forward,
    input backward,
    input left,
    input right,
    input [1:0] speed,
    output reg [9:0] car_x,
    output reg [8:0] car_y
);

    reg [18:0] clk_divider;
    reg clk_move;

    // Clock divider
    always @(posedge clk_100mhz or posedge rst) begin
        if (rst) begin
            clk_divider <= 19'd0;
            clk_move <= 1'b0;
        end else begin
            if (clk_divider == 19'd469999) begin
                clk_divider <= 19'd0;
                clk_move <= ~clk_move;
            end else begin
                clk_divider <= clk_divider + 1'b1;
            end
        end
    end

    // Car movement
    always @(posedge clk_move or posedge rst) begin
        if (rst) begin
            car_x <= 10'd364;
            car_y <= 9'd364;
        end else begin
            if (forward) begin
                car_y <= (car_y >= {1'b0, speed}) ? car_y - {1'b0, speed} : 9'd0;
            end else if (backward) begin
                car_y <= (car_y <= 9'd511 - {1'b0, speed}) ? car_y + {1'b0, speed} : 9'd511;
            end else if (left) begin
                car_x <= (car_x >= {2'b00, speed}) ? car_x - {2'b00, speed} : 10'd0;
            end else if (right) begin
                car_x <= (car_x <= 10'd1023 - {2'b00, speed}) ? car_x + {2'b00, speed} : 10'd1023;
            end
        end
    end

endmodule

module mealy_fsm (
    input wire clk,
    input wire reset,
    input wire in1,
    input wire in2,
    input wire in3,
    output reg out1,
    output reg out2
);

    // State encoding
    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;
    parameter S3 = 2'b11;

    reg [1:0] current_state, next_state;

    // State transition logic
    always @(*) begin
        case (current_state)
            S0: begin
                case ({in1, in2})
                    2'b00: next_state = S0;
                    2'b01: next_state = S1;
                    2'b10: next_state = S2;
                    2'b11: next_state = S3;
                endcase
            end
            S1: begin
                if (in3)
                    next_state = in1 ? S1 : S0;
                else
                    next_state = S1;
            end
            S2: begin
                next_state = in1 ? S0 : S2;
            end
            S3: begin
                if (~in3)
                    next_state = in1 ? S0 : S3;
                else
                    next_state = S3;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            S0: {out1, out2} = {in1, in2};
            S1: {out1, out2} = 2'b01;
            S2: {out1, out2} = 2'b10;
            S3: {out1, out2} = 2'b11;
            default: {out1, out2} = 2'b00;
        endcase
    end

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

endmodule

module sequential_binary_multiplier #(
    parameter dp_width = 8,
    parameter BC_size = 3
) (
    input wire [dp_width-1:0] Multiplicand,
    input wire [dp_width-1:0] Multiplier,
    input wire Start,
    input wire clock,
    input wire reset_b,
    output reg [2*dp_width-1:0] Product,
    output reg Ready
);

    reg [dp_width-1:0] A, B, Q;
    reg C;
    reg [BC_size-1:0] P;

    localparam S_idle = 3'b000, S_add = 3'b001, S_shift = 3'b010;
    reg [2:0] state, next_state;

    always @(posedge clock, negedge reset_b) begin
        if (!reset_b) begin
            state <= S_idle;
        end
        else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            S_idle: begin
                if (Start) begin
                    next_state = S_add;
                end
            end
            S_add: begin
                if (P == 0) begin
                    next_state = S_idle;
                end
                else begin
                    next_state = S_shift;
                end
            end
            S_shift: begin
                next_state = S_add;
            end
            default: begin
                next_state = S_idle;
            end
        endcase
    end

    always @(posedge clock, negedge reset_b) begin
        if (!reset_b) begin
            A <= 0;
            B <= 0;
            Q <= 0;
            C <= 0;
            P <= 0;
            Product <= 0;
            Ready <= 0;
        end
        else begin
            case (state)
                S_idle: begin
                    if (Start) begin
                        A <= Multiplicand;
                        B <= Multiplicand;
                        Q <= Multiplier;
                        C <= 0;
                        P <= BC_size - 1;
                        Product <= 0;
                        Ready <= 0;
                    end
                end
                S_add: begin
                    if (Q[0]) begin
                        {C, A} <= A + B;
                    end
                    else begin
                        A <= A;
                    end
                    P <= P - 1;
                end
                S_shift: begin
                    A <= {C, A[dp_width-1:1]};
                    Q <= {Q[dp_width-2:0], 1'b0};
                    C <= A[0];
                end
                default: begin
                    // Do nothing
                end
            endcase

            if (state == S_idle && P == 0) begin
                Product <= {A, Q};
                Ready <= 1;
            end
            else begin
                Ready <= 0;
            end
        end
    end

endmodule

module ALU(
    input [31:0] Read_data1,
    input [31:0] Read_data2,
    input [3:0] ALU_control,
    input ALUSrc,
    input [31:0] Sign_extend,
    output reg [31:0] ALU_Result,
    output reg Zero
);

always @(*) begin
    // Select the second operand
    reg [31:0] op2;
    if (ALUSrc == 1'b0) begin
        op2 = Read_data2;
    end else begin
        op2 = Sign_extend;
    end

    // Perform the ALU operation
    case (ALU_control)
        4'b0010: begin // Addition
            ALU_Result = Read_data1 + op2;
            Zero = 1'b0;
        end
        4'b1010: begin // Subtraction
            ALU_Result = Read_data1 - op2;
            Zero = 1'b0;
        end
        4'b0110: begin // Bitwise AND
            ALU_Result = Read_data1 & op2;
            Zero = 1'b0;
        end
        4'b0100: begin // Bitwise OR
            ALU_Result = Read_data1 | op2;
            Zero = 1'b0;
        end
        4'b1001: begin // Bitwise XOR
            ALU_Result = Read_data1 ^ op2;
            Zero = 1'b0;
        end
        4'b0101: begin // Bitwise NOR
            ALU_Result = ~(Read_data1 | op2);
            Zero = 1'b0;
        end
        4'b1100: begin // Bitwise NAND
            ALU_Result = ~(Read_data1 & op2);
            Zero = 1'b0;
        end
        4'b1101: begin // Pass-through
            ALU_Result = op2;
            Zero = 1'b0;
        end
        4'b0111: begin // Equal to zero
            if (op2 == 32'b0) begin
                ALU_Result = 32'b0;
                Zero = 1'b1;
            end else begin
                ALU_Result = 32'b0;
                Zero = 1'b0;
            end
        end
        4'b0001: begin // Not equal to zero
            if (op2 != 32'b0) begin
                ALU_Result = 32'b0;
                Zero = 1'b1;
            end else begin
                ALU_Result = 32'b0;
                Zero = 1'b0;
            end
        end
        default: begin
            ALU_Result = 32'b0;
            Zero = 1'b0;
        end
    endcase
end

endmodule

module key_debounce #(
    parameter DELAY_TIME = 18'h3ffff
)(
    input wire clk,
    input wire rst_n,
    input wire key_in,
    output reg key_vld
);

    // State encoding
    localparam IDLE         = 4'b0001;
    localparam PRESS_DELAY  = 4'b0010;
    localparam WAIT_RELEASE = 4'b0100;
    localparam RELEASE_DELA = 4'b1000;

    reg [3:0] current_state, next_state;
    reg [1:0] key_in_r;
    reg [17:0] cnt;
    wire key_in_pos, key_in_neg;

    // Edge detection
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            key_in_r <= 2'b11;
        else
            key_in_r <= {key_in_r[0], key_in};
    end

    assign key_in_pos = (key_in_r == 2'b01);
    assign key_in_neg = (key_in_r == 2'b10);

    // State machine: state register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // State machine: next state logic
    always @(*) begin
        case (current_state)
            IDLE:
                if (key_in_pos)
                    next_state = PRESS_DELAY;
                else
                    next_state = IDLE;
            PRESS_DELAY:
                if (key_in_neg)
                    next_state = IDLE;
                else if (cnt == DELAY_TIME)
                    next_state = WAIT_RELEASE;
                else
                    next_state = PRESS_DELAY;
            WAIT_RELEASE:
                if (key_in_neg)
                    next_state = RELEASE_DELA;
                else
                    next_state = WAIT_RELEASE;
            RELEASE_DELA:
                if (key_in_pos)
                    next_state = WAIT_RELEASE;
                else if (cnt == DELAY_TIME)
                    next_state = IDLE;
                else
                    next_state = RELEASE_DELA;
            default:
                next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            key_vld <= 1'b1;
        else
            key_vld <= (next_state == IDLE) || (next_state == PRESS_DELAY);
    end

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 18'd0;
        else if ((current_state == PRESS_DELAY) || (current_state == RELEASE_DELA))
            cnt <= (cnt == DELAY_TIME) ? 18'd0 : cnt + 1'b1;
        else
            cnt <= 18'd0;
    end

endmodule

module oneZoneDtr (
    input wire clk1,
    input wire clear,
    input wire dInew,
    input wire dSnew,
    output reg Zout
);

    // State encoding
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10,
               S3 = 2'b11;

    reg [1:0] state, next_state;

    // State register
    always @(posedge clk1 or posedge clear) begin
        if (clear)
            state <= S0;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            S0: next_state = (dInew && dSnew) ? S1 : S0;
            S1: begin
                if (dInew && dSnew)
                    next_state = S1;
                else if (!dInew && dSnew)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S2: next_state = (dInew && dSnew) ? S3 : S0;
            S3: next_state = (dInew && dSnew) ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(posedge clk1 or posedge clear) begin
        if (clear)
            Zout <= 1'b0;
        else
            Zout <= (state == S3);
    end

endmodule

