module Delay #(
    parameter DELAY_CLK = 2,
    parameter WIDTH = 8
) (
    input CLK,
    input RESETN,
    input [WIDTH-1:0] DIN,
    output reg [WIDTH-1:0] DOUT,
    output DELAY_READY,
    output DELAY_VALID
);

reg [WIDTH-1:0] fifo [DELAY_CLK-1:0];
reg [DELAY_CLK-1:0] delay_cnt;

always @(posedge CLK, negedge RESETN) begin
    if (~RESETN) begin
        for (int i = 0; i < DELAY_CLK-1; i++) begin
            fifo[i] <= 0;
        end
        delay_cnt <= 0;
        DOUT <= 0;
    end else begin
        if (DELAY_CLK <= 1) begin
            DOUT <= DIN;
        end else begin
            fifo[delay_cnt] <= DIN;
            DOUT <= fifo[DELAY_CLK-1];
            delay_cnt <= (delay_cnt == DELAY_CLK-1) ? 0 : delay_cnt + 1;
        end
    end
end

assign DELAY_READY = (DELAY_CLK <= 1) || (delay_cnt != DELAY_CLK-1);
assign DELAY_VALID = (DELAY_CLK <= 1) || (delay_cnt == DELAY_CLK-1);

endmodule

module shift_register #(
    parameter N = 4
) (
    input wire clk,
    input wire reset_n,
    input wire SI,
    input wire enable,
    output wire [N-1:0] Q
);

    reg [N-1:0] Q_reg, Q_next;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n)
            Q_reg <= {N{1'b0}};
        else
            Q_reg <= Q_next;
    end

    always @(*) begin
        if (~reset_n)
            Q_next = {N{1'b0}};
        else if (enable)
            Q_next = {Q_reg[N-2:0], SI};
        else
            Q_next = Q_reg;
    end

    assign Q = Q_reg;

endmodule

module RAM(
    input Enable,
    input ReadWrite,
    input Clock,
    input [15:0] DataIn,
    input [255:0] Result,
    input [255:0] C,
    input [255:0] AT,
    input [255:0] BB,
    input [255:0] FinResult,
    output reg [15:0] DataOut
);

    reg [15:0] MemArray [0:255];

    always @(posedge Clock) begin
        if (Enable) begin
            if (ReadWrite) begin
                if (Result[0]) DataOut <= MemArray[0];
                else if (C[0]) DataOut <= MemArray[1];
                else if (AT[0]) DataOut <= MemArray[2];
                else if (BB[0]) DataOut <= MemArray[3];
                else if (FinResult[0]) DataOut <= MemArray[4];
            end else begin
                if (Result[0]) MemArray[0] <= DataIn;
                else if (C[0]) MemArray[1] <= DataIn;
                else if (AT[0]) MemArray[2] <= DataIn;
                else if (BB[0]) MemArray[3] <= DataIn;
                else if (FinResult[0]) MemArray[4] <= DataIn;
            end
        end else begin
            DataOut <= 16'bZ;
        end
    end

endmodule

module CLA4bit(
    input  [3:0] A,
    input  [3:0] B,
    output [3:0] P,
    output [3:0] G,
    output       P03,
    output       G03
);

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
    endgenerate

    assign P03 = &P;
    assign G03 = G[3] | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

endmodule

module buttons (
    input wire clk,
    input wire key_c,
    output reg start
);

    // FSM states
    localparam WAITING = 2'b00;
    localparam SETUP = 2'b01;
    localparam SEND = 2'b10;
    localparam RELEASED = 2'b11;

    reg [1:0] state, next_state;
    reg [15:0] cnt_c;
    reg en, en0;

    // FSM state transitions
    always @(posedge clk) begin
        if (key_c == 1'b0)
            state <= WAITING;
        else
            state <= next_state;
    end

    // FSM next state logic and counter
    always @(posedge clk) begin
        case (state)
            WAITING: begin
                if (key_c == 1'b1) begin
                    next_state <= SETUP;
                    cnt_c <= 16'd0;
                end
                else begin
                    next_state <= WAITING;
                end
            end
            SETUP: begin
                if (cnt_c == 16'd50000) begin
                    next_state <= SEND;
                end
                else begin
                    cnt_c <= cnt_c + 1'b1;
                    next_state <= SETUP;
                end
            end
            SEND: begin
                next_state <= RELEASED;
            end
            RELEASED: begin
                if (key_c == 1'b0)
                    next_state <= WAITING;
                else
                    next_state <= RELEASED;
            end
            default: next_state <= WAITING;
        endcase
    end

    // Edge detection - first stage
    always @(posedge clk) begin
        en <= (state == SEND);
    end

    // Edge detection - second stage
    always @(posedge clk) begin
        en0 <= en;
    end

    // Output generation
    always @(*) begin
        start = en & ~en0;
    end

endmodule

module ex1(
