module hdb3_encoder (
    input wire i_rst_n,
    input wire i_clk,
    input wire [1:0] i_plug_b_code,
    output reg [1:0] o_hdb3_code
);

reg r_not_0_parity;

always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
        o_hdb3_code <= 2'b00;
        r_not_0_parity <= 1'b0;
    end else begin
        case (i_plug_b_code)
            2'b01: begin // Positive pulse
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b01;
                    r_not_0_parity <= ~r_not_0_parity;
                end else begin
                    o_hdb3_code <= 2'b10;
                    r_not_0_parity <= ~r_not_0_parity;
                end
            end
            2'b10: begin // Negative pulse
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b10;
                end else begin
                    o_hdb3_code <= 2'b01;
                end
            end
            2'b11: begin // Violation
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b01;
                    r_not_0_parity <= ~r_not_0_parity;
                end else begin
                    o_hdb3_code <= 2'b10;
                    r_not_0_parity <= ~r_not_0_parity;
                end
            end
            default: begin // No pulse (00)
                o_hdb3_code <= 2'b00;
            end
        endcase
    end
end

endmodule

module exeLoadUnit (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [104:0] rs2exe,
    input wire [31:0] load_data,
    input wire [31:0] dmem_write_addr,
    input wire [31:0] dmem_write_data,
    output reg [31:0] load_addr,
    output reg [63:0] loadunit2buf,
    output reg en_loadbuf,
    output reg [37:0] cdb
);

    // Internal registers
    reg [31:0] addr_reg;
    reg [4:0] dest_reg;
    reg [2:0] width_reg;
    reg loading_reg;

    // Unpacking rs2exe
    wire [31:0] opr1 = rs2exe[31:0];
    wire [31:0] offset = rs2exe[63:32];
    wire [4:0] dest = rs2exe[68:64];
    wire [2:0] width = rs2exe[71:69];

    // Stage 1: Address calculation
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            load_addr <= 32'b0;
            addr_reg <= 32'b0;
            dest_reg <= 5'b0;
            width_reg <= 3'b0;
            loading_reg <= 1'b0;
        end else if (enable) begin
            load_addr <= opr1 + offset;
            addr_reg <= opr1 + offset;
            dest_reg <= dest;
            width_reg <= width;
            loading_reg <= 1'b1;
        end
    end

    // Stage 2: Data retrieval and processing
    reg [31:0] cropped_data;
    always @(posedge clk) begin
        if (loading_reg) begin
            // Data bypassing
            reg [31:0] final_data;
            if (addr_reg == dmem_write_addr) begin
                final_data = dmem_write_data;
            end else begin
                final_data = load_data;
            end

            // Data cropping and extension
            case (width_reg)
                3'b000: cropped_data = {{24{final_data[7]}}, final_data[7:0]}; // Signed byte
                3'b001: cropped_data = {{16{final_data[15]}}, final_data[15:0]}; // Signed halfword
                3'b010: cropped_data = final_data; // Word
                3'b100: cropped_data = {24'b0, final_data[7:0]}; // Unsigned byte
                3'b101: cropped_data = {16'b0, final_data[15:0]}; // Unsigned halfword
                default: cropped_data = 32'bx;
            endcase

            // Output generation
            cdb <= {dest_reg, cropped_data};
            loadunit2buf <= {addr_reg, cropped_data};
            en_loadbuf <= 1'b1;
        end else begin
            cdb <= 38'bx;
            loadunit2buf <= 64'bx;
            en_loadbuf <= 1'b0;
        end
    end

endmodule

