module Detector (
    input wire Clk,
    input wire nReset,
    input wire Sin,
    input wire [3:0] Pattern,
    output wire [7:0] Pcount
);

reg [3:0] Buffer;
reg [7:0] Count;

always @(posedge Clk or negedge nReset) begin
    if (!nReset) begin
        Buffer <= 4'b0000;
        Count <= 8'b00000000;
    end else begin
        Buffer <= {Buffer[2:0], Sin};
        if (Buffer == Pattern) begin
            if (Count < 8'b11111111) begin
                Count <= Count + 1'b1;
            end
        end
    end
end

assign Pcount = Count;

endmodule

module ADC_Controller (
    input start,
    input Comp,
    input Clock,
    output reg sample,
    output reg datardy,
    output reg [5:0] B
);

    parameter State0 = 3'b000, State1 = 3'b001, State2 = 3'b010, State3 = 3'b011, State4 = 3'b100;
    reg [2:0] currentState, nextState;
    reg beginCount, counterRst;

    always @(posedge Clock) begin
        if (currentState == State0) begin
            if (start && !Comp) begin
                nextState <= State1;
            end else begin
                nextState <= State0;
            end
        end else if (currentState == State1) begin
            if (B == 6'b111111) begin
                nextState <= State2;
            end else begin
                nextState <= State1;
            end
        end else if (currentState == State2) begin
            if (!start && !Comp) begin
                nextState <= State3;
            end else begin
                nextState <= State0;
            end
        end else if (currentState == State3) begin
            if (!start && Comp) begin
                nextState <= State4;
            end else begin
                nextState <= State3;
            end
        end else if (currentState == State4) begin
            if (start && !Comp) begin
                nextState <= State0;
            end else begin
                nextState <= State4;
            end
        end
    end

    always @(posedge Clock) begin
        currentState <= nextState;

        case (currentState)
            State0: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 0;
                counterRst <= 0;
            end
            State1: begin
                sample <= 1;
                datardy <= 0;
                beginCount <= 1;
                counterRst <= 0;
                if (beginCount) begin
                    B <= B + 1;
                end
            end
            State2: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 0;
                counterRst <= 1;
                if (counterRst) begin
                    B <= 0;
                end
            end
            State3: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 1;
                counterRst <= 0;
            end
            State4: begin
                sample <= 0;
                datardy <= 1;
                beginCount <= 0;
                counterRst <= 0;
            end
        endcase
    end

endmodule

module data_format_uart (
    input [7:0] din,
    output [10:0] dout
