module adder_8bit(
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

    wire [7:0] p, g;
    wire [8:0] c;

    // Generate and propagate signals
    assign p = a ^ b;
    assign g = a & b;

    // Carry lookahead logic
    assign c[0] = 1'b0;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & g[0]) | (p[1] & p[0] & c[0]);
    assign c[3] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & c[0]);
    assign c[4] = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) | (p[3] & p[2] & p[1] & p[0] & c[0]);

    // Full adders for the remaining bits
    genvar i;
    generate
        for (i = 4; i < 8; i = i + 1) begin : full_adders
            full_adder fa (
                .a(a[i]),
                .b(b[i]),
                .cin(c[i]),
                .s(s[i]),
                .cout(c[i+1])
            );
        end
    endgenerate

    // Sum for the first 4 bits
    assign s[3:0] = p[3:0] ^ c[3:0];

    // Overflow detection
    assign overflow = (a[7] == b[7]) && (s[7] != a[7]);

endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output s,
    output cout
);

    assign s = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));

endmodule

module fsm (
    input cs_pin,
    input clk,
    input sclk_pin,
    input rw,
    output reg shift_wren,
    output reg reset_counter,
    output reg dm_wren,
    output reg addr_wren,
    output reg miso_en
);

    // Internal signals
    reg [3:0] counter;
    reg [2:0] current_state;

    // States
    parameter GET = 3'b000;
    parameter GOT = 3'b001;
    parameter READ1 = 3'b010;
    parameter READ2 = 3'b011;
    parameter READ3 = 3'b100;
    parameter WRITE1 = 3'b101;
    parameter WRITE2 = 3'b110;
    parameter DONE = 3'b111;

    always @(posedge clk) begin
        if (cs_pin) begin
            current_state <= GET;
            reset_counter <= 1'b1;
        end else begin
            case (current_state)
                GET: begin
                    if (counter == 4'd7) begin
                        current_state <= GOT;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                GOT: begin
                    if (rw) begin
                        current_state <= READ1;
                        shift_wren <= 1'b1;
                        miso_en <= 1'b1;
                    end else begin
                        current_state <= WRITE1;
                        addr_wren <= 1'b1;
                    end
                    reset_counter <= 1'b1;
                end
                READ1: begin
                    if (counter == 4'd7) begin
                        current_state <= READ2;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                READ2: begin
                    if (counter == 4'd7) begin
                        current_state <= READ3;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                READ3: begin
                    if (counter == 4'd7) begin
                        current_state <= DONE;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                WRITE1: begin
                    if (counter == 4'd7) begin
                        current_state <= WRITE2;
                        dm_wren <= 1'b1;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                WRITE2: begin
                    if (counter == 4'd7) begin
                        current_state <= DONE;
                        dm_wren <= 1'b0;
                        reset_counter <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                        reset_counter <= 1'b0;
                    end
                end
                DONE: begin
                    if (!cs_pin) begin
                        current_state <= GET;
                        reset_counter <= 1'b1;
                    end else begin
                        reset_counter <= 1'b0;
                    end
                end
                default: begin
                    current_state <= GET;
                    reset_counter <= 1'b1;
                end
            endcase
        end
    end

endmodule

