module TMDS_decoder(
    input wire clk,
    input wire rst,
    input wire [9:0] datain,
    output reg de,
    output reg [7:0] tmdsout,
    output reg [1:0] ctrl
);

    parameter CRTPAR0 = 10'b1101010100;
    parameter CRTPAR1 = 10'b0010101011;
    parameter CRTPAR2 = 10'b0101010100;
    parameter CRTPAR3 = 10'b1010101011;

    reg [7:0] data;

    always @(*) begin
        if (rst)
            data = 8'b0;
        else if (datain[9])
            data = ~datain[7:0];
        else
            data = datain[7:0];
    end

    always @(posedge clk) begin
        if (rst) begin
            ctrl <= 2'b00;
            de <= 1'b0;
            tmdsout <= 8'b0;
        end
        else begin
            case (datain)
                CRTPAR0: begin
                    ctrl <= 2'b00;
                    de <= 1'b0;
                end
                CRTPAR1: begin
                    ctrl <= 2'b01;
                    de <= 1'b0;
                end
                CRTPAR2: begin
                    ctrl <= 2'b10;
                    de <= 1'b0;
                end
                CRTPAR3: begin
                    ctrl <= 2'b11;
                    de <= 1'b0;
                end
                default: begin
                    ctrl <= 2'b00;
                    de <= 1'b1;
                    if (datain[8]) begin
                        tmdsout[0] <= data[0];
                        tmdsout[1] <= data[1] ^ data[0];
                        tmdsout[2] <= data[2] ^ data[1];
                        tmdsout[3] <= data[3] ^ data[2];
                        tmdsout[4] <= data[4] ^ data[3];
                        tmdsout[5] <= data[5] ^ data[4];
                        tmdsout[6] <= data[6] ^ data[5];
                        tmdsout[7] <= data[7] ^ data[6];
                    end
                    else begin
                        tmdsout[0] <= data[0];
                        tmdsout[1] <= data[1] ~^ data[0];
                        tmdsout[2] <= data[2] ~^ data[1];
                        tmdsout[3] <= data[3] ~^ data[2];
                        tmdsout[4] <= data[4] ~^ data[3];
                        tmdsout[5] <= data[5] ~^ data[4];
                        tmdsout[6] <= data[6] ~^ data[5];
                        tmdsout[7] <= data[7] ~^ data[6];
                    end
                end
            endcase
        end
    end

endmodule

module One_ms_Timer(
