    input rst
);

reg [15:0] Interal_cnt;

always @(posedge clk or negedge rst) begin
    if(!rst) begin
        Interal_cnt <= 0;
        One_ms_timeout <= 0;
    end
    else if(Enable) begin
        if(Interal_cnt == 16'h1C4F) begin
            Interal_cnt <= 0;
            One_ms_timeout <= 1;
        end
        else begin
            Interal_cnt <= Interal_cnt + 1;
            One_ms_timeout <= 0;
        end
    end
    else begin
        One_ms_timeout <= 0;
    end
end

endmodule

