    output reg [7:0] result
);

always @(*) begin
    case (select)
        2'b00: result = pc;
        2'b01: result = register;
        2'b10: result = position;
        2'b11: result = register0;
        default: result = 8'bx; // For simulation purposes
    endcase
end

endmodule

module Shifter_32_bit #(
    parameter ShifterMode = 1
)(
    input [31:0] DataA,
    input [4:0] ShiftAmount,
    output reg [31:0] Result
);

    always @(*) begin
        case (ShifterMode)
            0: Result = DataA << ShiftAmount;
            1: Result = DataA;
            2: Result = DataA >> ShiftAmount;
            3: Result = $signed(DataA) >>> ShiftAmount;
            4: Result = DataA;
            default: Result = DataA;
        endcase
    end

endmodule

module square_adder (
    input wire [7:0] signal_in_real,
    input wire [7:0] signal_in_imag,
    input wire ready,
    input wire done,
    output reg [29:0] signal_out,
    output reg complete
);

    reg [8:0] temp_real, temp_imag;
    reg [29:0] product, total, old_value;
    reg flag;

    always @(posedge ready) begin
        if (!done) begin
            // Scale and offset input signals
            temp_real = {1'b0, signal_in_real, 1'b0} - 9'd255;
            temp_imag = {1'b0, signal_in_imag, 1'b0} - 9'd255;

            // Calculate squared magnitude
            product = (temp_real * temp_real) + (temp_imag * temp_imag);

            // Accumulate total
            total = old_value + product;
            old_value = total;

            complete = 1'b0;
            flag = 1'b0;
        end
        else if (done && !flag) begin
            // Output final result
            signal_out = total;
            complete = 1'b1;
            flag = 1'b1;
        end
        else if (flag) begin
            // Reset for next sequence
            old_value = 30'd0;
            flag = 1'b0;
        end
    end

endmodule

module multiplyer(
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] out
);

reg t0, s;
reg [7:0] ain, bin;

always @(a or b) begin
    t0 <= 1;
end

always @(posedge t0) begin
    s <= 1;
end

always @(posedge s) begin
    out <= 0;
    ain <= a;
    bin <= b;

    while (bin != 0) begin
        out <= out + ain;
        bin <= bin - 1;
    end

    t0 <= 0;
    s <= 0;
end

endmodule

