module clfulladder(a, b, cin, sum, p, g);
    input a, b, cin;
    output sum, p, g;

    assign #2 sum = a ^ b ^ cin;
    assign #2 p = a ^ b;
    assign #2 g = a & b;
endmodule

module lookahead(c0, g0, g1, g2, g3, p0, p1, p2, p3, G0, P0, c1, c2, c3, c4);
    input c0, g0, g1, g2, g3, p0, p1, p2, p3;
    output G0, P0, c1, c2, c3, c4;

    assign #2 G0 = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
    assign #2 P0 = p3 & p2 & p1 & p0;
    assign #2 c1 = g0 | (p0 & c0);
    assign #2 c2 = g1 | (p1 & g0) | (p1 & p0 & c0);
    assign #2 c3 = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);
    assign #2 c4 = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0) | (p3 & p2 & p1 & p0 & c0);
endmodule

module add4_LA(a, b, cin, sum, cout, P0, G0);
    input [3:0] a, b;
    input cin;
    output [3:0] sum;
    output cout, P0, G0;

    wire [3:0] p, g;
    wire c1, c2, c3;

    clfulladder fa0(a[0], b[0], cin, sum[0], p[0], g[0]);
    clfulladder fa1(a[1], b[1], c1, sum[1], p[1], g[1]);
    clfulladder fa2(a[2], b[2], c2, sum[2], p[2], g[2]);
    clfulladder fa3(a[3], b[3], c3, sum[3], p[3], g[3]);

    lookahead la(cin, g[0], g[1], g[2], g[3], p[0], p[1], p[2], p[3], G0, P0, c1, c2, c3, cout);
endmodule

module add16_LA(a, b, sum, cout);
    input [15:0] a, b;
    output [15:0] sum;
    output cout;

    wire [3:0] P, G;
    wire c4, c8, c12;

    add4_LA add0(a[3:0], b[3:0], 1'b0, sum[3:0], c4, P[0], G[0]);
    add4_LA add1(a[7:4], b[7:4], c4, sum[7:4], c8, P[1], G[1]);
    add4_LA add2(a[11:8], b[11:8], c8, sum[11:8], c12, P[2], G[2]);
    add4_LA add3(a[15:12], b[15:12], c12, sum[15:12], cout, P[3], G[3]);

    lookahead la(1'b0, G[0], G[1], G[2], G[3], P[0], P[1], P[2], P[3], , , c4, c8, c12, cout);
endmodule

