module RealBackground (
    input wire Clk,
    input wire reset,
    input wire [22:0] read_address,
    inout wire [7:0] data_out,
    output reg [22:0] out_add,
    output reg [3:0] out1,
    output reg [3:0] out2,
    output reg sel
);

    // State definition
    localparam R1 = 1'b0;
    localparam R2 = 1'b1;

    reg state, next_state;
    reg [3:0] reg1;
    reg [22:0] add;

    // State transition logic
    always @(posedge Clk or posedge reset) begin
        if (reset)
            state <= R1;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = ~state;
    end

    // Output and register update logic
    always @(posedge Clk) begin
        case (state)
            R1: begin
                out_add <= read_address;
                out1 <= reg1;
                out2 <= 4'b0000;
                sel <= 1'b0;
                add <= read_address;
            end
            R2: begin
                reg1 <= data_out[7:4];
                out2 <= data_out[3:0];
                out1 <= 4'b0000;
                out_add <= add;
                sel <= 1'b1;
            end
        endcase
    end

endmodule

module gtlatch #(
    parameter PHASE = "ENCODED"
) (
    input wire extclk,
    input wire [21:0] gtin,
    input wire trig,
    input wire [2:0] phase,
    input wire [5:0] raw,
    output reg [24:0] gtout
);

reg trig_e;
reg [21:0] gt;

// Trigger edge detection
always @(posedge extclk or posedge trig) begin
    if (trig)
        trig_e <= 1'b1;
    else
        trig_e <= 1'b0;
end

// Data latching
always @(posedge extclk) begin
    if (trig_e)
        gt <= gtin;
end

// Output configuration
always @(*) begin
    if (PHASE == "RAW") begin
        gtout[24:19] = raw;
        gtout[18:0] = gt[18:0];
    end else begin // "ENCODED" (default)
        gtout[24:3] = gt;
        gtout[2:0] = phase;
    end
end

endmodule

module buttonController (
    input fastclk,
    input hit,
    input stand,
    input double,
    input newRound,
    input reset,
    output reg [5:0] userMove
);

    // Register variables to store delayed input signals
    reg hitd, standd, doubled, newRoundd, resetd;

    // Macro definitions for user moves
    `define NOMOVE 6'b000000
    `define MOVEHIT 6'b000001
    `define MOVESTAND 6'b000010
    `define MOVEDOUBLE 6'b000100
    `define MOVENEWROUND 6'b001000
    `define MOVERESET 6'b010000

    always @(posedge fastclk) begin
        // Set userMove to NOMOVE by default
        userMove <= `NOMOVE;

        // Delay input signals
        hitd <= hit;
        standd <= stand;
        doubled <= double;
        newRoundd <= newRound;
        resetd <= reset;

        // Check and set userMove based on input signals
        if (resetd) begin
            userMove <= `MOVERESET;
        end else if (newRoundd) begin
            userMove <= `MOVENEWROUND;
        end else if (hitd) begin
            userMove <= `MOVEHIT;
        end else if (standd) begin
            userMove <= `MOVESTAND;
        end else if (doubled) begin
            userMove <= `MOVEDOUBLE;
        end
    end

endmodule

module led_on_time #(
    parameter led_on_time = 62500000
) (
    input wire i_clk,
    input wire i_rst_n,
    input wire i_pulse,
    output reg o_led
);

    localparam IDLE_S = 1'b0;
    localparam LED_ON_S = 1'b1;

    reg state, next_state;
    reg [31:0] rv_time_cnt;

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state <= IDLE_S;
            rv_time_cnt <= 32'd0;
        end else begin
            state <= next_state;
            if (state == LED_ON_S) begin
                rv_time_cnt <= (rv_time_cnt == led_on_time - 1) ? 32'd0 : rv_time_cnt + 1'b1;
            end else begin
                rv_time_cnt <= 32'd0;
            end
        end
    end

    always @(*) begin
        case (state)
            IDLE_S: begin
                next_state = i_pulse ? LED_ON_S : IDLE_S;
                o_led = 1'b1;
            end
            LED_ON_S: begin
                next_state = (rv_time_cnt == led_on_time - 1) ? IDLE_S : LED_ON_S;
                o_led = 1'b0;
            end
            default: begin
                next_state = IDLE_S;
                o_led = 1'b1;
            end
        endcase
    end

endmodule

module leitor(
    input wire clk,
    input wire sinal,
    output reg [7:0] keyCode
);

    reg [16:0] contador;
    reg [5:0] cont_bits;
    reg [2:0] pos;

    initial begin
        contador = 0;
        cont_bits = 0;
        pos = 0;
    end

    always @(posedge clk or sinal) begin
        if (sinal == 1'b1) begin
            contador <= contador + 1;
        end
        else begin
            cont_bits <= cont_bits + 1;
            if (cont_bits >= 18 && cont_bits <= 25) begin
                if (contador == 23000) begin
                    keyCode[pos] <= 1'b0;
                    pos <= pos + 1;
                end
                else if (contador == 79000) begin
                    keyCode[pos] <= 1'b1;
                    pos <= pos + 1;
                end
            end
            if (cont_bits == 34) begin
                pos <= 0;
                cont_bits <= 0;
            end
            contador <= 0;
        end
    end

endmodule

module Pipe1Reg (
    input wire Clk,
    input wire Reset,
