module memory_system(
    input ph1, ph2, reset,
    input [15:0] address,
    inout [7:0] data,
    input read_write_sel
);

    reg [7:0] RAM [4095:0];
    reg [7:0] ROM [4095:0];
    reg [7:0] data_out;

    always @(posedge ph2) begin
        if (read_write_sel) begin
            case (address[15:12])
                4'b0000: data_out <= #3 RAM[address[11:0]];
                4'b1111: data_out <= #3 ROM[address[11:0]];
                default: data_out <= #3 8'b0;
            endcase
        end
    end

    always @(negedge ph2) begin
        if (!read_write_sel && address[15:12] == 4'b0000) begin
            RAM[address[11:0]] <= data;
        end
    end

    assign data = (read_write_sel) ? data_out : 8'bz;

endmodule

module pcPipeline(
    input clk,
    input nop,
    input [31:0] pc,
    output reg [31:0] pipeline2,
    output reg [31:0] pipeline3
);

reg [31:0] pipeline;
reg flag;

initial begin
    pipeline = 0;
    pipeline2 = 0;
    pipeline3 = 0;
    flag = 0;
end

always @(posedge clk) begin
    if (flag) begin
        flag <= 0;
    end
    if (nop) begin
        pipeline3 <= pipeline2 + 4;
        pipeline2 <= 0;
        pipeline <= 0;
        flag <= 1;
    end else begin
        pipeline3 <= pipeline2 + 4;
        pipeline2 <= pipeline;
        pipeline <= pc;
    end
end

endmodule

module leds (
    input wire clk,
    input wire rst,
    input wire [3:0] dig0,
    input wire [3:0] dig1,
    input wire [7:0] led,
    output wire cpld_clk,
    output wire cpld_rstn,
    output reg cpld_ld,
    output wire cpld_mosi
);

    reg [15:0] cntr;
    reg [3:0] digit;
    reg [7:0] seg_data;
    reg [15:0] mosi_shr;

    // Counter
    always @(posedge clk or posedge rst) begin
        if (rst)
            cntr <= 16'b0;
        else
            cntr <= cntr + 1'b1;
    end

    // Digit selection
    always @(*) begin
        digit = cntr[15] ? dig1 : dig0;
    end

    // Seven-segment decoder
    always @(*) begin
        case (digit)
            4'h0: seg_data = 8'b11000000;
            4'h1: seg_data = 8'b11111001;
            4'h2: seg_data = 8'b10100100;
            4'h3: seg_data = 8'b10110000;
            4'h4: seg_data = 8'b10011001;
            4'h5: seg_data = 8'b10010010;
            4'h6: seg_data = 8'b10000010;
            4'h7: seg_data = 8'b11111000;
            4'h8: seg_data = 8'b10000000;
            4'h9: seg_data = 8'b10010000;
            4'ha: seg_data = 8'b10001000;
            4'hb: seg_data = 8'b10000011;
            4'hc: seg_data = 8'b11000110;
            4'hd: seg_data = 8'b10100001;
            4'he: seg_data = 8'b10000110;
            4'hf: seg_data = 8'b10001110;
        endcase
    end

    // Serial data transmission
    always @(posedge clk or posedge rst) begin
        if (rst)
            mosi_shr <= 16'b0;
        else if (cntr[14:0] == 15'b0)
            mosi_shr <= {~seg_data, led};
        else if (!cpld_clk)
            mosi_shr <= {mosi_shr[14:0], 1'b0};
    end

    // CPLD interface
    assign cpld_clk = cntr[10];
    assign cpld_rstn = ~rst;
    assign cpld_mosi = mosi_shr[15];

    always @(posedge clk or posedge rst) begin
        if (rst)
            cpld_ld <= 1'b0;
        else
            cpld_ld <= (cntr[14:11] == 4'b0000);
    end

endmodule

module variable_stepdown (
    input wire in_clk,
    input wire [15:0] division,
    output reg out_clk
);

reg [15:0] count;

initial begin
    count = 16'd0;
    out_clk = 1'b0;
end

always @(posedge in_clk) begin
    if (count == division - 1) begin
        out_clk <= ~out_clk;
        count <= 16'd0;
    end else begin
        count <= count + 1'b1;
    end
end

endmodule

module inverse_reverse(
    input  [7:0] data_in,
    input        clk,
    input        rst_n,
    input        reverse,
    input        invert,
    output [7:0] data_out,
    output       valid
);

reg [7:0] data_reg;
reg       valid_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_reg <= 8'b0;
        valid_reg <= 1'b0;
    end else begin
        if (reverse && invert) begin
            data_reg <= ~{data_in[0], data_in[1], data_in[2], data_in[3], data_in[4], data_in[5], data_in[6], data_in[7]};
        end else if (reverse) begin
            data_reg <= {data_in[0], data_in[1], data_in[2], data_in[3], data_in[4], data_in[5], data_in[6], data_in[7]};
        end else if (invert) begin
            data_reg <= ~data_in;
        end else begin
            data_reg <= data_in;
        end
        valid_reg <= 1'b1;
    end
end

assign data_out = data_reg;
assign valid = valid_reg;

endmodule

module psram_clk(
    input  rstn,
    input  clk,
    input  sck_en,
    input  sck_pause,
    input  [3:0] sck_div,
    output sck_neg,
    output sck_pos,
    output sck
);

    reg [3:0] cnt;
    reg sck_int;

    wire [3:0] hi_div = sck_div[3:0];
    wire [3:0] lo_div = sck_div[3:0];

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt <= 4'd0;
            sck_int <= 1'b0;
        end
        else if (sck_en) begin
            if (!sck_pause) begin
                if (!sck_int && (cnt == lo_div - 1)) begin
                    sck_int <= 1'b1;
                    cnt <= 4'd0;
                end
                else if (sck_int && (cnt == hi_div - 1)) begin
                    sck_int <= 1'b0;
                    cnt <= 4'd0;
                end
                else begin
                    cnt <= cnt + 4'd1;
                end
            end
            else begin
                cnt <= 4'd0;
            end
        end
        else begin
            cnt <= 4'd0;
            sck_int <= 1'b0;
        end
    end

    assign sck_neg = sck_int;
    assign sck_pos = ~sck_int;
    assign sck = sck_int;

endmodule

module FAU(
    input x0, x1, x2, x3, x4, x5, x6, x7, x8, x9,
    output z0, z1, z2, z3, z4, z5, z6
);

wire new_n20_, new_n24_, new_n27_, new_n28_, new_n29_, new_n31_, new_n32_, new_n33_;

assign new_n20_ = (x7 & x8) | (x9 & (x7 | x8));
assign z0 = new_n20_ | ~x7 | ~x8 | x9;
assign z1 = (x7 ^ x9) | new_n20_ | x8;
assign z2 = new_n20_ | (~x8 & ~x7 & ~x9);
assign new_n24_ = x0 | x1 | x2 | x3;
assign z3 = new_n24_ | x0;
assign z4 = new_n20_ | ~x7 | ~x6 | (x8 & x9);
assign new_n27_ = x4 | x5 | x6;
assign new_n28_ = x1 | x2;
assign new_n29_ = x3 | x4;
assign z5 = new_n27_ | (~x0 & (new_n28_ | x3)) | (~new_n29_ & (x0 | ~x3));
assign new_n31_ = x7 & (x1 | x2 | x3 | x4 | x5 | x6);
assign new_n32_ = x7 & (x0 | x1 | x2 | x3 | x4 | x5 | x6);
assign new_n33_ = ~new_n20_ & ~new_n29_;
assign z6 = (x7 & (new_n31_ | new_n32_)) | (new_n33_);

endmodule

