module alu_8bit(
    input [7:0] a,
    input [7:0] b,
    input cin,
    input [2:0] select,
    output reg [7:0] out,
    output reg carry,
    output zero
);

    reg [8:0] result;

    always @(*) begin
        #1;
        case(select)
            3'b000: result = a + b + cin;  // ADD
            3'b001: result = a - b - 1 + cin;  // SUB
            3'b010: result = b - a - 1 + cin;  // SUB1
            3'b011: begin  // AND_OP
                result[7:0] = a & b;
                result[8] = 1'b0;
            end
            3'b100: begin  // OR_OP
                result[7:0] = a | b;
                result[8] = 1'b0;
            end
            3'b101: begin  // XOR_OP
                result[7:0] = a ^ b;
                result[8] = 1'b0;
            end
            3'b110: begin  // XOR1_OP
                result[7:0] = a ^~ b;
                result[8] = 1'b0;
            end
            default: result = 9'b0;
        endcase

        out = result[7:0];
        carry = result[8];
    end

    assign zero = (out == 8'b0);

endmodule

module adder32(
    input [31:0] a,
    input [31:0] b,
    output [31:0] sum,
    output cout
);

    wire [15:0] sum_lower, sum_upper0, sum_upper1;
    wire cout_lower, cout_upper0, cout_upper1;

    // Lower 16-bit addition
    adder16 lower_adder (
        .a(a[15:0]),
        .b(b[15:0]),
        .cin(1'b0),
        .sum(sum_lower),
        .cout(cout_lower)
    );

    // Upper 16-bit addition with carry-in 0
    adder16 upper_adder0 (
        .a(a[31:16]),
        .b(b[31:16]),
        .cin(1'b0),
        .sum(sum_upper0),
        .cout(cout_upper0)
    );

    // Upper 16-bit addition with carry-in 1
    adder16 upper_adder1 (
        .a(a[31:16]),
        .b(b[31:16]),
        .cin(1'b1),
        .sum(sum_upper1),
        .cout(cout_upper1)
    );

    // Multiplexer to select the correct upper sum and carry-out
    assign sum[15:0] = sum_lower;
    assign sum[31:16] = cout_lower ? sum_upper1 : sum_upper0;
    assign cout = cout_lower ? cout_upper1 : cout_upper0;

endmodule

