module timetag_interface (
    input wire clk,
    input wire cmd_wr,
    input wire [7:0] cmd_in,
    input wire data_rdy,
    input wire [7:0] data,
    output reg data_ack,
    output reg photon_pol,
    output reg [14:0] photon_time
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam RECEIVE_DATA = 2'b01;
    localparam PROCESS_DATA = 2'b10;

    // Command definitions
    localparam CMD_RESET = 8'h00;
    localparam CMD_ENABLE = 8'h01;
    localparam CMD_DISABLE = 8'h02;
    localparam CMD_SET_FREQ = 8'h03;

    reg [1:0] state;
    reg [1:0] next_state;
    reg device_enabled;
    reg [7:0] data_buffer;
    reg data_valid;

    // State machine
    always @(posedge clk) begin
        if (cmd_wr && cmd_in == CMD_RESET) begin
            state <= IDLE;
            device_enabled <= 0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (data_rdy && device_enabled)
                    next_state = RECEIVE_DATA;
            end
            RECEIVE_DATA: begin
                next_state = PROCESS_DATA;
            end
            PROCESS_DATA: begin
                next_state = IDLE;
            end
        endcase
    end

    // Command processing
    always @(posedge clk) begin
        if (cmd_wr) begin
            case (cmd_in)
                CMD_ENABLE: device_enabled <= 1;
                CMD_DISABLE: device_enabled <= 0;
                CMD_SET_FREQ: ; // Add frequency setting logic here if needed
            endcase
        end
    end

    // Data reception
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                data_ack <= 0;
                data_valid <= 0;
            end
            RECEIVE_DATA: begin
                data_buffer <= data;
                data_ack <= 1;
                data_valid <= 1;
            end
            PROCESS_DATA: begin
                data_ack <= 0;
            end
        endcase
    end

    // Data processing
    always @(posedge clk) begin
        if (state == PROCESS_DATA && data_valid) begin
            photon_pol <= data_buffer[7];
            photon_time <= {data_buffer[6:0], data[7:0]};
            data_valid <= 0;
        end
    end

endmodule

