module FixedPoint_AdderSub_CarryLookAhead #(
    parameter WIDTH = 16
)(
    input  wire [WIDTH-1:0] a,
    input  wire [WIDTH-1:0] b,
    input  wire             op,
    output wire [WIDTH-1:0] sum,
    output wire             overflowFlag
);

    wire [WIDTH-1:0] b_modified;
    wire [WIDTH-1:0] G, P;
    wire [WIDTH:0]   C;

    assign b_modified = b ^ {WIDTH{op}};

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin
            assign G[i] = a[i] & b_modified[i];
            assign P[i] = a[i] ^ b_modified[i];
        end
    endgenerate

    assign C[0] = op;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin
            assign C[i+1] = G[i] | (P[i] & C[i]);
        end
    endgenerate

    assign sum = P ^ C[WIDTH-1:0];
    assign overflowFlag = C[WIDTH] ^ C[WIDTH-1];

endmodule

module CoreDbgApb #(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32
) (
    input wire clk,
    input wire rst_n,

    // APB interface
    input wire [ADDR_WIDTH-1:0] addr,
    input wire sel,
    input wire enable,
    input wire wr_rd,
    input wire [DATA_WIDTH-1:0] wdata,
    input wire [(DATA_WIDTH/8)-1:0] wstrobe,
    output reg ready,
    output reg [DATA_WIDTH-1:0] rdata,

    // Core debug interface
    output reg core_dbg_req,
    output reg core_dbg_wr_rd,
    output reg [ADDR_WIDTH-1:0] core_dbg_addr,
    output reg [DATA_WIDTH-1:0] core_dbg_wdata,
    input wire [DATA_WIDTH-1:0] core_dbg_rdata,
    input wire core_dbg_rd_ready
);

    // FSM states
    localparam IDLE = 2'b00;
    localparam WRITE = 2'b01;
    localparam READ = 2'b10;
    localparam READ_READY = 2'b11;

    reg [1:0] state, next_state;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state and output logic
    always @(*) begin
        next_state = state;
        ready = 1'b0;
        core_dbg_req = 1'b0;
        core_dbg_wr_rd = wr_rd;
        core_dbg_addr = addr;
        core_dbg_wdata = wdata;

        case (state)
            IDLE: begin
                if (sel && enable) begin
                    core_dbg_req = 1'b1;
                    next_state = wr_rd ? WRITE : READ;
                end
            end

            WRITE: begin
                ready = 1'b1;
                next_state = IDLE;
            end

            READ: begin
                if (core_dbg_rd_ready) begin
                    rdata = core_dbg_rdata;
                    next_state = READ_READY;
                end
            end

            READ_READY: begin
                ready = 1'b1;
                next_state = IDLE;
            end
        endcase
    end

    // Debug logging
    always @(posedge clk) begin
        if (state == READ_READY)
            $display("CoreDbgApb: Read from addr 0x%h, data 0x%h", addr, rdata);
    end

endmodule

