module DualVGA (
    output reg [2:0] Red,
    output reg [2:0] Green,
    output reg [1:0] Blue,
    output reg HSync,
    output reg VSync,
    output reg [14:0] toMem,
    input Clock,
    input [15:0] memOut
);

    parameter HActive = 640, HFront = 16, HSyncLength = 96, HBack = 48;
    parameter VActive = 480, VFront = 10, VSyncLength = 2, VBack = 29;

    reg [9:0] XPos, YPos;
    reg [2:0] cycle;
    reg [15:0] colors;

    initial begin
        Red <= 0;
        Green <= 0;
        Blue <= 0;
        XPos <= 0;
        YPos <= 0;
        cycle <= 0;
        colors <= 0;
    end

    always @(posedge Clock) begin
        cycle <= cycle + 1;

        if (cycle == 1) begin
            toMem <= {YPos[8:0], XPos[9:0]};
        end
        else if (cycle == 2) begin
            colors <= memOut;
        end
        else if (cycle == 3) begin
            Red <= (XPos < HActive) && (YPos < VActive) ? colors[14:12] : 0;
            Green <= (XPos < HActive) && (YPos < VActive) ? colors[11:9] : 0;
            Blue <= (XPos < HActive) && (YPos < VActive) ? colors[8:7] : 0;
        end

        HSync <= (XPos >= HActive + HFront) && (XPos < HActive + HFront + HSyncLength);
        VSync <= (YPos >= VActive + VFront) && (YPos < VActive + VFront + VSyncLength);

        XPos <= (XPos == HActive + HFront + HSyncLength + HBack - 1) ? 0 : XPos + 1;
        YPos <= (XPos == HActive + HFront + HSyncLength + HBack - 1) ? ((YPos == VActive + VFront + VSyncLength + VBack - 1) ? 0 : YPos + 1) : YPos;
    end

endmodule

