module priority_encoder_8_to_3(
    input  wire [7:0] iData,
    input  wire       iEI,
    output reg [2:0]  oData,
    output reg        oEO
);

    always @(*) begin
        if (iEI) begin
            // If iData is all 1s, set oData to 3'b111 and oEO to 0
            if (iData == 8'b11111111) begin
                oData = 3'b111;
                oEO = 1'b0;
            end
            // If iData is not all 1s, set oData to 3'bxxx and oEO to 1'bx
            else begin
                oData = 3'bxxx;
                oEO = 1'bx;
            end
        end
        else begin
            // Check the position of the highest set bit in iData
            casex (iData)
                8'b1xxxxxxx: begin
                    oData = 3'b111;
                    oEO = 1'b1;
                end
                8'b01xxxxxx: begin
                    oData = 3'b110;
                    oEO = 1'b1;
                end
                8'b001xxxxx: begin
                    oData = 3'b101;
                    oEO = 1'b1;
                end
                8'b0001xxxx: begin
                    oData = 3'b100;
                    oEO = 1'b1;
                end
                8'b00001xxx: begin
                    oData = 3'b011;
                    oEO = 1'b1;
                end
                8'b000001xx: begin
                    oData = 3'b010;
                    oEO = 1'b1;
                end
                8'b0000001x: begin
                    oData = 3'b001;
                    oEO = 1'b1;
                end
                8'b00000001: begin
                    oData = 3'b000;
                    oEO = 1'b1;
                end
                default: begin
                    oData = 3'bxxx;
                    oEO = 1'bx;
                end
            endcase
        end
    end

endmodule

