module traffic_light_controller(
    input wire clk,
    input wire reset,
    output reg [3:0] lampA,
    output reg [3:0] lampB
);

    // Internal registers
    reg [5:0] cntA, cntB;
    reg [3:0] lampA_next, lampB_next;
    reg [5:0] cntA_next, cntB_next;

    // State definitions
    localparam GREEN = 4'b0010;
    localparam YELLOW = 4'b0100;
    localparam RED = 4'b1000;
    localparam RED_YELLOW = 4'b0001;

    // Sequential logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lampA <= GREEN;
            lampB <= GREEN;
            cntA <= 6'd55;
            cntB <= 6'd27;
        end else begin
            lampA <= lampA_next;
            lampB <= lampB_next;
            cntA <= cntA_next;
            cntB <= cntB_next;
        end
    end

    // Combinational logic
    always @(*) begin
        // Default: maintain current state
        lampA_next = lampA;
        lampB_next = lampB;
        cntA_next = (cntA == 6'd0) ? 6'd55 : cntA - 6'd1;
        cntB_next = (cntB == 6'd0) ? 6'd55 : cntB - 6'd1;

        // State transitions for lampA
        case (lampA)
            GREEN: if (cntA == 6'd52) lampA_next = YELLOW;
            YELLOW: if (cntA == 6'd28) lampA_next = RED;
            RED: if (cntA == 6'd24) lampA_next = RED_YELLOW;
            RED_YELLOW: if (cntA == 6'd0) lampA_next = GREEN;
        endcase

        // State transitions for lampB
        case (lampB)
            GREEN: if (cntB == 6'd52) lampB_next = YELLOW;
            YELLOW: if (cntB == 6'd28) lampB_next = RED;
            RED: if (cntB == 6'd24) lampB_next = RED_YELLOW;
            RED_YELLOW: if (cntB == 6'd0) lampB_next = GREEN;
        endcase
