module configurable_counter (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [3:0] i_D,
    input wire [1:0] mode,
    output reg [3:0] o_Q,
    output reg rco,
    output reg load
);

    // Mode definitions
    localparam P_3 = 2'b00;
    localparam M_1 = 2'b01;
    localparam P_1 = 2'b10;
    localparam CHARGE = 2'b11;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            o_Q <= 4'b0000;
            rco <= 1'b0;
            load <= 1'b0;
        end else if (enable) begin
            case (mode)
                P_3: begin
                    o_Q <= (o_Q + 4'd3 > 4'd15) ? o_Q + 4'd3 - 4'd16 : o_Q + 4'd3;
                    rco <= (o_Q >= 4'd13);
                    load <= 1'b0;
                end
                M_1: begin
                    o_Q <= (o_Q == 4'd0) ? 4'd15 : o_Q - 4'd1;
                    rco <= (o_Q == 4'd0);
                    load <= 1'b0;
                end
                P_1: begin
                    o_Q <= (o_Q == 4'd15) ? 4'd0 : o_Q + 4'd1;
                    rco <= (o_Q == 4'd15);
                    load <= 1'b0;
                end
                CHARGE: begin
                    o_Q <= i_D;
                    rco <= 1'b0;
                    load <= 1'b1;
                end
            endcase
        end else begin
            o_Q <= 4'bz;
            rco <= 1'b0;
            load <= 1'b0;
        end
    end

endmodule

