module hit_check #(
    parameter N_WAYS = 2,
    parameter TAG_BITS = 21,
    parameter N_POW = 4
) (
    input [TAG_BITS-1:0] tag_in,
    input [N_WAYS-1:0][TAG_BITS-1:0] line_tags,
    input [N_WAYS-1:0] line_empty,
    output reg hit,
    output reg miss,
    output reg [N_POW-1:0] hit_way
);

    reg [N_WAYS-1:0] hit_encoded;
    integer i;

    always @(*) begin
        hit_encoded = {N_WAYS{1'b0}};
        hit = 1'b0;
        miss = 1'b1;

        for (i = 0; i < N_WAYS; i = i + 1) begin
            if (tag_in == line_tags[i] && !line_empty[i]) begin
                hit_encoded[i] = 1'b1;
                hit = 1'b1;
                miss = 1'b0;
            end
        end

        hit_way = decode(hit_encoded);
    end

    function [N_POW-1:0] decode;
        input [N_WAYS-1:0] encoded;
        integer j;
        begin
            decode = {N_POW{1'b0}};
            for (j = 0; j < N_WAYS; j = j + 1) begin
                if (encoded[j]) begin
                    decode = j[N_POW-1:0];
                end
            end
        end
    endfunction

endmodule

module Timer (
    input wire iClk100M,
    input wire iRstN,
    input wire iPulse,
    output reg [15:0] oValue,
    output reg oValid
);

    parameter SPEED_CLK_DIV = 1000;

    // Clock divider
    reg [9:0] clk_div_counter;
    reg clk_div;

    always @(posedge iClk100M or negedge iRstN) begin
        if (!iRstN) begin
            clk_div_counter <= 0;
            clk_div <= 0;
        end else if (clk_div_counter == SPEED_CLK_DIV - 1) begin
            clk_div_counter <= 0;
            clk_div <= ~clk_div;
        end else begin
            clk_div_counter <= clk_div_counter + 1;
        end
    end

    // Time Counter
    reg [15:0] Time_Counter;
    reg enc, clr, lock, hungry;

    always @(posedge clk_div or negedge iRstN) begin
        if (!iRstN) begin
            Time_Counter <= 0;
        end else if (clr) begin
            Time_Counter <= 0;
        end else if (enc) begin
            if (Time_Counter == 16'hFFFF) begin
                hungry <= 1;
            end else begin
                Time_Counter <= Time_Counter + 1;
            end
        end
    end

    // FSM
    reg [2:0] state, next_state;
    localparam IDLE = 3'd0, COUNTING = 3'd1, SAVE = 3'd2, CLEAR = 3'd3, TIMEOUT = 3'd4;

    always @(posedge clk_div or negedge iRstN) begin
        if (!iRstN) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        enc = 0;
        clr = 0;
        lock = 0;

        case (state)
            IDLE: begin
                if (iPulse) next_state = COUNTING;
            end
            COUNTING: begin
                enc = 1;
                if (iPulse) next_state = SAVE;
                else if (hungry) next_state = TIMEOUT;
            end
            SAVE: begin
                lock = 1;
                next_state = CLEAR;
            end
            CLEAR: begin
                clr = 1;
                next_state = COUNTING;
            end
            TIMEOUT: begin
                if (iPulse) next_state = CLEAR;
            end
        endcase
    end

    // Time Storage
    reg [15:0] TimeR1, TimeR2, TimeR3, TimeR4;

    always @(posedge clk_div or negedge iRstN) begin
        if (!iRstN) begin
            TimeR1 <= 0;
            TimeR2 <= 0;
            TimeR3 <= 0;
            TimeR4 <= 0;
        end else if (lock) begin
            TimeR4 <= TimeR3;
            TimeR3 <= TimeR2;
            TimeR2 <= TimeR1;
            TimeR1 <= Time_Counter;
        end
    end

    // Averaging Circuit
    reg [17:0] Sum0, Sum1, Sum;

    always @(posedge clk_div or negedge iRstN) begin
        if (!iRstN) begin
            Sum0 <= 0;
            Sum1 <= 0;
            Sum <= 0;
            oValue <= 0;
            oValid <= 0;
        end else begin
            Sum0 <= TimeR1 + TimeR2;
            Sum1 <= TimeR3 + TimeR4;
            Sum <= Sum0 + Sum1;
            oValue <= Sum[17:2];
            oValid <= (TimeR1 != 0) && (TimeR2 != 0) && (TimeR3 != 0) && (TimeR4 != 0);
        end
    end

endmodule

module enable_clock #(
    parameter SYS_CLK_FREQ = 100_000_000,  // 100 MHz
    parameter TARGET_CLK_FREQ = 10_000_000, // 10 MHz
    parameter N = 3
) (
    input wire sys_clk,
    input wire sys_rst_n,
    output reg clk_flag
);

    localparam CNT_MAX = 24999;
    reg [14:0] r_cnt;

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            r_cnt <= 15'd0;
            clk_flag <= 1'b0;
        end else begin
            if (r_cnt == CNT_MAX) begin
                r_cnt <= 15'd0;
                clk_flag <= 1'b1;
            end else begin
                r_cnt <= r_cnt + 1'b1;
                clk_flag <= 1'b0;
            end
        end
    end

endmodule

module smbs (
