        for (i = 0; i < 4; i = i + 1) begin
            if (PB[i]) begin
                case (LB)
                    2'b00: W[i*4] = inp;
                    2'b01: W[i*4 + 1] = inp;
                    2'b10: W[i*4 + 2] = inp;
                    2'b11: W[i*4 + 3] = inp;
