module rc4 (
    input wire clk,
    input wire rst,
    input wire [7:0] keyinput,
    input wire need,
    output reg ready,
    output reg [7:0] k
);

    parameter keylength = 8;

    // State definitions
    localparam [3:0] RC4_KEYREAD = 4'd0,
                     RC4_KSA1    = 4'd1,
                     RC4_KSA2    = 4'd2,
                     RC4_KSA3    = 4'd3,
                     RC4_NEED    = 4'd4,
                     RC4_PRGA1   = 4'd5,
                     RC4_PRGA2   = 4'd6,
                     RC4_PRGA3   = 4'd7;

    reg [3:0] state;
    reg [7:0] key [0:keylength-1];
    reg [7:0] stream [0:255];
    reg [7:0] i, j;
    reg [7:0] keyindex;
    reg [7:0] temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= RC4_KEYREAD;
            ready <= 0;
            keyindex <= 0;
            i <= 0;
            j <= 0;
        end else begin
            case (state)
                RC4_KEYREAD: begin
                    if (keyindex < keylength) begin
                        key[keyindex] <= keyinput;
                        keyindex <= keyindex + 1;
                    end else begin
                        state <= RC4_KSA1;
                        i <= 0;
                        j <= 0;
                    end
                end

                RC4_KSA1: begin
                    stream[i] <= i;
                    if (i == 255) begin
                        state <= RC4_KSA2;
                        i <= 0;
                        j <= 0;
                    end else begin
                        i <= i + 1;
                    end
                end

                RC4_KSA2: begin
                    j <= j + stream[i] + key[i % keylength];
                    state <= RC4_KSA3;
                end

                RC4_KSA3: begin
                    temp <= stream[i];
                    stream[i] <= stream[j];
                    stream[j] <= temp;
                    if (i == 255) begin
                        state <= RC4_NEED;
                        i <= 0;
                        j <= 0;
                    end else begin
                        i <= i + 1;
                        state <= RC4_KSA2;
                    end
                end

                RC4_NEED: begin
                    if (need) begin
                        state <= RC4_PRGA1;
                        ready <= 0;
                    end
                end

                RC4_PRGA1: begin
                    i <= i + 1;
                    state <= RC4_PRGA2;
                end

                RC4_PRGA2: begin
                    j <= j + stream[i];
                    state <= RC4_PRGA3;
                end

                RC4_PRGA3: begin
                    temp <= stream[i];
                    stream[i] <= stream[j];
                    stream[j] <= temp;
                    k <= stream[(stream[i] + stream[j]) % 256];
                    ready <= 1;
                    state <= RC4_NEED;
                end

                default: state <= RC4_KEYREAD;
            endcase
        end
    end

endmodule

module digital_delay (
    input wire Enable,
    input wire Clk,
    input wire Reset,
    input wire CE_N,
    input wire OE_N,
    input wire WE_N,
    input wire UB_N,
    input wire LB_N,
    input wire [7:0] Time,
    input wire [7:0] Repeats,
    input wire [7:0] Mix,
    input wire [19:0] SRAM_ADDR,
    input wire [23:0] D_In,
    inout wire [15:0] SRAM_DQ,
    output reg [23:0] D_Out
);

    // Internal registers
    reg [19:0] write_addr;
    reg [19:0] read_addr;
    reg [7:0] repeat_count;
    reg [23:0] delayed_sample;
    reg [23:0] mixed_output;

    // SRAM control
    reg sram_we_n;
    reg [15:0] sram_data_out;
    wire [15:0] sram_data_in;

    assign SRAM_DQ = (!OE_N && WE_N) ? sram_data_out : 16'bz;
    assign sram_data_in = SRAM_DQ;

    always @(posedge Clk or posedge Reset) begin
        if (Reset) begin
            write_addr <= 20'b0;
            read_addr <= 20'b0;
            repeat_count <= 8'b0;
            D_Out <= 24'b0;
        end else if (Enable) begin
            // Write input sample to SRAM
            sram_we_n <= 1'b0;
            sram_data_out <= D_In[23:8];  // Write upper 16 bits
            write_addr <= (write_addr + 1) % (2**20);  // Circular buffer

            // Read delayed sample from SRAM
            sram_we_n <= 1'b1;
            read_addr <= (write_addr - Time) % (2**20);
            delayed_sample <= {sram_data_in, 8'b0};  // Pad with zeros for lower 8 bits

            // Mix original and delayed samples
            mixed_output <= (D_In * (8'd255 - Mix) + delayed_sample * Mix) / 8'd255;

            // Update output and repeat count
            if (repeat_count < Repeats) begin
                D_Out <= mixed_output;
                repeat_count <= repeat_count + 1;
            end else begin
                D_Out <= D_In;
                repeat_count <= 8'b0;
            end
        end
    end

    // SRAM control signals
    assign CE_N = !Enable;
    assign OE_N = sram_we_n;
    assign WE_N = sram_we_n;
    assign UB_N = 1'b0;
    assign LB_N = 1'b0;

endmodule

module combined_system(
    input wire clk,
    input wire reset,
    input wire shift_en,
    input wire load,
    input wire serial_in,
    input wire [3:0] parallel_in,
    output wire serial_out,
    output wire [3:0] final_output
);

    wire [3:0] shift_reg_out;
    wire [3:0] twos_complement_out;

    // 4-bit shift register
    shift_register_4bit shift_reg (
        .clk(clk),
        .reset(reset),
        .shift_en(shift_en),
        .load(load),
        .serial_in(serial_in),
        .parallel_in(parallel_in),
        .serial_out(serial_out),
        .parallel_out(shift_reg_out)
    );

    // 2's complement module
    twos_complement_4bit twos_comp (
        .in(shift_reg_out),
        .out(twos_complement_out)
    );

    // Bitwise AND operation
    assign final_output = shift_reg_out & twos_complement_out;

endmodule

module shift_register_4bit(
    input wire clk,
    input wire reset,
    input wire shift_en,
    input wire load,
    input wire serial_in,
    input wire [3:0] parallel_in,
    output wire serial_out,
    output reg [3:0] parallel_out
);

    always @(posedge clk or posedge reset) begin
        if (reset)
            parallel_out <= 4'b0000;
        else if (load)
            parallel_out <= parallel_in;
        else if (shift_en)
            parallel_out <= {serial_in, parallel_out[3:1]};
    end

    assign serial_out = parallel_out[0];

endmodule

module twos_complement_4bit(
    input wire [3:0] in,
    output wire [3:0] out
);

    assign out = ~in + 1'b1;

endmodule

module pwm_core_4ch (
    input wire clk,
    input wire [15:0] PR,
    input wire [15:0] CR1,
    input wire [15:0] CR2,
    input wire [15:0] CR3,
    input wire [15:0] CR4,
    input wire start,
    input wire stop,
    input wire reset,
    output wire PWM_out1,
    output wire PWM_out2,
    output wire PWM_out3,
    output wire PWM_out4,
    output wire [15:0] timerval_mon
);

    reg [15:0] timerval;
    reg pwm1, pwm2, pwm3, pwm4;

    always @(posedge clk) begin
        if (timerval >= PR) begin
            timerval <= 16'd0;
        end else begin
            timerval <= timerval + 1'b1;
        end
    end

    always @(posedge clk) begin
        pwm1 <= (timerval >= CR1);
        pwm2 <= (timerval >= CR2);
        pwm3 <= (timerval >= CR3);
        pwm4 <= (timerval >= CR4);
    end

    assign PWM_out1 = ~pwm1;
