module fifo_out_cal_addr (
    input [2:0] state,
    input [4:0] head,
    input [4:0] tail,
    input [5:0] data_count,
    output reg we,
    output reg re,
    output reg [4:0] next_head,
    output reg [4:0] next_tail,
    output reg [5:0] next_data_count
);

always @(*) begin
    case (state)
        3'b000: begin // IDLE
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        3'b001: begin // WRITE
            we = 1'b1;
            re = 1'b0;
            next_head = head;
            next_tail = tail + 1'b1;
            next_data_count = data_count + 1'b1;
        end
        3'b010: begin // READ
            we = 1'b0;
            re = 1'b1;
            next_head = head + 1'b1;
            next_tail = tail;
            next_data_count = data_count - 1'b1;
        end
        3'b011: begin // WR_ERROR
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        3'b100: begin // RD_ERROR
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        default: begin
            we = 1'bx;
            re = 1'bx;
            next_head = 5'bxxxxx;
            next_tail = 5'bxxxxx;
            next_data_count = 6'bxxxxxx;
        end
    endcase
end

endmodule

module Stopwatch(
    input Clk_50Mhz,
    input Button1Sw,
    input Button2Sw,
    input Button3Sw,
    output [7:0] MiliSecSW,
    output [7:0] SecSW,
    output [7:0] MinSW,
    output BlinkSW
);

    reg [7:0] mili_sec = 0;
    reg [7:0] sec = 0;
    reg [7:0] min = 0;
    reg run = 0;
    reg split = 0;
    reg [31:0] clk_cnt = 0;
    reg [7:0] split_mili_sec, split_sec, split_min;

    always @(posedge Clk_50Mhz) begin
        clk_cnt <= clk_cnt + 1;
        if (clk_cnt == 500_000) begin // 100 Hz clock
            clk_cnt <= 0;
            if (run) begin
                mili_sec <= mili_sec + 1;
                if (mili_sec == 100) begin
                    mili_sec <= 0;
                    sec <= sec + 1;
                    if (sec == 60) begin
                        sec <= 0;
                        min <= min + 1;
                        if (min == 100) begin
                            min <= 0;
                        end
                    end
                end
            end
        end
    end

    always @(posedge Button1Sw) begin
        run <= ~run;
    end

    always @(posedge Button2Sw) begin
        if (~run) begin
            mili_sec <= 0;
            sec <= 0;
            min <= 0;
        end
    end

    always @(posedge Button3Sw) begin
        split <= ~split;
        if (split) begin
            split_mili_sec <= mili_sec;
            split_sec <= sec;
            split_min <= min;
        end
    end

    assign MiliSecSW = (split) ? split_mili_sec : mili_sec;
    assign SecSW = (split) ? split_sec : sec;
    assign MinSW = (split) ? split_min : min;
    assign BlinkSW = split;

endmodule

