module year_counter (
    input wire clk_out,
    input wire rst_n,
    input wire increase,
    output reg [3:0] year1,
    output reg [3:0] year0,
    output reg over
);

    reg [3:0] year1_next, year0_next;
    reg over_next;

    // Combinational logic
    always @(*) begin
        year1_next = year1;
        year0_next = year0;
        over_next = 1'b0;

        if (increase) begin
            if (year1 == 4'd9 && year0 == 4'd9) begin
                year1_next = 4'd0;
                year0_next = 4'd0;
                over_next = 1'b1;
            end else if (year0 == 4'd9) begin
                year1_next = year1 + 1'b1;
                year0_next = 4'd0;
            end else begin
                year0_next = year0 + 1'b1;
            end
        end
    end

    // Sequential logic
    always @(posedge clk_out or negedge rst_n) begin
        if (!rst_n) begin
            year1 <= 4'd0;
            year0 <= 4'd0;
            over <= 1'b0;
        end else begin
            year1 <= year1_next;
            year0 <= year0_next;
            over <= over_next;
        end
    end

endmodule

module input_control_logic (
    input wire clk,
    input wire reset,
    input wire polarity,
    input wire send_in,
    input wire ready_arb_0,
    input wire ready_arb_1,
    input wire [7:0] hop_count,
    output reg send_arb_0,
    output reg send_arb_1,
    output wire ready_in,
    output reg enable_even,
    output reg enable_odd
);

    reg [1:0] odd_even_full;
    reg buffer_enable_odd, buffer_enable_even;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            odd_even_full <= 2'b00;
            buffer_enable_odd <= 1'b0;
            buffer_enable_even <= 1'b0;
            send_arb_0 <= 1'b0;
            send_arb_1 <= 1'b0;
            enable_even <= 1'b0;
            enable_odd <= 1'b0;
        end else begin
            // Buffer fullness management
            if (send_in) begin
                odd_even_full[polarity] <= 1'b1;
            end else if ((send_arb_0 | send_arb_1) & odd_even_full[polarity]) begin
                odd_even_full[polarity] <= 1'b0;
            end

            // Buffer enable signals
            buffer_enable_odd <= polarity & ~odd_even_full[1];
            buffer_enable_even <= ~polarity & ~odd_even_full[0];

            // Arbitration control
            send_arb_0 <= odd_even_full[polarity] & (hop_count != 8'd0) & (ready_arb_0 | ~ready_arb_1);
            send_arb_1 <= odd_even_full[polarity] & (hop_count == 8'd0) & ready_arb_1;

            // Data path enabling
            enable_even <= (~polarity & buffer_enable_even) | (odd_even_full[0] & (ready_arb_0 | ready_arb_1));
            enable_odd <= (polarity & buffer_enable_odd) | (odd_even_full[1] & (ready_arb_0 | ready_arb_1));
        end
    end

    // Input readiness
    assign ready_in = ~odd_even_full[~polarity] | ready_arb_0 | ready_arb_1;

endmodule

module example2(
    input wire start,
    input wire clk,
    output reg out
);

    reg started;
    reg [1:0] k;
    reg storage_start;

    initial begin
        k = 2'b01;
        started = 1'b0;
    end

    always @(posedge clk) begin
        storage_start <= start;

        if (storage_start) begin
            started <= 1'b1;
            k <= 2'b00;
        end
        else if (started) begin
            k <= k + 1'b1;
        end
    end

    always @(*) begin
        out = (k == 2'b00) ? 1'b1 : 1'b0;
    end

endmodule

module dac_max_finder(
    input [15:0] D,
    output reg [3:0] max_value,
    output reg [7:0] analog_out,
    output reg [7:0] sum_out
);

    reg [3:0] dac_input;
    reg [7:0] dac_output;
    integer i;

    // Priority encoder to find the highest set bit
    always @(*) begin
        max_value = 4'b0000;
        for (i = 15; i >= 0; i = i - 1) begin
            if (D[i]) begin
                max_value = i[3:0];
                i = -1; // Exit the loop
            end
        end
    end

    // Shift register to get the maximum value
    always @(*) begin
        dac_input = D >> (max_value - 3'b011);
    end

    // DAC implementation
    always @(*) begin
        dac_output = (dac_input * 8'd85) / 4'd15; // (Vin/15)*5 scaled to 8-bit
        analog_out = dac_output;
    end

    // Sum of analog output and maximum value
    always @(*) begin
        sum_out = analog_out + {4'b0000, max_value};
    end

endmodule

module SRC_imm_MUX (
    input [7:0] instr,
    input src1sel,
    input l_sw,
    output en,
    output [15:0] imm_src1
);

    wire [15:0] s1, s2;

    // Enable signal
    assign en = src1sel | l_sw;

    // Sign extension
    assign s1 = {{8{instr[7]}}, instr[7:0]};
    assign s2 = {{12{instr[3]}}, instr[3:0]};

    // Multiplexing
    assign imm_src1 = src1sel ? s1 :
                      l_sw    ? s2 :
                                16'h0;

endmodule

module x_oneshot(
    input d,
    input clock,
    output q
);

`ifdef DEBUG_X_ONESHOT
    output [39:0] sm_dsp;
`endif

reg [1:0] state;
parameter IDLE = 2'b00, PULSE = 2'b01, HOLD = 2'b10;

always @(posedge clock) begin
    case (state)
        IDLE: begin
            if (d) state <= PULSE;
            else state <= IDLE;
        end
        PULSE: begin
            state <= HOLD;
        end
        HOLD: begin
            if (~d) state <= IDLE;
            else state <= HOLD;
        end
    endcase
end

assign q = (state == PULSE);

`ifdef DEBUG_X_ONESHOT
    assign sm_dsp = {38'd0, state};
`endif

endmodule

module bit_counter_and_transition_detector (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    output reg [7:0] final_output
);

    // Population count
    reg [3:0] ones_count;
    always @(*) begin
        ones_count = data_in[0] + data_in[1] + data_in[2] + data_in[3] +
                     data_in[4] + data_in[5] + data_in[6] + data_in[7];
    end

    // Shift register for transition detection
    reg [7:0] shift_reg;
    always @(posedge clk or posedge rst) begin
        if (rst)
            shift_reg <= 8'b0;
        else
            shift_reg <= data_in;
    end

    // Transition detection and counting
    reg [7:0] transition_count;
    wire [7:0] transitions;
    assign transitions = data_in ^ shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            transition_count <= 8'b0;
        else
            transition_count <= transition_count + transitions[0] + transitions[1] +
                                transitions[2] + transitions[3] + transitions[4] +
                                transitions[5] + transitions[6] + transitions[7];
    end

    // Final output calculation
    always @(posedge clk or posedge rst) begin
        if (rst)
            final_output <= 8'b0;
        else
            final_output <= ones_count + transition_count[7:0];
    end

endmodule

module alu (
    input [31:0] data_in1,
    input [31:0] data_in2,
    input [2:0] funct3,
    input shift_ctrl,
    input sub_ctrl,
    output reg [31:0] data_out
);

    wire [4:0] shamt;
    assign shamt = data_in2[4:0];

    always @(*) begin
        case (funct3)
            3'b000: data_out = sub_ctrl ? data_in1 - data_in2 : data_in1 + data_in2;
            3'b001: data_out = data_in1 << shamt;
            3'b010: data_out = ($signed(data_in1) < $signed(data_in2)) ? 32'd1 : 32'd0;
            3'b011: data_out = (data_in1 < data_in2) ? 32'd1 : 32'd0;
            3'b100: data_out = data_in1 ^ data_in2;
            3'b101: begin
                if (shift_ctrl)
                    data_out = $signed(data_in1) >>> shamt;
                else
                    data_out = data_in1 >> shamt;
            end
            3'b110: data_out = data_in1 | data_in2;
            3'b111: data_out = data_in1 & data_in2;
            default: data_out = 32'b0;
        endcase
    end

endmodule

module regfile(
    input [31:0] data,
    input [4:0] ra, rb, rw,
    input nwr,
    input clock,
    output [31:0] A, B
);

