    initial begin
        integer i;
        for (i = 0; i < 32; i = i + 1) begin
            registers[i] = 32'b0;
        end
    end

    assign A = registers[ra];
    assign B = registers[rb];

    always @(posedge clock) begin
        if (nwr == 1'b0) begin
            registers[rw] <= data;
            $display("%0t: Register %d written with value %h. A = %h, B = %h", $time, rw, data, A, B);
        end
    end

endmodule

module leadzero #(
    parameter WIDTH = 8,
    parameter WORD = 4
)(
    input wire CLK,
    input wire ivalid,
    input wire rst_n,
    input wire mode,
    input wire [WIDTH-1:0] data,
    output reg ovalid,
    output reg [8:0] zero
);

    localparam IDLE = 2'b00;
    localparam CALC = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state, next_state;
    reg [2:0] word_count;
    reg [8:0] zero_count;

    // Leading zero count for 4-bit input
    function [1:0] count_zeros_4bit;
        input [3:0] nibble;
        begin
            casez (nibble)
                4'b1???: count_zeros_4bit = 2'd0;
                4'b01??: count_zeros_4bit = 2'd1;
                4'b001?: count_zeros_4bit = 2'd2;
                4'b0001: count_zeros_4bit = 2'd3;
                4'b0000: count_zeros_4bit = 2'd4;
            endcase
        end
    endfunction

    // Leading zero count for 8-bit input
    function [2:0] count_zeros_8bit;
        input [7:0] byte;
        begin
            if (byte[7:4] != 4'b0000)
                count_zeros_8bit = {1'b0, count_zeros_4bit(byte[7:4])};
            else
                count_zeros_8bit = 3'd4 + count_zeros_4bit(byte[3:0]);
        end
    endfunction

    // Leading zero count for 16-bit input
    function [3:0] count_zeros_16bit;
        input [15:0] word;
        begin
            if (word[15:8] != 8'b00000000)
                count_zeros_16bit = {1'b0, count_zeros_8bit(word[15:8])};
            else
                count_zeros_16bit = 4'd8 + count_zeros_8bit(word[7:0]);
        end
    endfunction

    // Calculate leading zeros based on WIDTH
    always @(*) begin
        case (WIDTH)
            4: zero_count = {7'b0, count_zeros_4bit(data[3:0])};
            8: zero_count = {6'b0, count_zeros_8bit(data[7:0])};
            16: zero_count = {5'b0, count_zeros_16bit(data[15:0])};
            default: zero_count = 9'd0;
        endcase
    end

    // State machine and output logic
    always @(posedge CLK or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            word_count <= 3'd0;
            zero <= 9'd0;
            ovalid <= 1'b0;
        end else begin
            state <= next_state;
            if (ivalid) begin
                if (word_count == WORD - 1 || (mode && zero_count != WIDTH)) begin
                    zero <= zero + zero_count;
                    word_count <= 3'd0;
                    ovalid <= 1'b1;
                end else begin
                    zero <= zero + zero_count;
                    word_count <= word_count + 1'b1;
                    ovalid <= 1'b0;
                end
            end else begin
                ovalid <= 1'b0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (ivalid) next_state = CALC;
            CALC: if (word_count == WORD - 1 || (mode && zero_count != WIDTH)) next_state = FINISH;
            FINISH: next_state = IDLE;
        endcase
    end

endmodule

module dsp_control (
