module decade_counter (
    input wire clk,
    input wire reset,
    input wire slowena,
    output reg [3:0] count
);

    wire [3:0] next_count;

    // Multiplexer logic for next state
    assign next_count[0] = count[0] ? 1'b0 : 1'b1;
    assign next_count[1] = (count == 4'd1 || count == 4'd3 || count == 4'd5 || count == 4'd7) ? 1'b1 :
                           (count == 4'd9) ? 1'b0 : count[1];
    assign next_count[2] = (count == 4'd3 || count == 4'd4 || count == 4'd5) ? 1'b1 :
                           (count == 4'd7 || count == 4'd8 || count == 4'd9) ? 1'b0 : count[2];
    assign next_count[3] = (count == 4'd7 || count == 4'd8 || count == 4'd9) ? 1'b0 :
                           (count == 4'd4 || count == 4'd5 || count == 4'd6) ? 1'b1 : count[3];

    // D flip-flops with asynchronous reset and slowena
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
        end else if (slowena) begin
            count <= next_count;
        end
    end

endmodule

module cpa_b1(
    input [1:0] x1, x2,
    input [1:0] ed, ec,
    input stall,
    input cin,
    output cout,
    output [1:0] carry,
    output [1:0] summ
);

    wire [1:0] s1;
    wire [1:0] add_in;

    assign s1 = x1 + x2;
    assign add_in = (stall) ? ec : ed;
    assign {cout, summ} = s1 + add_in + cin;
    assign carry = (stall) ? ec : ed;

endmodule

module wallace_tree_8x8(
    input [7:0] x,
    input [7:0] y,
    output [15:0] out,
    output [4:0][15:0] pp
);

    wire [7:0][15:0] i;
    wire [3:0][15:0] l0;
    wire [2:0][15:0] l1;
    wire [1:0][15:0] l2;
    wire [1:0][15:0] l3;

    // Partial product generation
    genvar j, k;
    generate
        for (j = 0; j < 8; j = j + 1) begin : gen_row
            for (k = 0; k < 16; k = k + 1) begin : gen_col
                if (k < j || k > j + 7)
                    assign i[j][k] = 1'b0;
                else
                    assign i[j][k] = x[k-j] & y[j];
            end
        end
    endgenerate

    // Wallace Tree Reduction
    // Level 0
    csa csa00(.a(i[0]), .b(i[1]), .c(i[2]), .sum(l0[0]), .carry(l0[1]));
    csa csa01(.a(i[3]), .b(i[4]), .c(i[5]), .sum(l0[2]), .carry(l0[3]));

    // Level 1
    csa csa10(.a(l0[0]), .b(l0[1]), .c(l0[2]), .sum(l1[0]), .carry(l1[1]));
    csa csa11(.a(l0[3]), .b(i[6]), .c(i[7]), .sum(l1[2]), .carry());

    // Level 2
    csa csa20(.a(l1[0]), .b(l1[1]), .c(l1[2]), .sum(l2[0]), .carry(l2[1]));

    // Level 3
    csa csa30(.a(l2[0]), .b(l2[1]), .c(16'b0), .sum(l3[0]), .carry(l3[1]));

    // Final addition
    rca rca_final(.a(l3[0]), .b({l3[1][14:0], 1'b0}), .cin(1'b0), .sum(out), .cout());

    // Assign partial products for debugging
    assign pp[0] = l0[0];
    assign pp[1] = l0[1];
    assign pp[2] = l1[0];
    assign pp[3] = l2[0];
    assign pp[4] = l3[0];

endmodule

module csa(
    input [15:0] a,
    input [15:0] b,
    input [15:0] c,
    output [15:0] sum,
    output [15:0] carry
);
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : gen_fa
            full_adder fa(.a(a[i]), .b(b[i]), .cin(c[i]), .sum(sum[i]), .cout(carry[i]));
        end
    endgenerate
endmodule

module rca(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout
);
    wire [16:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : gen_fa
            full_adder fa(.a(a[i]), .b(b[i]), .cin(carry[i]), .sum(sum[i]), .cout(carry[i+1]));
        end
    endgenerate

    assign cout = carry[16];
endmodule

module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);
    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (b & cin) | (a & cin);
endmodule

module counthours(
    input wire clk,
    input wire aumentar,
    input wire disminuir,
    output reg [7:0] counthours
);

    initial begin
        counthours = 8'd0;
    end

    always @(posedge clk) begin
        if (aumentar) begin
            if (counthours == 8'd23)
                counthours <= 8'd0;
            else
                counthours <= counthours + 8'd1;
        end
        else if (disminuir) begin
            if (counthours == 8'd0)
                counthours <= 8'd23;
            else
                counthours <= counthours - 8'd1;
        end
    end

endmodule

module Control(
    input wire ClockA,
    input wire Reset,
    input wire [2:0] PortA,
    input wire [2:0] PortB,
    input wire [5:0] Result,
    output reg [3:0] BCD,
    output reg [7:0] An
);

reg [1:0] Contador;

always @(posedge ClockA or negedge Reset) begin
    if (!Reset) begin
        Contador <= 2'b00;
        BCD <= 4'b0000;
        An <= 8'b11111111;
    end else begin
        case (Contador)
            2'b00: begin
                BCD <= {1'b0, PortA};
                An <= 8'b11111110;
            end
            2'b01: begin
                BCD <= {1'b0, PortB};
                An <= 8'b11111101;
            end
            2'b10: begin
                BCD <= {2'b00, Result[5:4]};
                An <= 8'b11111011;
            end
            2'b11: begin
                BCD <= Result[3:0];
                An <= 8'b11110111;
            end
        endcase
        Contador <= Contador + 1;
    end
end

endmodule

module render(
    input wire clk,
    input wire reset,
    input wire sw,
    input wire indisplayinterval,
    input wire square_on,
    input wire [8:0] switches,
