);

    reg [11:0] rgb_reg;

    always @(posedge clk) begin
        if (square_on) begin
            rgb_reg[11] <= 1'b0;
            rgb_reg[10:8] <= switches[8:6];
            rgb_reg[7] <= 1'b0;
            rgb_reg[6:4] <= switches[5:3];
            rgb_reg[3] <= 1'b0;
            rgb_reg[2:0] <= switches[2:0];
        end else begin
            rgb_reg <= 12'hFFF;
        end
    end

    assign rgb = indisplayinterval ? rgb_reg : 12'h000;

endmodule

module TickTackGenerator #(
    parameter N = 10416
) (
    input Clk,
    input Reset,
    output reg TickTack
);

reg [13:0] Counter;

always @(posedge Clk or posedge Reset) begin
    if (Reset) begin
        Counter <= 0;
        TickTack <= 1'b0;
    end
    else begin
        if (Counter == N - 1) begin
            Counter <= 0;
            TickTack <= 1'b1;
        end
        else begin
            Counter <= Counter + 1;
            TickTack <= 1'b0;
        end
    end
end

endmodule

module RegisterBlock (
    input wire clk,
    input wire rstn,
    input wire APB_M_0_psel,
    input wire APB_M_0_penable,
    input wire APB_M_0_pwrite,
    input wire [31:0] APB_M_0_paddr,
    input wire [31:0] APB_M_0_pwdata,
    output reg [31:0] APB_M_0_prdata,
    output reg APB_M_0_pready,
    output wire APB_M_0_pslverr,
    output reg Start,
    input wire Busy,
    output reg [31:0] DataOut,
    input wire [31:0] DataIn,
    output reg [15:0] WR,
    output reg [15:0] ClockDiv,
    output reg [15:0] NegDel
);

    reg RegStart;
    reg [31:0] RegDataOut;
    reg [15:0] RegWR;
    reg [15:0] RegClockDiv;
    reg [15:0] RegNegDel;

    wire apb_write = APB_M_0_psel && APB_M_0_penable && APB_M_0_pwrite;
    wire apb_read = APB_M_0_psel && APB_M_0_penable && !APB_M_0_pwrite;

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            RegStart <= 1'b0;
            RegDataOut <= 32'b0;
            RegWR <= 16'b0;
            RegClockDiv <= 16'b0;
            RegNegDel <= 16'b0;
            APB_M_0_pready <= 1'b0;
        end else begin
            APB_M_0_pready <= APB_M_0_psel && !APB_M_0_penable;

            if (apb_write) begin
                case (APB_M_0_paddr[7:2])
                    6'h00: RegStart <= APB_M_0_pwdata[0];
                    6'h02: RegDataOut <= APB_M_0_pwdata;
                    6'h04: RegWR <= APB_M_0_pwdata[15:0];
                    6'h05: RegClockDiv <= APB_M_0_pwdata[15:0];
                    6'h06: RegNegDel <= APB_M_0_pwdata[15:0];
                endcase
            end

            if (apb_read) begin
                case (APB_M_0_paddr[7:2])
                    6'h00: APB_M_0_prdata <= {31'b0, Start};
                    6'h01: APB_M_0_prdata <= {31'b0, Busy};
                    6'h02: APB_M_0_prdata <= RegDataOut;
                    6'h03: APB_M_0_prdata <= DataIn;
                    6'h04: APB_M_0_prdata <= {16'b0, RegWR};
                    6'h05: APB_M_0_prdata <= {16'b0, RegClockDiv};
                    6'h06: APB_M_0_prdata <= {16'b0, RegNegDel};
                    default: APB_M_0_prdata <= 32'b0;
                endcase
            end

            if (Start && Busy) begin
                RegStart <= 1'b0;
            end
        end
    end

    always @(*) begin
        Start = RegStart;
        DataOut = RegDataOut;
        WR = RegWR;
        ClockDiv = RegClockDiv;
        NegDel = RegNegDel;
    end

    assign APB_M_0_pslverr = 1'b0;

endmodule

module RegisterFile (
    input [4:0] A1, A2, A3,
    input [31:0] WD,
    input RFWr, clk,
    output [31:0] RD1, RD2
);

    reg [31:0] data [0:31];
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            data[i] = 32'b0;
    end

    assign RD1 = data[A1];
    assign RD2 = data[A2];

    always @(negedge clk) begin
        if (RFWr) begin
            if (A3 == 5'b11111)
                data[A3] <= WD + 4;
            else
                data[A3] <= WD;

            // Debug: Display all register contents
            for (i = 0; i < 32; i = i + 1)
                $display("R%d = %h", i, data[i]);
        end
    end

endmodule

