module PASS_ROM_controller_mod (
    input wire clk,
    input wire rst,
    input wire pass_allow,
    input wire [3:0] pass_input,
    input wire pass_load,
    input wire pass_pound,
    input wire [7:0] q_pwd,
    input wire [2:0] address_user,
    output reg wrong_pwd,
    output reg [5:0] address_pass,
    output reg allow,
    output reg flag
);

    // State encoding
    localparam INIT = 3'd0, WAIT_1 = 3'd1, WAIT_2 = 3'd2, CHECK = 3'd3, FINISH = 3'd4;

    reg [2:0] state, next_state;
    reg [2:0] digit_count;

    // State register
    always @(posedge clk or negedge rst) begin
        if (!rst)
            state <= INIT;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            INIT: next_state = pass_allow ? WAIT_1 : INIT;
            WAIT_1: next_state = pass_load ? WAIT_2 : WAIT_1;
            WAIT_2: next_state = CHECK;
            CHECK: begin
                if (pass_pound)
                    next_state = FINISH;
                else if (pass_load)
                    next_state = WAIT_2;
                else
                    next_state = CHECK;
            end
            FINISH: next_state = INIT;
            default: next_state = INIT;
        endcase
    end

    // Output and internal logic
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            wrong_pwd <= 0;
            address_pass <= 0;
            allow <= 0;
            flag <= 0;
            digit_count <= 0;
        end else begin
            case (state)
                INIT: begin
                    wrong_pwd <= 0;
                    address_pass <= {address_user, 3'b000};
                    allow <= 0;
                    flag <= 0;
                    digit_count <= 0;
                end
                WAIT_1: begin
                    if (pass_load)
                        address_pass <= address_pass + 1;
                end
                CHECK: begin
                    if (pass_input != q_pwd[3:0])
                        flag <= 1;
                    if (pass_load) begin
                        address_pass <= address_pass + 1;
                        digit_count <= digit_count + 1;
                    end
                end
                FINISH: begin
                    if (q_pwd == 8'h1F) begin
                        if (flag)
                            wrong_pwd <= 1;
                        else
                            allow <= 1;
                    end else begin
                        wrong_pwd <= 1;
                    end
                end
            endcase
        end
    end

endmodule

module parameterizable_rom #(
    parameter DATA_WIDTH = 8,
    parameter ROM_DEPTH = 8,
    parameter BASE_ADDR = 0,
    parameter ROM_FILE = ""
) (
    input wire clk,
    input wire n_rst,
    input wire [$clog2(ROM_DEPTH)-1:0] i_rom_rd_addr,
    output reg [DATA_WIDTH-1:0] o_rom_data_out
);

    reg [DATA_WIDTH-1:0] rom [0:ROM_DEPTH-1];
    wire cs;

    initial begin
        if (ROM_FILE != "") begin
            $readmemh(ROM_FILE, rom);
        end
    end

    assign cs = n_rst && (i_rom_rd_addr >= BASE_ADDR) && (i_rom_rd_addr < BASE_ADDR + ROM_DEPTH);

    always @(*) begin
        if (cs) begin
            o_rom_data_out = rom[i_rom_rd_addr - BASE_ADDR];
        end else begin
            o_rom_data_out = {DATA_WIDTH{1'b0}};
        end
    end

endmodule

