module display(
    input clk,
    input [31:0] data,
    output reg [7:0] an,
    output reg [7:0] seg
);

reg [3:0] num;
reg [31:0] cnt;

always @(posedge clk) begin
    cnt <= cnt + 1;
end

always @(*) begin
    case(cnt[17:15])
        3'b000: begin an = 8'b11111110; num = data[3:0]; end
        3'b001: begin an = 8'b11111101; num = data[7:4]; end
        3'b010: begin an = 8'b11111011; num = data[11:8]; end
        3'b011: begin an = 8'b11110111; num = data[15:12]; end
        3'b100: begin an = 8'b11101111; num = data[19:16]; end
        3'b101: begin an = 8'b11011111; num = data[23:20]; end
        3'b110: begin an = 8'b10111111; num = data[27:24]; end
        3'b111: begin an = 8'b01111111; num = data[31:28]; end
    endcase

    case(num)
        4'h0: seg = 8'b11000000;
        4'h1: seg = 8'b11111001;
        4'h2: seg = 8'b10100100;
        4'h3: seg = 8'b10110000;
        4'h4: seg = 8'b10011001;
        4'h5: seg = 8'b10010010;
        4'h6: seg = 8'b10000010;
        4'h7: seg = 8'b11111000;
        4'h8: seg = 8'b10000000;
        4'h9: seg = 8'b10010000;
        4'ha: seg = 8'b10001000;
        4'hb: seg = 8'b10000011;
        4'hc: seg = 8'b11000110;
        4'hd: seg = 8'b10100001;
        4'he: seg = 8'b10000110;
        4'hf: seg = 8'b10001110;
    endcase
end

