    output reg [7:0] pm_addr
);

    reg [7:0] pc;

    always @(posedge clk) begin
        pc <= pm_addr;
    end

    always @(*) begin
        if (sync_reset)
            pm_addr = 8'b0;
        else if (jmp)
            pm_addr = {jmp_addr, 4'b0000};
        else if (jmp_nz)
            pm_addr = dont_jmp ? (pc + 8'd1) : {jmp_addr, 4'b0000};
        else
            pm_addr = pc + 8'd1;
    end

endmodule

