module control_unit(
    input [2:0] opCode,
    output reg regDst,
    output reg aluSrc,
    output reg memtoReg,
    output reg regWrite,
    output reg memRead,
    output reg memWrite,
    output reg branch,
    output reg [1:0] aluOp
);

    always @(*) begin
        case (opCode)
            3'b000: begin // Load instruction
                regDst = 0;
                aluSrc = 1;
                memtoReg = 0;
                regWrite = 1;
                memRead = 1;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00;
            end
            3'b001: begin // Store instruction
                regDst = 0; // Don't care
                aluSrc = 1;
                memtoReg = 0; // Don't care
                regWrite = 0;
                memRead = 0;
                memWrite = 1;
                branch = 0;
                aluOp = 2'b00;
            end
            3'b010: begin // R-type instruction
                regDst = 1;
                aluSrc = 0;
                memtoReg = 0;
                regWrite = 1;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b10;
            end
            3'b011: begin // Branch instruction
                regDst = 0; // Don't care
                aluSrc = 0;
                memtoReg = 0; // Don't care
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 1;
                aluOp = 2'b01;
            end
            3'b100: begin // Jump instruction
                regDst = 0; // Don't care
                aluSrc = 0; // Don't care
                memtoReg = 0; // Don't care
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00; // Don't care
            end
            default: begin
                regDst = 0;
                aluSrc = 0;
                memtoReg = 0;
                regWrite = 0;
                memRead = 0;
                memWrite = 0;
                branch = 0;
                aluOp = 2'b00;
            end
        endcase
    end

endmodule

