module ALUctl(
    input wire clk,
    input wire [15:0] Inmediate,
    input wire [4:0] Itp,
    output reg [3:0] Operation
);

    // ALU Operations
    localparam [3:0] NOTA  = 4'b0000,
                     NOTB  = 4'b0001,
                     AND   = 4'b0010,
                     OR    = 4'b0011,
                     XOR   = 4'b0100,
                     NAND  = 4'b0101,
                     NOR   = 4'b0110,
                     XNOR  = 4'b0111,
                     ADDPP = 4'b1000,
                     ADDPN = 4'b1001,
                     ADDNP = 4'b1010,
                     ADDNN = 4'b1011;

    // Function Codes
    localparam [7:0] add   = 8'b00100000,
                     addU  = 8'b00100001,
                     sub   = 8'b00100010,
                     subU  = 8'b00100011,
                     andf  = 8'b00100100,
                     orf   = 8'b00100101,
                     xorf  = 8'b00100110,
                     norf  = 8'b00100111;

    wire [5:0] Funct;
    assign Funct = Inmediate[5:0];

    always @(posedge clk) begin
        case (Itp)
            5'b00000: // R-type instructions
                case (Funct)
                    add:  Operation <= ADDPP;
                    addU: Operation <= ADDPP;
                    sub:  Operation <= ADDPN;
                    subU: Operation <= ADDPN;
                    andf: Operation <= AND;
                    orf:  Operation <= OR;
                    xorf: Operation <= XOR;
                    norf: Operation <= NOR;
                    default: Operation <= 4'b0000;
                endcase
            5'b00100: // ADDI
                Operation <= ADDPP;
            5'b00101: // ADDIU
                Operation <= ADDPP;
            5'b00110: // ANDI
                Operation <= AND;
            5'b00111: // ORI
                Operation <= OR;
            5'b01000: // XORI
                Operation <= XOR;
            default:
                Operation <= 4'b0000;
        endcase
    end

endmodule

