module check_iloveyou0(
    input wire clk,
    input wire rst_n,
    input wire [7:0] cap_flow,
    input wire [7:0] low_flow,
    output reg [7:0] out_flow
);

    // State encoding
    localparam S0 = 4'd0, S1 = 4'd1, S2 = 4'd2, S3 = 4'd3, S4 = 4'd4,
               S5 = 4'd5, S6 = 4'd6, S7 = 4'd7, S8 = 4'd8, S9 = 4'd9,
               S10 = 4'd10, S11 = 4'd11;

    reg [3:0] CS, NS;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            CS <= S0;
            out_flow <= 8'h00;
        end else begin
            CS <= NS;
            case (CS)
                S0: begin
                    NS = S1;
                    out_flow <= 8'h00;
                end
                S1: begin
                    if (cap_flow == 8'h49) begin // 'I'
                        NS = S2;
                        out_flow <= cap_flow;
                    end else begin
                        NS = S1;
                    end
                end
                S2: begin
                    NS = S3;
                    out_flow <= 8'h20; // Space
                end
                S3: begin
                    if (cap_flow == 8'h4C) begin // 'L'
                        NS = S4;
                        out_flow <= cap_flow;
                    end else begin
                        NS = S3;
                    end
                end
                S4: begin
                    if (low_flow == 8'h6F) begin // 'o'
                        NS = S5;
                        out_flow <= low_flow;
                    end else begin
                        NS = S4;
                    end
                end
                S5: begin
                    if (low_flow == 8'h76) begin // 'v'
                        NS = S6;
                        out_flow <= low_flow;
                    end else begin
                        NS = S5;
                    end
                end
                S6: begin
                    if (low_flow == 8'h65) begin // 'e'
                        NS = S7;
                        out_flow <= low_flow;
                    end else begin
                        NS = S6;
                    end
                end
                S7: begin
                    NS = S8;
                    out_flow <= 8'h20; // Space
                end
                S8: begin
                    if (cap_flow == 8'h59) begin // 'Y'
                        NS = S9;
                        out_flow <= cap_flow;
                    end else begin
                        NS = S8;
                    end
                end
                S9: begin
                    if (low_flow == 8'h6F) begin // 'o'
                        NS = S10;
                        out_flow <= low_flow;
                    end else begin
                        NS = S9;
                    end
                end
                S10: begin
                    if (low_flow == 8'h75) begin // 'u'
                        NS = S11;
                        out_flow <= low_flow;
                    end else begin
                        NS = S10;
                    end
                end
                S11: begin
                    NS = S0;
                    out_flow <= 8'h21; // '!'
                end
                default: begin
                    NS = S0;
                    out_flow <= 8'h00;
                end
            endcase
        end
    end

endmodule

