module clk_gen #(
    parameter CLK_RATIO = 1
) (
    input wire clkrst_b,
    input wire i_pad_clk,
    input wire gate_en0,
    input wire gate_en1,
    input wire psel,
    input wire penable,
    input wire pwrite,
    output wire sys_clk,
    output wire per_clk,
    output wire cpu_clk,
    output wire slow_clk,
    output wire clk_en,
    output reg [31:0] prdata,
    output wire [2:0] pad_biu_clkratio
);

    reg [3:0] cnt;
    wire cnt_zero;
    reg [3:0] div_cnt;
    reg slow_clk_reg;

    // Clock ratio management
    always @(posedge i_pad_clk or negedge clkrst_b) begin
        if (!clkrst_b)
            cnt <= 4'b0;
        else if (cnt == CLK_RATIO - 1)
            cnt <= 4'b0;
        else
            cnt <= cnt + 1'b1;
    end

    assign cnt_zero = (cnt == 4'b0);
    assign sys_clk = (CLK_RATIO == 1) ? i_pad_clk : cnt_zero;

    // Clock enable generation
    generate
        if (CLK_RATIO == 1)
            assign clk_en = 1'b1;
        else if (CLK_RATIO == 2)
            assign clk_en = cnt_zero;
        else
            assign clk_en = (cnt == CLK_RATIO - 2);
    endgenerate

    // APB interface
    always @(posedge i_pad_clk or negedge clkrst_b) begin
        if (!clkrst_b)
            prdata <= 32'b0;
        else if (psel && penable && !pwrite)
            prdata <= {29'b0, CLK_RATIO[2:0]};
    end

    assign pad_biu_clkratio = CLK_RATIO[2:0];

    // Slow clock generation
    always @(posedge i_pad_clk or negedge clkrst_b) begin
        if (!clkrst_b) begin
            div_cnt <= 4'hF;
            slow_clk_reg <= 1'b0;
        end else if (div_cnt == 4'h0) begin
            div_cnt <= 4'hF;
            slow_clk_reg <= ~slow_clk_reg;
        end else begin
            div_cnt <= div_cnt - 1'b1;
        end
    end

    assign slow_clk = slow_clk_reg;

    // Output clock signals
    assign per_clk = sys_clk;
    assign cpu_clk = gate_en0 ? slow_clk :
                     gate_en1 ? 1'b0 :
                     i_pad_clk;

endmodule

module cacheline_adaptor (
    input clk,
    input reset_n,
    input [255:0] line_i,
    input [31:0] address_i,
    input read_i,
    input write_i,
    input [63:0] burst_i,
    input resp_i,
    output reg [255:0] line_o,
    output reg resp_o,
    output reg [63:0] burst_o,
    output reg [31:0] address_o,
    output reg read_o,
    output reg write_o
);

reg [2:0] count, count2;
reg [255:0] line_buffer;

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        count <= 3'b000;
        count2 <= 3'b000;
        line_o <= 256'b0;
        resp_o <= 1'b0;
        burst_o <= 64'b0;
        address_o <= 32'b0;
        read_o <= 1'b0;
        write_o <= 1'b0;
        line_buffer <= 256'b0;
    end else begin
        if (read_i) begin
            case (count)
                3'b000: begin
                    read_o <= 1'b1;
                    address_o <= address_i;
                    count <= count + 1;
                end
                3'b001, 3'b010, 3'b011, 3'b100: begin
                    if (resp_i) begin
                        line_buffer <= {burst_i, line_buffer[255:64]};
                        count <= count + 1;
                    end
                end
                3'b101: begin
                    read_o <= 1'b0;
                    line_o <= line_buffer;
                    resp_o <= 1'b1;
                    count <= count + 1;
                end
                3'b110: begin
                    resp_o <= 1'b0;
                    count <= 3'b000;
                end
            endcase
        end else if (write_i) begin
            case (count2)
                3'b000: begin
                    write_o <= 1'b1;
                    address_o <= address_i;
                    line_buffer <= line_i;
                    count2 <= count2 + 1;
                end
                3'b001, 3'b010, 3'b011, 3'b100: begin
                    burst_o <= line_buffer[63:0];
                    line_buffer <= {64'b0, line_buffer[255:64]};
                    if (resp_i) begin
                        count2 <= count2 + 1;
                    end
                end
                3'b101: begin
                    write_o <= 1'b0;
                    resp_o <= 1'b1;
                    count2 <= count2 + 1;
                end
                3'b110: begin
                    resp_o <= 1'b0;
                    count2 <= 3'b000;
                end
            endcase
        end
    end
end

endmodule

module bomb (
    input wire Clk,
    input wire Reset,
    input wire [15:0] keycode, keycode1,
    input wire [9:0] Ball_X_Pos, Ball_Y_Pos,
    input wire player_id,
    input wire [3:0] bomb_on,
    output reg [23:0] Xbomb,
    output reg [23:0] Ybomb,
    output reg [3:0] bombstart
);

    wire [5:0] Xcoord_in, Ycoord_in;
    reg [7:0] place_bomb;
    integer i;

    assign Xcoord_in = Ball_X_Pos / 40;
    assign Ycoord_in = Ball_Y_Pos / 40;

    always @(*) begin
        place_bomb = (player_id) ? 8'h44 : 8'h98;
    end

    always @(*) begin
        bombstart = 4'b0000;
        if ((keycode == place_bomb) || (keycode1 == place_bomb)) begin
            case (bomb_on)
                4'b0000: bombstart = 4'b0001;
                4'b0001: bombstart = 4'b0010;
                4'b0011: bombstart = 4'b0100;
                4'b0111: bombstart = 4'b1000;
                default: bombstart = 4'b0000;
            endcase
        end
    end

    always @(posedge Clk) begin
        for (i = 0; i < 4; i = i + 1) begin
            if (bombstart[i]) begin
                Xbomb[6*i +: 6] <= Xcoord_in;
                Ybomb[6*i +: 6] <= Ycoord_in;
            end else if (!bomb_on[i]) begin
                Xbomb[6*i +: 6] <= 6'bz;
                Ybomb[6*i +: 6] <= 6'bz;
            end
        end
    end

endmodule

module commandordata(
    input clk,
    input [15:0] data_length,
    input [31:0] data,
    input [8:0] wr_ddr,
    input [15:0] total_length,
    input data_valid,
    output reg [31:0] rx_data,
    output reg [8:0] ram_wr_ddr,
    output reg reset,
    output reg [15:0] data_o_length,
    output reg [15:0] total_o_length,
    output data_o_valid
);

    reg [63:0] command;
    reg [1:0] flag;
    reg flag_reset;

    always @(posedge clk) begin
        if (data_length == 16 || total_length == 36) begin
            if (data_valid) begin
                command <= {command[31:0], data};
                flag <= flag + 1;
                data_o_length <= 32;
                total_o_length <= 64;
            end
        end
        else begin
            rx_data <= data;
            ram_wr_ddr <= wr_ddr;
            data_o_length <= data_length;
            total_o_length <= total_length;
        end
    end

    always @(posedge clk) begin
        if (flag[1]) begin
            if (command[63:56] == 0) begin
                reset <= 1;
                flag_reset <= 1;
            end
            else begin
                reset <= 0;
                flag_reset <= 0;
            end
        end
        else begin
            reset <= 0;
            flag_reset <= 0;
        end
    end

    assign data_o_valid = flag[1];

endmodule

