module address_decoder #(
    parameter N = 32
) (
    input wire write_enable,
    input wire [N-1:0] address,
    input wire [N-1:0] data_input,
    input wire [N-1:0] ps2_read,
    input wire [N-1:0] ram_read,
    input wire [N-1:0] vram_read,
    input wire vsync,

    output reg ram_we,
    output reg vram_we,
    output reg ps2_read_ack,
    output reg vsync_read_ack,
    output reg [N-3:0] ram_address,
    output reg [N-3:0] vram_address,
    output reg [N-1:0] ram_data,
    output reg [N-1:0] vram_data,
    output reg [N-1:0] data_output
);

    always @(*) begin
        // Default values
        ram_we = 0;
        vram_we = 0;
        ps2_read_ack = 0;
        vsync_read_ack = 0;
        ram_address = 'z;
        vram_address = 'z;
        ram_data = 'z;
        vram_data = 'z;
        data_output = 'z;

        case (write_enable)
            1'b0: begin // Read operation
                if (address >= 32'h0000 && address <= 32'h3FFF) begin
                    // RAM read
                    ram_address = address[N-1:2];
                    data_output = ram_read;
                end
                else if (address >= 32'h4000 && address <= 32'h4003) begin
                    // PS/2 read
                    data_output = ps2_read;
                    ps2_read_ack = 1;
                end
                else if (address >= 32'h4004 && address <= 32'h40FF) begin
                    // VRAM read
                    vram_address = address[N-1:2] - 14'h1001;
                    data_output = vram_read;
                end
                else if (address >= 32'h4100 && address <= 32'h4103) begin
                    // Vsync read
                    data_output = {31'b0, vsync};
                    vsync_read_ack = 1;
                end
            end

            1'b1: begin // Write operation
                if (address >= 32'h0000 && address <= 32'h3FFF) begin
                    // RAM write
                    ram_we = 1;
                    ram_address = address[N-1:2];
                    ram_data = data_input;
                end
                else if (address >= 32'h4000 && address <= 32'h4003) begin
                    // PS/2 write acknowledgment
                    ps2_read_ack = 1;
                end
                else if (address >= 32'h4004 && address <= 32'h40FF) begin
                    // VRAM write
                    vram_we = 1;
                    vram_address = address[N-1:2] - 14'h1001;
                    vram_data = data_input;
                end
                else if (address >= 32'h4100 && address <= 32'h4103) begin
                    // Vsync write acknowledgment
                    vsync_read_ack = 1;
                end
            end
        endcase
    end

endmodule

module cmp(
    input [31:0] Data1,
    input [31:0] Data2,
    input [2:0] CMPOp,
    output reg CMPResult
);

reg result;

always @(Data1, Data2, CMPOp) begin
    case (CMPOp)
        3'b000: result = 1'b1;
        3'b001: result = (Data1 == Data2);
        3'b010: result = (Data1 != Data2);
        3'b011: result = (Data1[31] == 1'b1);
        3'b100: result = (Data1[31] == 1'b0);
        3'b101: result = (Data1[31] == 1'b1);
        3'b110: result = (Data1[31] == 1'b0);
        default: result = 1'b1;
    endcase
end

assign CMPResult = result;

endmodule

module fullAdder(
    input a, b, c_in,
    output sum, c_out
);
    assign sum = a ^ b ^ c_in;
    assign c_out = (a & b) | (b & c_in) | (a & c_in);
endmodule

