module ALU(
    input [31:0] word1, word2,
    input [1:0] ALUOp,
    input bitinvert,
    output [31:0] out
);
    wire [31:0] word3, out1, out2;
    wire [31:0] carry;

    // Modify word2 based on bitinvert
    assign word3 = word2 ^ {32{bitinvert}};

    // Logical operations
    assign out1 = ALUOp[0] ? (word1 | word3) : (word1 & word3);

    // Arithmetic operation (addition/subtraction)
    fullAdder FA0(word1[0], word3[0], bitinvert, out2[0], carry[0]);
    genvar i;
    generate
        for (i = 1; i < 32; i = i + 1) begin : adder_loop
            fullAdder FA(word1[i], word3[i], carry[i-1], out2[i], carry[i]);
        end
    endgenerate

    // Select final output
    mux32_2to1 MUX(out1, out2, ALUOp[1], out);
endmodule

