    // Partial initialization of memory
    initial begin
        ram[0] = 8'd0;
        ram[1] = 8'd24;
        ram[2] = 8'd7;
        ram[3] = 8'd0;
        ram[4] = 8'd0;
        ram[5] = 8'd1;
    end

    // Synchronous write operation
    always @(posedge clk) begin
        if (we) begin
            ram[addr] <= data_in;
