module ToneGenerator #(
    parameter DELAY = 735000,
    parameter ADDR_MAX = 610
)(
    input wire clk,
    input wire rst,
    input wire [6:0] note,
    input wire [6:0] tone_original,
    output reg [9:0] addr,
    output reg [6:0] tone
);

reg addr_add;
reg [31:0] count;

// Counter and Address Increment Control
always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 32'd0;
        addr_add <= 1'b0;
    end else begin
        if (count >= (note + 1) * DELAY - 1) begin
            count <= 32'd0;
            addr_add <= 1'b1;
        end else begin
            count <= count + 1;
            addr_add <= 1'b0;
        end
    end
end

// Address Generation
always @(posedge clk or posedge rst) begin
    if (rst) begin
        addr <= 10'd0;
    end else if (addr_add) begin
        if (addr >= ADDR_MAX) begin
            addr <= 10'd0;
        end else begin
            addr <= addr + 1;
        end
    end
end

// Tone Output
always @(posedge clk or posedge rst) begin
    if (rst) begin
        tone <= 7'd0;
    end else begin
        tone <= tone_original;
    end
end

endmodule

