module clockSwitch (
    input wire clk,
    input wire reset,
    input wire switchClock,
    output reg clk1,
    output reg clk2,
    output reg clk3
);

    reg [3:0] count;

    always @(posedge clk or posedge reset or posedge switchClock) begin
        if (reset) begin
            count <= 4'b0000;
        end else if (switchClock) begin
            if (count == 4'b0011) begin
                count <= 4'b0000;
            end else begin
                count <= count + 1;
            end
        end
    end

    always @(posedge clk) begin
        case (count)
            4'b0000: begin
                clk1 <= clk;
                clk2 <= 1'b0;
                clk3 <= 1'b0;
            end
            4'b0001: begin
                clk1 <= 1'b0;
                clk2 <= clk;
                clk3 <= 1'b0;
            end
            4'b0010: begin
                clk1 <= 1'b0;
                clk2 <= 1'b0;
                clk3 <= clk;
            end
            default: begin
                clk1 <= 1'b0;
                clk2 <= 1'b0;
                clk3 <= 1'b0;
            end
        endcase
    end

endmodule

