    output reg [3:0] bcd,
    output reg [7:0] anodos
);

    reg [2:0] contador;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            contador <= 3'b000;
        end else begin
            contador <= contador + 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bcd <= 4'b0000;
            anodos <= 8'b11111111;
        end else begin
            case (contador)
                3'b000: begin
                    bcd <= d1;
                    anodos <= usados[0] ? ~8'b00000001 : 8'b11111111;
                end
                3'b001: begin
                    bcd <= d2;
                    anodos <= usados[1] ? ~8'b00000010 : 8'b11111111;
                end
                3'b010: begin
                    bcd <= d3;
                    anodos <= usados[2] ? ~8'b00000100 : 8'b11111111;
                end
                3'b011: begin
                    bcd <= d4;
                    anodos <= usados[3] ? ~8'b00001000 : 8'b11111111;
                end
                3'b100: begin
                    bcd <= d5;
                    anodos <= usados[4] ? ~8'b00010000 : 8'b11111111;
                end
                3'b101: begin
                    bcd <= d6;
                    anodos <= usados[5] ? ~8'b00100000 : 8'b11111111;
                end
                3'b110: begin
                    bcd <= d7;
                    anodos <= usados[6] ? ~8'b01000000 : 8'b11111111;
                end
                3'b111: begin
                    bcd <= d8;
                    anodos <= usados[7] ? ~8'b10000000 : 8'b11111111;
                end
            endcase
        end
    end

endmodule

