        tIstrFlag = 4'b0000;

        casez (istrWord[6:2])
            5'b0_0000: tIstrFlag = 4'b0001;
            5'b0_0100: tIstrFlag = 4'b0010;
            5'b0_1000: tIstrFlag = 4'b0011;
            5'b0_1100: tIstrFlag = 4'b0100;
            5'b1_1000: tIstrFlag = 4'b0101;
            5'b1_1001: tIstrFlag = 4'b0110;
            5'b1_1011: tIstrFlag = 4'b0111;
            5'b01_100: begin
                if (istrWord[29:25] == 5'b00000)
                    tIstrFlag = 4'b1000;
                else
                    tIstrFlag = 4'b1001;
            end
            5'b01_110: begin
                if (istrWord[29:25] == 5'b00000)
                    tIstrFlag = 4'b1010;
                else
                    tIstrFlag = 4'b1011;
            end
            default: tIstrFlag = 4'b0000;
        endcase

        if (istrWord[1:0] != 2'b11)
            tIstrFlag = 4'b0000;

        istrFlag = tIstrFlag;
    end

