module Counter #(
    parameter Divisor = 25000000,
    parameter Bits = 4
) (
    input ClkIn,
    input Rst,
    output [6:0] Seg,
    output [3:0] Anode
);

reg [Bits-1:0] counter;
reg clk_en;
reg [Bits-1:0] CountTemp;

always @(posedge ClkIn or posedge Rst) begin
    if (Rst) begin
        counter <= 0;
        clk_en <= 0;
    end
    else begin
        if (counter == Divisor-1) begin
            counter <= 0;
            clk_en <= 1;
        end
        else begin
            counter <= counter + 1;
            clk_en <= 0;
        end
    end
end

always @(posedge ClkIn or posedge Rst) begin
    if (Rst)
        CountTemp <= 0;
    else if (clk_en)
        CountTemp <= CountTemp + 1;
end

assign Seg = (CountTemp == 0) ? 7'b1000000 :
             (CountTemp == 1) ? 7'b1111001 :
             (CountTemp == 2) ? 7'b0100100 :
             (CountTemp == 3) ? 7'b0110000 :
             (CountTemp == 4) ? 7'b0011001 :
             (CountTemp == 5) ? 7'b0010010 :
             (CountTemp == 6) ? 7'b0000010 :
             (CountTemp == 7) ? 7'b1111000 :
             (CountTemp == 8) ? 7'b0000000 :
             (CountTemp == 9) ? 7'b0010000 : 7'b1000000;

assign Anode = 4'b1110;

endmodule

