module fifo #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 4,
    parameter RAM_DEPTH = 1 << ADDR_WIDTH
) (
    input wire clock,
    input wire reset,
    input wire wn,
    input wire rn,
    input wire [DATA_WIDTH-1:0] DATAIN,
    output reg [DATA_WIDTH-1:0] DATAOUT,
    output wire full,
    output wire empty
);

    reg [DATA_WIDTH-1:0] memory [0:RAM_DEPTH-1];
    reg [ADDR_WIDTH-1:0] wptr, rptr;
    reg [ADDR_WIDTH:0] count;

    assign full = &count;
    assign empty = ~|count;

    always @(posedge clock or negedge reset) begin
        if (!reset) begin
            wptr <= 0;
            rptr <= 0;
            count <= 0;
            DATAOUT <= 0;
        end else begin
            if (wn && !full) begin
                memory[wptr] <= DATAIN;
                wptr <= wptr + 1;
            end

            if (rn && !empty) begin
                rptr <= rptr + 1;
            end

            if (wn && !rn && !full)
                count <= count + 1;
            else if (!wn && rn && !empty)
                count <= count - 1;

            DATAOUT <= memory[rptr];
        end
    end

endmodule

