module cachetest (
    input wire clk,
    input wire rst,
    input wire ready_in,
    output reg valid_out
);

    reg [7:0] holdoff_counter;
    reg [3:0] distance_counter;
    reg [4:0] gen_state;
    reg possibly_valid;
    wire gen_step;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            holdoff_counter <= 8'd80;
            distance_counter <= 4'd0;
            gen_state <= 5'd0;
            valid_out <= 1'b0;
            possibly_valid <= 1'b0;
        end else begin
            if (holdoff_counter != 8'd0) begin
                holdoff_counter <= holdoff_counter - 8'd1;
            end

            if (ready_in) begin
                if (distance_counter == 4'd1) begin
                    distance_counter <= 4'd0;
                    possibly_valid <= 1'b1;
                end else begin
                    distance_counter <= distance_counter + 4'd1;
                    possibly_valid <= 1'b0;
                end
            end

            if (gen_step) begin
                case (gen_state)
                    5'd0: begin
                        gen_state <= 5'd1;
                        valid_out <= 1'b0;
                    end
                    5'd1: begin
                        gen_state <= 5'd2;
                        valid_out <= possibly_valid;
                    end
                    5'd2: begin
                        gen_state <= 5'd3;
                        valid_out <= 1'b0;
                    end
                    5'd3: begin
                        gen_state <= 5'd0;
                        valid_out <= 1'b0;
                    end
                    default: gen_state <= 5'd0;
                endcase
            end
        end
    end

    assign gen_step = ready_in && (distance_counter == 4'd1) && (holdoff_counter == 8'd0);

endmodule

module SevenHexDecoder (
    input [3:0] i_hex,
    output reg [6:0] o_seven_ten,
    output reg [6:0] o_seven_one
);

    // Seven-segment display patterns for digits 0-9
    parameter D0 = 7'b1000000;
    parameter D1 = 7'b1111001;
    parameter D2 = 7'b0100100;
    parameter D3 = 7'b0110000;
    parameter D4 = 7'b0011001;
    parameter D5 = 7'b0010010;
    parameter D6 = 7'b0000010;
    parameter D7 = 7'b1111000;
    parameter D8 = 7'b0000000;
    parameter D9 = 7'b0010000;

    always @* begin
        case(i_hex)
            4'h0: begin o_seven_ten = D0; o_seven_one = D0; end
            4'h1: begin o_seven_ten = D0; o_seven_one = D1; end
            4'h2: begin o_seven_ten = D0; o_seven_one = D2; end
            4'h3: begin o_seven_ten = D0; o_seven_one = D3; end
            4'h4: begin o_seven_ten = D0; o_seven_one = D4; end
            4'h5: begin o_seven_ten = D0; o_seven_one = D5; end
            4'h6: begin o_seven_ten = D0; o_seven_one = D6; end
            4'h7: begin o_seven_ten = D0; o_seven_one = D7; end
            4'h8: begin o_seven_ten = D0; o_seven_one = D8; end
            4'h9: begin o_seven_ten = D0; o_seven_one = D9; end
            4'ha: begin o_seven_ten = D1; o_seven_one = D0; end
            4'hb: begin o_seven_ten = D1; o_seven_one = D1; end
            4'hc: begin o_seven_ten = D1; o_seven_one = D2; end
            4'hd: begin o_seven_ten = D1; o_seven_one = D3; end
            4'he: begin o_seven_ten = D1; o_seven_one = D4; end
            4'hf: begin o_seven_ten = D1; o_seven_one = D5; end
            default: begin o_seven_ten = 7'b1111111; o_seven_one = 7'b1111111; end
        endcase
    end

endmodule

