module Val2_Generator(
    input [11:0] Shift_operand,
    input [31:0] Rm_Val,
    input imm,
    input MEM_EN,
    output reg [31:0] Val2
);

reg [31:0] rotation_temp;
reg [31:0] rotated;
reg [31:0] Rm_rotation_temp;
reg [31:0] Rm_rotated;

always @(*) begin
    if (MEM_EN) begin
        Val2 = {{20{Shift_operand[11]}}, Shift_operand};
    end
    else if (imm) begin
        rotation_temp = {Shift_operand[7:0], Shift_operand[7:0]};
        rotated = (Shift_operand[7:0] == 0) ? Shift_operand : (rotation_temp >> Shift_operand[7:0]);
        Val2 = rotated;
    end
    else begin
        case (Shift_operand[1:0])
            2'b00: Val2 = Rm_Val << Shift_operand[4:0];
            2'b01: Val2 = Rm_Val >> Shift_operand[4:0];
            2'b10: Val2 = $signed(Rm_Val) >>> Shift_operand[4:0];
            2'b11: begin
                Rm_rotation_temp = {Rm_Val, Rm_Val};
                Rm_rotated = (Shift_operand[4:0] == 0) ? Rm_Val : (Rm_rotation_temp >> Shift_operand[4:0]);
                Val2 = Rm_rotated;
            end
            default: Val2 = 32'bX;
        endcase
    end
end

endmodule

module Speed (
    input en,
    input rst,
    input clk,
    input reed,
    input [7:0] circ,
    input start,
    output reg Busy,
    output reg Ready,
    output reg [6:0] speed,
    output reg valid,
    output reg [25:0] dividend,
    output reg [25:0] divisor,
    input [15:0] dividerres
);

    reg [15:0] cnt;
    reg [15:0] tim;
    reg [2:0] waiting;
    reg [23:0] cico;

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 16'h0;
            tim <= 16'h0;
            waiting <= 3'h0;
            cico <= 24'h0;
            speed <= 7'h0;
            valid <= 1'b0;
            Busy <= 1'b0;
            Ready <= 1'b0;
            dividend <= 26'h0;
            divisor <= 26'h0;
        end else if (en) begin
            if (reed) begin
                cnt <= 16'h0;
            end else begin
                cnt <= cnt + 16'h1;
            end
            tim <= cnt;
            if (start) begin
                case (waiting)
                    3'h0: waiting <= 3'h1;
                    3'h1: begin
                        if (!Busy) begin
                            cico <= {8'h0, circ} * 24'h186a0;
                            dividend <= cico;
                            divisor <= {10'h0, tim};
                            Busy <= 1'b1;
                            waiting <= 3'h2;
                        end
                    end
                    3'h2: begin
                        if (Busy) begin
                            waiting <= 3'h3;
                        end
                    end
                    3'h3: begin
                        if (Busy) begin
                            waiting <= 3'h4;
                        end
                    end
                    3'h4: begin
                        if (Ready) begin
                            speed <= (dividerres > 7'd99) ? 7'd99 : dividerres[6:0];
                            valid <= 1'b1;
                            Busy <= 1'b0;
                            Ready <= 1'b0;
                            waiting <= 3'h0;
                            if (cnt > 16'h3e80) begin
                                speed <= 7'h0;
                            end
                        end
                    end
                endcase
            end else begin
                valid <= 1'b0;
            end
        end
    end

endmodule

module FSM_Tx(
    input tx_start,
    input clk,
    input reset,
    output reg load,
    output reg shift,
    output reg [1:0] mux_sel
);

reg [2:0] p_s, n_s; // present state, next state
reg [2:0] count;

localparam IDLE = 3'b000;
localparam START = 3'b001;
localparam DATA = 3'b010;
localparam PARITY = 3'b011;
localparam STOP = 3'b100;

always @(posedge clk or negedge reset) begin
    if (!reset)
        p_s <= IDLE;
    else
        p_s <= n_s;
end

always @(*) begin
    case (p_s)
        IDLE: begin
            load = 0;
            shift = 0;
            mux_sel = 2'b11;
            if (tx_start)
                n_s = START;
            else
                n_s = IDLE;
        end
        START: begin
            load = 1;
            shift = 0;
            mux_sel = 2'b00;
            n_s = DATA;
        end
        DATA: begin
            load = 0;
            shift = 1;
            mux_sel = 2'b01;
            if (count == 3'd7)
                n_s = PARITY;
            else
                n_s = DATA;
        end
        PARITY: begin
            load = 0;
            shift = 0;
            mux_sel = 2'b10;
            n_s = STOP;
        end
        STOP: begin
            load = 0;
            shift = 0;
            mux_sel = 2'b11;
            if (tx_start)
                n_s = START;
            else
                n_s = IDLE;
        end
        default:
            n_s = IDLE;
    endcase
end

always @(posedge clk or negedge reset) begin
    if (!reset)
        count <= 0;
    else if (p_s == DATA)
        count <= count + 1;
    else
        count <= 0;
end

endmodule

