module pipeline #(
    parameter SYMBOLS_PER_BEAT = 4,
    parameter BITS_PER_SYMBOL = 8,
    parameter REGISTERED = 1
) (
    input wire clk,
    input wire reset,
    input wire in_ready,
    input wire in_valid,
    input wire [SYMBOLS_PER_BEAT*BITS_PER_SYMBOL-1:0] in_data,
    output wire out_ready,
    output reg out_valid,
    output reg [SYMBOLS_PER_BEAT*BITS_PER_SYMBOL-1:0] out_data
);

    localparam DATA_WIDTH = SYMBOLS_PER_BEAT * BITS_PER_SYMBOL;

    reg [DATA_WIDTH-1:0] stage1_data;
    reg stage1_valid;
    reg [DATA_WIDTH-1:0] stage2_data;
    reg stage2_valid;

    wire stage1_ready;
    wire stage2_ready;

    assign out_ready = !stage2_valid || stage2_ready;
    assign stage2_ready = out_ready;
    assign stage1_ready = !stage2_valid || stage2_ready;
    assign in_ready = !stage1_valid || stage1_ready;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            stage1_valid <= 1'b0;
            stage2_valid <= 1'b0;
            out_valid <= 1'b0;
        end else begin
            if (stage1_ready) begin
                stage1_valid <= in_valid;
            end

            if (stage2_ready) begin
                stage2_valid <= stage1_valid;
            end

            out_valid <= stage2_valid;
        end
    end

    generate
        if (REGISTERED) begin
            always @(posedge clk) begin
                if (in_ready && in_valid) begin
                    stage1_data <= in_data;
                end

                if (stage1_ready && stage1_valid) begin
                    stage2_data <= stage1_data;
                end

                if (stage2_ready && stage2_valid) begin
                    out_data <= stage2_data;
                end
            end
        end else begin
            always @(*) begin
                stage1_data = in_data;
                stage2_data = stage1_data;
                out_data = stage2_data;
            end
        end
    endgenerate

endmodule

