module CSA(
    input wire A,
    input wire B,
    input wire Sin,
    input wire Cin,
    output wire Sout,
    output wire Cout
);

    wire combine;

    assign combine = A & B;
    assign Sout = combine ^ Sin ^ Cin;
    assign Cout = (combine & Sin) | (Cin & (combine ^ Sin));

