module csr_unit (
    input wire CLK,
    input wire RST,
    input wire INT_TAKEN,
    input wire [11:0] ADDR,
    input wire [31:0] PC,
    input wire [31:0] WD,
    input wire WR_EN,
    output reg [31:0] RD,
    output reg [31:0] CSR_MEPC,
    output reg [31:0] CSR_MTVEC,
    output reg CSR_MIE
);

    // CSR addresses
    typedef enum logic [11:0] {
        MIE   = 12'h304,
        MTVEC = 12'h305,
        MEPC  = 12'h341
    } csr_t;

    // Reset and write logic
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            CSR_MTVEC <= 32'b0;
            CSR_MEPC <= 32'b0;
            CSR_MIE <= 1'b0;
        end else if (WR_EN) begin
            case (ADDR)
                MTVEC: CSR_MTVEC <= WD;
                MEPC:  CSR_MEPC <= WD;
                MIE:   CSR_MIE <= WD[0];
            endcase
        end else if (INT_TAKEN) begin
            CSR_MEPC <= PC;
            CSR_MIE <= 1'b0;
        end
    end

    // Read logic
    always @(*) begin
        case (ADDR)
            MTVEC: RD = CSR_MTVEC;
            MEPC:  RD = CSR_MEPC;
            MIE:   RD = {31'b0, CSR_MIE};
            default: RD = 32'b0;
        endcase
    end

endmodule

module voltage_gen #(
    parameter ADC_WIDTH = 12
)(
    input wire clk,
    input wire n_rst,
    input wire inc_tv,
    input wire dec_tv,
    output reg [ADC_WIDTH-1:0] target_v
);

    localparam STEP_SIZE = 64;
    localparam INITIAL_VALUE = 2048;

    always @(posedge clk or negedge n_rst) begin
        if (!n_rst) begin
            target_v <= INITIAL_VALUE;
        end else begin
            if (inc_tv) begin
                target_v <= target_v + STEP_SIZE;
            end else if (dec_tv) begin
                target_v <= target_v - STEP_SIZE;
            end
        end
    end

endmodule

module top;

