  assign arr2[0][1] = arr1[0][1];                  // Direct element addressing
  assign {arr2[0][3], arr2[0][2]} = {arr1[0][2], arr1[0][3]};  // Range addressing
  assign {arr2[1][1], arr2[1][0]} = {arr1[1][0], arr1[1][1]}; // Positive indexing
  assign {arr2[1][3], arr2[1][2]} = {arr1[1][2], arr1[1][3]}; // Negative indexing

