module int16_float32_altpriority_encoder_6e8 (
    input [3:0] data,
    output reg [1:0] q,
    output reg zero
);

always @(*) begin
    if (data == 4'b0000) begin
        q = 2'b00;
        zero = 1'b1;
    end else if (data[0]) begin
        q = 2'b00;
        zero = 1'b0;
    end else if (data[1]) begin
        q = 2'b01;
        zero = 1'b0;
    end else if (data[2]) begin
        q = 2'b10;
        zero = 1'b0;
    end else begin // data[3] must be 1
        q = 2'b11;
        zero = 1'b0;
    end
end

endmodule

