module bram_sm (
    input wire CLK,
    input wire RST_L,
    input wire re,
    output reg ram_dvalid
);

    reg [1:0] current_state, next_state;

    parameter IDLE = 2'b00;
    parameter WAIT = 2'b01;
    parameter DVALID = 2'b10;
    parameter DVALID_PIPELINE = 2'b11;

    always @(*) begin
        case (current_state)
            IDLE: next_state = re ? WAIT : IDLE;
            WAIT: next_state = re ? DVALID_PIPELINE : DVALID;
            DVALID: next_state = re ? WAIT : DVALID;
            DVALID_PIPELINE: next_state = re ? DVALID_PIPELINE : DVALID;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge CLK or negedge RST_L) begin
        if (!RST_L) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        ram_dvalid = (current_state == DVALID) || (current_state == DVALID_PIPELINE);
    end

endmodule

