module qmem_monitor #(
    parameter QAW = 10,
    parameter QDW = 32,
    parameter QSW = 4,
    parameter MODULE_NAME = "qmem_monitor",
    parameter LOG_FILE = "qmem_monitor.log",
    parameter DEBUG = 0
) (
    input clk,
    input rst,
    input cs,
    input we,
    input [QSW-1:0] sel,
    input [QAW-1:0] adr,
    input [QDW-1:0] dat_w,
    output [QDW-1:0] dat_r,
    input ack,
    input err,
    output error
);

    reg [QAW-1:0] adr_r, adr_wr, adr_rd;
    reg [QDW-1:0] dat_w_r, dat_r_r;
    reg [QSW-1:0] sel_r;
    reg we_r;
    reg ack_r, err_r;
    reg trn, trn_r;
    reg log;
    reg [63:0] write_count, read_count;
    integer log_file;

    assign dat_r = dat_r_r;
    assign error = err_r;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            adr_r <= 0;
            dat_w_r <= 0;
            sel_r <= 0;
            we_r <= 0;
            ack_r <= 0;
            err_r <= 0;
            trn <= 0;
            trn_r <= 0;
            log <= 0;
            write_count <= 0;
            read_count <= 0;
        end else begin
            adr_r <= adr;
            dat_w_r <= dat_w;
            sel_r <= sel;
            we_r <= we;
            ack_r <= ack;
            err_r <= err;
            trn <= cs & (ack | err);
            trn_r <= trn;
            if (trn && we && log) begin
                adr_wr <= adr_r;
                dat_r_r <= dat_r;
                write_count <= write_count + 1;
            end
            if (trn_r && !we_r && log) begin
                adr_rd <= adr_r;
                dat_r_r <= dat_r;
                read_count <= read_count + 1;
            end
        end
    end

    task start;
        begin
            write_count = 0;
            read_count = 0;
            log_file = $fopen(LOG_FILE, "w");
            log = 1;
        end
    endtask

    task stop;
        begin
            log = 0;
            $fdisplay(log_file, "Total Write Transactions: %d", write_count);
            $fdisplay(log_file, "Total Read Transactions: %d", read_count);
            $fclose(log_file);
        end
    endtask

endmodule

