module FindMaxMin (
    input [31:0] R_temp,
    input [31:0] G_temp,
    input [31:0] B_temp,
    output reg [31:0] Cmax,
    output reg [31:0] Cmin
);

always @(*) begin
    // Initialize Cmax and Cmin with R_temp
    Cmax = R_temp;
    Cmin = R_temp;

    // Compare G_temp with current Cmax and update if necessary
    if (G_temp > Cmax) begin
        Cmax = G_temp;
    end

    // Compare B_temp with current Cmax and update if necessary
    if (B_temp > Cmax) begin
        Cmax = B_temp;
    end

    // Compare G_temp with current Cmin and update if necessary
    if (G_temp < Cmin) begin
        Cmin = G_temp;
    end

    // Compare B_temp with current Cmin and update if necessary
    if (B_temp < Cmin) begin
        Cmin = B_temp;
    end
end

endmodule

module dc_offset_removal #(
    parameter ALPHA_SHIFT = 8,
    parameter DATA_WIDTH = 14,
    parameter ADDR_WIDTH = 4
) (
    input wire clk,
    input wire rst,
    input wire set_stb,
    input wire [ADDR_WIDTH-1:0] set_addr,
    input wire [DATA_WIDTH-1:0] set_data,
    input wire signed [DATA_WIDTH-1:0] in,
    output reg signed [DATA_WIDTH-1:0] out
);

    // Register file
    reg [DATA_WIDTH-1:0] reg_file [0:(1<<ADDR_WIDTH)-1];

    // Internal signals
    reg signed [DATA_WIDTH-1:0] y_prev;
    wire signed [DATA_WIDTH-1:0] alpha_x;
    wire signed [DATA_WIDTH-1:0] one_minus_alpha_y;

    // Calculate alpha * x(n)
    assign alpha_x = in >>> ALPHA_SHIFT;

    // Calculate (1 - alpha) * y(n-1)
    assign one_minus_alpha_y = y_prev - (y_prev >>> ALPHA_SHIFT);

    // Declare the 'integer' variable outside the always block
    integer i;

    // Main processing logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out <= 0;
            y_prev <= 0;
            for (i = 0; i < (1<<ADDR_WIDTH); i = i + 1) begin
                reg_file[i] <= 0;
            end
        end else begin
            // Update output and previous value
            out <= alpha_x + one_minus_alpha_y;
            y_prev <= out;

            // Handle register file writes
            if (set_stb) begin
                reg_file[set_addr] <= set_data;
            end
        end
    end

endmodule

module Timer #(
    parameter realmaxcount = 50000000
)(
    input clr,
    input strtcntr,
    input Loop,
    input inc,
    input dec,
    input clk,
    input reset,
    output reg [64:0] count,
    output yes,
    output LED4,
    output LED5
);

reg [64:0] maxcount;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
        maxcount <= realmaxcount;
    end
    else if (clr) begin
        count <= 0;
        maxcount <= realmaxcount;
    end
    else if (strtcntr) begin
        count <= 0;
    end
    else if (Loop) begin
        if (inc) begin
            count <= count + 1;
        end
        else if (dec) begin
            count <= count - 1;
        end
        else begin
            count <= count + 1;
        end
    end
    else begin
        count <= count + 1;
        if (count >= maxcount) begin
            count <= 0;
            maxcount <= realmaxcount;
        end
    end
end

assign yes = (count == maxcount - 1);
assign LED4 = (count >= 2000000);
assign LED5 = (count <= 25000000);

endmodule

