module bin_to_bcd_4bit(
    input [3:0] bin,
    output [7:0] bcd
);

    wire nb3, nb2, nb1;

    assign nb3 = ~bin[3];
    assign nb2 = ~bin[2];
    assign nb1 = ~bin[1];

    assign bcd[7:5] = 3'b000;

    assign bcd[4] = bin[3] & (bin[2] | bin[1]);
    assign bcd[3] = (nb3 & bin[2]) | (bin[3] & nb2 & bin[1]);
    assign bcd[2] = (nb3 & nb2 & bin[1]) | (nb3 & bin[2] & nb1) | (bin[3] & nb2 & nb1);
    assign bcd[1] = (nb3 & nb2 & bin[1]) | (nb3 & bin[2] & nb1) | (bin[3] & nb2 & bin[1]) | (bin[3] & bin[2] & nb1);
    assign bcd[0] = bin[0];

endmodule

module irigb_clk_gen #(
    parameter CLKFREQ = 100_000_000 // Input clock frequency in Hz (default 100 MHz)
)(
    input  wire rst,
    input  wire clk,
    output wire clk_10KHz_out,
    output wire clk_1KHz_out
);

    localparam HALF_10KHZ = CLKFREQ / (2 * 10_000);
    localparam DIVIDER_10 = CLKFREQ / (2 * 1_000);

    reg clk_10KHz;
    reg clk_1KHz;
    reg [31:0] cnt_10KHz;
    reg [31:0] cnt_div;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt_10KHz <= 0;
            cnt_div <= 0;
            clk_10KHz <= 0;
            clk_1KHz <= 0;
        end
        else begin
            // 10 kHz clock generation
            if (cnt_10KHz == HALF_10KHZ - 1) begin
                clk_10KHz <= ~clk_10KHz;
                cnt_10KHz <= 0;
            end
            else begin
                cnt_10KHz <= cnt_10KHz + 1;
            end

            // 1 kHz clock generation
            if (cnt_div == DIVIDER_10 - 1) begin
                clk_1KHz <= ~clk_1KHz;
                cnt_div <= 0;
            end
            else begin
                cnt_div <= cnt_div + 1;
            end
        end
    end

    assign clk_10KHz_out = clk_10KHz;
    assign clk_1KHz_out = clk_1KHz;

endmodule

