module fsm (
    input wire clk,
    input wire reset,
    input wire a,
    input wire b,
    output reg y0,
    output reg y1
);

    // State encoding
    localparam [1:0] s0 = 2'b00,
                     s1 = 2'b01,
                     s2 = 2'b11;

    // State register
    reg [1:0] state_reg, state_next;

    // State register update
    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= s0;
        else
            state_reg <= state_next;
    end

    // Next state logic
    always @(*) begin
        case (state_reg)
            s0: begin
                if (a && b)
                    state_next = s2;
                else if (a && !b)
                    state_next = s1;
                else
                    state_next = s0;
            end
            s1: begin
                if (a)
                    state_next = s0;
                else
                    state_next = s1;
            end
            s2: state_next = s0;
            default: state_next = s0;
        endcase
    end

    // Output logic
    always @(*) begin
        y1 = (state_reg == s0) || (state_reg == s1);
        y0 = (state_reg == s0) && a && b;
    end

endmodule

