module ALU (
    input [31:0] reg1data,
    input [31:0] ALU2,
    input [3:0] ALUfunc,
    input [4:0] shamt,
    output reg [31:0] ALUout,
    output zero,
    output overflow
);

    always @(*) begin
        case (ALUfunc)
            4'b0010: ALUout = reg1data + ALU2;
            4'b0110: ALUout = reg1data - ALU2;
            4'b0000: ALUout = reg1data & ALU2;
            4'b0001: ALUout = reg1data | ALU2;
            4'b1001: ALUout = reg1data ^ ALU2;
            4'b1100: ALUout = ALU2 << shamt;
            4'b0111: ALUout = ($signed(reg1data) < $signed(ALU2)) ? 32'd1 : 32'd0;
            4'b1101: ALUout = ALU2 << 16;
            4'b1110: ALUout = (reg1data < ALU2) ? 32'd1 : 32'd0;
            4'b1011: begin
                ALUout = $signed(ALU2);
                for (int i = 0; i < shamt; i = i + 1) begin
                    ALUout = {ALUout[31], ALUout[31:1]};
                end
            end
            default: ALUout = 32'b0;
        endcase
    end

    assign zero = (ALUout == 32'b0);

endmodule

