module brown_out_reset #(
    parameter THRESHOLD = 3.3 // Default threshold voltage in volts
)(
    input wire clk,
    input wire rst,
    input wire [7:0] vdd, // Assuming 8-bit ADC value for VDD
    output reg sys_rst
);

    // Convert THRESHOLD to 8-bit ADC value (assuming 0-5V range)
    localparam THRESHOLD_ADC = $rtoi(THRESHOLD * 255 / 5);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sys_rst <= 1'b1;
        end else begin
            if (vdd < THRESHOLD_ADC) begin
                sys_rst <= 1'b1;
            end else begin
                sys_rst <= 1'b0;
            end
        end
    end

endmodule

module i2c_master_bmp280 (
    input FPGA_CLK1_50,
    input [1:0] KEY,
    output reg i2c_scl,
    inout i2c_sda
);

    reg [9:0] i2c_clk_count;
    reg i2c_clk;
    reg [2:0] state;
    reg [7:0] address, data;
    reg [2:0] count;
    reg sda_out;
    reg GO;

    localparam IDLE = 3'd0, START = 3'd1, ADDRESS = 3'd2, RW = 3'd3, WACK = 3'd4, DATA = 3'd5, STOP = 3'd6, WACK2 = 3'd7;

    wire reset_n = KEY[0];

    always @(posedge FPGA_CLK1_50 or negedge reset_n) begin
        if (!reset_n) begin
            i2c_clk_count <= 10'd0;
            i2c_clk <= 1'b0;
        end else begin
            if (i2c_clk_count == 10'd499) begin
                i2c_clk_count <= 10'd0;
                i2c_clk <= ~i2c_clk;
            end else begin
                i2c_clk_count <= i2c_clk_count + 1'b1;
            end
        end
    end

    always @(posedge FPGA_CLK1_50 or negedge reset_n) begin
        if (!reset_n) begin
            GO <= 1'b0;
        end else if (KEY[1] == 1'b0) begin
            GO <= 1'b1;
        end else if (state == STOP) begin
            GO <= 1'b0;
        end
    end

    always @(posedge i2c_clk or negedge reset_n) begin
        if (!reset_n) begin
            state <= IDLE;
            i2c_scl <= 1'b1;
            sda_out <= 1'b1;
            address <= 8'hEE;
            data <= 8'hD0;
            count <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    i2c_scl <= 1'b1;
                    sda_out <= 1'b1;
                    if (GO) state <= START;
                end
                START: begin
                    sda_out <= 1'b0;
                    state <= ADDRESS;
                end
                ADDRESS: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= address[7-count];
                        if (count == 3'd7) begin
                            count <= 3'd0;
                            state <= RW;
                        end else begin
                            count <= count + 1'b1;
                        end
                    end
                end
                RW: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= 1'b0;
                        state <= WACK;
                    end
                end
                WACK: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b1 && i2c_sda == 1'b0) begin
                        state <= DATA;
                    end
                end
                DATA: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= data[7-count];
                        if (count == 3'd7) begin
                            count <= 3'd0;
                            state <= WACK2;
                        end else begin
                            count <= count + 1'b1;
                        end
                    end
                end
                WACK2: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b1 && i2c_sda == 1'b0) begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    i2c_scl <= 1'b1;
                    sda_out <= 1'b0;
                    if (i2c_scl == 1'b1) begin
                        sda_out <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    assign i2c_sda = (state == WACK || state == WACK2) ? 1'bz : sda_out;

endmodule

module fibonacci_mon(
    input clk,
    input reset,
    input iSTART,
    input [3:0] iN,
    output reg oREADY,
    output reg oDONE,
    output reg [9:0] oFIB,
    output reg fout
);

reg [9:0] fib_result;

function [9:0] fib_calc;
    input [3:0] n;
    reg [9:0] f0, f1, swp;
begin
    if (n == 0) fib_calc = 0;
    else if (n == 1) fib_calc = 1;
    else begin
        f0 = 0; f1 = 1;
        for (int i = 2; i <= n; i++) begin
            swp = f1;
            f1 = f0 + f1;
            f0 = swp;
        end
        fib_calc = f1;
    end
end
endfunction

initial begin
    #10000 $finish; // Watchdog timer
end

always @(posedge clk) begin
    if (reset) begin
        oREADY <= 1'b1;
        oDONE <= 1'b0;
        oFIB <= 0;
        fout <= 0;
    end
    else if (oREADY && iSTART) begin
        fib_result = fib_calc(iN);
        oDONE <= 1'b1;
        oREADY <= 1'b0;
        oFIB <= fib_result;
        if (fib_result != oFIB) begin
            $fwrite(fout, "Error: Fibonacci number mismatch. Expected: %d, Actual: %d\n", fib_result, oFIB);
        end
    end
    else begin
        oDONE <= 1'b0;
        oREADY <= 1'b1;
    end
end

endmodule

module volume_detector_slow (
    input wire clk_in,
    input wire [11:0] mic_in,
    output reg [3:0] volume_out_lowres,
    output reg [7:0] volume_out_hires,
    output reg [3:0] volume_out_log
);

reg [13:0] counter;
reg [11:0] max_value, min_value;
reg [11:0] volume_diff;

always @(posedge clk_in) begin
    counter <= counter + 1;

    if (counter == 0) begin
        volume_diff = max_value - min_value;

        volume_out_lowres <= volume_diff[11:8];
        volume_out_hires <= volume_diff[11:4];

        if (volume_diff >= 2048) volume_out_log <= 4'd12;
        else if (volume_diff >= 1024) volume_out_log <= 4'd11;
        else if (volume_diff >= 512) volume_out_log <= 4'd10;
        else if (volume_diff >= 256) volume_out_log <= 4'd9;
        else if (volume_diff >= 128) volume_out_log <= 4'd8;
        else if (volume_diff >= 64) volume_out_log <= 4'd7;
        else if (volume_diff >= 32) volume_out_log <= 4'd6;
        else if (volume_diff >= 16) volume_out_log <= 4'd5;
        else if (volume_diff >= 8) volume_out_log <= 4'd4;
        else if (volume_diff >= 4) volume_out_log <= 4'd3;
        else if (volume_diff >= 2) volume_out_log <= 4'd2;
        else if (volume_diff >= 1) volume_out_log <= 4'd1;
        else volume_out_log <= 4'd0;

        max_value <= mic_in;
        min_value <= mic_in;
    end else begin
        if (mic_in > max_value) max_value <= mic_in;
        if (mic_in < min_value) min_value <= mic_in;
    end
end

endmodule

module multiplier_block (
    input [31:0] i_data0,
    output [31:0] o_data0
);

    wire [31:0] w1, w1024, w16, w17, w2176, w2193, w3217, w25736, w25753;

    assign w1 = i_data0;
    assign w1024 = w1 << 10;
    assign w16 = w1 << 4;
    assign w17 = w1 + w16;
    assign w2176 = w17 << 7;
    assign w2193 = w17 + w2176;
    assign w3217 = w2193 + w1024;
    assign w25736 = w3217 << 3;
    assign w25753 = w17 + w25736;

    assign o_data0 = w25753;

endmodule

module surround_with_regs (
    input [31:0] i_data0,
    input clk,
    output reg [31:0] o_data0
);

    reg [31:0] i_data0_reg;
    wire [31:0] o_data0_from_mult;

    always @(posedge clk) begin
        i_data0_reg <= i_data0;
        o_data0 <= o_data0_from_mult;
    end

    multiplier_block mult (
        .i_data0(i_data0_reg),
        .o_data0(o_data0_from_mult)
    );

endmodule

module ram_rst_ctrl #(
    parameter G_ADDR = 8,
    parameter G_DEPTH = 2**G_ADDR
) (
    input wire clk,
    input wire rst_n,
    input wire clrena,
    output reg clrrdy,
    output reg clrwe,
    output wire [G_ADDR-1:0] clraddr
);

    reg [G_ADDR-1:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= {G_ADDR{1'b0}};
            clrwe <= 1'b0;
            clrrdy <= 1'b1;
        end else if (clrena) begin
            count <= {G_ADDR{1'b0}};
            clrwe <= 1'b1;
            clrrdy <= 1'b0;
        end else if (!clrrdy) begin
            if (count == G_DEPTH - 1) begin
                clrwe <= 1'b0;
                clrrdy <= 1'b1;
            end else begin
                count <= count + 1'b1;
            end
        end
    end

    assign clraddr = count;

endmodule

module binary_to_bcd #(
    parameter W = 8
) (
    input [W-1:0] bin,
    output reg [(W+(W-4)/3+1)*4-1:0] bcd
);

    integer i, j;
    reg [W-1:0] tmp;
    reg [3:0] digit;

    always @(*) begin
        bcd = 0;
        tmp = bin;

        for (i = 0; i < W-3; i = i + 1) begin
            // Shift binary input left by 1 bit
            tmp = tmp << 1;

            // Check each BCD digit
            for (j = 0; j < (W+(W-4)/3+1); j = j + 1) begin
                digit = bcd[j*4 +: 4];

                // Add 3 to the digit if it's greater than 4
                if (digit >= 5)
                    digit = digit + 3;

                // Shift the digit left by 1 bit
                digit = {digit[2:0], tmp[W-1]};

                // Update the BCD output
                bcd[j*4 +: 4] = digit;
            end
        end
    end

endmodule

module MemController (
    input wire clk,
    input wire rst,

    // Base Memory Interface
    input wire [31:0] baseDIn,
    input wire [21:0] baseA,
    input wire baseWr,
    input wire baseRd,
    output reg [31:0] baseDOut,
    inout wire [31:0] baseIO,
    output wire [19:0] baseAddr,
    output wire baseCeN,
    output wire [3:0] baseBeN,
    output wire baseOeN,
    output wire baseWeN,

    // External Memory Interface (unused)
    output wire extCeN,
    output wire extOeN,
    output wire extWeN,

    // UART Interface (unused)
    input wire uartRxD,
    output wire uartTxD
);

    // State definition
    localparam IDLE = 3'd0, RD_1 = 3'd1, RD_2 = 3'd2, WR_1 = 3'd3, WR_2 = 3'd4, DONE = 3'd5;
    reg [2:0] state, next_state;

    // Internal signals
    reg baseZ;
    reg [31:0] writeData;

    // State machine
    always @(posedge clk or posedge rst) begin
        if (rst)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = baseRd ? RD_1 : (baseWr ? WR_1 : IDLE);
            RD_1: next_state = RD_2;
            RD_2: next_state = DONE;
            WR_1: next_state = WR_2;
            WR_2: next_state = DONE;
            DONE: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            baseDOut <= 32'h0;
            writeData <= 32'h0;
            baseZ <= 1'b1;
        end else begin
            case (state)
                IDLE: begin
                    if (baseWr) writeData <= baseDIn;
                    baseZ <= 1'b1;
                end
                RD_2: baseDOut <= baseIO;
                WR_1: baseZ <= 1'b0;
                DONE: baseZ <= 1'b1;
            endcase
        end
    end

    // Control signals
    assign baseAddr = baseA[21:2];
    assign baseCeN = 1'b0;
    assign baseBeN = 4'b0000;
    assign baseOeN = (state == RD_1 || state == RD_2) ? 1'b0 : 1'b1;
    assign baseWeN = (state == WR_1 || state == WR_2) ? 1'b0 : 1'b1;

    // Tri-state buffer for baseIO
    assign baseIO = baseZ ? 32'bz : writeData;

    // Unused external memory interface
    assign extCeN = 1'b1;
    assign extOeN = 1'b1;
    assign extWeN = 1'b1;

    // UART interface (unused)
    assign uartTxD = 1'b1;

endmodule

module readwritecontrolmux (
    input wire read,
    input wire write,
    input wire outofboundaccess,
    input wire [1:0] idexreadcontrolout,
    input wire [1:0] idexwritecontrolout,
    input wire wrcheckin,
    output reg [1:0] memdecoderreadcontrolout,
    output reg [1:0] memdecoderwritecontrolout,
    output reg wrcheckout
);

always @(*) begin
    if (outofboundaccess) begin
        memdecoderreadcontrolout = 2'b11;
        memdecoderwritecontrolout = 2'b11;
        wrcheckout = 1'b0;
    end
    else if (read && write) begin
        memdecoderreadcontrolout = 2'b11;
        memdecoderwritecontrolout = 2'b11;
        wrcheckout = 1'b0;
    end
    else if (write) begin
        memdecoderreadcontrolout = idexreadcontrolout;
        memdecoderwritecontrolout = 2'b11;
        wrcheckout = wrcheckin;
    end
    else if (read) begin
        memdecoderreadcontrolout = 2'b11;
        memdecoderwritecontrolout = idexwritecontrolout;
        wrcheckout = 1'b0;
    end
    else begin
        memdecoderreadcontrolout = idexreadcontrolout;
        memdecoderwritecontrolout = idexwritecontrolout;
        wrcheckout = wrcheckin;
    end
end

endmodule

