// BCD Counter Module
module BCD_COUNT (
    input wire CK,
    input wire CE,
    input wire AR,
    output reg CO,
    output reg [3:0] Q
);

always @(posedge CK or negedge AR) begin
    if (!AR) begin
        Q <= 4'b0000;
        CO <= 1'b0;
    end else if (CE) begin
        if (Q == 4'b1001) begin
            Q <= 4'b0000;
            CO <= 1'b1;
        end else begin
            Q <= Q + 1'b1;
            CO <= 1'b0;
        end
    end else begin
        CO <= 1'b0;
    end
end

endmodule

// Testbench Module
module BCD_COUNT_TEST;

