module adder_subtractor(
    input [3:0] A,
    input [3:0] B,
    input S,
    input clk,
    output reg [3:0] X
);

    wire [3:0] B_mux;
    wire [3:0] sum;
    wire [4:0] carry;

    // Instantiate MUX modules for each bit of B
    MUX mux0(.A(B[0]), .B(~B[0]), .S(S), .Y(B_mux[0]));
    MUX mux1(.A(B[1]), .B(~B[1]), .S(S), .Y(B_mux[1]));
    MUX mux2(.A(B[2]), .B(~B[2]), .S(S), .Y(B_mux[2]));
    MUX mux3(.A(B[3]), .B(~B[3]), .S(S), .Y(B_mux[3]));

    // Instantiate FA modules for 4-bit RCA
    FA fa0(.A(A[0]), .B(B_mux[0]), .C_in(S), .Sum(sum[0]), .C_out(carry[1]));
    FA fa1(.A(A[1]), .B(B_mux[1]), .C_in(carry[1]), .Sum(sum[1]), .C_out(carry[2]));
    FA fa2(.A(A[2]), .B(B_mux[2]), .C_in(carry[2]), .Sum(sum[2]), .C_out(carry[3]));
    FA fa3(.A(A[3]), .B(B_mux[3]), .C_in(carry[3]), .Sum(sum[3]), .C_out(carry[4]));

    // Register the output
    always @(posedge clk) begin
        X <= sum;
    end

endmodule

// 1-bit Full Adder module
module FA(
    input A,
    input B,
    input C_in,
    output Sum,
    output C_out
);
    assign Sum = A ^ B ^ C_in;
    assign C_out = (A & B) | (B & C_in) | (A & C_in);
endmodule

// 1-bit Multiplexer module
module MUX(
    input A,
    input B,
    input S,
    output Y
);
    assign Y = S ? B : A;
endmodule

module Pc #(
    parameter WIDTH = 32
)(
    output reg [WIDTH-1:0] out,
    input [WIDTH-1:0] in,
    input clk
);

    reg temp;

    always @(posedge clk) begin
        if (!temp) begin
            out <= {WIDTH{1'b0}};
            temp <= 1'b1;
        end
        else begin
            out <= in;
        end
    end

endmodule

module gray (
    input Clk,
    input Reset,
    input En,
    output reg [2:0] Output,
    output reg Overflow
);

reg [2:0] state;

always @(posedge Clk) begin
    if (Reset) begin
        state <= 3'b000;
        Overflow <= 1'b0;
    end
    else if (En) begin
        case (state)
            3'b000: begin
                state <= 3'b001;
                Output <= 3'b000;
            end
            3'b001: begin
                state <= 3'b011;
                Output <= 3'b001;
            end
            3'b011: begin
                state <= 3'b010;
                Output <= 3'b011;
            end
            3'b010: begin
                state <= 3'b110;
                Output <= 3'b010;
            end
            3'b110: begin
                state <= 3'b111;
                Output <= 3'b110;
            end
            3'b111: begin
                state <= 3'b101;
                Output <= 3'b111;
            end
            3'b101: begin
                state <= 3'b100;
                Output <= 3'b101;
            end
            3'b100: begin
                state <= 3'b000;
                Output <= 3'b100;
                Overflow <= 1'b1;
            end
        endcase
    end
end

endmodule

module regFile(
    input [5:0]  readReg1, readReg2, readReg3,
    input [31:0] writeData,
    input [5:0]  writeAddress,
    input        stored,
    input [31:0] endereco,
    input        ck,
    input        writeReg,
    input        inCMD,
    input        emit,
    output reg   stored_OK,
    output [31:0] readData1, readData2, readData3
);

reg [31:0] registers [63:0];

always @(posedge ck) begin
    if (stored) begin
        registers[endereco - 1] <= endereco;
        stored_OK <= 1;
    end
    else if (writeReg) begin
        if (inCMD) begin
            registers[40] <= writeData;
        end
        else begin
            registers[writeAddress] <= writeData;
        end
        stored_OK <= 0;
    end
    else begin
        stored_OK <= 0;
    end
end

assign readData1 = (emit) ? registers[40] : registers[readReg1];
assign readData2 = registers[readReg2];
assign readData3 = registers[readReg3];

endmodule

module Syscall(
    input wire syscall_control,
    input wire sysstall,
    input wire [31:0] v0,
    input wire [31:0] a0,
    output reg stat_control,
    output reg print
);

    initial begin
        stat_control = 0;
        print = 0;
    end

    always @* begin
        if (syscall_control && !sysstall) begin
            case (v0)
                32'd1: $display("%d", $signed(a0));
                32'd4: begin
                    print = 1;
                    #1 print = 0;
                end
            endcase
        end

        if (v0 == 32'd10) begin
            $display("Program is finished running");
            stat_control = 1;
            #1 $finish;
        end
    end

endmodule

module ALU_Ctrl (
    input [5:0] funct_i,
    input [2:0] ALUOp_i,
    output reg [3:0] ALU_operation_o,
    output reg [1:0] FURslt_o
);

always @(*) begin
    if (ALUOp_i == 3'b001) begin
        ALU_operation_o = 4'b0010;
        FURslt_o = 2'b00;
    end
    else begin
        case ({ALUOp_i, funct_i})
            9'b000_100000: begin // add
                ALU_operation_o = 4'b0010;
                FURslt_o = 2'b00;
            end
            9'b000_100010: begin // sub
                ALU_operation_o = 4'b0110;
                FURslt_o = 2'b00;
            end
            9'b000_100100: begin // and
                ALU_operation_o = 4'b0000;
                FURslt_o = 2'b00;
            end
            9'b000_100101: begin // or
                ALU_operation_o = 4'b0001;
                FURslt_o = 2'b00;
            end
            9'b000_101010: begin // slt
                ALU_operation_o = 4'b0111;
                FURslt_o = 2'b00;
            end
            9'b101_000000: begin // sll
                ALU_operation_o = 4'b1000;
                FURslt_o = 2'b10;
            end
            9'b101_000011: begin // sra
                ALU_operation_o = 4'b1011;
                FURslt_o = 2'b10;
            end
            default: begin
                ALU_operation_o = 4'b1111;
                FURslt_o = 2'b11;
            end
        endcase
    end
end

