module edge_detect #(
    parameter N = 8,
    parameter RST_DELAY = 100
) (
    input wire clk,
    input wire nreset,
    input wire [N-1:0] din,
    input wire bvalid,
    output reg edge_detected
);

    reg [N-1:0] tmp;
    reg [$clog2(RST_DELAY)-1:0] rst_cntr;
    reg reset_delay_done;

    always @(posedge clk or negedge nreset) begin
        if (!nreset) begin
            tmp <= {N{1'b0}};
            edge_detected <= 1'b0;
            rst_cntr <= {$clog2(RST_DELAY){1'b0}};
            reset_delay_done <= 1'b0;
        end else begin
            if (!reset_delay_done) begin
                if (rst_cntr == RST_DELAY - 1) begin
                    reset_delay_done <= 1'b1;
                    edge_detected <= 1'b1;
                end else begin
                    rst_cntr <= rst_cntr + 1'b1;
                    edge_detected <= 1'b0;
                end
            end else begin
                if (bvalid) begin
                    if (din != tmp) begin
                        edge_detected <= 1'b1;
                    end else begin
                        edge_detected <= 1'b0;
                    end
                    tmp <= din;
                end else begin
                    edge_detected <= 1'b0;
                end
            end
        end
    end

endmodule

module MEMORY (
