    input wire [31:0] r,
    input wire done,
    output reg [31:0] m,
    output reg [31:0] e,
    output reg [31:0] n,
    output reg [31:0] RESULT,
    output reg DONE
);

    reg done1;

    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            m <= 32'b0;
            e <= 32'b0;
            n <= 32'b0;
            RESULT <= 32'b0;
            done1 <= 1'b0;
            DONE <= 1'b0;
        end else begin
            if (LOAD) begin
                m <= M;
                e <= E;
                n <= N;
            end

            done1 <= done;
            DONE <= done1;

            if (done && !DONE) begin
                RESULT <= r;
            end
        end
    end

endmodule

