module combined_system (
    input wire clk,
    input wire reset,
    input wire direction,
    input wire load,
    input wire [7:0] load_value,
    input wire [7:0] data_in_0,
    input wire [7:0] data_in_1,
    input wire [7:0] data_in_2,
    input wire [7:0] data_in_3,
    input wire [1:0] select,
    output wire [7:0] final_output
);

    wire [7:0] counter_output;
    wire [7:0] mux_output;

    // Up/Down Counter
    up_down_counter counter (
        .clk(clk),
        .reset(reset),
        .direction(direction),
        .load(load),
        .load_value(load_value),
        .count(counter_output)
    );

    // 4-to-1 Multiplexer
    multiplexer_4to1 mux (
        .data_in_0(data_in_0),
        .data_in_1(data_in_1),
        .data_in_2(data_in_2),
        .data_in_3(data_in_3),
        .select(select),
        .data_out(mux_output)
    );

    // Adder module
    adder output_adder (
        .a(counter_output),
        .b(mux_output),
        .sum(final_output)
    );

endmodule

module up_down_counter (
    input wire clk,
    input wire reset,
    input wire direction,
    input wire load,
    input wire [7:0] load_value,
    output reg [7:0] count
);

    always @(posedge clk or posedge reset) begin
        if (reset)
            count <= 8'b0;
        else if (load)
            count <= load_value;
        else if (direction)
            count <= count + 1;
        else
            count <= count - 1;
    end

endmodule

module multiplexer_4to1 (
    input wire [7:0] data_in_0,
    input wire [7:0] data_in_1,
    input wire [7:0] data_in_2,
    input wire [7:0] data_in_3,
    input wire [1:0] select,
    output reg [7:0] data_out
);

    always @(*) begin
        case (select)
            2'b00: data_out = data_in_0;
            2'b01: data_out = data_in_1;
            2'b10: data_out = data_in_2;
            2'b11: data_out = data_in_3;
        endcase
    end

endmodule

