module CLA_64bit(
    input [63:0] a,
    input [63:0] b,
    input cin,
    output [63:0] result,
    output cout
);

    wire [15:0] c;
    wire [3:0] g, p;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : cla_16bit_block
            CLA_16bit cla_16bit (
                .a(a[16*i+15:16*i]),
                .b(b[16*i+15:16*i]),
                .cin(i == 0 ? cin : c[4*i-1]),
                .sum(result[16*i+15:16*i]),
                .cout(c[4*i+3:4*i])
            );
        end
    endgenerate

    generate
        for (i = 0; i < 4; i = i + 1) begin : generate_propagate
            assign g[i] = &a[16*i+15:16*i] & &b[16*i+15:16*i];
            assign p[i] = |a[16*i+15:16*i] ^ |b[16*i+15:16*i];
        end
    endgenerate

    assign cout = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) | (p[3] & p[2] & p[1] & p[0] & cin);

endmodule

module CLA_16bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output [3:0] cout
);

    wire [3:0] g, p;
    wire [3:0] c;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : cla_4bit_block
            CLA_4bit cla_4bit (
                .a(a[4*i+3:4*i]),
                .b(b[4*i+3:4*i]),
                .cin(i == 0 ? cin : c[i-1]),
                .sum(sum[4*i+3:4*i]),
                .cout(c[i])
            );
        end
    endgenerate

    assign cout = c;

endmodule

module CLA_4bit(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] g, p;
    wire [3:0] c;

    assign g = a & b;
    assign p = a ^ b;

    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & g[0]) | (p[1] & p[0] & c[0]);
    assign c[3] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & c[0]);

    assign sum = p ^ {c[2:0], cin};
    assign cout = c[3];

endmodule

