    assign row_3 = {square_7_status, square_8_status, square_9_status};

    assign diag_1 = {square_1_status, square_5_status, square_9_status};
    assign diag_2 = {square_3_status, square_5_status, square_7_status};

    reg player_win_reg;

    always @(*) begin
        if (clr) begin
            player_win_reg = 1'b0;
        end else begin
            player_win_reg = (column_1 == 6'b010101 || column_1 == 6'b101010 ||
                              column_2 == 6'b010101 || column_2 == 6'b101010 ||
                              column_3 == 6'b010101 || column_3 == 6'b101010 ||
                              row_1 == 6'b010101 || row_1 == 6'b101010 ||
                              row_2 == 6'b010101 || row_2 == 6'b101010 ||
                              row_3 == 6'b010101 || row_3 == 6'b101010 ||
                              diag_1 == 6'b010101 || diag_1 == 6'b101010 ||
                              diag_2 == 6'b010101 || diag_2 == 6'b101010);
        end
    end

    assign player_win = player_win_reg;

endmodule

