module FETCH (
    input wire [7:0] programByte,
    input wire clk,
    input wire phaseOut,
    input wire reset,
    output reg [3:0] instruction,
    output reg [3:0] operand
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            instruction <= 4'b0000;
            operand <= 4'b0000;
        end
        else if (!phaseOut) begin
            instruction <= programByte[7:4];
            operand <= programByte[3:0];
        end
    end

