);

    logic [3:0] memory [0:5000];

    initial begin
        $readmemh("sprite/explode.txt", memory);
    end

    always_ff @(posedge Clk) begin
        explode_index <= memory[read_address];
    end

endmodule

module edge_detector (
    input wire clk,
    input wire rst_n,
    input wire a,
    output reg rise,
    output reg down
);

    reg [2:0] a_delay;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_delay <= 3'b000;
            rise <= 1'b0;
            down <= 1'b0;
        end else begin
            // Pipeline stage 1: Shift register
            a_delay <= {a_delay[1:0], a};

            // Pipeline stage 2: Edge detection
            rise <= a_delay[1] & ~a_delay[2];
            down <= ~a_delay[1] & a_delay[2];
        end
    end

endmodule

module dark_frame (
    input wire clk,
    input wire [15:0] vxNorm, vyNorm,
    input wire signed [15:0] G1_10b, R1_10b, B1_10b, G2_10b,
    input wire [63:0] dark_row_rdata, dark_col_rdata,
    output reg [11:0] dark_row_raddr, dark_col_raddr,
    output reg signed [15:0] G1_dark_10b, R1_dark_10b, B1_dark_10b, G2_dark_10b
);

    // Internal registers for dark frame data
    reg signed [15:0] dark_row_G1, dark_row_R1, dark_row_B1, dark_row_G2;
    reg signed [15:0] dark_col_G1, dark_col_R1, dark_col_B1, dark_col_G2;

    always @(posedge clk) begin
        // Address generation
        dark_row_raddr <= vyNorm[15:4];
        dark_col_raddr <= vxNorm[15:4];

        // Dark frame data extraction
        dark_row_G1 <= $signed(dark_row_rdata[15:0]);
        dark_row_R1 <= $signed(dark_row_rdata[31:16]);
        dark_row_B1 <= $signed(dark_row_rdata[47:32]);
        dark_row_G2 <= $signed(dark_row_rdata[63:48]);

        dark_col_G1 <= $signed(dark_col_rdata[15:0]);
        dark_col_R1 <= $signed(dark_col_rdata[31:16]);
        dark_col_B1 <= $signed(dark_col_rdata[47:32]);
        dark_col_G2 <= $signed(dark_col_rdata[63:48]);

        // Dark frame subtraction
        G1_dark_10b <= G1_10b - dark_row_G1 - dark_col_G1;
        R1_dark_10b <= R1_10b - dark_row_R1 - dark_col_R1;
        B1_dark_10b <= B1_10b - dark_row_B1 - dark_col_B1;
        G2_dark_10b <= G2_10b - dark_row_G2 - dark_col_G2;
    end

endmodule

module calculator (
    input wire [2:0] opcode,
    input wire [7:0] operand_a,
    input wire [7:0] operand_b,
    output reg [7:0] result
);

    // Define opcodes
    localparam ADD = 3'b000;
    localparam SUB = 3'b001;
    localparam MUL = 3'b010;
    localparam DIV = 3'b011;

    always @(*) begin
        case (opcode)
            ADD: result = operand_a + operand_b;
            SUB: result = operand_a - operand_b;
            MUL: result = operand_a * operand_b;
            DIV: result = operand_a / operand_b;
            default: result = 8'b0; // Default case, set result to 0
        endcase
    end

endmodule

module sublime_voice_mixer #(
    parameter NUM_VOICES = 4,
    parameter VOICE_DATA_WIDTH = 32
) (
    input clk,
    input rst,
    input [($clog2(NUM_VOICES)-1):0] active_voice,
    input active_voice_changed,
    input signed [VOICE_DATA_WIDTH-1:0] active_voice_data,
    input signed [15:0] active_voice_velocity,
    output reg signed [VOICE_DATA_WIDTH-1:0] mixed_data
);

    reg signed [VOICE_DATA_WIDTH-1:0] mul_op1, mul_op2;
    reg signed [VOICE_DATA_WIDTH*2-1:0] mul_res;
    reg signed [VOICE_DATA_WIDTH-1:0] mul_res_neg;
    reg mul_valid;
    reg last_voice;
    reg [($clog2(NUM_VOICES)-1):0] mix_count;
    reg signed [VOICE_DATA_WIDTH-1:0] mix;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mixed_data <= 0;
            mul_valid <= 0;
            last_voice <= 0;
            mix_count <= 0;
            mix <= 0;
        end else begin
            if (active_voice_changed) begin
                mul_op1 <= active_voice_data;
                mul_op2 <= active_voice_velocity;
                mul_valid <= 1;
                last_voice <= (active_voice == (NUM_VOICES - 1));
                mix_count <= active_voice;
            end

            if (mul_valid) begin
                mul_res <= mul_op1 * mul_op2;
                mul_res_neg <= -mul_res[VOICE_DATA_WIDTH*2-1:VOICE_DATA_WIDTH];
                mul_valid <= 0;
            end

            if (!mul_valid) begin
                mix <= mix + mul_res_neg;
            end

            if (last_voice) begin
                mixed_data <= mix;
                mix <= 0;
            end
        end
    end

endmodule

