module fsm(
    input wr,
    input dr,
    input init,
    input clk2,
    input clk_10m,
    input rst,
    input [7:0] dbi,
    input [7:0] direc,
    output reg [7:0] db,
    output reg rs,
    output reg e
);

reg [3:0] estado;
reg [3:0] nestado;

parameter base = 4'b0000;
parameter activation = 4'b0001;
parameter enable1 = 4'b0010;
parameter mode = 4'b0011;
parameter enable2 = 4'b0100;
parameter erase = 4'b0101;
parameter enable3 = 4'b0110;
parameter initfinish = 4'b0111;
parameter write = 4'b1000;
parameter enable4 = 4'b1001;
parameter direction = 4'b1010;
parameter enabledirec = 4'b1011;

always @(posedge clk2) begin
    estado <= nestado;
end

always @(posedge clk_10m) begin
    case (estado)
        base: begin
            if (init) nestado <= activation;
            else if (wr) nestado <= write;
            else nestado <= base;
            db <= 8'b00000000;
            rs <= 0;
            e <= 0;
        end
        activation: begin
            nestado <= enable1;
            db <= 8'b00111000;
            rs <= 0;
            e <= 1;
        end
        enable1: begin
            nestado <= mode;
            db <= 8'b00000000;
            rs <= 0;
            e <= 1;
        end
        mode: begin
            nestado <= enable2;
            db <= 8'b00110111;
            rs <= 0;
            e <= 1;
        end
        enable2: begin
            if (init) nestado <= erase;
            else nestado <= enable2;
            db <= 8'b00000000;
            rs <= 0;
            e <= 1;
        end
        erase: begin
            nestado <= enable3;
            db <= 8'b00110101;
            rs <= 0;
            e <= 1;
        end
        enable3: begin
            nestado <= initfinish;
            db <= 8'b00000000;
            rs <= 0;
            e <= 1;
        end
        initfinish: begin
            nestado <= base;
            db <= 8'b00000000;
            rs <= 0;
            e <= 0;
        end
        write: begin
            nestado <= enable4;
            db <= dbi;
            rs <= 0;
            e <= 1;
        end
        enable4: begin
            nestado <= base;
            db <= 8'b00000000;
            rs <= 0;
            e <= 0;
        end
        direction: begin
            nestado <= enabledirec;
            db <= direc;
            rs <= 0;
            e <= 1;
        end
        enabledirec: begin
            nestado <= base;
            db <= 8'b00000000;
            rs <= 0;
            e <= 0;
        end
        default: begin
            nestado <= base;
            db <= 8'b00000000;
            rs <= 0;
            e <= 0;
        end
    endcase
end

endmodule

`timescale 1ns/10ps

module CLK_DIV #(
    parameter N = 512
) (
    input wire clk,
    input wire rst,
    output wire div_clk
);

`ifndef UD
    `define UD #1
`endif

reg [12:0] clk_cnt;
reg clk_out_tmp;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        clk_cnt <= `UD 13'd0;
        clk_out_tmp <= `UD 1'b0;
    end else begin
        if (clk_cnt == N/2 - 1) begin
            clk_cnt <= `UD 13'd1;
            clk_out_tmp <= `UD ~clk_out_tmp;
        end else begin
            clk_cnt <= `UD clk_cnt + 1'b1;
        end
    end
end

assign div_clk = clk_out_tmp;

endmodule

module fab(
    input clk, reset, s,
    input [7:0] in,
    input [1:0] op,
    output reg [7:0] out,
    output reg done
);

    parameter Wait = 3'b000, INIT1 = 3'b001, INIT2 = 3'b010,
              FIB1 = 3'b011, FIB2 = 3'b100, FIB3 = 3'b101, FIB4 = 3'b110,
              FACT1 = 3'b111, FACT2 = 3'b000, FACT3 = 3'b001, Pond = 3'b010;

    reg [7:0] A, B, C, sum;
    reg [2:0] present_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            present_state <= Wait;
            done <= 0;
        end else begin
            present_state <= next_state;
        end
    end

    always @(*) begin
        case (present_state)
            Wait: next_state = s ? (op == 2'b00 ? INIT1 : (op == 2'b01 ? FIB1 : FACT1)) : Wait;
            INIT1: next_state = INIT2;
            INIT2: next_state = Pond;
            FIB1: next_state = FIB2;
            FIB2: next_state = (C == 0) ? Pond : FIB3;
            FIB3: next_state = FIB4;
            FIB4: next_state = FIB2;
            FACT1: next_state = (C == 1) ? Pond : FACT2;
            FACT2: next_state = FACT3;
            FACT3: next_state = FACT1;
            Pond: next_state = s ? Pond : Wait;
            default: next_state = Wait;
        endcase
    end

    always @(posedge clk) begin
        case (present_state)
            Wait: begin
                A <= 0;
                B <= 1;
                C <= in;
                done <= 0;
            end
            INIT1: begin
                out <= B;
                done <= 1;
            end
            FIB1: begin
                sum <= A + B;
                C <= C - 1;
            end
            FIB3: begin
                A <= B;
                B <= sum;
            end
            FIB4: begin
                sum <= A + B;
                C <= C - 1;
            end
            FACT1: begin
                if (C == 1) begin
                    out <= B;
                    done <= 1;
                end
            end
            FACT2: begin
                B <= B * C;
            end
            FACT3: begin
                C <= C - 1;
            end
        endcase
    end

endmodule

