module top(
    input x,
    input y,
    input cin,
    output reg A,
    output reg cout
);

reg A1, cout1;
reg int1, int2, int3;

initial begin
    A = 0;
    cout = 0;
end

always @(posedge x) begin
`ifndef BUG
    A1 = ~y + &cin;
    cout1 = cin ? |y : ~^A;
    A <= (A1 & y & cin) | (A1 & ~y & ~cin) | (~A1 & y & ~cin) | (A & ~y & cin);
    cout <= cout1 & cin & ~|y;

    if (x & y)
        int1 = 1'b1;
    else if (~x & ~y)
        int1 = 1'b0;
    else
        int1 = 1'bx;

    if (y | cin)
        int2 = 1'b1;
    else if (~y & ~cin)
        int2 = 1'b0;
    else
        int2 = 1'bx;

    if (x ^ y ^ cin)
        int3 = 1'b1;
    else if (~(x ^ y ^ cin))
        int3 = 1'b0;
    else
        int3 = 1'bx;
`else
    A <= 1'bz;
    cout <= 1'bz;
`endif
end

endmodule

