module EXT_FIFO_WR_CTRL (
    input        CLK,
    input        RESET,
    input        RD_RST_N,
    input        MASTER_SINK_DAV,
    input        MASTER_SINK_VAL,
    input        MASTER_SINK_SOP,
    input        MASTER_SINK_EOP,
    input        MASTER_SINK_ERR,
    input  [3:0] MASTER_SINK_MTY,
    input [31:0] MASTER_SINK_DAT,
    input        FIFOA_AF_N,
    input        FIFOA_FF_N,
    output       WR_RST_N,
    output       MASTER_SINK_ENA,
    output       FIFOA_RST_N,
    output       FIFOA_CS_N,
    output       FIFOA_EN,
    output       FIFOA_WR,
    output [31:0] FIFOA_DATA
);

    reg        wr_rst_n;
    reg        master_sink_ena;
    reg        fifoa_rst_n;
    reg        fifoa_cs_n;
    reg        fifoa_en;
    reg        fifoa_wr;
    reg [31:0] fifoa_data;

    always @(posedge CLK or negedge RESET) begin
        if (!RESET) begin
            wr_rst_n <= 1'b0;
            master_sink_ena <= 1'b0;
            fifoa_rst_n <= 1'b0;
            fifoa_cs_n <= 1'b1;
            fifoa_en <= 1'b0;
            fifoa_wr <= 1'b0;
            fifoa_data <= 32'b0;
        end
        else begin
            wr_rst_n <= RD_RST_N;
            fifoa_rst_n <= RD_RST_N;

            if (MASTER_SINK_DAV && MASTER_SINK_VAL) begin
                if (!FIFOA_FF_N && !FIFOA_AF_N) begin
                    master_sink_ena <= 1'b1;
                    fifoa_cs_n <= 1'b0;
                    fifoa_en <= 1'b1;
                    fifoa_wr <= 1'b1;
                    fifoa_data <= MASTER_SINK_DAT;
                end
                else begin
                    master_sink_ena <= 1'b0;
                    fifoa_cs_n <= 1'b1;
                    fifoa_en <= 1'b0;
                    fifoa_wr <= 1'b0;
                end
            end
            else begin
                master_sink_ena <= 1'b0;
                fifoa_cs_n <= 1'b1;
                fifoa_en <= 1'b0;
                fifoa_wr <= 1'b0;
            end
        end
    end

    assign WR_RST_N = wr_rst_n;
    assign MASTER_SINK_ENA = master_sink_ena;
    assign FIFOA_RST_N = fifoa_rst_n;
    assign FIFOA_CS_N = fifoa_cs_n;
    assign FIFOA_EN = fifoa_en;
    assign FIFOA_WR = fifoa_wr;
    assign FIFOA_DATA = fifoa_data;

endmodule

module clkdiv #(
    parameter DIVFREQ = 100,
    parameter DIVBITS = 26,
    parameter CLKFREQ = 100_000_000,
    parameter DIVAMT = CLKFREQ / (2 * DIVFREQ)
) (
    input wire clk,
    input wire reset,
    output reg sclk
);

    reg [DIVBITS-1:0] q;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 0;
            sclk <= 0;
        end else if (q == DIVAMT - 1) begin
            q <= 0;
            sclk <= ~sclk;
        end else begin
            q <= q + 1;
        end
    end

endmodule

module counter (
    input wire clk,
    input wire start_ram_init,
    output reg [7:0] addr,
    output reg write_enable,
    output reg ram_init_done
);

    reg [7:0] i;

    initial begin
        i = 8'b0;
        ram_init_done = 1'b0;
    end

    always @(posedge clk) begin
        write_enable = 1'b1;

        if (i > 8'd254) begin
            write_enable = 1'b0;
            ram_init_done = 1'b1;
        end
        else if (start_ram_init) begin
            i = i + 1'b1;
        end
    end

    assign addr = i;

endmodule

