module lowp3_2 (
    input wire [27:0] signal_in,
    input wire clock_in,
    input wire reset,
    input wire enable,
    output reg [27:0] signal_out
);

    parameter N = 1024;
    parameter N_down_sample = 4;

    reg [1:0] down_sample_clk;
    reg [27:0] signal_in_latch;
    reg [37:0] signal_out_tmp;
    reg [9:0] count;

    always @(posedge clock_in or posedge reset) begin
        if (reset) begin
            down_sample_clk <= 2'b00;
            signal_in_latch <= 28'b0;
        end else if (enable) begin
            if (down_sample_clk == N_down_sample - 1) begin
                down_sample_clk <= 2'b00;
                signal_in_latch <= signal_in;
            end else begin
                down_sample_clk <= down_sample_clk + 1'b1;
            end
        end
    end

    always @(posedge clock_in or posedge reset) begin
        if (reset) begin
            signal_out_tmp <= 38'b0;
            count <= 10'b0;
            signal_out <= 28'b0;
        end else if (enable) begin
            if (down_sample_clk == 2'b00) begin
                if (count == N - 1) begin
                    signal_out <= signal_out_tmp[37:10];
                    signal_out_tmp <= {10'b0, signal_in_latch};
                    count <= 10'b0;
                end else begin
                    signal_out_tmp <= signal_out_tmp + {10'b0, signal_in_latch};
                    count <= count + 1'b1;
                end
            end
        end
    end

endmodule

module system(
    input [2:0] in,
    output [2:0] out
);

    wire [2:0] and_out;
    wire [2:0] or_out;

    // Constant values
    parameter [2:0] AND_CONST = 3'b111;
    parameter [2:0] OR_CONST = 3'b101;

    // AND operation
    assign and_out[0] = in[0] & AND_CONST[0];
    assign and_out[1] = in[1] & AND_CONST[1];
    assign and_out[2] = in[2] & AND_CONST[2];

    // OR operation with constant
    assign or_out[0] = and_out[0] | OR_CONST[0];
    assign or_out[1] = and_out[1] | OR_CONST[1];
    assign or_out[2] = and_out[2] | OR_CONST[2];

    // Final output
    assign out = or_out;

endmodule

