module moving_average_filter (
    input wire update,
    input wire [8:0] newData,
    output wire [8:0] filtData
);

    reg [8:0] data0, data1, data2, data3;
    reg [10:0] sum;

    always @(posedge update) begin
        data3 <= data2;
        data2 <= data1;
        data1 <= data0;
        data0 <= newData;
        sum <= data0 + data1 + data2 + data3;
    end

    assign filtData = sum[10:2] - 9'b000000011;

endmodule

module barrelShifter #(
    parameter N = 16,
    parameter C = 4,
    parameter O = 2
)(
    input [(N-1):0] In,
    input [(C-1):0] Cnt,
    input [(O-1):0] Op,
    output [(N-1):0] Out
);

    wire [(N-1):0] shift1, shift2, shift3, res;
    wire [(N-1):0] lshift1, lshift2, lshift3, res2;

    // Logical Shift
    assign shift1 = (Cnt[0]) ? (In >> 1) : In;
    assign shift2 = (Cnt[1]) ? (shift1 >> 2) : shift1;
    assign shift3 = (Cnt[2]) ? (shift2 >> 4) : shift2;
    assign res = (Cnt[3]) ? (shift3 >> 8) : shift3;

    // Arithmetic Shift
    assign lshift1 = (Cnt[0]) ? ({(Op[0] ? In[N-1] : 1'b0), In[(N-1):1]}) : In;
    assign lshift2 = (Cnt[1]) ? ({(Op[0] ? lshift1[N-1] : 1'b0), lshift1[(N-1):2]}) : lshift1;
    assign lshift3 = (Cnt[2]) ? ({(Op[0] ? lshift2[N-1] : 1'b0), lshift2[(N-1):4]}) : lshift2;
    assign res2 = (Cnt[3]) ? ({(Op[0] ? lshift3[N-1] : 1'b0), lshift3[(N-1):8]}) : lshift3;

    assign Out = (Op[1]) ? res : res2;

endmodule

