module fp_adder (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [31:0] A,
    input wire [31:0] B,
    output reg valid,
    output reg [31:0] result
);

    // Internal registers
    reg signA, signB, signC;
    reg [7:0] expA, expB, expC;
    reg [22:0] mantisA, mantisB;
    reg [23:0] exManA, exManB;
    reg [24:0] sum;
    reg [7:0] expDiff;
    reg [4:0] normShift;

    // Combinational logic
    always @(*) begin
        // Extract sign, exponent, and mantissa
        signA = A[31];
        signB = B[31];
        expA = A[30:23];
        expB = B[30:23];
        mantisA = A[22:0];
        mantisB = B[22:0];

        // Extend mantissas with implicit leading 1
        exManA = {1'b1, mantisA};
        exManB = {1'b1, mantisB};

        // Compare exponents and swap if necessary
        if (expA < expB) begin
            {signA, signB} = {signB, signA};
            {expA, expB} = {expB, expA};
            {exManA, exManB} = {exManB, exManA};
        end

        // Align mantissas
        expDiff = expA - expB;
        exManB = exManB >> expDiff;

        // Add or subtract based on signs
        if (signA == signB)
            sum = exManA + exManB;
        else
            sum = exManA - exManB;

        // Normalize result
        if (sum[24]) begin
            sum = sum >> 1;
            expC = expA + 1;
        end else begin
            normShift = 0;
            while (!sum[23] && normShift < 24) begin
                sum = sum << 1;
                normShift = normShift + 1;
            end
            expC = expA - normShift;
        end

        // Set result sign
        signC = signA;

        // Handle special case: cancellation
        if (sum == 0) begin
            signC = 0;
            expC = 0;
        end
    end

    // Sequential logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            valid <= 0;
            result <= 32'b0;
        end else if (enable) begin
            valid <= 1;
            result <= {signC, expC, sum[22:0]};
        end else begin
            valid <= 0;
        end
    end

endmodule

module trace_memory_controller (
    input wire clk,
    input wire rst_n,
    input wire trace_enable,
    input wire on_chip_mem_enable,
    input wire ext_mem_enable,
    input wire data_ready,
    input wire [31:0] instruction_data,
    input wire [31:0] data_trace,
    output reg on_chip_mem_write,
    output reg [31:0] on_chip_mem_addr,
    output reg [31:0] on_chip_mem_data,
    output reg ext_mem_write,
    output reg [31:0] ext_mem_addr,
    output reg [31:0] ext_mem_data,
    output reg jtag_tdo,
    input wire jtag_tck,
    input wire jtag_tms,
    input wire jtag_tdi
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam WRITE_ON_CHIP = 2'b01;
    localparam WRITE_EXT = 2'b10;
    localparam JTAG_TRANSFER = 2'b11;

    reg [1:0] state, next_state;
    reg [31:0] on_chip_mem_addr_counter;
    reg [31:0] ext_mem_addr_counter;

    // JTAG interface
    reg [31:0] jtag_data_buffer;
    reg [5:0] jtag_bit_counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            on_chip_mem_addr_counter <= 32'h0;
            ext_mem_addr_counter <= 32'h0;
            jtag_data_buffer <= 32'h0;
            jtag_bit_counter <= 6'h0;
        end else begin
            state <= next_state;
            if (state == WRITE_ON_CHIP && on_chip_mem_enable)
                on_chip_mem_addr_counter <= on_chip_mem_addr_counter + 1;
            if (state == WRITE_EXT && ext_mem_enable)
                ext_mem_addr_counter <= ext_mem_addr_counter + 1;
            if (state == JTAG_TRANSFER) begin
                if (jtag_tck) begin
                    jtag_data_buffer <= {jtag_data_buffer[30:0], jtag_tdi};
                    jtag_bit_counter <= jtag_bit_counter + 1;
                end
            end
        end
    end

    always @(*) begin
        next_state = state;
        on_chip_mem_write = 1'b0;
        ext_mem_write = 1'b0;
        on_chip_mem_addr = on_chip_mem_addr_counter;
        on_chip_mem_data = 32'h0;
        ext_mem_addr = ext_mem_addr_counter;
        ext_mem_data = 32'h0;
        jtag_tdo = 1'b0;

        case (state)
            IDLE: begin
                if (trace_enable && data_ready) begin
                    if (on_chip_mem_enable)
                        next_state = WRITE_ON_CHIP;
                    else if (ext_mem_enable)
                        next_state = WRITE_EXT;
                end
            end

            WRITE_ON_CHIP: begin
                on_chip_mem_write = 1'b1;
                on_chip_mem_data = instruction_data;
                if (!on_chip_mem_enable || !data_ready)
                    next_state = IDLE;
            end

            WRITE_EXT: begin
                ext_mem_write = 1'b1;
                ext_mem_data = data_trace;
                if (!ext_mem_enable || !data_ready)
                    next_state = IDLE;
                else if (jtag_tms)
                    next_state = JTAG_TRANSFER;
            end

            JTAG_TRANSFER: begin
                jtag_tdo = jtag_data_buffer[31];
                if (jtag_bit_counter == 6'h20) begin
                    next_state = IDLE;
                    jtag_bit_counter = 6'h0;
                end
            end
        endcase
    end

endmodule

