module blinker(
    input rst,
    input clk,
    input [31:0] control,
    input [31:0] prescale,
    input [7:0] shortDelay,
    input [7:0] midDelay,
    input [7:0] longDelay,
    output reg blink
);

reg [31:0] prescaler;
reg prescaled;
reg [7:0] delayCounter;
reg [2:0] step;
reg [1:0] delaySelect;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        blink <= 0;
        step <= 0;
        prescaler <= 1;
        prescaled <= 0;
        delayCounter <= 0;
    end
    else begin
        case (control[1:0])
            2'b00: begin // Disable blinker
                blink <= 0;
                step <= 0;
            end
            2'b01: begin // Enable blinker
                blink <= 1;
                step <= 0;
            end
            2'b10: begin // Activate state machine
                if (prescaled) begin
                    prescaled <= 0;
                    delayCounter <= 0;
                    case (delaySelect)
                        2'b00: delayCounter <= shortDelay;
                        2'b01: delayCounter <= midDelay;
                        2'b10: delayCounter <= longDelay;
                        default: delayCounter <= 0;
                    endcase
                    case (step)
                        3'b000: step <= 3'b001;
                        3'b001: step <= 3'b010;
                        3'b010: step <= 3'b011;
                        3'b011: step <= 3'b100;
                        3'b100: step <= 3'b101;
                        3'b101: step <= 3'b110;
                        3'b110: step <= 3'b111;
                        3'b111: step <= 3'b000;
                        default: step <= 0;
                    endcase
                end
                else begin
                    prescaled <= (prescaler == prescale);
                    prescaler <= prescaler + 1;
                    if (delayCounter > 0) begin
                        delayCounter <= delayCounter - 1;
                    end
                end
                blink <= ~step[0];
            end
            default: begin
                blink <= 0;
                step <= 0;
            end
        endcase
    end
end

always @(*) begin
    case (step)
        3'b000, 3'b001: delaySelect = 2'b00;
        3'b010, 3'b011: delaySelect = 2'b01;
        3'b100, 3'b101, 3'b110, 3'b111: delaySelect = 2'b10;
        default: delaySelect = 2'b00;
    endcase
end

endmodule

