module full_adder(
    input a0, b0, c0, a1, b1,
    output s_out, c_out, s2, s3
);

    wire sum_1, carry_1, carry_2;

    half_adder ha1 (
        .a(a0),
        .b(b0),
        .sum(sum_1),
        .carry(carry_1)
    );

    half_adder ha2 (
        .a(sum_1),
        .b(c0),
        .sum(s_out),
        .carry(carry_2)
    );

    assign c_out = carry_1 | carry_2;

    test1 t1 (
        .a(a1),
        .b(b1),
        .s(s2)
    );

    test2 t2 (
        .a(a1),
        .b(b1),
        .s(s3)
    );

endmodule

