module probador(
    output reg clk,
    output reg rst,
    input [9:0] data_in
);

    reg [9:0] data_in_reg;

    initial begin
        rst = 1;
        data_in_reg = 10'b0;
        clk = 0;

        @(posedge clk);
        rst = 0;

        @(posedge clk);
        data_in_reg = 10'd25;

        @(posedge clk);
        data_in_reg = 10'd45;

        repeat (4) begin
            @(posedge clk);
            data_in_reg = data_in_reg + 20;
        end

        @(posedge clk);
        data_in_reg = 10'd0;

        repeat (5) begin
            @(posedge clk);
            data_in_reg = 10'd0;
        end

        @(posedge clk);
        data_in_reg = 10'd20;

        repeat (5) begin
            @(posedge clk);
            data_in_reg = data_in_reg + 20;
        end

        @(posedge clk);
        data_in_reg = 10'd0;

        repeat (4) begin
            @(posedge clk);
        end

        $finish;
    end

    always @(posedge clk) begin
        if (rst) begin
            data_in_reg <= 10'b0;
        end else begin
            data_in_reg <= data_in_reg;
        end
    end

    always #2 clk = ~clk;
endmodule

module jbi_1r1w_16x160 (
    input wire rdclk,
    input wire read_en,
    input wire [3:0] rd_adr,
    input wire wrclk,
    input wire wr_en,
