    input wire [159:0] din,
    input wire rst_l,
    output reg [159:0] dout
);

    // Declare the memory array
    reg [159:0] mem [0:15];

    // Read operation
    always @(posedge rdclk) begin
        if (!rst_l) begin
            dout <= 160'b0;
        end else if (read_en) begin
            dout <= mem[rd_adr];
        end
    end

    // Write operation
    always @(posedge wrclk) begin
        if (!rst_l) begin
            integer i;
            for (i = 0; i < 16; i = i + 1) begin
                mem[i] <= 160'b0;
            end
        end else if (wr_en) begin
            mem[wr_adr] <= din;
        end
    end

endmodule

module grayscale #(
    parameter P_PIXEL_DEPTH = 24,
    parameter P_SUBPIXEL_DEPTH = P_PIXEL_DEPTH / 3
)(
    input wire I_CLK,
    input wire I_RESET,
    input wire [P_PIXEL_DEPTH-1:0] I_PIXEL,
    output wire [P_SUBPIXEL_DEPTH-1:0] O_PIXEL
);

    wire [P_SUBPIXEL_DEPTH-1:0] w_i_red, w_i_green, w_i_blue;
    reg [P_SUBPIXEL_DEPTH-1:0] q_o_pixel, n_o_pixel;

    // Extract color components
    assign w_i_red   = I_PIXEL[P_PIXEL_DEPTH-1 -: P_SUBPIXEL_DEPTH];
    assign w_i_green = I_PIXEL[P_PIXEL_DEPTH-P_SUBPIXEL_DEPTH-1 -: P_SUBPIXEL_DEPTH];
    assign w_i_blue  = I_PIXEL[P_SUBPIXEL_DEPTH-1:0];

    // Combinational logic for grayscale conversion
    always @(*) begin
        n_o_pixel = (w_i_red >> 2) + (w_i_red >> 5) + (w_i_red >> 6) +
                    (w_i_green >> 1) + (w_i_green >> 4) + (w_i_green >> 6) + (w_i_green >> 7) +
                    (w_i_blue >> 4) + (w_i_blue >> 5) + (w_i_blue >> 6);
    end

    // Sequential logic
    always @(posedge I_CLK or posedge I_RESET) begin
        if (I_RESET)
            q_o_pixel <= {P_SUBPIXEL_DEPTH{1'b0}};
        else
            q_o_pixel <= n_o_pixel;
    end

    // Output assignment
    assign O_PIXEL = q_o_pixel;

endmodule

