module uart_tx (
    input wire [7:0] tx_data,
    input wire tx_en,
    input wire bdclk,
    input wire sysclk,
    input wire reset,
    output reg tx_status_out,
    output reg uart_tx
);

    reg [3:0] num;
    reg [4:0] status;
    reg tx_status;

    always @(posedge sysclk or negedge reset) begin
        if (!reset) begin
            uart_tx <= 1'b1;
            status <= 5'd0;
            num <= 4'd0;
            tx_status <= 1'b1;
        end else begin
            if (tx_en && tx_status) begin
                tx_status <= 1'b0;
            end else if (!tx_status) begin
                if (bdclk) begin
                    if (status == 5'd15) begin
                        status <= 5'd0;
                        if (num == 4'd9) begin
                            num <= 4'd0;
                            tx_status <= 1'b1;
                        end else begin
                            num <= num + 1'b1;
                        end
                    end else begin
                        status <= status + 1'b1;
                    end
                end
            end
        end
    end

    always @(posedge sysclk) begin
        if (!tx_status) begin
            case (num)
                4'd0: uart_tx <= 1'b0; // Start bit
                4'd1: uart_tx <= tx_data[0];
                4'd2: uart_tx <= tx_data[1];
                4'd3: uart_tx <= tx_data[2];
                4'd4: uart_tx <= tx_data[3];
                4'd5: uart_tx <= tx_data[4];
                4'd6: uart_tx <= tx_data[5];
                4'd7: uart_tx <= tx_data[6];
                4'd8: uart_tx <= tx_data[7];
                4'd9: uart_tx <= 1'b1; // Stop bit
                default: uart_tx <= 1'b1;
            endcase
        end else begin
            uart_tx <= 1'b1;
        end
    end

    always @(posedge sysclk) begin
        tx_status_out <= tx_status;
    end

endmodule

