// nco (Numerically Controlled Oscillator) module
module nco(
    input clk,
    input rst_n,
    input [31:0] num,
    output reg clk_gen
);

    reg [31:0] cnt;

    always @(posedge clk) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_gen <= 0;
        end
        else begin
            if (cnt == (num / 2 - 1)) begin
                cnt <= 0;
                clk_gen <= ~clk_gen;
            end
            else begin
                cnt <= cnt + 1;
            end
        end
    end

endmodule

