module Decoder(
    input  [5:0] instr_op_i,
    output reg  RegWrite_o,
    output reg  [2:0] ALU_op_o,
    output reg  ALUSrc_o,
    output reg  RegDst_o,
    output reg  Branch_o
);

always @(*) begin
    case (instr_op_i)
        6'b000000: begin // R-type instructions
            RegWrite_o = 1'b1;
            ALU_op_o = 3'b010;
            ALUSrc_o = 1'b0;
            RegDst_o = 1'b1;
            Branch_o = 1'b0;
        end
        6'b001000: begin // addi
            RegWrite_o = 1'b1;
            ALU_op_o = 3'b011;
            ALUSrc_o = 1'b1;
            RegDst_o = 1'b0;
            Branch_o = 1'b0;
        end
        6'b001011: begin // ori
            RegWrite_o = 1'b1;
            ALU_op_o = 3'b100;
            ALUSrc_o = 1'b1;
            RegDst_o = 1'b0;
            Branch_o = 1'b0;
        end
        6'b000100: begin // beq
            RegWrite_o = 1'b0;
            ALU_op_o = 3'b001;
            ALUSrc_o = 1'b0;
            RegDst_o = 1'b1;
            Branch_o = 1'b1;
        end
        6'b001111: begin // lui
            RegWrite_o = 1'b1;
            ALU_op_o = 3'b101;
            ALUSrc_o = 1'b1;
            RegDst_o = 1'b0;
            Branch_o = 1'b0;
        end
        6'b001101: begin // ori
            RegWrite_o = 1'b1;
            ALU_op_o = 3'b110;
            ALUSrc_o = 1'b1;
            RegDst_o = 1'b0;
            Branch_o = 1'b0;
        end
        default: begin
            RegWrite_o = 1'b0;
            ALU_op_o = 3'b000;
            ALUSrc_o = 1'b0;
            RegDst_o = 1'b0;
            Branch_o = 1'b0;
        end
    endcase
end

endmodule

module data_processing_unit(
    input [7:0] in,
    input clk,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);

localparam FIRST = 2'b00;
localparam SECOND = 2'b01;
localparam THIRD = 2'b10;
localparam DONE = 2'b11;

reg [1:0] cs, ns;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        cs <= FIRST;
    end
    else begin
        cs <= ns;
    end
end

always @(*) begin
    case (cs)
        FIRST: begin
            if (in[3]) begin
                ns = SECOND;
            end
            else begin
                ns = FIRST;
            end
            out_bytes = out_bytes;
            done = 1'b0;
        end
        SECOND: begin
            ns = THIRD;
            out_bytes[23:16] = in;
            done = 1'b0;
        end
        THIRD: begin
            ns = DONE;
            out_bytes[15:8] = in;
            done = 1'b0;
        end
        DONE: begin
            if (in[3]) begin
                ns = SECOND;
            end
            else begin
                ns = FIRST;
            end
            out_bytes[7:0] = in;
            done = 1'b1;
        end
        default: begin
            ns = FIRST;
            out_bytes = out_bytes;
            done = 1'b0;
        end
    endcase
end

endmodule

module shiftL(
    input [31:0] in,
    input [1:0] num,
    output reg [31:0] out
);
    always @(*) begin
        case(num)
            2'b00: out = in;
            2'b01: out = {in[23:0], in[31:24]};
            2'b10: out = {in[15:0], in[31:16]};
            2'b11: out = {in[7:0], in[31:8]};
        endcase
    end
endmodule

module shiftR(
    input [31:0] in,
    input [1:0] num,
    output [31:0] out
);
    wire [1:0] numtmp;
    assign numtmp = 4 - num;

    shiftL sl(
        .in(in),
        .num(numtmp),
        .out(out)
    );
endmodule

module shiftRows(
    input [127:0] in,
    input flag,
    output [127:0] out
);
    wire [1:0] num [3:0];
    assign num[0] = 2'b00;
    assign num[1] = flag ? 2'b11 : 2'b01;
    assign num[2] = 2'b10;
    assign num[3] = flag ? 2'b01 : 2'b11;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : shift_gen
            shiftL sl(
                .in(in[32*i+31:32*i]),
                .num(num[i]),
                .out(out[32*i+31:32*i])
            );
        end
    endgenerate
endmodule

