module register_file (
    input clk,
    input reset,
    input [4:0] field_reg_src1,
    input [4:0] field_reg_src2,
    input [4:0] field_reg_dest,
    input [31:0] reg_input_data,
    input reg_write_enable,
    output reg [31:0] reg_out_bus1,
    output reg [31:0] reg_out_bus2
);

    reg [31:0] registers [0:31];
    reg [31:0] tmp_reg_out_bus1;
    reg [31:0] tmp_reg_out_bus2;

    always @(negedge clk) begin
        if (~reset) begin
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                registers[i] <= 32'h0000_0000;
            end
            reg_out_bus1 <= 32'hzzzz_zzzz;
            reg_out_bus2 <= 32'hzzzz_zzzz;
        end
        else begin
            tmp_reg_out_bus1 <= registers[field_reg_src1];
            tmp_reg_out_bus2 <= registers[field_reg_src2];

            if (reg_write_enable) begin
                registers[field_reg_dest] <= reg_input_data;
            end
        end
    end

    always @(*) begin
        reg_out_bus1 = tmp_reg_out_bus1;
        reg_out_bus2 = tmp_reg_out_bus2;
    end

endmodule

module emio_mux (
    input wire emio_uart0_txd,
    input wire [15:0] emio_gpio_o,
    input wire [1:0] gpi,
    output wire emio_uart0_rxd,
    output wire [15:0] emio_gpio_i,
    output wire [1:0] gpo
);

    // GPIO Input Handling
    assign emio_gpio_i[15:4] = 12'b0;  // Upper 12 bits hardwired to 0
    assign emio_gpio_i[3:2] = gpi;     // Bits 3:2 connected to gpi
    assign emio_gpio_i[1:0] = 2'b0;    // Lower 2 bits hardwired to 0

    // UART RX Handling
    assign emio_uart0_rxd = gpi[0];

    // GPIO Output and UART TX Multiplexing
    assign gpo[0] = emio_gpio_o[6] ? emio_uart0_txd : emio_gpio_o[0];

    // Direct GPIO Output
    assign gpo[1] = emio_gpio_o[1];

endmodule

module Clock_Divisor_VGA(
    input wire clock,
    input wire reset,
    output reg clock_1S
);

    parameter count_50M = 300000;
    reg [18:0] counter_50M;

    always @(posedge clock or posedge reset) begin
        if (reset) begin
            counter_50M <= 19'd0;
            clock_1S <= 1'b1;
        end else begin
            if (counter_50M == count_50M - 1) begin
                counter_50M <= 19'd0;
                clock_1S <= ~clock_1S;
            end else begin
                counter_50M <= counter_50M + 1'b1;
            end
        end
    end

endmodule

module shift_register #(
    parameter N = 4
) (
    input wire CLK,
    input wire EN,
    input wire in,
    output reg [N-1:0] Q,
    output wire f
);

    // Initialize the shift register to all zeros
    initial begin
        Q = {N{1'b0}};
    end

    // Shift register logic
    always @(posedge CLK) begin
        if (EN) begin
            Q <= {Q[N-2:0], in};
        end
    end

    // Assign flag output
    assign f = Q[3];

endmodule

