module alucontrol(
    input [1:0] aluop,
    input [6:0] funct7,
    input [2:0] funct3,
    output reg [3:0] alucon
);

always @(*) begin
    if (aluop == 2'b10) begin
        alucon = {funct7[5], funct3};
    end
    else if (aluop == 2'b00) begin
        alucon = 4'b0000;
    end
    else if (aluop == 2'b01) begin
        case (funct3)
            3'b000, 3'b001: alucon = 4'b1000;
            3'b100, 3'b101: alucon = 4'b0010;
            3'b110, 3'b111: alucon = 4'b0011;
            default: alucon = 10;
        endcase
    end
    else begin
        alucon = 10;
    end
end

endmodule

module snake(
    input master_clk,
    input up, down, left, right,
    input reset, start,
    output reg VGA_vsync,
    output reg [7:0] VGA_R, VGA_G, VGA_B
);

    // Internal signals
    reg [9:0] xloc, yloc;
    reg [9:0] rand_x, rand_y;
    reg VGA_clk;
    reg [7:0] R, G, B;
    reg [1:0] direction;
    reg body_collision, border_collision, game_over;
    reg [9:0] snakeX[0:99], snakeY[0:99];
    reg [9:0] appleX, appleY;
    parameter BORDERX1 = 20, BORDERX2 = 620, BORDERX3 = 40, BORDERX4 = 600;
    parameter BORDERY1 = 40, BORDERY2 = 440, BORDERY3 = 60, BORDERY4 = 420;
    reg apple_collision, bad_collision;
    reg [6:0] roundcount;

    // Snake movement logic
    always @(posedge master_clk) begin
        if (reset) begin
            direction <= 0;
            snakeX[0] <= BORDERX1 + 20;
            snakeY[0] <= BORDERY1 + 20;
            for (int i = 1; i < 100; i = i + 1) begin
                snakeX[i] <= snakeX[0];
                snakeY[i] <= snakeY[0];
            end
            rand_x <= $urandom_range(BORDERX3, BORDERX4 - 20);
            rand_y <= $urandom_range(BORDERY3, BORDERY4 - 20);
            roundcount <= 0;
        end
        else if (start) begin
            if (up && direction != 2) begin
                direction <= 0;
            end
            else if (down && direction != 0) begin
                direction <= 2;
            end
            else if (left && direction != 1) begin
                direction <= 3;
            end
            else if (right && direction != 3) begin
                direction <= 1;
            end

            for (int i = 99; i > 0; i = i - 1) begin
                snakeX[i] <= snakeX[i-1];
                snakeY[i] <= snakeY[i-1];
            end

            case (direction)
                0: yloc <= yloc - 1;
                1: xloc <= xloc + 1;
                2: yloc <= yloc + 1;
                3: xloc <= xloc - 1;
            endcase

            snakeX[0] <= xloc;
            snakeY[0] <= yloc;

            // Apple collision detection
            apple_collision = (snakeX[0] == appleX && snakeY[0] == appleY);
            if (apple_collision) begin
                rand_x <= $urandom_range(BORDERX3, BORDERX4 - 20);
                rand_y <= $urandom_range(BORDERY3, BORDERY4 - 20);
                roundcount <= roundcount + 1;
            end

            // Border collision detection
            border_collision = (xloc < BORDERX1 || xloc > BORDERX2 || yloc < BORDERY1 || yloc > BORDERY2);

            // Self-collision detection
            bad_collision = 0;
            for (int i = 1; i < 100; i = i + 1) begin
                if (snakeX[0] == snakeX[i] && snakeY[0] == snakeY[i]) begin
                    bad_collision = 1;
                    break;
                end
            end

            game_over = border_collision || bad_collision;
        end
    end

    // VGA output generation
    always @(posedge VGA_clk) begin
        if (game_over) begin
            VGA_vsync <= 1;
            VGA_R <= 8'hff;
            VGA_G <= 8'h00;
            VGA_B <= 8'h00;
        end
        else begin
            VGA_vsync <= 0;
            for (int i = 0; i < 100; i = i + 1) begin
                if (xloc == snakeX[i] && yloc == snakeY[i]) begin
                    VGA_R <= 8'h00;
                    VGA_G <= 8'hff;
                    VGA_B <= 8'h00;
                    break;
                end
                else if (rand_x == xloc && rand_y == yloc) begin
                    VGA_R <= 8'hff;
                    VGA_G <= 8'h00;
                    VGA_B <= 8'h00;
                    break;
                end
                else begin
                    VGA_R <= 8'h80;
                    VGA_G <= 8'h80;
                    VGA_B <= 8'h80;
                end
            end
        end
    end

endmodule

module score(
    input wire clk,
    input wire rst,
    input wire [9:0] mario_posx,
    input wire [9:0] barrel_posx,
    input wire [8:0] mario_posy,
    input wire [8:0] barrel_posy,
    input wire barrel_fall,
    input wire mario_jumping,
    output reg [10:0] count
);

    // State definition
    localparam START = 3'd0;
    localparam DIFFERENT_FLOOR = 3'd1;
    localparam SAME_FLOOR_NO_INTERSECTION = 3'd2;
    localparam SAME_FLOOR_WITH_INTERSECTION = 3'd3;
    localparam GOAL = 3'd4;

    reg [2:0] current_state, next_state;

    // Dimensions
    localparam MARIO_WIDTH = 34;
    localparam MARIO_HEIGHT = 36;
    localparam BARREL_WIDTH_ROLLING = 32;
    localparam BARREL_WIDTH_FALLING = 42;
    localparam BARREL_HEIGHT = 24;
    localparam JUMP_HEIGHT = 60;

    wire same_floor;
    wire intersection;

    // Check if Mario and barrel are on the same floor
    assign same_floor = (barrel_fall) ? 
                        (mario_posy + MARIO_HEIGHT > barrel_posy && mario_posy < barrel_posy + BARREL_HEIGHT) :
                        (mario_posy + MARIO_HEIGHT > barrel_posy && mario_posy < barrel_posy + BARREL_HEIGHT + JUMP_HEIGHT);

    // Check if Mario and barrel intersect horizontally
    assign intersection = (barrel_fall) ?
                          (mario_posx + MARIO_WIDTH > barrel_posx && mario_posx < barrel_posx + BARREL_WIDTH_FALLING) :
                          (mario_posx + MARIO_WIDTH > barrel_posx && mario_posx < barrel_posx + BARREL_WIDTH_ROLLING);

    // State transition logic
    always @(*) begin
        case(current_state)
            START: next_state = DIFFERENT_FLOOR;
            DIFFERENT_FLOOR: 
                if(same_floor && !intersection) next_state = SAME_FLOOR_NO_INTERSECTION;
                else if(same_floor && intersection) next_state = SAME_FLOOR_WITH_INTERSECTION;
                else next_state = DIFFERENT_FLOOR;
            SAME_FLOOR_NO_INTERSECTION:
                if(!same_floor) next_state = DIFFERENT_FLOOR;
                else if(intersection) next_state = SAME_FLOOR_WITH_INTERSECTION;
                else next_state = SAME_FLOOR_NO_INTERSECTION;
            SAME_FLOOR_WITH_INTERSECTION:
                if(!same_floor) next_state = DIFFERENT_FLOOR;
                else if(!intersection) next_state = SAME_FLOOR_NO_INTERSECTION;
                else if(mario_jumping) next_state = GOAL;
                else next_state = SAME_FLOOR_WITH_INTERSECTION;
            GOAL: next_state = DIFFERENT_FLOOR;
            default: next_state = START;
        endcase
    end

    // State and score update
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            current_state <= START;
            count <= 11'd0;
        end else begin
            current_state <= next_state;
            if(current_state == GOAL) count <= count + 1'b1;
        end
    end

endmodule

module I2C_Controller(
    input CLOCK,
    input [23:0] I2C_DATA,
    input GO,
    input W_R,
    input RESET,
    output reg I2C_SCLK,
    output reg I2C_SDAT,
    output reg END,
    output reg ACK,
    output reg [5:0] SD_COUNTER,
    output reg SDO
);

reg [23:0] SD;
reg ACK1, ACK2, ACK3;

always @(posedge CLOCK or negedge RESET) begin
    if (!RESET) begin
        SD <= 24'h0;
        ACK1 <= 1'b0;
        ACK2 <= 1'b0;
        ACK3 <= 1'b0;
        SD_COUNTER <= 6'd0;
        SDO <= 1'b1;
        I2C_SCLK <= 1'b0;
        I2C_SDAT <= 1'bZ;
        END <= 1'b0;
        ACK <= 1'b0;
    end
    else if (GO) begin
        SD <= I2C_DATA;
        if (SD_COUNTER == 6'd0) begin
            SDO <= W_R;
        end
        else if (SD_COUNTER >= 1 && SD_COUNTER <= 24) begin
            SDO <= SD[23 - (SD_COUNTER - 1)];
        end
        else if (SD_COUNTER == 25) begin
            ACK1 <= I2C_SDAT;
        end
        else if (SD_COUNTER == 26) begin
            ACK2 <= I2C_SDAT;
        end
        else if (SD_COUNTER == 27) begin
            ACK3 <= I2C_SDAT;
        end
        else begin
            SDO <= 1'b1;
        end

        I2C_SCLK <= (SD_COUNTER >= 4 && SD_COUNTER <= 30) ? 1'b1 : 1'b0;
        I2C_SDAT <= (SDO == 1'b0) ? 1'b0 : 1'bZ;
        END <= (SD_COUNTER == 6'd35) ? 1'b1 : 1'b0;
        ACK <= (ACK1 & ACK2 & ACK3) ? 1'b1 : 1'b0;
        SD_COUNTER <= SD_COUNTER + 1'b1;
    end
end

endmodule

module peripheral_msi_data_resize_wb #(
    parameter AW  = 32,
    parameter MDW = 32,
    parameter SDW = 8
) (
    input  wire                 clk_i,
    input  wire                 rst_i,

    // Wishbone master interface
    input  wire [AW-1:0]        wbm_adr_i,
    input  wire [MDW-1:0]       wbm_dat_i,
    output wire [MDW-1:0]       wbm_dat_o,
    input  wire                 wbm_we_i,
    input  wire [MDW/8-1:0]     wbm_sel_i,
    input  wire                 wbm_stb_i,
    input  wire                 wbm_cyc_i,
    output wire                 wbm_ack_o,
    output wire                 wbm_err_o,
    output wire                 wbm_rty_o,
    input  wire [2:0]           wbm_cti_i,
    input  wire [1:0]           wbm_bte_i,

    // Wishbone slave interface
    output wire [AW-1:0]        wbs_adr_o,
    output wire [SDW-1:0]       wbs_dat_o,
    input  wire [SDW-1:0]       wbs_dat_i,
    output wire                 wbs_we_o,
    output wire [SDW/8-1:0]     wbs_sel_o,
    output wire                 wbs_stb_o,
    output wire                 wbs_cyc_o,
    input  wire                 wbs_ack_i,
    input  wire                 wbs_err_i,
    input  wire                 wbs_rty_i,
    output wire [2:0]           wbs_cti_o,
    output wire [1:0]           wbs_bte_o
);

    localparam RATIO = MDW / SDW;
    localparam SEL_WIDTH = $clog2(RATIO);

    // Address translation
    assign wbs_adr_o = {wbm_adr_i[AW-1:SEL_WIDTH], {SEL_WIDTH{1'b0}}};

    // Data width conversion
    wire [SEL_WIDTH-1:0] byte_sel = wbm_adr_i[SEL_WIDTH-1:0];

    // Write operation
    assign wbs_dat_o = wbm_dat_i[byte_sel*SDW +: SDW];
    assign wbs_sel_o = wbm_sel_i[byte_sel];

    // Read operation
    genvar i;
    generate
        for (i = 0; i < RATIO; i = i + 1) begin : gen_read_data
            assign wbm_dat_o[i*SDW +: SDW] = (i == byte_sel) ? wbs_dat_i : {SDW{1'b0}};
        end
    endgenerate

    // Control signal passing
    assign wbs_we_o  = wbm_we_i;
    assign wbs_stb_o = wbm_stb_i;
    assign wbs_cyc_o = wbm_cyc_i;
    assign wbs_cti_o = wbm_cti_i;
    assign wbs_bte_o = wbm_bte_i;

    // Response signal passing
    assign wbm_ack_o = wbs_ack_i;
    assign wbm_err_o = wbs_err_i;
    assign wbm_rty_o = wbs_rty_i;

endmodule

module hypercpu_registers #(
    parameter REG_COUNT = 16,
    parameter REG_BITS = $clog2(REG_COUNT),
    parameter SP_ADDR = 4'hE,
    parameter PC_ADDR = 4'hF
)(
    input wire mclk,
    input wire reset,
    input wire [REG_BITS-1:0] read_a_addr,
    input wire [REG_BITS-1:0] read_b_addr,
    input wire [REG_BITS-1:0] write_addr,
    input wire [31:0] write_data,
    input wire write_enable,
    input wire [31:0] next_sp,
    input wire [31:0] next_pc,
    output wire [31:0] read_a_data,
    output wire [31:0] read_b_data,
    output wire [31:0] read_sp,
    output wire [31:0] read_pc
);

    reg [31:0] registers [0:REG_COUNT-1];
    integer i;

    assign read_a_data = registers[read_a_addr];
    assign read_b_data = registers[read_b_addr];
    assign read_sp = registers[SP_ADDR];
    assign read_pc = registers[PC_ADDR];

    always @(negedge mclk or negedge reset) begin
        if (!reset) begin
            for (i = 0; i < REG_COUNT; i = i + 1) begin
                registers[i] <= 32'b0;
            end
        end else begin
            if (write_enable) begin
                registers[write_addr] <= write_data;
            end
            registers[SP_ADDR] <= next_sp;
            registers[PC_ADDR] <= next_pc;
        end
    end

endmodule

module synchSP(
    input CLK,
    input D,
    output Qout
);

wire clk20Hz;
wire debounced_signal;

debounce_divider div_inst (
    .clk100Mhz(CLK),
    .clk20Hz(clk20Hz)
);

debouncer deb_inst (
    .CLK(clk20Hz),
    .Da(D),
    .Qb(debounced_signal)
