module debounce_divider(
    input clk100Mhz,
    output reg clk20Hz
);

reg [21:0] counter = 0;

always @(posedge clk100Mhz) begin
    if (counter == 2_499_999) begin
        counter <= 0;
        clk20Hz <= ~clk20Hz;
    end else begin
        counter <= counter + 1;
    end
end

endmodule

module debouncer(
    input CLK,
    input Da,
    output reg Qb
);

reg Q1;

always @(posedge CLK) begin
    Q1 <= Da;
    Qb <= Q1;
end

endmodule

module singlePulse(
    input CLK,
    input D,
    output reg SP
);

reg Q1;

always @(posedge CLK) begin
    Q1 <= D;
    SP <= D & ~Q1;
end

