module counter_4bit (
    input wire clk,
    input wire reset,
    output reg [3:0] count,
    output reg overflow
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
        overflow <= 1'b0;
    end else begin
        if (count == 4'b1111) begin
            count <= 4'b0000;
            overflow <= 1'b1;
        end else begin
            count <= count + 1'b1;
            overflow <= 1'b0;
        end
    end
end

endmodule

module mux(
    input pressed,
    input [3:0] reg1, reg2, reg3, S, minus, s1, p2, p1,
    input Cout,
    output reg [3:0] out0, out1, out2, out3
);

always @(*) begin
    case(reg3)
        4'd10: begin
            out0 = reg1;
            out1 = reg2;
            out2 = {3'b000, Cout};
            out3 = S;
        end
        4'd13: begin
            out0 = reg1;
            out1 = reg2;
            out2 = minus;
            out3 = s1;
        end
        4'd11: begin
            out0 = reg1;
            out1 = reg2;
            out2 = p2;
            out3 = p1;
        end
        default: begin
            out0 = reg1;
            out1 = reg2;
            out2 = 4'b0000;
            out3 = 4'b0000;
        end
    endcase
end

endmodule

module parameterized_flip_flop #(
    parameter DATA_WIDTH = 32
) (
    input wire clk,
    input wire rst,
    input wire write1_en_i,
    input wire write2_en_i,
    input wire write3_en_i,
    input wire read1_en_i,
    input wire [DATA_WIDTH-1:0] data1_i,
    input wire [DATA_WIDTH-1:0] data2_i,
    input wire [DATA_WIDTH-1:0] data3_i,
    output wire [DATA_WIDTH-1:0] data1_o
);

    reg [DATA_WIDTH-1:0] data_tmp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_tmp <= {DATA_WIDTH{1'b0}};
        end else if (write1_en_i) begin
            data_tmp <= data1_i;
        end else if (write2_en_i) begin
            data_tmp <= data2_i;
        end else if (write3_en_i) begin
            data_tmp <= data3_i;
        end
    end

    assign data1_o = read1_en_i ? data_tmp : {DATA_WIDTH{1'b0}};

endmodule

module sourceout_ctrl_2bit(
    input clk,
    input nRST,
    input [31:0] data_length,
    input [31:0] blank_length,
    input [14:0] fifo_usedw,
    output reg data_en
);

    localparam IDLE = 3'b000;
    localparam WAIT_SEND = 3'b001;
    localparam START_SEND = 3'b010;
    localparam SEND_POS = 3'b011;
    localparam SEND_NEG = 3'b100;

    reg [2:0] state;
    reg [31:0] pos_num, neg_num, count;
    reg [14:0] fifo_usedw_reg;

    always @(posedge clk or negedge nRST) begin
        if (!nRST) begin
            state <= IDLE;
            data_en <= 1'b0;
            count <= 32'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    data_en <= 1'b0;
                    if (fifo_usedw >= 15'h1388) begin // 5000 entries
                        state <= WAIT_SEND;
                    end
                end
                WAIT_SEND: begin
                    if (fifo_usedw >= 15'h1388) begin
                        state <= START_SEND;
                    end
                end
                START_SEND: begin
                    count <= 32'b0;
                    state <= SEND_POS;
                end
                SEND_POS: begin
                    data_en <= 1'b1;
                    count <= count + 1;
                    if (count == pos_num) begin
                        if (neg_num != 0) begin
                            state <= SEND_NEG;
                        end
                        else begin
                            state <= SEND_POS;
                        end
                    end
                end
                SEND_NEG: begin
                    data_en <= 1'b0;
                    count <= count + 1;
                    if (count == neg_num) begin
                        state <= SEND_POS;
                    end
                end
            endcase

            if (fifo_usedw < 15'h1388) begin
                state <= IDLE;
            end

            fifo_usedw_reg <= fifo_usedw;
            pos_num <= (data_length * 32'd2) / 32'd1;
            neg_num <= (blank_length * 32'd2) / 32'd1;
        end
    end

endmodule

module adder_subtractor(
    input [3:0] a,
    input [3:0] b,
    input s,
    output c_out,
    output [3:0] result
);

    wire [3:0] b_xor;
    wire [3:0] carry;

    // XOR b with s to negate b when subtracting
    assign b_xor = b ^ {4{s}};

    // Instantiate full adders
    full_adder fa0 (.a(a[0]), .b(b_xor[0]), .carry_in(s),      .sum(result[0]), .carry_out(carry[0]));
    full_adder fa1 (.a(a[1]), .b(b_xor[1]), .carry_in(carry[0]), .sum(result[1]), .carry_out(carry[1]));
    full_adder fa2 (.a(a[2]), .b(b_xor[2]), .carry_in(carry[1]), .sum(result[2]), .carry_out(carry[2]));
    full_adder fa3 (.a(a[3]), .b(b_xor[3]), .carry_in(carry[2]), .sum(result[3]), .carry_out(c_out));

endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);
    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (b & carry_in) | (a & carry_in);
endmodule

module RSP(
    input CLK, RESET,
    input [3:0] key_row,
    output reg [2:0] key_col,
    output reg [2:0] key_data1,
    output reg [2:0] key_data2
);

reg [1:0] state;
reg [1:0] RANDOM;
reg [1:0] user_number;
reg [1:0] rsp_number;
reg key_stop;
reg clk1, clk2;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        state <= 0;
        key_col <= 0;
        key_data1 <= 0;
        key_data2 <= 0;
        RANDOM <= 0;
        user_number <= 0;
        rsp_number <= 0;
        key_stop <= 0;
        clk1 <= 0;
        clk2 <= 0;
    end
    else begin
        clk1 <= ~clk1;
        clk2 <= ~clk2;

        case (state)
            0: begin // no_scan
                key_col <= 0;
                if (!key_row[0] || !key_row[1] || !key_row[2] || !key_row[3]) begin
                    key_stop <= 1;
                    state <= 1;
                end
                else begin
                    key_stop <= 0;
                    state <= 1;
                end
            end
            1: begin // column1
                key_col <= 1;
                case (key_row)
                    4'b0001: user_number <= 0; // rock
                    4'b0010: user_number <= 1; // paper
                    4'b0100: user_number <= 2; // scissors
                    default: user_number <= 0;
                endcase
                state <= 2;
            end
            2: begin // column2
                key_col <= 2;
                state <= 3;
            end
            3: begin // column3
                key_col <= 3;
                if (key_stop) begin
                    RANDOM <= $random % 3;
                    rsp_number <= RANDOM;
                    case (user_number)
                        0: key_data1 <= 1; // rock
                        1: key_data1 <= 2; // paper
                        2: key_data1 <= 3; // scissors
                        default: key_data1 <= 0;
                    endcase
                    case (rsp_number)
                        0: key_data2 <= 1; // rock
                        1: key_data2 <= 2; // paper
                        2: key_data2 <= 3; // scissors
                        default: key_data2 <= 0;
                    endcase
                end
                state <= 0;
            end
            default: state <= 0;
        endcase
    end
end
endmodule

module exact1or2(
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] C
);

    wire condition_a, condition_b, condition_c;

    assign condition_a = (A == 4'b0001 || A == 4'b0010 || A == 4'b0100 || A == 4'b1000);
    assign condition_b = (B != 4'b0000 && B != 4'b1111);
    assign condition_c = ~^B;  // XNOR reduction

    always @(*) begin
        if (condition_a && condition_b && condition_c)
            C = 8'b01110000;
        else
            C = 8'b00000000;
    end

endmodule

module case4(
    input [7:0] SW,
    input [3:0] B,
    output [7:0] ALUOut
);

    exact1or2 e1or2(
        .A(SW[3:0]),
        .B(SW[7:4]),
        .C(ALUOut)
    );

endmodule

module FullAdder(
    input  [1:0] i_a,
    input  [1:0] i_b,
    input        i_carry,
    output [1:0] o_sum,
    output       o_carry
);

wire w_WIRE_0, w_WIRE_1, w_WIRE_2, w_WIRE_3, w_WIRE_4, w_WIRE_5, w_WIRE_6, w_WIRE_7, w_WIRE_8, w_WIRE_9, w_WIRE_10, w_WIRE_11, w_WIRE_12;

// Sum calculation
assign w_WIRE_0 = i_b[0] ^ i_carry;
assign o_sum[0] = i_a[0] ^ w_WIRE_0;

assign w_WIRE_1 = i_a[1] ^ i_b[1];
assign w_WIRE_2 = i_a[0] & i_b[0];
assign w_WIRE_3 = i_carry & w_WIRE_2;
assign w_WIRE_4 = w_WIRE_1 | w_WIRE_3;
assign o_sum[1] = w_WIRE_4;

// Carry calculation
assign w_WIRE_5 = i_a[0] | i_b[0];
assign w_WIRE_6 = w_WIRE_5 & i_carry;
assign w_WIRE_7 = i_a[1] & i_b[1];
assign w_WIRE_8 = w_WIRE_4 & w_WIRE_6;
assign w_WIRE_9 = w_WIRE_7 | w_WIRE_8;
assign o_carry = w_WIRE_9;

endmodule

module chooser2 (
    input [1:0] op,
    input [7:0] x, y, z,
    output reg [7:0] a, b, c
);

    // Operation mode parameters
    parameter ZERO = 2'b00;
    parameter DT = 2'b01;
    parameter YZAB = 2'b10;
    parameter XZAB = 2'b11;

    always @(*) begin
        case (op)
            ZERO: begin
                a = 8'b0;
                b = 8'b0;
                c = 8'b0;
            end
            DT: begin
                a = x;
                b = y;
                c = z;
            end
            YZAB: begin
                a = y;
                b = z;
                c = x;
            end
            XZAB: begin
                a = x;
                b = z;
                c = y;
            end
            default: begin
                a = 8'bx;
                b = 8'bx;
                c = 8'bx;
            end
        endcase
    end

endmodule

module PipeRegEM (
    input clk,
    input reset,
    input [4:0] WriteRegE,
    input [31:0] InstructionE,
    input [31:0] PCouter8E,
    input [31:0] ReadData2E,
    input [31:0] ALUOutE,
    output reg [4:0] WriteRegM,
    output reg [31:0] InstructionM,
    output reg [31:0] PCouter8M,
    output reg [31:0] ReadData2M,
    output reg [31:0] ALUOutM
);

    always @(posedge clk) begin
        if (reset) begin
            WriteRegM <= 5'b0;
            InstructionM <= 32'b0;
            PCouter8M <= 32'b0;
            ReadData2M <= 32'b0;
            ALUOutM <= 32'b0;
        end else begin
            WriteRegM <= WriteRegE;
            InstructionM <= InstructionE;
            PCouter8M <= PCouter8E;
            ReadData2M <= ReadData2E;
            ALUOutM <= ALUOutE;
        end
    end

endmodule

module ALU (
    input [31:0] read_data_1,
    input [31:0] read_data_2,
    input [2:0] AluCtr,
    output reg [31:0] Alu_Result,
    output Zero
);

    always @(*) begin
        case (AluCtr)
            3'b010: Alu_Result = read_data_1 + read_data_2;
            3'b110: Alu_Result = read_data_1 - read_data_2;
            3'b000: Alu_Result = read_data_1 & read_data_2;
            3'b001: Alu_Result = read_data_1 | read_data_2;
            3'b011: Alu_Result = ~(read_data_1 | read_data_2);
            3'b100: Alu_Result = read_data_1 << read_data_2[4:0];
            3'b101: Alu_Result = read_data_1 >> read_data_2[4:0];
            3'b111: Alu_Result = ($signed(read_data_1) < $signed(read_data_2)) ? 32'd1 : 32'd0;
            default: Alu_Result = 32'd0;
        endcase
    end

    assign Zero = (Alu_Result == 32'd0);

endmodule

module register_file (
    input wire clk,
    input wire reset,
    input wire rg_wrt_en,
    input wire [4:0] rg_wrt_addr,
    input wire [4:0] rg_rd_addr1,
    input wire [4:0] rg_rd_addr2,
    input wire [31:0] rg_wrt_data,
    output wire [31:0] rg_rd_data1,
    output wire [31:0] rg_rd_data2
);

    reg [31:0] register_file [0:31];
    integer i;

    // Asynchronous read
    assign rg_rd_data1 = register_file[rg_rd_addr1];
    assign rg_rd_data2 = register_file[rg_rd_addr2];

    // Synchronous write and reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 32; i = i + 1) begin
                register_file[i] <= 32'b0;
            end
        end else if (rg_wrt_en) begin
            register_file[rg_wrt_addr] <= rg_wrt_data;
        end
    end

endmodule

module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

    wire [4:0] C;
    assign C[0] = CIN;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : full_adder
            assign S[i] = A[i] ^ B[i] ^ C[i];
            assign C[i+1] = (A[i] & B[i]) | (A[i] & C[i]) | (B[i] & C[i]);
        end
    endgenerate

    assign COUT = C[4];

endmodule

module PCPUcontroller (
    input wire myclk,
    input wire button,
    input wire reset,
    output reg sense
);

    // State encoding
    localparam STOP = 2'b00;
    localparam INC  = 2'b01;
    localparam TRAP = 2'b10;

    // State registers
    reg [1:0] state, nextstate;

    // State transition logic
    always @(*) begin
        case (state)
            STOP: nextstate = button ? INC : STOP;
            INC:  nextstate = TRAP;
            TRAP: nextstate = button ? TRAP : STOP;
            default: nextstate = STOP;
        endcase
    end

    // State update
    always @(posedge myclk or posedge reset) begin
        if (reset)
            state <= STOP;
        else
            state <= nextstate;
    end

    // Output logic
    always @(*) begin
        if (reset)
            sense = 1'b0;
        else if (state == INC)
            sense = 1'b1;
        else
            sense = 1'b0;
    end

endmodule

module init (
    input wire clk,
    input wire rst_n,
    input wire en,
    output reg rdy,
    output reg [7:0] addr,
    output reg [7:0] wrdata,
    output reg wren
);

    // State parameters
    localparam RESET = 3'b000;
    localparam LOOP  = 3'b001;
    localparam END   = 3'b010;

    // State register
    reg [2:0] state, next_state;

    // Counter
    reg [8:0] current_count;
    reg counter_count;
    wire [8:0] next_count;

    // Completion flag
    reg is_done;

    // State register
    vDFF_async #(3) state_reg (
        .clk(clk),
        .rst_n(rst_n),
        .d(next_state),
        .q(state)
    );

    // Counter logic
    assign next_count = current_count + 1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_count <= 9'd0;
        else if (counter_count)
            current_count <= (current_count == 9'd256) ? current_count : next_count;
    end

    // Next state logic
    always @(*) begin
        case (state)
            RESET: next_state = en ? LOOP : RESET;
            LOOP:  next_state = is_done ? END : LOOP;
            END:   next_state = END;
            default: next_state = RESET;
        endcase
    end

    // Output and control logic
    always @(*) begin
        rdy = 1'b0;
        addr = 8'd0;
        wrdata = 8'd0;
        wren = 1'b0;
        counter_count = 1'b0;
        is_done = 1'b0;

        case (state)
            RESET: begin
                rdy = 1'b1;
            end
            LOOP: begin
                if (current_count < 9'd256) begin
                    counter_count = 1'b1;
                    addr = current_count[7:0];
                    wrdata = current_count[7:0];
                    wren = 1'b1;
                end else begin
                    is_done = 1'b1;
                end
            end
            END: begin
                rdy = 1'b1;
            end
        endcase
    end

endmodule

// Asynchronous reset D flip-flop module
module vDFF_async #(
    parameter WIDTH = 1
) (
    input wire clk,
    input wire rst_n,
    input wire [WIDTH-1:0] d,
    output reg [WIDTH-1:0] q
);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            q <= {WIDTH{1'b0}};
        else
            q <= d;
    end

endmodule

module combined_system (
    input wire clk,
    input wire [15:0] a,
    input wire [15:0] b,
    input wire [3:0] priority_input,
    output wire [3:0] highest_priority,
    output wire [31:0] final_result
);

    wire [31:0] mult_result;

    // 16-bit signed multiplication module
    signed_multiplier mult (
        .clk(clk),
        .a(a),
        .b(b),
        .result(mult_result)
    );

    // 4-bit priority encoder module
    priority_encoder encoder (
        .clk(clk),
        .input_bits(priority_input),
        .output_binary(highest_priority)
    );

    // Additional functional module
    result_combiner combiner (
        .mult_result(mult_result),
        .highest_priority(highest_priority),
        .final_result(final_result)
    );

endmodule

module signed_multiplier (
    input wire clk,
    input wire [15:0] a,
    input wire [15:0] b,
    output reg [31:0] result
);

    always @(negedge clk) begin
        result <= $signed(a) * $signed(b);
    end

endmodule

module priority_encoder (
    input wire clk,
    input wire [3:0] input_bits,
    output reg [3:0] output_binary
);

    always @(posedge clk) begin
        casez (input_bits)
            4'b1???: output_binary <= 4'd3;
            4'b01??: output_binary <= 4'd2;
            4'b001?: output_binary <= 4'd1;
            4'b0001: output_binary <= 4'd0;
            default: output_binary <= 4'd0;
        endcase
    end

endmodule

module result_combiner (
    input wire [31:0] mult_result,
    input wire [3:0] highest_priority,
    output wire [31:0] final_result
);

    assign final_result = mult_result + {28'b0, highest_priority};

endmodule

module Merge_input_value #(
    parameter RX_COUNT = 4
) (
    input wire clk,
    input wire rst,
    input wire uart_input_dv,
    input wire [7:0] uart_input_data,
    output reg system_instruction_valid,
    output reg [31:0] system_instruction
);

    reg [2:0] rx_counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            rx_counter <= 0;
            system_instruction <= 32'b0;
            system_instruction_valid <= 1'b0;
        end else begin
            system_instruction_valid <= 1'b0;

            if (uart_input_dv) begin
                system_instruction <= {uart_input_data, system_instruction[31:8]};

                if (rx_counter == RX_COUNT - 1) begin
                    rx_counter <= 0;
                    system_instruction_valid <= 1'b1;
                end else begin
                    rx_counter <= rx_counter + 1;
                end
            end
        end
    end

endmodule

module Countbcd (
    input wire clk,
    input wire enable,
    output reg [3:0] out
);

    // Initialize output to 0
    initial begin
        out = 4'b0000;
    end

    always @(posedge clk) begin
        if (enable) begin
            if (out == 4'b1001 || out >= 4'b1010) begin
                // Reset to 0 if count is 9 or in an invalid state (10-15)
                out <= 4'b0000;
            end else begin
                // Increment the counter
                out <= out + 1'b1;
            end
        end
    end

endmodule

