module fifo_1deep #(
    parameter dw = 8
) (
    input wire clk,
    input wire clr,
    input wire we,
    input wire [dw-1:0] dati,
    output reg full,
    output reg [dw-1:0] dato,
    output reg empty,
    input wire re
);

    reg [dw-1:0] buffer;
    reg data_valid;

    always @(posedge clk) begin
        if (clr) begin
            buffer <= {dw{1'bx}};
            dato <= {dw{1'bx}};
            data_valid <= 1'b0;
            full <= 1'b0;
            empty <= 1'b1;
        end else begin
            if (we && (empty || re)) begin
                buffer <= dati;
                data_valid <= 1'b1;
            end

            if (re && data_valid) begin
                dato <= buffer;
                if (!we) begin
                    data_valid <= 1'b0;
                end
            end

            full <= data_valid && !re;
            empty <= !data_valid || (re && !we);
        end
    end

endmodule

