module gen_CLK #(
    parameter N = 200
) (
    input wire clk,
    input wire rst,
    input wire en,
    output reg [19:0] counter_num,
    output reg pulse_counter
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter_num <= 20'd0;
            pulse_counter <= 1'b0;
        end else if (en) begin
            if (counter_num == N - 1) begin
                counter_num <= 20'd0;
                pulse_counter <= 1'b1;
            end else begin
                counter_num <= counter_num + 1'b1;
                pulse_counter <= 1'b0;
            end
        end else begin
            pulse_counter <= 1'b0;
        end
    end

endmodule

// Memory Module
module memory (
    input wire clk,
    input wire [31:0] idata,
    input wire [15:0] addr,
    input wire [1:0] rw,
    output reg [47:0] odata
);

    reg [7:0] mem [0:65535];  // 64KB memory array

    initial begin
        $readmemb("mem_init.txt", mem);
    end

    always @(posedge clk) begin
        case (rw)
            2'b01: mem[addr] <= idata[7:0];  // Write 8 bits
            2'b10: begin  // Write 16 bits
                mem[addr] <= idata[7:0];
                mem[addr+1] <= idata[15:8];
            end
            2'b11: begin  // Write 32 bits
                mem[addr] <= idata[7:0];
                mem[addr+1] <= idata[15:8];
                mem[addr+2] <= idata[23:16];
                mem[addr+3] <= idata[31:24];
            end
        endcase
    end

    always @(posedge clk) begin
        odata <= {mem[addr+5], mem[addr+4], mem[addr+3], mem[addr+2], mem[addr+1], mem[addr]};
    end

endmodule

