module pid_filter(
input wire clk,
input wire resetn,
input wire en,
input wire [15:0] K,
input wire [15:0] AK,
input wire [15:0] B,
input wire [15:0] setpoint,
input wire [15:0] measure,
output wire [15:0] cmd,
output wire dir
);
parameter [31:0] clk_period_ns=8;
parameter [31:0] pid_period_ns=20000000;
// 50Hz PID for RC based ESC
parameter tick_modulo = (pid_period_ns / clk_period_ns) - 1;
reg [nbit[tick_modulo] - 1:0] tick_count;
reg [1:0] cycle_count; reg [1:0] cycle_count_old;
wire en_cycle_counter;
wire reload;
reg [31:0] acc; wire [31:0] sum;
reg [31:0] mult_op;
reg [15:0] op1; reg [15:0] op2;
reg [15:0] mc; reg [15:0] xn; reg [15:0] xnn;
wire xn_sign; wire xnn_sign; wire mc_sign; reg sign; reg sign_latched;
wire latch_res;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      tick_count <= tick_modulo;
    end else begin
      if(reload == 1'b1) begin
        tick_count <= tick_modulo;
      end
      else begin
        tick_count <= tick_count - 1;
      end
    end
  end
  assign reload = tick_count == 0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      cycle_count <= {2{1'b1}};
      cycle_count_old <= {2{1'b0}};
    end else begin
      if(reload == 1'b1) begin
        cycle_count <= {2{1'b1}};
      end
      else if(en_cycle_counter == 1'b1) begin
        cycle_count <= cycle_count - 1;
      end
      cycle_count_old <= cycle_count;
    end
  end
  assign en_cycle_counter = cycle_count != 0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      mult_op <= {32{1'b0}};
    end else begin
      if(reload == 1'b1) begin
        mult_op <= {32{1'b0}};
      end
      else begin
        mult_op <= op1 * op2;
      end
    end
  end
  assign sum = sign_latched == 1'b0 ? acc - (mult_op) : acc + (mult_op);
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      acc <= {32{1'b0}};
      sign_latched <= 1'b0;
    end else begin
      if(reload == 1'b1) begin
        acc <= {32{1'b0}};
      end
      else begin
        acc <= sum;
      end
      sign_latched <= sign;
    end
  end
  // sequence
  // 1) acc += K * xn
  // 2) acc -= AK * xn-1
  // 3) acc += B * mcn-1
  // 4) mcn = acc/1024
  always @(*) begin
    case(cycle_count)
      2'b11 : op1 <= K;
      2'b10 : op1 <= AK;
      2'b01 : op1 <= B;
      default : op1 <= {16{1'b0}};
    endcase
  end
  always @(*) begin
    case(cycle_count)
      2'b11 : op2 <= ( ( $signed(xn) < 0 ) ? -$signed(xn) : xn );
      2'b10 : op2 <= ( ( $signed(xnn) < 0 ) ? -$signed(xnn) : xnn );
      2'b01 : op2 <= ( ( $signed(mc) < 0 ) ? -$signed(mc) : mc );
      default : op2 <= {16{1'b0}};
    endcase
  end
  always @(*) begin
    case(cycle_count)
      2'b11 : sign <= xn_sign;
      2'b10 : sign <=  ~xnn_sign;
      2'b01 : sign <= mc_sign;
      default : sign <= 1'b0;
    endcase
  end
  assign xn_sign = xn > 0 ? 1'b1 : 1'b0;
  assign xnn_sign = xnn > 0 ? 1'b1 : 1'b0;
  assign mc_sign = mc > 0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      xnn <= {16{1'b0}};
      xn <= {16{1'b0}};
    end else begin
      if(reload == 1'b1) begin
        xn <= setpoint - measure;
        xnn <= xn;
      end
    end
  end
  assign latch_res = cycle_count == 0 && cycle_count_old == 1 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      mc <= {16{1'b0}};
    end else begin
      if(latch_res == 1'b1) begin
        mc <= acc[25:10];
      end
    end
  end
  assign cmd = en == 1'b0 ? {16{1'b0}} : mc < 0 ?  ~(mc) : mc;
  assign dir = mc < 0 ? 1'b1 : 1'b0;
endmodule

module pll2(
input wire CLKIN_IN,
output wire CLK0_OUT,
output wire CLK1_OUT,
output wire CLK2_OUT,
output wire CLK3_OUT
);
