wire CLKFBOUT;
wire CLKFB;
wire CLKFBIN;
wire CLKIN;
wire CLK0;
wire CLK0_BUF;
wire CLK1;
wire CLK1_BUF;
wire CLK2;
wire CLK2_BUF;
wire CLK3;
