  PLL_BASE #(
      .BANDWIDTH(9'bOPTIMIZED),
    .CLK_FEEDBACK(8'bCLKFBOUT),
    .COMPENSATION(18'bSYSTEM_SYNCHRONOUS),
    // not sure this is correct
    .DIVCLK_DIVIDE(1),
    .CLKFBOUT_MULT(15),
