    // 480 / 12 = 40 MHZ
    .CLKOUT3_PHASE(0.000),
    .CLKOUT3_DUTY_CYCLE(0.500),
    .CLKIN_PERIOD(31.250),
    .REF_JITTER(0.010))
  INST_PLL(
      // Input clock control
    .CLKIN(CLKIN_IN),
    .CLKFBIN(CLKFBIN),
    // Output clocks
    .CLKFBOUT(CLKFBOUT),
    .CLKOUT0(CLK0),
    .CLKOUT1(CLK1),
    .CLKOUT2(CLK2),
    .CLKOUT3(CLK3),
    .CLKOUT4(/* open */),
    .CLKOUT5(/* open */),
    .LOCKED(/* open */),
    .RST(GND_BIT));
