module keyboard_processor(
input wire Clk,
input wire [1:0] Status,
input wire ps2data,
input wire Reset,
output wire [10:0] SR_Out,
output wire [10:0] PR_Out
);
//takes in modified clock
//from keyboard
//one code
//prev code
reg ClrSR; wire ClrPR;
reg SR_In; reg Ld_SR; reg Ld_PR; reg Shift_En;
wire [10:0] D_In;
wire nreset; wire data;
  assign nreset = Reset;
  assign data = ps2data;
  reg_unit Registers(
      .Clk(Clk),
    .ClrSR(ClrSR),
    .ClrPR(ClrPR),
    .D_In(D_In),
    .SR_In(SR_In),
    .Ld_SR(Ld_SR),
    .Ld_PR(Ld_PR),
    .Shift_En(Shift_En),
    .SR(SR_Out),
    .PR(PR_Out));
  always @(Status, data) begin : P1
  //shift data from prev code into another register
    if((Status == 2'b10)) begin
      Shift_En <= 1'b1;
    end
    else begin
      Shift_En <= 1'b0;
    end
    ClrSR <= nreset;
    ClrPr <= nreset;
    SR_In <= data;
    Ld_SR <= 1'b0;
    Ld_PR <= 1'b0;
  end
endmodule

