module spi_sreg(
input wire clk,
input wire rst,
input wire shift,
input wire load,
input wire [size_g - 1:0] din,
output wire [size_g - 1:0] dout,
input wire sin,
output wire sout
);
parameter [31:0] size_g=8;
//control signals
//shift left
//load parallel
//data signals
//parallel data in (latched)
//parallel data out
//serial data in (to lsb)
//serial data out (from msb)
reg [size_g - 1:0] shiftReg;
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      shiftReg <= {((size_g - 1)-(0)+1){1'b0}};
    end else begin
      if(shift == 1'b1) begin
        shiftReg <= {shiftReg[size_g - 2:0],sin};
      end
      else if(load == 1'b1) begin
        shiftReg <= din;
      end
    end
  end
  assign dout = shiftReg;
  assign sout = shiftReg[size_g - 1];
endmodule

