module g05_comp6(
input wire [5:0] A,
input wire [5:0] B,
output wire AeqB
);
wire SYNTHESIZED_WIRE_0;
wire SYNTHESIZED_WIRE_1;
wire SYNTHESIZED_WIRE_2;
wire SYNTHESIZED_WIRE_3;
wire SYNTHESIZED_WIRE_4;
wire SYNTHESIZED_WIRE_5;
  assign SYNTHESIZED_WIRE_1 =  ~(A[0] ^ B[0]);
  assign SYNTHESIZED_WIRE_2 =  ~(A[1] ^ B[1]);
  assign SYNTHESIZED_WIRE_0 =  ~(A[2] ^ B[2]);
  assign SYNTHESIZED_WIRE_3 =  ~(A[3] ^ B[3]);
  assign SYNTHESIZED_WIRE_4 =  ~(A[4] ^ B[4]);
  assign SYNTHESIZED_WIRE_5 =  ~(A[5] ^ B[5]);
  assign AeqB = SYNTHESIZED_WIRE_0 & SYNTHESIZED_WIRE_1 & SYNTHESIZED_WIRE_2 & SYNTHESIZED_WIRE_3 & SYNTHESIZED_WIRE_4 & SYNTHESIZED_WIRE_5;
endmodule

