module FSM(
input wire clock,
input wire reset,
input wire nivel,
input wire abierto,
input wire cerrado,
input wire [1:0] piso,
input wire [1:0] boton,
output reg [1:0] boton_memoria,
output reg accionador_puerta,
output reg accionador_subir,
output reg accionador_bajar
);
parameter [2:0]
  inicial = 0,
  parado = 1,
  cerrando = 2,
  marcha = 3,
  abriendo = 4;
reg [2:0] presente = inicial;
reg [1:0] bot;  // Almacena botón pulsado      
reg [1:0] piso_ini;  // Piso de partida
  always @(posedge reset, posedge clock) begin
    if(reset == 1'b1) begin
      presente <= inicial;
    end else begin
      case(presente)
      inicial : begin
        // Estado inicial para que se nivele
        if(nivel == 1'b1) begin
          presente <= parado;
        end
      end
      parado : begin
        // Espera la pulsación de un botón
        if((bot != 2'b00) && (bot != piso)) begin
          presente <= cerrando;
        end
      end
      cerrando : begin
        // Cierra la puerta
        if(cerrado == 1'b1) begin
          presente <= marcha;
        end
      end
      marcha : begin
        // Lleva el ascensor a su piso
        if((bot == piso) && (nivel == 1'b1)) begin
          presente <= abriendo;
        end
      end
      abriendo : begin
        // Abre las puertas
        if(abierto == 1'b1) begin
          presente <= parado;
        end
      end
      endcase
    end
  end
  always @(posedge clock) begin
    boton_memoria <= bot;
    case(presente)
    inicial : begin
      // Al encender puede que este entre dos pisos
      if(piso != 2'b01) begin
        accionador_subir <= 1'b0;
        // Bajamos
        accionador_bajar <= 1'b1;
      end
      accionador_puerta <= 1'b0;
      // Cerrada
    end
    parado : begin
      accionador_subir <= 1'b0;
      // Parado
      accionador_bajar <= 1'b0;
      accionador_puerta <= 1'b1;
      // Abierta
    end
    cerrando : begin
      accionador_subir <= 1'b0;
      // Parado
      accionador_bajar <= 1'b0;
      accionador_puerta <= 1'b0;
    end
    marcha : begin
      if(bot < piso_ini) begin
        accionador_subir <= 1'b0;
        // Bajamos
        accionador_bajar <= 1'b1;
      end
      else begin
        accionador_subir <= 1'b1;
        // Subimos
        accionador_bajar <= 1'b0;
      end
      accionador_puerta <= 1'b0;
      // Cerrada
    end
    abriendo : begin
      accionador_subir <= 1'b0;
      // Parado
      accionador_bajar <= 1'b0;
      accionador_puerta <= 1'b1;
      // Abrir
    end
    endcase
  end
  always @(posedge reset, posedge clock, posedge piso) begin : P1
  // Captura la pulsación del botón
      // y el piso donde se encuentra
    if(reset == 1'b1) begin
      bot <= 2'b00;
      piso_ini <= piso;
    end else begin
      if(presente == parado) begin
        if((boton == 2'b01) || (boton == 2'b10) || (boton == 2'b11)) begin
          bot <= boton;
        end
        else begin
          bot <= 2'b00;
          // Cualquier otra combinación no vale
        end
        piso_ini <= piso;
      end
    end
  end
endmodule

module running_avg(
input wire clk,
input wire [size - 1:0] input,
output reg [size - 1:0] output
);
parameter [31:0] size=11;
reg [16 * size - 1:0] buff;
reg [size + 4 - 1:0] summed;
reg [size - 1:0] div;
  always @(posedge clk) begin
    buff[16 * size - 1:1 * size] <= buff[15 * size - 1:0 * size];
    //shift up
    buff[1 * size - 1:0] <= input;
    summed <= ({4'b0000,buff[16 * size - 1:15 * size]}) + ({4'b0000,buff[15 * size - 1:14 * size]}) + ({4'b0000,buff[14 * size - 1:13 * size]}) + ({4'b0000,buff[13 * size - 1:12 * size]}) + ({4'b0000,buff[12 * size - 1:11 * size]}) + ({4'b0000,buff[11 * size - 1:10 * size]}) + ({4'b0000,buff[10 * size - 1:9 * size]}) + ({4'b0000,buff[9 * size - 1:8 * size]}) + ({4'b0000,buff[8 * size - 1:7 * size]}) + ({4'b0000,buff[7 * size - 1:6 * size]}) + ({4'b0000,buff[6 * size - 1:5 * size]}) + ({4'b0000,buff[5 * size - 1:4 * size]}) + ({4'b0000,buff[4 * size - 1:3 * size]}) + ({4'b0000,buff[3 * size - 1:2 * size]}) + ({4'b0000,buff[2 * size - 1:1 * size]}) + ({4'b0000,buff[1 * size - 1:0]});
    div <= summed[size + 4 - 1:4];
    output <= div;
  end
endmodule

