module gclock(
input wire CLOCK_27,
input wire reset,
output wire clock_out
);
reg temporal;
reg [31:0] counter = 0;
  always @(posedge reset, posedge CLOCK_27) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      counter <= 0;
    end else begin
      if((counter == 13499999)) begin
        temporal <=  ~(temporal);
        counter <= 0;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  assign clock_out = temporal;
endmodule

