module Debouncer(
input wire Clock,
input wire Reset,
input wire Input,
output reg Output
);
parameter [31:0] Delay;
reg [31:0] DelayCounter;
reg Internal;
  always @(posedge Clock, posedge Reset) begin
    if(Reset == 1'b1) begin
      Output <= 1'b0;
      Internal <= 1'b0;
      DelayCounter <= 0;
    end else begin
      if(Input != Internal) begin
        Internal <= Input;
        DelayCounter <= 0;
      end
      else if(DelayCounter == Delay) begin
        Output <= Internal;
      end
      else begin
        DelayCounter <= DelayCounter + 1;
      end
    end
  end
endmodule

