module CNE_01200_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_D,
output wire o_Q
);
// Clock signal
// Reset signal
// D Flip-Flop input signal
// D Flip-Flop output signal
reg Q;  // D Flip-Flop output
  //CODE
  // D FlipFlop process
  always @(posedge i_Clock, posedge i_Reset_n) begin
    if((i_Reset_n == 1'b0)) begin
      Q <= 1'b0;
    end else begin
      Q <= i_D;
    end
  end
  //CODE
  assign o_Q = Q;
endmodule

