module MI32_ASYNC_FSMM(
input wire RESET,
input wire CLK,
input wire RD,
input wire WR,
input wire ACK,
output wire REQ,
output wire ARDY,
output wire DONE
);
// ----------------------------------------------------------------------------
//                               Architecture
// ----------------------------------------------------------------------------
parameter [1:0]
  wait_for_op = 0,
  wait_for_ack = 1,
  wait_for_nack = 2;
reg [1:0] fsm;
reg [1:0] fsm_next;
wire sig_req;
wire sig_ardy;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      fsm <= wait_for_op;
    end else begin
      fsm <= fsm_next;
    end
  end
  always @(fsm, RD, WR, ACK) begin
    fsm_next <= fsm;
    case(fsm)
    wait_for_op : begin
      if(RD == 1'b1 || WR == 1'b1) begin
        fsm_next <= wait_for_ack;
      end
    end
    wait_for_ack : begin
      if(ACK == 1'b1) begin
        fsm_next <= wait_for_nack;
      end
    end
    wait_for_nack : begin
      if(ACK == 1'b0) begin
        fsm_next <= wait_for_op;
      end
    end
    endcase
  end
  assign REQ = fsm == wait_for_ack ? 1'b1 : 1'b0;
  assign ARDY = fsm == wait_for_op ? 1'b1 : 1'b0;
  assign DONE = fsm == wait_for_ack && ACK == 1'b1 ? 1'b1 : 1'b0;
endmodule

