module RAMAccessInstrument(
input wire SI,
output wire SO,
input wire SEL,
input wire SE,
input wire CE,
input wire UE,
input wire RST,
input wire TCK,
output wire MEM_SIB_SEL,
input wire [DataSize - 1:0] RAM_data_read,
output wire [DataSize - 1:0] RAM_data_write,
output wire [AddressSize - 1:0] RAM_address_out,
output wire RAM_write_enable
);
parameter [31:0] DataSize=8;
parameter [31:0] AddressSize=8;
// Scan Interface scan_client ----------
// ScanInPort 
// ScanOutPort
// SelectPort
//--------------------------------------   
// ShiftEnPort
// CaptureEnPort
// UpdateEnPort
// ResetPort
// TCKPort
// RAM interface
reg [AddressSize - 1:0] RAM_address; wire [AddressSize - 1:0] RAM_address_update;
reg RAM_addr_inc_reg;
reg RAM_write_enable_internal;
reg RAM_write_enable_strobe;
wire [DataSize - 1:0] RAM_data_write_internal;
reg sib_addr_update_strobe; reg sib_data_update_strobe;
reg sib_addr_toUE_prev; reg sib_data_toUE_prev;
wire [1:0] Addr_service_bits; wire [1:0] Addr_service_bits_update;
wire sib_mem_so; wire sib_data_so; wire sib_addr_so; wire addr_sreg_so; wire service_sreg_so;
wire data_sreg_so;
wire sib_mem_toCE; wire sib_data_toCE; wire sib_addr_toCE;
wire sib_mem_toSE; wire sib_data_toSE; wire sib_addr_toSE;
wire sib_mem_toUE; wire sib_data_toUE; wire sib_addr_toUE;
wire sib_mem_toSEL; wire sib_data_toSEL; wire sib_addr_toSEL;
wire sib_mem_toRST; wire sib_data_toRST; wire sib_addr_toRST;
wire sib_mem_toTCK; wire sib_data_toTCK; wire sib_addr_toTCK;
wire sib_mem_toSI; wire sib_data_toSI; wire sib_addr_toSI;
  assign RAM_address_out = RAM_address;
  assign RAM_data_write = RAM_data_write_internal;
  assign RAM_write_enable = RAM_write_enable_strobe & RAM_write_enable_internal;
  //          .-------.     
  //  SI -----|sib_mem|-- SO      
  //          '-------'  
  //            |    |_________________________________________________.
  //            |                                                      |
  //            |  .----------.                      .------------.    |
  //            '--| sib_data |--------------------->| sib_addr   |----' 
  //               '----------'                      '------------'   
  //                |      |_____________               |      |______________           
  //                |     _____________  |              |   ______   _______  |          
  //                '--->|   data      |-'              '->|we,inc|-|address|-'              
  //                     '-------------'                   '------' '-------'
  // Auto increment bit is MSb in Address shift register
  assign SO = sib_mem_so;
  assign MEM_SIB_SEL = sib_mem_toSEL;
  // Top-level SIB for integration into system's IJTAG network
  SIB_mux_pre sib_mem(
      .SI(SI),
    .SE(SE),
    .UE(UE),
    .CE(CE),
    .SEL(SEL),
    .RST(RST),
    .TCK(TCK),
    .SO(sib_mem_so),
    .fromSO(sib_addr_so),
    .toCE(sib_mem_toCE),
    .toSE(sib_mem_toSE),
    .toUE(sib_mem_toUE),
    .toSEL(sib_mem_toSEL),
    .toRST(sib_mem_toRST),
    .toTCK(sib_mem_toTCK),
    .toSI(sib_mem_toSI));
  // Underlying SIB for efficient access to RAM data
  SIB_mux_pre sib_data(
      .SI(sib_mem_toSI),
    .SE(sib_mem_toSE),
    .UE(sib_mem_toUE),
    .CE(sib_mem_toCE),
    .SEL(sib_mem_toSEL),
    .RST(sib_mem_toRST),
    .TCK(sib_mem_toTCK),
    .SO(sib_data_so),
    .fromSO(data_sreg_so),
    .toCE(sib_data_toCE),
    .toSE(sib_data_toSE),
    .toUE(sib_data_toUE),
    .toSEL(sib_data_toSEL),
    .toRST(sib_data_toRST),
    .toTCK(sib_data_toTCK),
    .toSI(sib_data_toSI));
  // Shift register for RAM data
  SReg #(
      .Size(DataSize))
  data_shiftreg(
      // Scan Interface scan_client ----------
    .SI(sib_data_toSI),
    // Input Port SI = SI
    .SO(data_sreg_so),
    .SEL(sib_data_toSEL),
    .SE(sib_data_toSE),
    .UE(sib_data_toUE),
    .CE(sib_data_toCE),
    .RST(sib_data_toRST),
    .TCK(sib_data_toTCK),
    .DI(RAM_data_read),
    .DO(RAM_data_write_internal));
  // Underlying SIB for setting access address
  SIB_mux_pre sib_addr(
      .SI(sib_data_so),
    .SE(sib_mem_toSE),
    .UE(sib_mem_toUE),
    .CE(sib_mem_toCE),
    .SEL(sib_mem_toSEL),
    .RST(sib_mem_toRST),
    .TCK(sib_mem_toTCK),
    .SO(sib_addr_so),
    .fromSO(addr_sreg_so),
    .toCE(sib_addr_toCE),
    .toSE(sib_addr_toSE),
    .toUE(sib_addr_toUE),
    .toSEL(sib_addr_toSEL),
    .toRST(sib_addr_toRST),
    .toTCK(sib_addr_toTCK),
    .toSI(sib_addr_toSI));
  // Shift register for Address increment bit and write enable bit
  SReg #(
      .Size(2))
  service_bits_shiftreg(
      // Scan Interface scan_client ----------
    .SI(sib_addr_toSI),
    .SO(service_sreg_so),
    .SEL(sib_addr_toSEL),
    .SE(sib_addr_toSE),
    .CE(sib_addr_toCE),
    .UE(sib_addr_toUE),
    .RST(sib_addr_toRST),
    .TCK(sib_addr_toTCK),
    .DI(Addr_service_bits),
    .DO(Addr_service_bits_update));
  assign Addr_service_bits = {RAM_write_enable_internal,RAM_addr_inc_reg};
  // Shift register for RAM address
  SReg #(
      .Size(AddressSize))
  addr_shiftreg(
      // Scan Interface scan_client ----------
    .SI(service_sreg_so),
    .SO(addr_sreg_so),
    .SEL(sib_addr_toSEL),
    .SE(sib_addr_toSE),
    .CE(sib_addr_toCE),
    .UE(sib_addr_toUE),
    .RST(sib_addr_toRST),
    .TCK(sib_addr_toTCK),
    .DI(RAM_address),
    .DO(RAM_address_update));
  always @(negedge TCK) begin
    sib_addr_toUE_prev <= sib_addr_toUE;
    sib_data_toUE_prev <= sib_data_toUE;
    sib_addr_update_strobe <=  ~sib_addr_toUE_prev & sib_addr_toUE & sib_addr_toSEL;
    sib_data_update_strobe <=  ~sib_data_toUE_prev & sib_data_toUE & sib_data_toSEL;
  end
  always @(negedge TCK, negedge RST) begin
    if(RST == 1'b1) begin
      RAM_addr_inc_reg <= 1'b0;
      RAM_write_enable_internal <= 1'b0;
    end else begin
      RAM_addr_inc_reg <= Addr_service_bits_update[0];
      // Auto increment bit
      RAM_write_enable_internal <= Addr_service_bits_update[1];
      // Write enable bit
    end
  end
  always @(negedge TCK, negedge RST) begin
    if(RST == 1'b1) begin
      RAM_write_enable_strobe <= 1'b0;
    end else begin
      RAM_write_enable_strobe <= sib_data_update_strobe;
    end
  end
  always @(negedge TCK, negedge RST) begin
    if(RST == 1'b1) begin
      RAM_address <= {((AddressSize - 1)-(0)+1){1'b0}};
    end else begin
      if(sib_addr_update_strobe == 1'b1) begin
        RAM_address <= RAM_address_update;
      end
      else if(RAM_write_enable_strobe == 1'b1 && RAM_addr_inc_reg == 1'b1) begin
        RAM_address <= (RAM_address) + 1;
      end
    end
  end
endmodule

