module uartParser(
input wire clr,
input wire clk,
input wire txBusy,
input wire [7:0] rxData,
input wire newRxData,
output reg [7:0] txData,
output reg newTxData,
output wire intReq,
input wire intGnt,
input wire [7:0] intRdData,
output wire [AW - 1:0] intAddress,
output reg [7:0] intWrData,
output wire intWrite,
output wire intRead
);
// parameters 
parameter [31:0] AW=8;
// global signals 
// global reset input
// global clock input
// transmit and receive internal interface signals from uart interface
// signs that transmitter is busy
// data byte received
// signs that a new byte was received
// data byte to transmit
// asserted to indicate that there is a new data byte for transmission
// internal bus to register file 
// 
// 
// data read from register file
// address bus to register file
// write data to register file
// write control to register file
// read control to register file
// internal constants 
// main (receive) state machine states
reg [3:0] mainSm;  // main state machine
parameter mainIdle = 4'b0000;
parameter mainWhite1 = 4'b0001;
parameter mainData = 4'b0010;
parameter mainWhite2 = 4'b0011;
parameter mainAddr = 4'b0100;
parameter mainEol = 4'b0101;  // binary mode extension states
parameter mainBinCmd = 4'b1000;
parameter mainBinAdrh = 4'b1001;
parameter mainBinAdrl = 4'b1010;
parameter mainBinLen = 4'b1011;
parameter mainBinData = 4'b1100;  // transmit state machine
reg [2:0] txSm;  // transmit state machine
parameter txIdle = 3'b000;
parameter txHiNib = 3'b001;
parameter txLoNib = 3'b100;
parameter txCharCR = 3'b101;
parameter txCharLF = 3'b110;  // define characters used by the parser
parameter charNul = 8'h00;
parameter charTab = 8'h09;
parameter charLF = 8'h0A;
parameter charCR = 8'h0D;
parameter charSpace = 8'h20;
parameter charZero = 8'h30;
parameter charOne = 8'h31;
parameter charTwo = 8'h32;
parameter charThree = 8'h33;
parameter charFour = 8'h34;
parameter charFive = 8'h35;
parameter charSix = 8'h36;
parameter charSeven = 8'h37;
parameter charEight = 8'h38;
parameter charNine = 8'h39;
parameter charAHigh = 8'h41;
parameter charBHigh = 8'h42;
parameter charCHigh = 8'h43;
parameter charDHigh = 8'h44;
parameter charEHigh = 8'h45;
parameter charFHigh = 8'h46;
parameter charRHigh = 8'h52;
parameter charWHigh = 8'h57;
parameter charALow = 8'h61;
parameter charBLow = 8'h62;
parameter charCLow = 8'h63;
parameter charDLow = 8'h64;
parameter charELow = 8'h65;
parameter charFLow = 8'h66;
parameter charRLow = 8'h72;
parameter charWLow = 8'h77;  // binary extension mode commands - the command is indicated by bits 5:4 of the command byte
parameter binCmdNop = 2'b00;
parameter binCmdRead = 2'b01;
parameter binCmdWrite = 2'b10;
wire dataInHexRange;  // indicates that the received data is in the range of hex number
wire binLastByte;  // last byte flag indicates that the current byte in the command is the last
wire txEndP;  // transmission end pulse
reg readOp;  // read operation flag
reg writeOp;  // write operation flag
reg binReadOp;  // binary mode read operation flag
reg binWriteOp;  // binary mode write operation flag
reg sendStatFlag;  // send status flag
reg addrAutoInc;  // address auto increment mode
reg [7:0] dataParam;  // operation data parameter
reg [3:0] dataNibble;  // data nibble from received character
reg [15:0] addrParam;  // operation address parameter
wire [3:0] addrNibble;  // data nibble from received character
reg [7:0] binByteCount;  // binary mode byte counter
reg [AW - 1:0] iIntAddress;  // 
reg iWriteReq;  // 
reg iIntWrite;  // 
reg readDone;  // internally generated read done flag
reg readDoneS;  // sampled read done
reg [7:0] readDataS;  // sampled read data
reg iReadReq;  // 
reg iIntRead;  // 
reg [7:0] txChar;  // transmit byte from nibble to character conversion
reg sTxBusy;  // sampled tx_busy for falling edge detection
wire [3:0] txNibble;  // nibble value for transmission
// module implementation
// main state machine
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      mainSm <= mainIdle;
    end else begin
      if((newRxData == 1'b1)) begin
        case(mainSm)
                // wait for a read ('r') or write ('w') command
        // binary extension - an all zeros byte enabled binary commands 
        mainIdle : begin
          // check received character
          if((rxData == charNul)) begin
            // an all zeros received byte enters binary mode
            mainSm <= mainBinCmd;
          end
          else if(((rxData == charRLow) || (rxData == charRHigh))) begin
            // on read wait to receive only address field
            mainSm <= mainWhite2;
          end
          else if(((rxData == charWLow) || (rxData == charWHigh))) begin
            // on write wait to receive data and address
            mainSm <= mainWhite1;
          end
          else if(((rxData == charCR) || (rxData == charLF))) begin
            // on new line sta in idle
            mainSm <= mainIdle;
          end
          else begin
            // any other character wait to end of line (EOL)
            mainSm <= mainEol;
          end
          // wait for white spaces till first data nibble 
        end
        mainWhite1 : begin
          // wait in this case until any white space character is received. in any
          // valid character for data value switch to data state. a new line or carriage
          // return should reset the state machine to idle.
          // any other character transitions the state machine to wait for EOL.
          if(((rxData == charSpace) || (rxData == charTab))) begin
            mainSm <= mainWhite1;
          end
          else if((dataInHexRange == 1'b1)) begin
            mainSm <= mainData;
          end
          else if(((rxData == charCR) || (rxData == charLF))) begin
            mainSm <= mainIdle;
          end
          else begin
            mainSm <= mainEol;
          end
          // receive data field
        end
        mainData : begin
          // wait while data in hex range. white space transition to wait white 2 state.
          // CR and LF resets the state machine. any other value cause state machine to
          // wait til end of line.
          if((dataInHexRange == 1'b1)) begin
            mainSm <= mainData;
          end
          else if(((rxData == charSpace) || (rxData == charTab))) begin
            mainSm <= mainWhite2;
          end
          else if(((rxData == charCR) || (rxData == charLF))) begin
            mainSm <= mainIdle;
          end
          else begin
            mainSm <= mainEol;
          end
          // wait for white spaces till first address nibble
        end
        mainWhite2 : begin
          // similar to MAIN_WHITE1
          if(((rxData == charSpace) || (rxData == charTab))) begin
            mainSm <= mainWhite2;
          end
          else if((dataInHexRange == 1'b1)) begin
            mainSm <= mainAddr;
          end
          else if(((rxData == charCR) || (rxData == charLF))) begin
            mainSm <= mainIdle;
          end
          else begin
            mainSm <= mainEol;
          end
          // receive address field
        end
        mainAddr : begin
          // similar to MAIN_DATA
          if((dataInHexRange == 1'b1)) begin
            mainSm <= mainAddr;
          end
          else if(((rxData == charCR) || (rxData == charLF))) begin
            mainSm <= mainIdle;
          end
          else begin
            mainSm <= mainEol;
          end
          // wait to EOL
        end
        mainEol : begin
          // wait for CR or LF to move back to idle
          if(((rxData == charCR) || (rxData == charLF))) begin
            mainSm <= mainIdle;
          end
          // binary extension
          // wait for command - one byte
        end
        mainBinCmd : begin
          // check if command is a NOP command
          if((rxData[5:4] == binCmdNop)) begin
            // if NOP command then switch back to idle state
            mainSm <= mainIdle;
          end
          else begin
            // not a NOP command, continue receiving parameters
            mainSm <= mainBinAdrh;
          end
          // wait for address parameter - two bytes
          // high address byte
        end
        mainBinAdrh : begin
          // switch to next state
          mainSm <= mainBinAdrl;
          // low address byte
        end
        mainBinAdrl : begin
          // switch to next state
          mainSm <= mainBinLen;
          // wait for length parameter - one byte
        end
        mainBinLen : begin
          // check if write command else command reception ended
          if((binWriteOp == 1'b1)) begin
            // wait for write data
            mainSm <= mainBinData;
          end
          else begin
            // command reception has ended
            mainSm <= mainIdle;
          end
          // on write commands wait for data till end of buffer as specified by length parameter
        end
        mainBinData : begin
          // if this is the last data byte then return to idle
          if((binLastByte == 1'b1)) begin
            mainSm <= mainIdle;
          end
          // go to idle
        end
        default : begin
          mainSm <= mainIdle;
        end
        endcase
      end
    end
  end
  // read operation flag
  // write operation flag
  // binary mode read operation flag
  // binary mode write operation flag
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      readOp <= 1'b0;
      writeOp <= 1'b0;
      binReadOp <= 1'b0;
      binWriteOp <= 1'b0;
    end else begin
      if(((mainSm == mainIdle) && (newRxData == 1'b1))) begin
        // the read operation flag is set when a read command is received in idle state and cleared
        // if any other character is received during that state.
        if(((rxData == charRLow) || (rxData == charRHigh))) begin
          readOp <= 1'b1;
        end
        else begin
          readOp <= 1'b0;
        end
        // the write operation flag is set when a write command is received in idle state and cleared 
        // if any other character is received during that state.
        if(((rxData == charWLow) || (rxData == charWHigh))) begin
          writeOp <= 1'b1;
        end
        else begin
          writeOp <= 1'b0;
        end
      end
      if(((mainSm == mainBinCmd) && (newRxData == 1'b1) && (rxData[5:4] == binCmdRead))) begin
        // read command is started on reception of a read command
        binReadOp <= 1'b1;
      end
      else if(((binReadOp == 1'b1) && (txEndP == 1'b1) && (binLastByte == 1'b1))) begin
        // read command ends on transmission of the last byte read
        binReadOp <= 1'b0;
      end
      if(((mainSm == mainBinCmd) && (newRxData == 1'b1) && (rxData[5:4] == binCmdWrite))) begin
        // write command is started on reception of a write command
        binWriteOp <= 1'b1;
      end
      else if(((mainSm == mainBinData) && (newRxData == 1'b1) && (binLastByte == 1'b1))) begin
        binWriteOp <= 1'b0;
      end
    end
  end
  // send status flag - used only in binary extension mode
  // address auto increment - used only in binary extension mode
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      sendStatFlag <= 1'b0;
      addrAutoInc <= 1'b0;
    end else begin
      if(((mainSm == mainBinCmd) && (newRxData == 1'b1))) begin
        // check if a status byte should be sent at the end of the command
        sendStatFlag <= rxData[0];
        // check if address should be automatically incremented or not.
        // Note that when rx_data[1] is set, address auto increment is disabled.
        addrAutoInc <=  ~(rxData[1]);
      end
    end
  end
  // operation data parameter
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      dataParam <= {8{1'b0}};
    end else begin
      if(((mainSm == mainWhite1) && (newRxData == 1'b1) && (dataInHexRange == 1'b1))) begin
        dataParam <= {4'b0000,dataNibble};
      end
      else if(((mainSm == mainData) && (newRxData == 1'b1) && (dataInHexRange == 1'b1))) begin
        dataParam <= {dataParam[3:0],dataNibble};
      end
    end
  end
  // operation address parameter
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      addrParam <= {16{1'b0}};
    end else begin
      if(((mainSm == mainWhite2) && (newRxData == 1'b1) && (dataInHexRange == 1'b1))) begin
        addrParam <= {12'h000,dataNibble};
      end
      else if(((mainSm == mainAddr) && (newRxData == 1'b1) && (dataInHexRange == 1'b1))) begin
        addrParam <= {addrParam[11:0],dataNibble};
        // binary extension
      end
      else if((mainSm == mainBinAdrh)) begin
        addrParam[15:8] <= rxData;
      end
      else if((mainSm == mainBinAdrl)) begin
        addrParam[7:0] <= rxData;
      end
    end
  end
  // binary mode command byte counter is loaded with the length parameter and counts down to zero.
  // NOTE: a value of zero for the length parameter indicates a command of 256 bytes.
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      binByteCount <= {8{1'b0}};
    end else begin
      if(((mainSm == mainBinLen) && (newRxData == 1'b1))) begin
        binByteCount <= rxData;
      end
      else if((((mainSm == mainBinData) && (binWriteOp == 1'b1) && (newRxData == 1'b1)) || ((binReadOp == 1'b1) && (txEndP == 1'b1)))) begin
        // byte counter is updated on every new data received in write operations and for every 
        // byte transmitted for read operations.
        binByteCount <= binByteCount - 1;
      end
    end
  end
  // internal write control and data
  // internal read control
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      iReadReq <= 1'b0;
      iIntRead <= 1'b0;
      iWriteReq <= 1'b0;
      iIntWrite <= 1'b0;
      intWrData <= {8{1'b0}};
    end else begin
      if(((mainSm == mainAddr) && (writeOp == 1'b1) && (newRxData == 1'b1) && (dataInHexRange == 1'b0))) begin
        iWriteReq <= 1'b1;
        intWrData <= dataParam;
        // binary extension mode
      end
      else if(((mainSm == mainBinData) && (binWriteOp == 1'b1) && (newRxData == 1'b1))) begin
        iWriteReq <= 1'b1;
        intWrData <= rxData;
      end
      else if(((intGnt == 1'b1) && (iWriteReq == 1'b1))) begin
        iWriteReq <= 1'b0;
        iIntWrite <= 1'b1;
      end
      else begin
        iIntWrite <= 1'b0;
      end
      if(((mainSm == mainAddr) && (readOp == 1'b1) && (newRxData == 1'b1) && (dataInHexRange == 1'b0))) begin
        iReadReq <= 1'b1;
        // binary extension
      end
      else if(((mainSm == mainBinLen) && (binReadOp == 1'b1) && (newRxData == 1'b1))) begin
        // the first read request is issued on reception of the length byte
        iReadReq <= 1'b1;
      end
      else if(((binReadOp == 1'b1) && (txEndP == 1'b1) && (binLastByte == 1'b0))) begin
        // the next read requests are issued after the previous read value was transmitted and
        // this is not the last byte to be read.
        iReadReq <= 1'b1;
      end
      else if(((intGnt == 1'b1) && (iReadReq == 1'b1))) begin
        iReadReq <= 1'b0;
        iIntRead <= 1'b1;
      end
      else begin
        iIntRead <= 1'b0;
      end
    end
  end
  // internal address
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      iIntAddress <= {((AW - 1)-(0)+1){1'b0}};
    end else begin
      if(((mainSm == mainAddr) && (newRxData == 1'b1) && (dataInHexRange == 1'b0))) begin
        iIntAddress <= addrParam[AW - 1:0];
        // binary extension
      end
      else if(((mainSm == mainBinLen) && (newRxData == 1'b1))) begin
        // sample address parameter on reception of length byte
        iIntAddress <= addrParam[AW - 1:0];
      end
      else if(((addrAutoInc == 1'b1) && (((binReadOp == 1'b1) && (txEndP == 1'b1) && (binLastByte == 1'b0)) || ((binWriteOp == 1'b1) && (iIntWrite == 1'b1))))) begin
        // address is incremented on every read or write if enabled
        iIntAddress <= iIntAddress + 1;
      end
    end
  end
  // read done flag and sampled data read
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      readDone <= 1'b0;
      readDoneS <= 1'b0;
      readDataS <= {8{1'b0}};
    end else begin
      // read done flag
      readDone <= iIntRead;
      // sampled read done
      readDoneS <= readDone;
      // sampled data read
      if((readDone == 1'b1)) begin
        readDataS <= intRdData;
      end
    end
  end
  // transmit state machine and control
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      txSm <= txIdle;
      txData <= {8{1'b0}};
      newTxData <= 1'b0;
    end else begin
      case(txSm)
            // wait for read done indication
      txIdle : begin
        // on end of every read operation check how the data read should be transmitted
        // according to read type: ascii or binary.
        if((readDoneS == 1'b1)) begin
          // on binary mode read transmit byte value
          if((binReadOp == 1'b1)) begin
            // note that there is no need to change state
            txData <= readDataS;
            newTxData <= 1'b1;
          end
          else begin
            txSm <= txHiNib;
            txData <= txChar;
            newTxData <= 1'b1;
          end
          // check if status byte should be transmitted
        end
        else if((((sendStatFlag == 1'b1) && (binReadOp == 1'b1) && (txEndP == 1'b1) && (binLastByte == 1'b1)) || ((sendStatFlag == 1'b1) && (binWriteOp == 1'b1) && (newRxData == 1'b1) && (binLastByte == 1'b1)) || ((mainSm == mainBinCmd) && (newRxData == 1'b1) && (rxData[5:4] == binCmdNop)))) begin
          // send status byte - currently a constant
          txData <= 8'h5A;
          newTxData <= 1'b1;
        end
        else begin
          newTxData <= 1'b0;
        end
      end
      txHiNib : begin
        // wait for transmit to end
        if((txEndP == 1'b1)) begin
          txSm <= txLoNib;
          txData <= txChar;
          newTxData <= 1'b1;
        end
        else begin
          newTxData <= 1'b0;
        end
        // wait for transmit to end
      end
      txLoNib : begin
        if((txEndP == 1'b1)) begin
          txSm <= txCharCR;
          txData <= charCR;
          newTxData <= 1'b1;
        end
        else begin
          newTxData <= 1'b0;
        end
        // wait for transmit to end
      end
      txCharCR : begin
        if((txEndP == 1'b1)) begin
          txSm <= txCharLF;
          txData <= charLF;
          newTxData <= 1'b1;
        end
        else begin
          newTxData <= 1'b0;
        end
        // wait for transmit to end
      end
      txCharLF : begin
        if((txEndP == 1'b1)) begin
          txSm <= txIdle;
        end
        // clear tx new data flag
        newTxData <= 1'b0;
        // return to idle
      end
      default : begin
        txSm <= txIdle;
      end
      endcase
    end
  end
  // sampled tx_busy
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      sTxBusy <= 1'b1;
    end else begin
      sTxBusy <= txBusy;
    end
  end
  // indicates that the received data is in the range of hex number
  assign dataInHexRange = (((rxData >= charZero) && (rxData <= charNine)) || ((rxData >= charAHigh) && (rxData <= charFHigh)) || ((rxData >= charALow) && (rxData <= charFLow))) ? 1'b1 : 1'b0;
  // last byte in command flag
  assign binLastByte = (binByteCount == 8'h01) ? 1'b1 : 1'b0;
  // select the nibble to the nibble to character conversion
  assign txNibble = (txSm == txHiNib) ? readDataS[3:0] : readDataS[7:4];
  // tx end pulse
  assign txEndP = ((txBusy == 1'b0) && (sTxBusy == 1'b1)) ? 1'b1 : 1'b0;
  // character to nibble conversion
  always @(*) begin
    case(rxData)
      charZero : dataNibble <= 4'h0;
      charOne : dataNibble <= 4'h1;
      charTwo : dataNibble <= 4'h2;
      charThree : dataNibble <= 4'h3;
      charFour : dataNibble <= 4'h4;
      charFive : dataNibble <= 4'h5;
      charSix : dataNibble <= 4'h6;
      charSeven : dataNibble <= 4'h7;
      charEight : dataNibble <= 4'h8;
      charNine : dataNibble <= 4'h9;
      charALow : dataNibble <= 4'hA;
      charAHigh : dataNibble <= 4'hA;
      charBLow : dataNibble <= 4'hB;
      charBHigh : dataNibble <= 4'hB;
      charCLow : dataNibble <= 4'hC;
      charCHigh : dataNibble <= 4'hC;
      charDLow : dataNibble <= 4'hD;
      charDHigh : dataNibble <= 4'hD;
      charELow : dataNibble <= 4'hE;
      charEHigh : dataNibble <= 4'hE;
      charFLow : dataNibble <= 4'hF;
      charFHigh : dataNibble <= 4'hF;
      default : dataNibble <= 4'hF;
    endcase
  end
  // nibble to character conversion
  always @(*) begin
    case(txNibble)
      4'h0 : txChar <= charZero;
      4'h1 : txChar <= charOne;
      4'h2 : txChar <= charTwo;
      4'h3 : txChar <= charThree;
      4'h4 : txChar <= charFour;
      4'h5 : txChar <= charFive;
      4'h6 : txChar <= charSix;
      4'h7 : txChar <= charSeven;
      4'h8 : txChar <= charEight;
      4'h9 : txChar <= charNine;
      4'hA : txChar <= charAHigh;
      4'hB : txChar <= charBHigh;
      4'hC : txChar <= charCHigh;
      4'hD : txChar <= charDHigh;
      4'hE : txChar <= charEHigh;
      4'hF : txChar <= charFHigh;
      default : txChar <= charFHigh;
    endcase
  end
  assign intAddress = iIntAddress;
  assign intWrite = iIntWrite;
  assign intRead = iIntRead;
  assign intReq = (iReadReq == 1'b1) ? 1'b1 : (iWriteReq == 1'b1) ? 1'b1 : 1'b0;
endmodule

