module DownCounter(
input wire clk,
input wire rst,
input wire en,
input wire [nbits - 1:0] load_value,
input wire load,
output wire [nbits - 1:0] Q
);
parameter [31:0] nbits=8;
reg [nbits - 1:0] value = 1'b0;
  assign Q = value;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      value <= {((nbits - 1)-(0)+1){1'b0}};
    end
    else begin
      if(load == 1'b1) begin
        value <= load_value;
      end
      else if(en == 1'b1) begin
        value <= (value) - 1;
      end
    end
  end
endmodule

module alt_dspbuilder_case_statement_GN4KF5KLTA(
