module h100(
input wire clk,
input wire reset,
input wire [23:0] E,
output reg T
);
// clock et reset
// entrée/sortie
//-----------------------------------------------------------------------------
//  Partie Opérative
//-----------------------------------------------------------------------------
parameter [1:0]
  LOAD = 0,
  DECR = 1,
  NOOP = 2;
  // la commande courante
reg [1:0] CMD;  // le registre de stockage, compteur des clocks
reg [23:0] R;  // boolean vrai si R est à 0
wire R_IS_NULL;  //-----------------------------------------------------------------------------
// Partie Contrôle
//-----------------------------------------------------------------------------
parameter [1:0]
  ST_LOAD = 0,
  ST_DECR = 1,
  ST_TICK = 2;
reg [1:0] state;
  //-----------------------------------------------------------------------------
  //  Partie Opérative
  //-----------------------------------------------------------------------------
  always @(posedge clk) begin
    if(CMD == LOAD) begin
      // charges 'E' dans le compteur 'R', en multipliant par 2
      R <= E;
    end
    else if(CMD == DECR) begin
      R <= R - 1;
    end
  end
  assign R_IS_NULL = R == 0 ? 1'b1 : 1'b0;
  //-----------------------------------------------------------------------------
  // Partie Contrôle
  //-----------------------------------------------------------------------------
  // Inputs:  R_IS_NULL, state
  // Outputs: T, CMD, state
  //-----------------------------------------------------------------------------
  // fonction de transitition    
  always @(posedge reset, posedge clk) begin
    if(reset == 1'b1) begin
      state <= ST_LOAD;
    end else begin
      case(state)
      ST_LOAD : begin
        state <= ST_DECR;
      end
      ST_DECR : begin
        if(R_IS_NULL == 1'b1) begin
          state <= ST_TICK;
        end
      end
      ST_TICK : begin
        state <= ST_LOAD;
      end
      endcase
    end
  end
  // fonction de sortie    
  always @(*) begin
    case(state)
      ST_TICK : T <= 1'b1;
      default : T <= 1'b0;
    endcase
  end
  always @(*) begin
    case(state)
      ST_LOAD : CMD <= LOAD;
      ST_DECR : CMD <= DECR;
      ST_TICK : CMD <= NOOP;
    endcase
  end
endmodule

