module ALU4(
input wire [3:0] a,
input wire [3:0] b,
input wire [2:0] op,
output wire [3:0] r,
output wire [3:0] m
);
wire [3:0] s_a; wire [3:0] s_b; reg [3:0] s_r;
wire [7:0] s_m;
  assign s_a = a;
  assign s_b = b;
  assign s_m = s_a * s_b;
  always @(*) begin
    case(op)
      3'b000 : s_r <= s_a + s_b;
      3'b001 : s_r <= s_a - s_b;
      3'b010 : s_r <= s_m[3:0];
      3'b011 : s_r <= s_a / s_b;
      3'b100 : s_r <= s_a % s_b;
      3'b101 : s_r <= s_a & s_b;
      3'b110 : s_r <= s_a | s_b;
      3'b111 : s_r <= s_a ^ s_b;
    endcase
  end
  assign r = s_r;
  assign m = (op == 3'b010) ? s_m[7:4] : {4{1'b0}};
endmodule

