module txuart(
input wire clk,
input wire rst,
input wire [7:0] parallell_data_in,
input wire parallell_data_in_valid,
output reg parallell_data_in_sent,
output reg uart_data_out,
output reg busy
);
//*****************************************************************************
//*  DEFINE: Architecture                                                     *
//****************************************************************************
parameter [1:0]
  TXSTATE_IDLE = 0,
  TXSTATE_START = 1,
  TXSTATE_DATA = 2,
  TXSTATE_STOP = 3;
reg [1:0] send_state;
parameter [0:0]
  CLKSTATE_IDLE = 0,
  CLKSTATE_COUNTING = 1;
reg clk_state;
reg [7:0] send_data;
reg uart_clk_re;
  always @(posedge clk, posedge rst) begin : P2
    reg [31:0] uart_clk_cnt = 0;
    if(rst == 1'b1) begin
      uart_clk_cnt = 0;
      uart_clk_re <= 1'b0;
    end else begin
      case(clk_state)
      CLKSTATE_IDLE : begin
        uart_clk_cnt = 0;
        uart_clk_re <= 1'b0;
      end
      CLKSTATE_COUNTING : begin
        //TODO: fix average frequency
        if(uart_clk_cnt == 2604) begin
          uart_clk_re <= 1'b1;
          uart_clk_cnt = 0;
        end
        else begin
          uart_clk_re <= 1'b0;
          uart_clk_cnt = uart_clk_cnt + 1;
        end
      end
      endcase
    end
  end
  //
  // when data_in_valid goes high, start sending out data
  //
  always @(posedge clk, posedge rst) begin : P1
    reg [31:0] send_cnt = 0;
    if(rst == 1'b1) begin
      send_state <= TXSTATE_IDLE;
      clk_state <= CLKSTATE_IDLE;
      send_cnt = 0;
      uart_data_out <= 1'b1;
      parallell_data_in_sent <= 1'b0;
      busy <= 1'b0;
    end else begin
      parallell_data_in_sent <= 1'b0;
      case(send_state)
      TXSTATE_IDLE : begin
        uart_data_out <= 1'b1;
        //high during idle
        busy <= 1'b0;
        clk_state <= CLKSTATE_IDLE;
        send_cnt = 0;
        if((parallell_data_in_valid == 1'b1)) begin
          send_state <= TXSTATE_START;
          clk_state <= CLKSTATE_COUNTING;
          //restart UART clock
          busy <= 1'b1;
          send_data <= parallell_data_in;
        end
      end
      TXSTATE_START : begin
        uart_data_out <= 1'b0;
        //start bit low
        if(uart_clk_re == 1'b1) begin
          send_state <= TXSTATE_DATA;
        end
      end
      TXSTATE_DATA : begin
        uart_data_out <= send_data[send_cnt];
        if(uart_clk_re == 1'b1) begin
          send_cnt = send_cnt + 1;
          if((send_cnt > 7)) begin
            send_state <= TXSTATE_STOP;
          end
        end
      end
      TXSTATE_STOP : begin
        uart_data_out <= 1'b1;
        //stop bit high
        if(uart_clk_re == 1'b1) begin
          parallell_data_in_sent <= 1'b1;
          //transmit done
          send_state <= TXSTATE_IDLE;
          busy <= 1'b0;
        end
      end
      endcase
    end
  end
// *** EOF ***
endmodule

module ClockPrescaler(
output wire clk_25MHZ,
output wire clk_25HZ,
output wire [31:0] GPIO_0,
input wire RST_N,
input wire MCLK
);
//------SYSTEMS signals
reg clk;
reg clkBall;
  always @(posedge MCLK, posedge RST_N) begin : P1
    reg [31:0] timeCount;
    reg [31:0] timeCountBall;
    if(RST_N == 1'b0) begin
      timeCount = 0;
      timeCountBall = 0;
      clk <= 1'b0;
      clkBall <= 1'b0;
    end else begin
      timeCount = timeCount + 1;
      timeCountBall = timeCountBall + 1;
      if(timeCount == 1) begin
        clk <=  ~clk;
        timeCount = 0;
      end
      if(timeCountBall == 1999999) begin
        clkBall <= 1'b1;
        timeCountBall = 0;
      end
      else begin
        clkBall <= 1'b0;
      end
    end
  end
  assign clk_25MHZ = clk;
  assign clk_25HZ = clkBall;
endmodule

