module chenillard(
input wire clk,
input wire reset,
input wire button,
output wire led1,
output wire led2,
output wire led3,
output wire led4
);
parameter [2:0]
  e1 = 0,
  e2 = 1,
  e3 = 2,
  e4 = 3,
  e5 = 4,
  e6 = 5;
reg [2:0] state; reg [2:0] next_state;
  //state register
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      state <= e1;
    end else begin
      state <= next_state;
    end
  end
  //state transition
  always @(state) begin
    case(state)
    e1 : begin
      next_state <= e2;
    end
    e2 : begin
      next_state <= e3;
    end
    e3 : begin
      next_state <= e4;
    end
    e4 : begin
      next_state <= e5;
    end
    e5 : begin
      next_state <= e6;
    end
    e6 : begin
      next_state <= e1;
    end
    endcase
  end
  //output function
  assign led1 = state == e1 ? 1'b1 : 1'b0;
  assign led2 = state == e2 || state == e6 ? 1'b1 : 1'b0;
  assign led3 = state == e3 || state == e5 ? 1'b1 : 1'b0;
  assign led4 = state == e4 ? 1'b1 : 1'b0;
endmodule

