module Dbncr(
input wire clk_i,
input wire sig_i,
output wire pls_o
);
parameter [31:0] NR_OF_CLKS=4095;
// Number of System Clock periods while the incoming signal 
// has to be stable until a one-shot output signal is generated
reg [31:0] cnt;
reg sigTmp;
reg stble; reg stbleTmp;
  always @(posedge clk_i) begin
    if(sig_i == sigTmp) begin
      // Count the number of clock periods if the signal is stable
      if(cnt == (NR_OF_CLKS - 1)) begin
        stble <= sig_i;
      end
      else begin
        cnt <= cnt + 1;
      end
    end
    else begin
      // Reset counter and sample the new signal value
      cnt <= 0;
      sigTmp <= sig_i;
    end
  end
  always @(posedge clk_i) begin
    stbleTmp <= stble;
  end
  // generate the one-shot output signal
  assign pls_o = stbleTmp == 1'b0 && stble == 1'b1 ? 1'b1 : 1'b0;
endmodule

