input wire reset,
input wire sync,
input wire pulse,
input wire set_hr,
input wire set_min,
input wire set_inc,
input wire set_dec,
input wire [3:0] key_code,
input wire key_hit,
output wire [15:0] bcdout,
output wire [3:0] debug
);
wire sync_min; wire inc_min; wire dec_min; wire maxval_min; wire zero_min;
wire sync_hr; wire inc_hr; wire dec_hr;
reg min_key; reg min_up; reg min_down;
reg hour_key; reg hour_up; reg hour_down;
  always @(negedge sync) begin
    // filter out defined button combinations for setting minutes
    min_key <= ( ~set_hr) & set_min & ( ~set_inc) & ( ~set_dec);
    min_up <= ( ~set_hr) & set_min & set_inc & ( ~set_dec);
    min_down <= ( ~set_hr) & set_min & ( ~set_inc) & set_dec;
    // filter out defined button combinations for setting minutes
    hour_key <= set_hr & ( ~set_min) & ( ~set_inc) & ( ~set_dec);
    hour_up <= set_hr & ( ~set_min) & set_inc & ( ~set_dec);
    hour_down <= set_hr & ( ~set_min) & ( ~set_inc) & set_dec;
  end
  // drive minute digits
  assign sync_min = (min_key & key_hit) | (( ~min_key) & sync);
  assign inc_min = min_up | (( ~min_up) & pulse);
  assign dec_min = min_down;
  // drive hour digits
  assign sync_hr = (hour_key & key_hit) | (( ~hour_key) & sync);
  assign inc_hr = hour_up | (( ~hour_up) & maxval_min & pulse);
  assign dec_hr = hour_down;
  // debug signals
  assign debug[3] = inc_min;
  assign debug[2] = dec_min;
  assign debug[1] = sync_min;
  assign debug[0] = sync;
  bcd_counter min(
      .reset(reset),
    .clk(sync_min),
    .set(min_key),
    .inc(inc_min),
    .dec(dec_min),
    .maxval(8'h59),
    .setval(key_code),
    .is_zero(zero_min),
    .is_maxval(maxval_min),
    .bcd(bcdout[7:0]));
  bcd_counter hour(
      .reset(reset),
    .clk(sync_hr),
    .set(hour_key),
    .inc(inc_hr),
    .dec(dec_hr),
    .maxval(8'h23),
    .setval(key_code),
    //is_zero => debug(2),
    //is_maxval => debug(3),
    .bcd(bcdout[15:8]));
endmodule

module g23_YMD_counter(
input wire clock,
input wire reset,
input wire count_enable,
input wire load_enable,
input wire [11:0] y_set,
input wire [3:0] m_set,
input wire [4:0] d_set,
input wire y_inc,
input wire m_inc,
input wire d_inc,
output wire [11:0] years,
output wire [3:0] months,
output wire [4:0] days
);
// ASYNC, Should be connected to the master 50MHz clock.
// ASYNC, When high the counts are all set to zero.
// SYNC, A pulse with a width of 1 master clock cycle.
// SYNC, if high sets count values to Y_Set, M_Set, and D_Set inputs
reg [31:0] y;
reg [31:0] m;
reg [31:0] d;
wire last_year;
wire last_month;
reg last_day;
wire leap_year;
wire mth_31d;
wire mth_30d;
wire mth_29d;
wire mth_28d;
  assign years = y;
  assign months = m;
  assign days = d;
  assign last_year = y >= 2100 ? 1'b1 : 1'b0;
  assign last_month = m >= 12 ? 1'b1 : 1'b0 | y_inc;
  assign leap_year = ((y % 4) == 0 && (y % 100) != 0 && (y % 400) == 0) ? 1'b1 : 1'b0;
  assign mth_31d = (m == 1) || (m == 3) || (m == 5) || (m == 7) || (m == 8) || (m == 10) || (m == 12) ? 1'b1 : 1'b0;
  assign mth_30d = (m == 4) || (m == 6) || (m == 9) || (m == 11) ? 1'b1 : 1'b0;
  assign mth_29d = (m == 2) && leap_year == 1'b1 ? 1'b1 : 1'b0;
  assign mth_28d = (m == 2) && leap_year == 1'b0 ? 1'b1 : 1'b0;
  // The counters are copycats from slide 43 in the VHDL 3 pdf
  // counts from 1 to 31
  always @(posedge reset, posedge clock) begin
    if(reset == 1'b1) begin
      d <= 1;
    end else begin
      last_day <= 1'b0;
      if(load_enable == 1'b1) begin
        d <= D_set;
      end
      if(count_enable == 1'b1 || d_inc == 1'b1) begin
        if(mth_31d == 1'b1 && d < 31) begin
          d <= d + 1;
        end
        else if(mth_30d == 1'b1 && d < 30) begin
          d <= d + 1;
        end
        else if(mth_29d == 1'b1 && d < 29) begin
          d <= d + 1;
        end
        else if(mth_28d == 1'b1 && d < 28) begin
          d <= d + 1;
        end
        else begin
          // RESET EVERYTHING
          d <= 1;
          last_day <= 1'b1;
        end
      end
      //if enable
    end
  end
  // counts from 1 to 12
  always @(posedge reset, posedge clock, posedge last_day) begin
    if(reset == 1'b1) begin
      m <= 1;
    end else begin
      if(load_enable == 1'b1) begin
        m <= M_set;
      end
      if(last_day == 1'b1 || m_inc == 1'b1) begin
        if(last_month == 1'b0) begin
          m <= m + 1;
        end
        else begin
          m <= 1;
        end
        //if load
      end
      //if enable
    end
  end
  // counts from 0 to 4000
  always @(posedge reset, posedge clock, posedge last_month, posedge last_day) begin
    if(reset == 1'b1) begin
      y <= 2000;
    end else begin
      if(load_enable == 1'b1) begin
        y <= Y_set;
      end
      if((last_day == 1'b1 && last_month == 1'b1) || y_inc == 1'b1) begin
        if(last_year == 1'b1) begin
          y <= 2000;
        end
        else begin
          y <= y + 1;
        end
        //if load
      end
      //if enable
    end
  end
endmodule

