module T80se(
input wire RESET_n,
input wire CLK_n,
input wire CLKEN,
input wire WAIT_n,
input wire INT_n,
input wire NMI_n,
input wire BUSRQ_n,
output wire M1_n,
output reg MREQ_n,
output reg IORQ_n,
output reg RD_n,
output reg WR_n,
output wire RFSH_n,
output wire HALT_n,
output wire BUSAK_n,
output wire [15:0] A,
input wire [7:0] DI,
output wire [7:0] DO
);
parameter [31:0] Mode=0;
parameter [31:0] T2Write=0;
parameter [31:0] IOWait=1;
// 0 => Single cycle I/O, 1 => Std I/O cycle
wire IntCycle_n;
wire NoRead;
wire Write;
wire IORQ;
reg [7:0] DI_Reg;
wire [2:0] MCycle;
wire [2:0] TState;
  T80 #(
      .Mode(Mode),
    .IOWait(IOWait))
  u0(
      .CEN(CLKEN),
    .M1_n(M1_n),
    .IORQ(IORQ),
    .NoRead(NoRead),
    .Write(Write),
    .RFSH_n(RFSH_n),
    .HALT_n(HALT_n),
    .WAIT_n(Wait_n),
    .INT_n(INT_n),
    .NMI_n(NMI_n),
    .RESET_n(RESET_n),
    .BUSRQ_n(BUSRQ_n),
    .BUSAK_n(BUSAK_n),
    .CLK_n(CLK_n),
    .A(A),
    .DInst(DI),
    .DI(DI_Reg),
    .DO(DO),
    .MC(MCycle),
    .TS(TState),
    .IntCycle_n(IntCycle_n));
  always @(posedge RESET_n, posedge CLK_n) begin
    if(RESET_n == 1'b0) begin
      RD_n <= 1'b1;
      WR_n <= 1'b1;
      IORQ_n <= 1'b1;
      MREQ_n <= 1'b1;
      DI_Reg <= 8'b00000000;
    end else begin
      if(CLKEN == 1'b1) begin
        RD_n <= 1'b1;
        WR_n <= 1'b1;
        IORQ_n <= 1'b1;
        MREQ_n <= 1'b1;
        if(MCycle == 3'b001) begin
          if(TState == 3'b001 || (TState == 3'b010 && Wait_n == 1'b0)) begin
            RD_n <=  ~IntCycle_n;
            MREQ_n <=  ~IntCycle_n;
            IORQ_n <= IntCycle_n;
          end
          if(TState == 3'b011) begin
            MREQ_n <= 1'b0;
          end
        end
        else begin
          if((TState == 3'b001 || (TState == 3'b010 && Wait_n == 1'b0)) && NoRead == 1'b0 && Write == 1'b0) begin
            RD_n <= 1'b0;
            IORQ_n <=  ~IORQ;
            MREQ_n <= IORQ;
          end
          if(T2Write == 0) begin
            if(TState == 3'b010 && Write == 1'b1) begin
              WR_n <= 1'b0;
              IORQ_n <=  ~IORQ;
              MREQ_n <= IORQ;
            end
          end
          else begin
            if((TState == 3'b001 || (TState == 3'b010 && Wait_n == 1'b0)) && Write == 1'b1) begin
              WR_n <= 1'b0;
              IORQ_n <=  ~IORQ;
              MREQ_n <= IORQ;
            end
          end
        end
        if(TState == 3'b010 && Wait_n == 1'b1) begin
          DI_Reg <= DI;
        end
      end
    end
  end
endmodule

