module p4add(
input wire [N - 1:0] A,
input wire [N - 1:0] B,
input wire Cin,
input wire sign,
output wire [N - 1:0] S,
output wire Cout
);
parameter [31:0] N=32;
parameter [31:0] logN=5;
wire [N / 4:0] carry_pro;
wire [N - 1:0] new_B;
  xor_gen #(
      .N(N))
  xor32(
      B,
    sign,
    new_B);
  carry_tree #(
      .N(N),
    .logN(logN))
  ct(
      A,
    new_B,
    carry_pro[0],
    carry_pro[N / 4:1]);
  sum_gen #(
      .N(N))
  add(
      A,
    new_B,
    carry_pro[N / 4:0],
    S);
  assign carry_pro[0] = Cin ^ sign;
  assign Cout = carry_pro[N / 4];
endmodule

