module shiftR(
input wire [width - 1:0] A,
input wire Ci,
input wire [2:0] OP,
output reg [width - 1:0] S,
output reg Co
);
parameter [31:0] width=8;
  always @(A, OP, Ci) begin
    S[width - 2:0] <= A[width - 1:1];
    Co <= A[0];
    case(OP)
    3'b110 : begin
      //SR0
      S[width - 1] <= 1'b0;
    end
    3'b111 : begin
      //SR1
      S[width - 1] <= 1'b1;
    end
    3'b010 : begin
      //SRX
      S[width - 1] <= A[width - 1];
    end
    3'b000 : begin
      //SRA
      S[width - 1] <= Ci;
    end
    3'b100 : begin
      //RR
      S[width - 1] <= A[0];
    end
    default : begin
      S[width - 1] <= 1'b0;
    end
    endcase
  end
endmodule

