module GAME_CTRL(
input wire CLK,
input wire RST,
input wire WIN,
input wire LOSE,
input wire KEY_W,
input wire KEY_S,
input wire KEY_A,
input wire KEY_D,
output reg GEN5_EN,
output reg [2:0] SCREEN_CODE,
output wire GAME_ON,
output wire [7:0] WATER
);
// clock
// reset
// vyhra
// prohra
// klavesa W
// klavesa S
// klavesa A
// klavesa D
// vygenerovani pocatecnich komponent
// game screen code
// in game or in screen
// voda co tece v nadrzi pred zacatkem hry
// Debug mode for skiping levels
parameter DEBUG = False;
parameter [3:0]
  level1_sc = 0,
  level1 = 1,
  level2_sc = 2,
  level2 = 3,
  level3_sc = 4,
  level3 = 5,
  level4_sc = 6,
  level4 = 7,
  win_sc = 8,
  lose_sc = 9;
reg [3:0] present_st;
reg [3:0] next_st;
reg [24:0] water_speed_counter;
reg [7:0] water_in_progress;
reg game_en;
reg next_part_of_water;
  // Pametova cast stavoveho automatu
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      present_st <= level1_sc;
    end else begin
      present_st <= next_st;
    end
  end
  // Rozhodovaci cast stavoveho automatu
  always @(present_st, KEY_W, KEY_S, KEY_A, KEY_D, WIN, LOSE) begin
    case(present_st)
    level1_sc : begin
      //uvodni obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level1;
      end
      else if((KEY_A == 1'b1 && DEBUG == True)) begin
        next_st <= level2_sc;
      end
      else if((KEY_W == 1'b1 && DEBUG == True)) begin
        next_st <= level3_sc;
      end
      else if((KEY_D == 1'b1 && DEBUG == True)) begin
        next_st <= level4_sc;
      end
      else begin
        next_st <= level1_sc;
      end
    end
    level1 : begin
      //level 1
      if((WIN == 1'b1)) begin
        next_st <= level2_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level1;
      end
    end
    level2_sc : begin
      //level 2 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level2;
      end
      else begin
        next_st <= level2_sc;
      end
    end
    level2 : begin
      //level 2
      if((WIN == 1'b1)) begin
        next_st <= level3_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level2;
      end
    end
    level3_sc : begin
      //level 3 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level3;
      end
      else begin
        next_st <= level3_sc;
      end
    end
    level3 : begin
      //level 3
      if((WIN == 1'b1)) begin
        next_st <= level4_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level3;
      end
    end
    level4_sc : begin
      //level 4 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level4;
      end
      else begin
        next_st <= level4_sc;
      end
    end
    level4 : begin
      //level 4
      if((WIN == 1'b1)) begin
        next_st <= win_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level4;
      end
    end
    win_sc : begin
      //win
      if((KEY_S == 1'b1)) begin
        next_st <= level1_sc;
      end
      else begin
        next_st <= win_sc;
      end
    end
    lose_sc : begin
      //lose
      if((KEY_S == 1'b1)) begin
        next_st <= level1_sc;
      end
      else begin
        next_st <= lose_sc;
      end
    end
    default : begin
      next_st <= level1_sc;
    end
    endcase
  end
  // Vystupni cast stavoveho automatu
  always @(present_st) begin
    case(present_st)
    level1_sc : begin
      // start screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b000;
      game_en <= 1'b0;
    end
    level1 : begin
      // lvl 1
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level2_sc : begin
      // lvl 2 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b100;
      game_en <= 1'b0;
    end
    level2 : begin
      // lvl 2
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level3_sc : begin
      // lvl 3 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b101;
      game_en <= 1'b0;
    end
    level3 : begin
      // lvl 3
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level4_sc : begin
      // lvl 4 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b110;
      game_en <= 1'b0;
    end
    level4 : begin
      // lvl 4
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    win_sc : begin
      // win screen
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b010;
      game_en <= 1'b0;
    end
    lose_sc : begin
      // game over screen
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b011;
      game_en <= 1'b0;
    end
    default : begin
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b000;
      game_en <= 1'b0;
    end
    endcase
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      water_speed_counter <= {25{1'b0}};
      next_part_of_water <= 1'b0;
    end else begin
      if((game_en == 1'b1)) begin
        if((water_speed_counter < 10000000)) begin
          // uprav, pokud chces jinou rychlost. max 1048575
          water_speed_counter <= water_speed_counter + 1;
          next_part_of_water <= 1'b0;
        end
        else begin
          water_speed_counter <= {25{1'b0}};
          next_part_of_water <= 1'b1;
        end
      end
      else begin
        water_speed_counter <= {25{1'b0}};
        next_part_of_water <= 1'b0;
      end
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      water_in_progress <= {8{1'b0}};
    end else begin
      if((game_en == 1'b1)) begin
        if((next_part_of_water == 1'b1)) begin
          if((water_in_progress < 255)) begin
            water_in_progress <= water_in_progress + 1;
          end
          else begin
            water_in_progress <= 255;
          end
        end
      end
      else begin
        water_in_progress <= {8{1'b0}};
      end
    end
  end
  assign WATER = water_in_progress;
  assign GAME_ON = game_en;
endmodule

module BCD_CNT(
input wire CLK,
input wire RESET,
output reg [11:0] DOUT12
);
reg [11:0] BCD_CNT_REG;
  always @(posedge CLK) begin
    DOUT12 <= BCD_CNT_REG;
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[3:0] <= {4{1'b0}};
    end else begin
      //低4位遇9变0
      if((BCD_CNT_REG[3:0] == 4'b1001)) begin
        BCD_CNT_REG[3:0] <= {4{1'b0}};
      end
      else begin
        BCD_CNT_REG[3:0] <= BCD_CNT_REG[3:0] + 1;
      end
    end
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[7:4] <= {4{1'b0}};
    end else begin
      //中间4位先判断是否有低4位的进位，有才会计数
      if((BCD_CNT_REG[3:0] == 4'b1001)) begin
        if((BCD_CNT_REG[7:4] == 4'b1001)) begin
          BCD_CNT_REG[7:4] <= {4{1'b0}};
        end
        else begin
          BCD_CNT_REG[7:4] <= BCD_CNT_REG[7:4] + 1;
        end
      end
      else begin
        BCD_CNT_REG[7:4] <= BCD_CNT_REG[7:4];
      end
    end
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[11:8] <= {4{1'b0}};
    end else begin
      //高4位先判断是否有来自中间4位的进位
      if((BCD_CNT_REG[7:4] == 4'b1001)) begin
        if((BCD_CNT_REG[11:8] == 4'b1001)) begin
          BCD_CNT_REG[11:8] <= {4{1'b0}};
        end
        else begin
          BCD_CNT_REG[11:8] <= BCD_CNT_REG[11:8] + 1;
        end
      end
      else begin
        BCD_CNT_REG[11:8] <= BCD_CNT_REG[11:8];
      end
    end
  end
endmodule

module gpio_port(
input wire rst_n_i,
input wire wb_clk_i,
input wire [2:0] wb_addr_i,
input wire [31:0] wb_data_i,
output wire [31:0] wb_data_o,
input wire wb_cyc_i,
input wire [3:0] wb_sel_i,
input wire wb_stb_i,
input wire wb_we_i,
output wire wb_ack_o,
inout wire [31:0] gpio_pins_b
);
// our port :)
wire [31:0] gpio_ddr;
wire [31:0] gpio_psr;
wire [31:0] gpio_pdr;
wire gpio_pdr_wr;
wire [31:0] gpio_sopr;
wire gpio_sopr_wr;
wire [31:0] gpio_copr;
wire gpio_copr_wr;  // regsiter containing current output state
reg [31:0] gpio_reg;  // registers for synchronization of input pins
reg [31:0] gpio_pins_sync1;
reg [31:0] gpio_pins_sync0;
  // syn
  wb_slave_gpio_port wb_slave(
      .rst_n_i(rst_n_i),
    .wb_clk_i(wb_clk_i),
    .wb_addr_i(wb_addr_i),
    .wb_data_i(wb_data_i),
    .wb_data_o(wb_data_o),
    .wb_cyc_i(wb_cyc_i),
    .wb_sel_i(wb_sel_i),
    .wb_stb_i(wb_stb_i),
    .wb_we_i(wb_we_i),
    .wb_ack_o(wb_ack_o),
    .gpio_ddr_o(gpio_ddr),
    .gpio_psr_i(gpio_pins_sync1),
    .gpio_pdr_o(gpio_pdr),
    .gpio_pdr_wr_o(gpio_pdr_wr),
    .gpio_sopr_o(gpio_sopr),
    .gpio_sopr_wr_o(gpio_sopr_wr),
    .gpio_copr_o(gpio_copr),
    .gpio_copr_wr_o(gpio_copr_wr));
  always @(posedge wb_clk_i, posedge rst_n_i) begin
      // process
    if((rst_n_i == 1'b0)) begin
      gpio_reg <= {32{1'b0}};
    end else begin
      if((gpio_pdr_wr == 1'b1)) begin
        // write operation to "PDR" register -
        // set the new values of GPIO outputs
        gpio_reg <= gpio_pdr;
      end
      if((gpio_sopr_wr == 1'b1)) begin
        // write to "SOPR" reg - set ones
        for (i=0; i <= 31; i = i + 1) begin
          if((gpio_sopr[i] == 1'b1)) begin
            gpio_reg[i] <= 1'b1;
          end
        end
      end
      if((gpio_copr_wr == 1'b1)) begin
        // write to "COPR" reg - set zeros
        for (i=0; i <= 31; i = i + 1) begin
          if((gpio_copr[i] == 1'b1)) begin
            gpio_reg[i] <= 1'b0;
          end
        end
      end
    end
  end
  // synchronizing process for input pins
  always @(posedge wb_clk_i, posedge rst_n_i) begin
      // process
    if((rst_n_i == 1'b0)) begin
      gpio_pins_sync0 <= {32{1'b0}};
      gpio_pins_sync1 <= {32{1'b0}};
    end else begin
      gpio_pins_sync0 <= gpio_pins_b;
      gpio_pins_sync1 <= gpio_pins_sync0;
    end
  end
  // generate the tristate buffers for I/O pins
  genvar i;
  generate for (i=0; i <= 31; i = i + 1) begin: gen_tristates
      assign gpio_pins_b[i] = gpio_ddr[i] == 1'b1 ? gpio_reg[i] : 1'bZ;
  end
  endgenerate
endmodule

