module gpio(
input wire clock,
input wire reset_n,
input wire [7:0] data_in,
output reg [7:0] data_out,
input wire [3:0] address,
input wire rd_n,
input wire wr_n,
input wire cs_n,
inout wire [7:0] pa,
inout wire [7:0] pb
);
// Processor interface
// Global clock
// Active low reset
// GPIO Ports (for connection to the outside world)
reg [7:0] porta;
reg [7:0] portb;
reg [7:0] ddra;
reg [7:0] ddrb;
reg [7:0] pina;
reg [7:0] pinb;
  genvar i;
  generate for (i=0; i <= 7; i = i + 1) begin: gen_port
      assign pa[i] = ddra[i] == 1'b0 ? porta[i] : 1'bZ;
    assign pb[i] = ddrb[i] == 1'b0 ? portb[i] : 1'bZ;
  end
  endgenerate
  always @(posedge clock) begin
    if((reset_n == 1'b0)) begin
      porta <= 8'h00;
      portb <= 8'h00;
      ddra <= 8'hFF;
      ddrb <= 8'hFF;
    end
    else if((wr_n == 1'b0 && cs_n == 1'b0)) begin
      case(address)
      4'b0000 : begin
        porta <= data_in;
      end
      4'b0001 : begin
        porta <= data_in | porta;
      end
      4'b0010 : begin
        porta <= ( ~data_in) & porta;
      end
      4'b0011 : begin
        porta <= data_in ^ porta;
      end
      4'b0100 : begin
        ddra <= data_in;
      end
      4'b0101 : begin
        ddra <= data_in | ddra;
      end
      4'b0110 : begin
        ddra <= ( ~data_in) & ddra;
      end
      4'b0111 : begin
        ddra <= data_in ^ ddra;
      end
      4'b1000 : begin
        portb <= data_in;
      end
      4'b1001 : begin
        portb <= data_in | portb;
      end
      4'b1010 : begin
        portb <= ( ~data_in) & portb;
      end
      4'b1011 : begin
        portb <= data_in ^ portb;
      end
      4'b1100 : begin
        ddrb <= data_in;
      end
      4'b1101 : begin
        ddrb <= data_in | ddrb;
      end
      4'b1110 : begin
        ddrb <= ( ~data_in) & ddrb;
      end
      4'b1111 : begin
        ddrb <= data_in ^ ddrb;
      end
      default : begin
      end
      endcase
    end
  end
  always @(address, pina, pinb, ddra, ddrb, rd_n, cs_n) begin
    if((rd_n == 1'b0 && cs_n == 1'b0)) begin
      case(address[3:2])
      2'b00 : begin
        data_out <= pina;
      end
      2'b01 : begin
        data_out <= ddra;
      end
      2'b10 : begin
        data_out <= pinb;
      end
      2'b11 : begin
        data_out <= ddrb;
      end
      default : begin
        data_out <= 8'h00;
      end
      endcase
    end
    else begin
      data_out <= 8'h00;
    end
  end
  always @(posedge clock) begin
    pina <= pa;
    pinb <= pb;
  end
endmodule

