module clk_gen(
input wire clk,
input wire reset,
output wire clk_out
);
parameter [31:0] CLOCK_SPEED=50000000;
parameter [31:0] REQUIRED_HZ=1;
parameter COUNT_MAX = CLOCK_SPEED / (REQUIRED_HZ * 2);
reg [31:0] count = 0;
reg clk_s;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      count <= 0;
      clk_s <= 1'b0;
    end else begin
      if(count == (COUNT_MAX - 1)) begin
        count <= 0;
        if(clk_s == 1'b1) begin
          clk_s <= 1'b0;
        end
        else begin
          clk_s <= 1'b1;
        end
      end
      else begin
        count <= count + 1;
      end
    end
  end
  assign clk_out = clk_s;
endmodule

