module vga_controller(
input wire clk,
input wire rst,
output reg hs,
output reg vs,
output reg blank,
output reg [9:0] hpix,
output reg [9:0] vpix
);
// horizontal timing
// sync pulse
parameter [31:0] H_S=800;
parameter [31:0] H_DISP=640;
parameter [31:0] H_FP=16;
parameter [31:0] H_PW=96;
parameter [31:0] H_BP=48;
parameter [31:0] V_S=521;
parameter [31:0] V_DISP=480;
parameter [31:0] V_FP=10;
parameter [31:0] V_PW=2;
parameter [31:0] V_BP=29;
// assuming a clock of 25MHz
// reset (synchronous)
// Horizontal sync pulse. Active low
// Vertical sync pulse. Active low
// Blanking interval indicator.  Active low.
// Color to monitor should be black when active
// (ie, AND this signal with your color signals).
// horizontal coordinate
// vertical coordinate
//
// Constants
parameter hVisible = H_DISP;
parameter hSyncStart = H_DISP + H_FP;
parameter hSyncEnd = H_DISP + H_FP + H_PW;
parameter hTotalCount = H_DISP + H_FP + H_PW + H_BP;
parameter vVisible = V_DISP;
parameter vSyncStart = V_DISP + V_FP;
parameter vSyncEnd = V_DISP + V_FP + V_PW;
parameter vTotalCount = V_DISP + V_FP + V_PW + V_BP;  //
// Signals
reg nextHsync;
reg nextVsync;
reg [10:0] vCounter = 1'b0;
wire [11:0] hCounter = 1'b0;  //
  always @(posedge clk) begin
    hs <= nextHsync;
    vs <= nextVsync;
    hpix <= hCounter[9:0];
    vpix <= vCounter[9:0];
    //
    if(((hCounter < hVisible) && (vCounter < vVisible))) begin
      blank <= 1'b1;
    end
    else begin
      blank <= 1'b0;
    end
    //
    if((hCounter != (hTotalCount - 1))) begin
      hcounter <= hcounter + 1;
    end
    else begin
      hcounter <= {1{1'b0}};
      if((vCounter == (vTotalCount - 1))) begin
        vCounter <= {11{1'b0}};
      end
      else begin
        vCounter <= vCounter + 1;
      end
    end
    //
    if(((hcounter >= hSyncStart) && (hcounter < hSyncEnd))) begin
      nextHsync <= 1'b0;
    end
    else begin
      nextHsync <= 1'b1;
    end
    //
    if(((vcounter >= vSyncStart) && (vcounter < vSyncEnd))) begin
      nextVsync <= 1'b1;
    end
    else begin
      nextVsync <= 1'b0;
    end
  end
endmodule

module oneshot(
input wire CLK,
input wire RESET,
input wire ONESHOT_IN,
output wire ONESHOT_OUT
);
parameter [31:0] SIZE=22;
reg [SIZE - 1:0] COUNTER;
wire [SIZE - 1:0] ONES;
reg LOCK;
  assign ONES = {((SIZE - 1)-(0)+1){1'b1}};
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      LOCK <= 1'b0;
      COUNTER <= {((SIZE - 1)-(0)+1){1'b0}};
    end
    else begin
      if(ONESHOT_IN == 1'b1) begin
        LOCK <= 1'b1;
      end
      if(LOCK == 1'b1) begin
        if(COUNTER != ONES) begin
          COUNTER <= COUNTER + 1;
        end
        else begin
          LOCK <= 1'b0;
          COUNTER <= {((SIZE - 1)-(0)+1){1'b0}};
        end
      end
    end
  end
  assign ONESHOT_OUT = LOCK;
endmodule

