module pwm(
input wire clk,
input wire masterReset,
input wire en,
input wire [7:0] duty,
output reg pwm_out
);
parameter [31:0] sys_clk=100000000;
parameter [31:0] pwm_freq=50;
parameter period = sys_clk / pwm_freq;
reg [31:0] count = 0;
reg [31:0] duty_cycle = 0;
  always @(posedge clk, posedge masterReset) begin
    if((masterReset == 1'b1)) begin
      count <= 0;
      pwm_out <= 1'b1;
    end else begin
      if((en == 1'b1)) begin
        duty_cycle <= ((duty) * period) / ((2 ** 8) - 1);
      end
      else begin
        if((count == (period - 1))) begin
          count <= 0;
          pwm_out <= 1'b1;
        end
        else begin
          count <= count + 1;
        end
        if((count < duty_cycle)) begin
          pwm_out <= 1'b1;
        end
        else if((count >= duty_cycle)) begin
          pwm_out <= 1'b0;
        end
      end
    end
  end
endmodule

