);
parameter [31:0] NBIT=8;
parameter POL=1'b1;
reg [NBIT - 1:0] Qp;
reg old_value = 1'b0;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      Qp <= {((NBIT - 1)-(0)+1){1'b0}};
      old_value <= 1'b0;
    end else begin
      if(sraz == 1'b1) begin
        Qp <= {((NBIT - 1)-(0)+1){1'b0}};
