module four_bit_comparator(
input wire [3:0] a,
input wire [3:0] b,
input wire l,
input wire g,
input wire e,
output wire eq,
output wire gt,
output wire lt
);
wire a0_b0_eq; wire a0_b0_gt; wire a0_b0_lt;
wire a1_b1_eq; wire a1_b1_gt; wire a1_b1_lt;
wire a2_b2_eq; wire a2_b2_gt; wire a2_b2_lt;
wire a3_b3_eq; wire a3_b3_gt; wire a3_b3_lt;
  assign a0_b0_gt = a[0] & ( ~b[0]);
  assign a0_b0_lt = ( ~a[0]) & b[0];
  assign a0_b0_eq = a[0] ^ b[0];
  assign a1_b1_gt = a[1] & ( ~b[1]);
  assign a1_b1_lt = ( ~a[1]) & b[1];
  assign a1_b1_eq = a[1] ^ b[1];
  assign a2_b2_gt = a[2] & ( ~b[2]);
  assign a2_b2_lt = ( ~a[2]) & b[2];
  assign a2_b2_eq = a[2] ^ b[2];
  assign a3_b3_gt = a[3] & ( ~b[3]);
  assign a3_b3_lt = ( ~a[3]) & b[3];
  assign a3_b3_eq = a[3] ^ b[3];
  assign eq = a3_b3_eq & a2_b2_eq & a1_b1_eq & a0_b0_eq;
  assign gt = a3_b3_gt | (a2_b2_gt & a3_b3_eq) | (a1_b1_gt & a2_b2_eq & a3_b3_eq) | (a0_b0_gt & a1_b1_eq & a2_b2_eq & a3_b3_eq);
  assign lt = a3_b3_lt | (a2_b2_lt & a3_b3_eq) | (a1_b1_lt & a2_b2_eq & a3_b3_eq) | (a0_b0_lt & a1_b1_eq & a2_b2_eq & a3_b3_eq);
endmodule

