  assign PIN38 = EMode_n == 1'b0 ? LIC : 1'bZ;
  assign EXTAL = EMode_n == 1'b0 ? 1'b0 : PIN38;
  assign TSC = EMode_n == 1'b0 ? PIN39 : 1'b0;
