  // A locally generated test clock
  // 1.8457 MHz in E     Mode (6809E) so it can drive E     (PIN34)
  // 7.3728 MHz in Normal Mode (6809) so it can drive EXTAL (PIN38)
  assign clock_test = EMode_n == 1'b0 ? clk_count[1] : clock7_3728;
  // Quadrature clock generator, unused in 6809E mode
  always @(posedge EXTAL) begin
    if((MRDY == 1'b1)) begin
      if((quadrature == 2'b00)) begin
        quadrature <= 2'b01;
      end
      else if((quadrature == 2'b01)) begin
        quadrature <= 2'b11;
      end
      else if((quadrature == 2'b11)) begin
        quadrature <= 2'b10;
      end
      else begin
        quadrature <= 2'b00;
      end
    end
  end
  // Seperate piece of circuitry that emits a 7.3728MHz clock
  DCM1 inst_dcm1(
      .CLKIN_IN(clock49),
    .CLK0_OUT(clock7_3728),
    .CLK0_OUT1(/* open */),
    .CLK2X_OUT(/* open */));
  always @(posedge clock7_3728) begin
    clk_count <= clk_count + 1;
  end
endmodule

module output_queue_control(
input wire clk,
input wire reset,
input wire [FABRIC_DATA_WIDTH - 1:0] oqctrl_in_data,
input wire oqctrl_in_valid,
input wire [FRAME_LENGTH_WIDTH - 1:0] oqctrl_in_length,
input wire [VLAN_PRIO_WIDTH - 1:0] oqctrl_in_prio,
input wire [TIMESTAMP_WIDTH - 1:0] oqctrl_in_timestamp,
output reg [NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_B - 1:0] oqctrl_out_mem_wr_addr,
output reg oqctrl_out_mem_wenable,
output reg [OQ_MEM_ADDR_WIDTH_A - 1:0] oqctrl_out_mem_addr,
output wire [FABRIC_DATA_WIDTH - 1:0] oqctrl_out_mem_data,
output reg oqctrl_out_fifo_wenable,
output reg [OQ_FIFO_DATA_WIDTH - 1:0] oqctrl_out_fifo_data,
output wire [VLAN_PRIO_WIDTH - 1:0] oqctrl_out_fifo_prio
);
parameter [31:0] FABRIC_DATA_WIDTH;
parameter [31:0] FRAME_LENGTH_WIDTH;
parameter [31:0] NR_OQ_FIFOS;
parameter [31:0] VLAN_PRIO_WIDTH;
parameter [31:0] TIMESTAMP_WIDTH;
parameter [31:0] OQ_MEM_ADDR_WIDTH_A;
parameter [31:0] OQ_MEM_ADDR_WIDTH_B;
parameter [31:0] OQ_FIFO_DATA_WIDTH;
parameter [31:0] FABRIC2TRANSMITTER_DATA_WIDTH_RATIO;
// input interface fabric
// output interface memory check
// output interface memory
// output interface fifo
// state machine
parameter [0:0]
  IDLE = 0,
  WRITE_MEM = 1;
  // state signals
reg cur_state;
reg nxt_state;  // config_output_state machine signals
reg read_reg_sig = 1'b0;
reg update_cnt_sig = 1'b0;
reg reset_frame_length_sig = 1'b0;
reg update_mem_ptr_sig = 1'b0;  // process registers
reg [FRAME_LENGTH_WIDTH - 1:0] frame_length_cnt;
reg [FRAME_LENGTH_WIDTH - 1:0] frame_length_reg;
reg [TIMESTAMP_WIDTH - 1:0] timestamp_reg;
reg [VLAN_PRIO_WIDTH - 1:0] prio_reg;
reg [NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:0] mem_start_ptr_reg;
wire [VLAN_PRIO_WIDTH - 1:0] high_priority_border_value_reg = 3'b001;
  // next state logic
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      cur_state <= IDLE;
    end
    else begin
      cur_state <= nxt_state;
    end
  end
  // Decode next data_input_state, combinitorial logic
  always @(cur_state, oqctrl_in_valid, frame_length_cnt, frame_length_reg) begin
    // default signal assignments
    nxt_state <= IDLE;
    read_reg_sig <= 1'b0;
    update_cnt_sig <= 1'b0;
    reset_frame_length_sig <= 1'b0;
    update_mem_ptr_sig <= 1'b0;
    oqctrl_out_mem_wenable <= 1'b0;
    oqctrl_out_fifo_wenable <= 1'b0;
    case(cur_state)
    IDLE : begin
      if(oqctrl_in_valid == 1'b1) begin
        nxt_state <= WRITE_MEM;
        read_reg_sig <= 1'b1;
        // read_reg_p
        update_cnt_sig <= 1'b1;
        // cnt_frame_length_p
        oqctrl_out_mem_wenable <= 1'b1;
      end
    end
    WRITE_MEM : begin
      nxt_state <= WRITE_MEM;
      if(frame_length_cnt >= frame_length_reg) begin
        nxt_state <= IDLE;
        reset_frame_length_sig <= 1'b1;
        // cnt_frame_length_p
        oqctrl_out_fifo_wenable <= 1'b1;
        update_mem_ptr_sig <= 1'b1;
        // update_mem_ptr_p
      end
      else if(oqctrl_in_valid == 1'b1) begin
        nxt_state <= WRITE_MEM;
        update_cnt_sig <= 1'b1;
        // cnt_frame_length_p
        oqctrl_out_mem_wenable <= 1'b1;
      end
    end
    endcase
  end
  // count frame bytes received from fabric
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      frame_length_cnt <= {((FRAME_LENGTH_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      frame_length_cnt <= frame_length_cnt;
      if(reset_frame_length_sig == 1'b1) begin
        frame_length_cnt <= {((FRAME_LENGTH_WIDTH - 1)-(0)+1){1'b0}};
      end
      else if(update_cnt_sig == 1'b1) begin
        frame_length_cnt <= frame_length_cnt + FABRIC2TRANSMITTER_DATA_WIDTH_RATIO;
      end
    end
  end
  // read the frame length of the incoming frame
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      frame_length_reg <= {((FRAME_LENGTH_WIDTH - 1)-(0)+1){1'b0}};
      timestamp_reg <= {((TIMESTAMP_WIDTH - 1)-(0)+1){1'b0}};
      prio_reg <= {((VLAN_PRIO_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      frame_length_reg <= frame_length_reg;
      timestamp_reg <= timestamp_reg;
      prio_reg <= prio_reg;
      if(read_reg_sig == 1'b1) begin
        frame_length_reg <= oqctrl_in_length;
        timestamp_reg <= oqctrl_in_timestamp;
        prio_reg <= oqctrl_in_prio;
      end
    end
  end
  // update memory start address of next incoming frame
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      mem_start_ptr_reg <= {((NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1)-(0)+1){1'b0}};
    end
    else begin
      mem_start_ptr_reg <= mem_start_ptr_reg;
      if(update_mem_ptr_sig == 1'b1) begin
        if(NR_OQ_FIFOS == 2 && prio_reg >= high_priority_border_value_reg) begin
          mem_start_ptr_reg[NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:(NR_OQ_FIFOS - 1) * OQ_MEM_ADDR_WIDTH_A] <= mem_start_ptr_reg[NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:(NR_OQ_FIFOS - 1) * OQ_MEM_ADDR_WIDTH_A] + frame_length_cnt[FRAME_LENGTH_WIDTH - 1:OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A] + 1;
        end
        else begin
          mem_start_ptr_reg[OQ_MEM_ADDR_WIDTH_A - 1:0] <= mem_start_ptr_reg[OQ_MEM_ADDR_WIDTH_A - 1:0] + frame_length_cnt[FRAME_LENGTH_WIDTH - 1:OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A] + 1;
        end
      end
    end
  end
  // switch fabric 32 bit
  always @(high_priority_border_value_reg, mem_start_ptr_reg, frame_length_cnt, timestamp_reg, oqctrl_in_prio, frame_length_reg) begin
    if(NR_OQ_FIFOS == 1) begin
      oqctrl_out_mem_addr <= mem_start_ptr_reg + frame_length_cnt[FRAME_LENGTH_WIDTH - 1:OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A];
      oqctrl_out_fifo_data <= {mem_start_ptr_reg,2'b00,timestamp_reg,frame_length_reg};
      oqctrl_out_mem_wr_addr <= {mem_start_ptr_reg,2'b00};
    end
    else begin
      oqctrl_out_mem_wr_addr <= {mem_start_ptr_reg[NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:(NR_OQ_FIFOS - 1) * OQ_MEM_ADDR_WIDTH_A],2'b00,mem_start_ptr_reg[OQ_MEM_ADDR_WIDTH_A - 1:0],2'b00};
      if(oqctrl_in_prio >= high_priority_border_value_reg) begin
        oqctrl_out_mem_addr <= mem_start_ptr_reg[NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:(NR_OQ_FIFOS - 1) * OQ_MEM_ADDR_WIDTH_A] + frame_length_cnt[FRAME_LENGTH_WIDTH - 1:OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A];
        oqctrl_out_fifo_data <= {mem_start_ptr_reg[NR_OQ_FIFOS * OQ_MEM_ADDR_WIDTH_A - 1:(NR_OQ_FIFOS - 1) * OQ_MEM_ADDR_WIDTH_A],2'b00,timestamp_reg,frame_length_reg};
      end
      else begin
        oqctrl_out_mem_addr <= mem_start_ptr_reg[OQ_MEM_ADDR_WIDTH_A - 1:0] + frame_length_cnt[FRAME_LENGTH_WIDTH - 1:OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A];
        oqctrl_out_fifo_data <= {mem_start_ptr_reg[OQ_MEM_ADDR_WIDTH_A - 1:0],2'b00,timestamp_reg,frame_length_reg};
      end
    end
  end
  // switch fabric 16 bit
  //    output_p : process(high_priority_border_value_reg, mem_start_ptr_reg, frame_length_cnt, timestamp_reg, oqctrl_in_prio, frame_length_reg)
  //    begin
  //        if NR_OQ_FIFOS = 1 then
  //            oqctrl_out_mem_addr     <= mem_start_ptr_reg + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //            oqctrl_out_fifo_data    <= mem_start_ptr_reg & "0" & timestamp_reg & frame_length_reg;
  //            oqctrl_out_mem_wr_addr  <= mem_start_ptr_reg & "0";
  //        else
  //            oqctrl_out_mem_wr_addr  <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) & "0" &
  //                                            mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0) & "0";
  //            if oqctrl_in_prio >= high_priority_border_value_reg then
  //                oqctrl_out_mem_addr     <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) 
  //                                + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //                oqctrl_out_fifo_data    <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) & "0" & timestamp_reg & frame_length_reg;
  //            else
  //                oqctrl_out_mem_addr     <= mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0) 
  //                                + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //                oqctrl_out_fifo_data    <= mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0) & "0" & timestamp_reg & frame_length_reg;
  //            end if;
  //        end if;
  //    end process;
  // switch fabric 8 bit
  //    output_p : process(high_priority_border_value_reg, mem_start_ptr_reg, frame_length_cnt, timestamp_reg, oqctrl_in_prio, frame_length_reg)
  //    begin
  //        if NR_OQ_FIFOS = 1 then
  //            oqctrl_out_mem_addr     <= mem_start_ptr_reg + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //            oqctrl_out_fifo_data    <= mem_start_ptr_reg & timestamp_reg & frame_length_reg;
  //            oqctrl_out_mem_wr_addr  <= mem_start_ptr_reg;
  //        else
  //            oqctrl_out_mem_wr_addr  <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) &
  //                                            mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0);
  //            if oqctrl_in_prio >= high_priority_border_value_reg then
  //                oqctrl_out_mem_addr     <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) 
  //                                + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //                oqctrl_out_fifo_data    <= mem_start_ptr_reg(NR_OQ_FIFOS*OQ_MEM_ADDR_WIDTH_A-1 downto (NR_OQ_FIFOS-1)*OQ_MEM_ADDR_WIDTH_A) & timestamp_reg & frame_length_reg;
  //            else
  //                oqctrl_out_mem_addr     <= mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0) 
  //                                + frame_length_cnt(FRAME_LENGTH_WIDTH-1 downto OQ_MEM_ADDR_WIDTH_B - OQ_MEM_ADDR_WIDTH_A);
  //                oqctrl_out_fifo_data    <= mem_start_ptr_reg(OQ_MEM_ADDR_WIDTH_A-1 downto 0) & timestamp_reg & frame_length_reg;
  //            end if;
  //        end if;
  //    end process;
  assign oqctrl_out_mem_data = oqctrl_in_data;
  assign oqctrl_out_fifo_prio = prio_reg;
endmodule

module RightShft(
input wire RST,
input wire CLK,
input wire [3:0] CTRL,
input wire [7:0] DATAWR,
output wire Tx
);
reg Txn; reg Txp;
  always @(CTRL, DATAWR) begin
    case(CTRL)
    4'b0000 : begin
      Txn <= 1'b1;
      // Hold
    end
    4'b0001 : begin
      Txn <= 1'b0;
      // Start
    end
    4'b0010 : begin
      Txn <= DATAWR[0];
      // DATARD(0)
    end
    4'b0011 : begin
      Txn <= DATAWR[1];
      // DATARD(1)
    end
    4'b0100 : begin
      Txn <= DATAWR[2];
      // DATARD(2)
    end
    4'b0101 : begin
      Txn <= DATAWR[3];
      // DATARD(3)
    end
    4'b0110 : begin
      Txn <= DATAWR[4];
      // DATARD(4)
    end
    4'b0111 : begin
      Txn <= DATAWR[5];
      // DATARD(5)
    end
    4'b1000 : begin
      Txn <= DATAWR[6];
      // DATARD(6)
    end
    4'b1001 : begin
      Txn <= DATAWR[7];
      // DATARD(7)
    end
    4'b1010 : begin
      Txn <= 1'b1;
      // Stop
    end
    default : begin
      Txn <= 1'b1;
    end
    endcase
  end
  always @(posedge RST, posedge CLK) begin
    if((RST == 1'b0)) begin
      Txp <= 1'b0;
    end else begin
      Txp <= Txn;
    end
  end
  assign Tx = Txp;
endmodule

module ControlUnit(
input wire CLK,
input wire C,
input wire Z,
input wire INT,
input wire RST,
input wire [4:0] OPCODE_HI_5,
input wire [1:0] OPCODE_LO_2,
output reg PC_LD,
output reg PC_INC,
output reg PC_RESET,
output reg [1:0] PC_MUX_SEL,
output reg SP_LD,
output reg SP_RESET,
output reg SP_INCR,
output reg SP_DECR,
output reg RF_WR,
output reg [1:0] RF_WR_SEL,
output reg [3:0] ALU_SEL,
output reg ALU_OPY_SEL,
output reg SCR_WR,
output reg [1:0] SCR_ADDR_SEL,
output reg SCR_DATA_SEL,
output reg C_FLAG_SEL,
output reg C_FLAG_LD,
output reg C_FLAG_SET,
output reg C_FLAG_CLR,
output reg SHAD_C_LD,
output reg Z_FLAG_SEL,
output reg Z_FLAG_LD,
output reg Z_FLAG_SET,
output reg Z_FLAG_CLR,
output reg SHAD_Z_LD,
output reg I_FLAG_SET,
output reg I_FLAG_CLR,
output reg IO_OE
);
// State machine signals
parameter [1:0]
  ST_init = 0,
  ST_fet = 1,
  ST_exec = 2,
  ST_int = 3;
reg [1:0] PS; reg [1:0] NS;  // Opcode
reg [6:0] sig_OPCODE_7;
  // Assign next state
  always @(posedge CLK, posedge NS, posedge RST) begin
    if((RST == 1'b1)) begin
      PS <= ST_init;
    end else begin
      PS <= NS;
    end
  end
  // Translate instruction to signals
  always @(OPCODE_HI_5, OPCODE_LO_2, sig_OPCODE_7, C, Z, PS, NS, INT) begin
    sig_OPCODE_7 <= {OPCODE_HI_5,OPCODE_LO_2};
    case(PS)
        // STATE: the init cycle ------------------------------------
    ST_init : begin
      NS <= ST_fet;
      // Initialize all control outputs to non-active states and reset the PC and SP to all zeros.      
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_RESET <= 1'b1;
      PC_INC <= 1'b0;
      SP_LD <= 1'b0;
      SP_RESET <= 1'b1;
      SP_INCR <= 1'b0;
      SP_DECR <= 1'b0;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      ALU_OPY_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      SCR_DATA_SEL <= 1'b0;
      C_FLAG_SEL <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      SHAD_C_LD <= 1'b0;
      Z_FLAG_SEL <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      SHAD_Z_LD <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      IO_OE <= 1'b0;
      //WRITE_STROBE  <= '0';   READ_STROBE <= '0';		 	
      // STATE: the fetch cycle -----------------------------------
    end
    ST_fet : begin
      NS <= ST_exec;
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_RESET <= 1'b0;
      PC_INC <= 1'b1;
      SP_LD <= 1'b0;
      SP_RESET <= 1'b0;
      SP_INCR <= 1'b0;
      SP_DECR <= 1'b0;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      ALU_OPY_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      SCR_DATA_SEL <= 1'b0;
      C_FLAG_SEL <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      SHAD_C_LD <= 1'b0;
      Z_FLAG_SEL <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      SHAD_Z_LD <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      IO_OE <= 1'b0;
      //WRITE_STROBE  <= '0';   READ_STROBE <= '0';		 				
      // STATE: the execute cycle ---------------------------------
    end
    ST_exec : begin
      if((INT == 1'b1)) begin
        NS <= ST_int;
      end
      else begin
        NS <= ST_fet;
      end
      // Repeat the default block for all variables here, noting that any output values desired to be different
      // from init values shown below will be assigned in the following case statements for each opcode.
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_RESET <= 1'b0;
      PC_INC <= 1'b0;
      SP_LD <= 1'b0;
      SP_RESET <= 1'b0;
      SP_INCR <= 1'b0;
      SP_DECR <= 1'b0;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      ALU_OPY_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      SCR_DATA_SEL <= 1'b0;
      C_FLAG_SEL <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      SHAD_C_LD <= 1'b0;
      Z_FLAG_SEL <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      SHAD_Z_LD <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      IO_OE <= 1'b0;
      //WRITE_STROBE  <= '0';   READ_STROBE <= '0';		 
      if((sig_OPCODE_7 == 7'b0000100)) begin
        // ADD reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0000;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10100)) begin
        // ADD reg-immed
        ALU_OPY_SEL <= 1'b1;
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0000;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000101)) begin
        // ADDC reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0001;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10101)) begin
        // ADDC reg-immed
        ALU_OPY_SEL <= 1'b1;
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0001;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000000)) begin
        // AND reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0101;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10000)) begin
        // AND reg-immed
        ALU_OPY_SEL <= 1'b1;
        ALU_SEL <= 4'b0101;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100100)) begin
        // ASR reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1101;
        Z_FLAG_LD <= 1'b1;
        C_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0010101)) begin
        // BRCC
        if((c == 1'b0)) begin
          PC_LD <= 1'b1;
        end
      end
      else if((sig_OPCODE_7 == 7'b0010100)) begin
        // BRCS
        if((c == 1'b1)) begin
          PC_LD <= 1'b1;
        end
      end
      else if((sig_OPCODE_7 == 7'b0010010)) begin
        // BREQ
        if((Z == 1'b1)) begin
          PC_LD <= 1'b1;
        end
      end
      else if((sig_OPCODE_7 == 7'b0010000)) begin
        // BRN
        PC_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0010011)) begin
        // BRNE
        if((Z == 1'b0)) begin
          PC_LD <= 1'b1;
        end
      end
      else if((sig_OPCODE_7 == 7'b0010001)) begin
        // CALL
        PC_LD <= 1'b1;
        SP_LD <= 1'b1;
        SCR_ADDR_SEL <= 2'b10;
        SCR_ADDR_SEL <= 2'b11;
        SCR_WR <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110000)) begin
        // CLC
        C_FLAG_CLR <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110101)) begin
        // CLI (INT)
        I_FLAG_CLR <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0001000)) begin
        // CMP reg-reg
        ALU_SEL <= 4'b0100;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b11000)) begin
        // CMP reg-immed
        ALU_SEL <= 4'b0100;
        ALU_OPY_SEL <= 1'b1;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000010)) begin
        // EXOR reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0111;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10010)) begin
        // EXOR reg-immed
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0111;
        ALU_OPY_SEL <= 1'b1;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b11001)) begin
        // IN
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b11;
      end
      else if((sig_OPCODE_7 == 7'b0001010)) begin
        // LD reg-reg
        SCR_ADDR_SEL <= 2'b00;
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b01;
      end
      else if((OPCODE_HI_5 == 5'b11100)) begin
        // LD reg-immed
        SCR_ADDR_SEL <= 2'b01;
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b01;
      end
      else if((sig_OPCODE_7 == 7'b0100000)) begin
        // LSL
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1001;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100001)) begin
        // LSR
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1010;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0001001)) begin
        // MOV reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1110;
      end
      else if((OPCODE_HI_5 == 5'b11011)) begin
        // MOV reg-immed
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1110;
        ALU_OPY_SEL <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000001)) begin
        // OR reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0110;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10001)) begin
        // OR reg-immed
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0110;
        ALU_OPY_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b11010)) begin
        // OUT
        IO_OE <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100110)) begin
        // POP
        SCR_ADDR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b01;
        SCR_ADDR_SEL <= 2'b11;
        SP_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100101)) begin
        // PUSH
        SCR_WR <= 1'b1;
        SCR_ADDR_SEL <= 2'b11;
        SCR_ADDR_SEL <= 2'b10;
        SP_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110010)) begin
        // RET
        SCR_ADDR_SEL <= 2'b10;
        PC_MUX_SEL <= 2'b01;
        PC_LD <= 1'b1;
        SCR_ADDR_SEL <= 2'b11;
        SP_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110110)) begin
        // RETID (INT)
        SCR_ADDR_SEL <= 2'b10;
        PC_MUX_SEL <= 2'b01;
        PC_LD <= 1'b1;
        SCR_ADDR_SEL <= 2'b11;
        SP_LD <= 1'b1;
        I_FLAG_CLR <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110111)) begin
        // RETIE (INT)
        SCR_ADDR_SEL <= 2'b10;
        PC_MUX_SEL <= 2'b01;
        PC_LD <= 1'b1;
        SCR_ADDR_SEL <= 2'b11;
        SP_LD <= 1'b1;
        I_FLAG_SET <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100010)) begin
        // ROL
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1011;
        Z_FLAG_LD <= 1'b1;
        C_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0100011)) begin
        // ROR
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b1100;
        Z_FLAG_LD <= 1'b1;
        C_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110001)) begin
        // SEC
        C_FLAG_SET <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0110100)) begin
        // SEI (INT)
        I_FLAG_SET <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0001011)) begin
        // ST reg-reg
        SCR_WR <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b11101)) begin
        // ST reg-immed
        SCR_WR <= 1'b1;
        SCR_ADDR_SEL <= 2'b01;
      end
      else if((sig_OPCODE_7 == 7'b0000110)) begin
        // SUB reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0010;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10110)) begin
        // SUB reg-immed
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0010;
        ALU_OPY_SEL <= 1'b1;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000111)) begin
        // SUBC reg-reg
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0011;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10111)) begin
        // SUBC reg-immed
        ALU_OPY_SEL <= 1'b1;
        RF_WR <= 1'b1;
        ALU_SEL <= 4'b0011;
        C_FLAG_LD <= 1'b1;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0000011)) begin
        // TEST reg-reg
        ALU_SEL <= 4'b1000;
        Z_FLAG_LD <= 1'b1;
      end
      else if((OPCODE_HI_5 == 5'b10011)) begin
        // TEST reg-immed
        ALU_OPY_SEL <= 1'b1;
        ALU_SEL <= 4'b1000;
        Z_FLAG_LD <= 1'b1;
      end
      else if((sig_OPCODE_7 == 7'b0101000)) begin
        // WSP
        SCR_ADDR_SEL <= 2'b00;
        SP_LD <= 1'b1;
      end
      else begin
        // repeat the default block here to avoid incompletely specified outputs and hence avoid
        // the problem of inadvertently created latches within the synthesized system.						
        PC_LD <= 1'b0;
        PC_MUX_SEL <= 2'b00;
        PC_RESET <= 1'b0;
        PC_INC <= 1'b0;
        SP_LD <= 1'b0;
        SP_RESET <= 1'b0;
        SP_INCR <= 1'b0;
        SP_DECR <= 1'b0;
        RF_WR <= 1'b0;
        RF_WR_SEL <= 2'b00;
        ALU_OPY_SEL <= 1'b0;
        ALU_SEL <= 4'b0000;
        SCR_WR <= 1'b0;
        SCR_ADDR_SEL <= 2'b00;
        SCR_DATA_SEL <= 1'b0;
        C_FLAG_SEL <= 1'b0;
        C_FLAG_LD <= 1'b0;
        C_FLAG_SET <= 1'b0;
        C_FLAG_CLR <= 1'b0;
        SHAD_C_LD <= 1'b0;
        Z_FLAG_SEL <= 1'b0;
        Z_FLAG_LD <= 1'b0;
        Z_FLAG_SET <= 1'b0;
        Z_FLAG_CLR <= 1'b0;
        SHAD_Z_LD <= 1'b0;
        I_FLAG_SET <= 1'b0;
        I_FLAG_CLR <= 1'b0;
        IO_OE <= 1'b0;
        //WRITE_STROBE  <= '0';   READ_STROBE <= '0';		            
      end
      // STATE: the interrupt cycle -----------------------------------
    end
    ST_int : begin
      NS <= ST_fet;
      PC_LD <= 1'b1;
      PC_MUX_SEL <= 2'b10;
      PC_RESET <= 1'b0;
      PC_INC <= 1'b0;
      SP_LD <= 1'b1;
      SP_RESET <= 1'b0;
      SP_INCR <= 1'b1;
      SP_DECR <= 1'b0;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      ALU_OPY_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_ADDR_SEL <= 2'b11;
      SCR_DATA_SEL <= 1'b0;
      C_FLAG_SEL <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      SHAD_C_LD <= 1'b0;
      Z_FLAG_SEL <= 1'b0;
