      //WRITE_STROBE  <= '0';   READ_STROBE <= '0';		 					
    end
    default : begin
      NS <= ST_fet;
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_RESET <= 1'b1;
      PC_INC <= 1'b0;
      SP_LD <= 1'b0;
      SP_RESET <= 1'b1;
      SP_INCR <= 1'b0;
      SP_DECR <= 1'b0;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      ALU_OPY_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      SCR_DATA_SEL <= 1'b0;
      C_FLAG_SEL <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      SHAD_C_LD <= 1'b0;
      Z_FLAG_SEL <= 1'b0;
