module scrambler(
input wire clk,
input wire bypass0,
input wire bypass1,
input wire [71:0] in_data,
output reg [71:0] out_data
);
reg [15:0] lfsr_state = 1'b1;
parameter SR = 9'b100011100;  // K28.0 ia used to reset the scrambler
  always @(posedge clk) begin : P1
    reg [15:0] s0;
    reg [15:0] s1;
    s0 = lfsr_state;
    //------------------------------------------
    // Process symbol 0
    //------------------------------------------        
    if(in_data[8] == 1'b1 || bypass0 == 1'b1) begin
      // Bypass the scrambler for 'K' symbols (but still update LFSR state!)
      out_data[8:0] <= in_data[8:0];
    end
    else begin
      out_data[0] <= in_data[0] ^ s0[15];
      out_data[1] <= in_data[1] ^ s0[14];
      out_data[2] <= in_data[2] ^ s0[13];
      out_data[3] <= in_data[3] ^ s0[12];
      out_data[4] <= in_data[4] ^ s0[11];
      out_data[5] <= in_data[5] ^ s0[10];
      out_data[6] <= in_data[6] ^ s0[9];
      out_data[7] <= in_data[7] ^ s0[8];
      out_data[8] <= 1'b0;
    end
    // generate intermediate scrambler state            
    if(in_data[8:0] == SR) begin
      s1 = 16'hFFFF;
    end
    else begin
      s1[0] = s0[8];
      s1[1] = s0[9];
      s1[2] = s0[10];
      s1[3] = s0[11] ^ s0[8];
      s1[4] = s0[12] ^ s0[8] ^ s0[9];
      s1[5] = s0[13] ^ s0[8] ^ s0[9] ^ s0[10];
      s1[6] = s0[14] ^ s0[9] ^ s0[10] ^ s0[11];
      s1[7] = s0[15] ^ s0[10] ^ s0[11] ^ s0[12];
      s1[8] = s0[0] ^ s0[11] ^ s0[12] ^ s0[13];
      s1[9] = s0[1] ^ s0[12] ^ s0[13] ^ s0[14];
      s1[10] = s0[2] ^ s0[13] ^ s0[14] ^ s0[15];
      s1[11] = s0[3] ^ s0[14] ^ s0[15];
      s1[12] = s0[4] ^ s0[15];
      s1[13] = s0[5];
      s1[14] = s0[6];
      s1[15] = s0[7];
    end
    //------------------------------------------
    // Process symbol 1
    //------------------------------------------        
    if(in_data[17] == 1'b1 || bypass1 == 1'b1) begin
      // Bypass the scrambler for 'K' symbols (but still update LFSR state!)
      out_data[17:9] <= in_data[17:9];
    end
    else begin
      // Scramble symbol 1
      out_data[9] <= in_data[9] ^ s1[15];
      out_data[10] <= in_data[10] ^ s1[14];
      out_data[11] <= in_data[11] ^ s1[13];
      out_data[12] <= in_data[12] ^ s1[12];
      out_data[13] <= in_data[13] ^ s1[11];
      out_data[14] <= in_data[14] ^ s1[10];
      out_data[15] <= in_data[15] ^ s1[9];
      out_data[16] <= in_data[16] ^ s1[8];
      out_data[17] <= 1'b0;
    end
    // Update scrambler state
    if(in_data[17:9] == SR) begin
      lfsr_state <= 16'hFFFF;
    end
    else begin
      lfsr_state[0] <= s1[8];
      lfsr_state[1] <= s1[9];
      lfsr_state[2] <= s1[10];
      lfsr_state[3] <= s1[11] ^ s1[8];
      lfsr_state[4] <= s1[12] ^ s1[8] ^ s1[9];
      lfsr_state[5] <= s1[13] ^ s1[8] ^ s1[9] ^ s1[10];
      lfsr_state[6] <= s1[14] ^ s1[9] ^ s1[10] ^ s1[11];
      lfsr_state[7] <= s1[15] ^ s1[10] ^ s1[11] ^ s1[12];
      lfsr_state[8] <= s1[0] ^ s1[11] ^ s1[12] ^ s1[13];
      lfsr_state[9] <= s1[1] ^ s1[12] ^ s1[13] ^ s1[14];
      lfsr_state[10] <= s1[2] ^ s1[13] ^ s1[14] ^ s1[15];
      lfsr_state[11] <= s1[3] ^ s1[14] ^ s1[15];
      lfsr_state[12] <= s1[4] ^ s1[15];
      lfsr_state[13] <= s1[5];
      lfsr_state[14] <= s1[6];
      lfsr_state[15] <= s1[7];
    end
  end
endmodule

