module befunge_pc_v2(
input wire clk,
input wire reset,
output wire [(grid_power * 2) - 1:0] pc_address,
input wire [1:0] dir,
input wire skip,
input wire en
);
parameter [31:0] grid_power;
//dir:
//0 = right
//1 = down
//2 = left
//3 = up
reg [(grid_power * 2) - 1:0] pc_address_int;
reg [grid_power - 1:0] pc_row;
reg [grid_power - 1:0] pc_col;
  assign pc_address[(grid_power * 2) - 1:(grid_power * 2) / 2] = pc_col;
  assign pc_address[((grid_power * 2) / 2) - 1:0] = pc_row;
  always @(posedge reset, posedge clk) begin : P1
    reg [31:0] increment;
    if((reset == 1'b1)) begin
      pc_address_int <= {(((grid_power * 2) - 1)-(0)+1){1'b0}};
      pc_row <= {((grid_power - 1)-(0)+1){1'b0}};
      pc_col <= {((grid_power - 1)-(0)+1){1'b0}};
      increment = 1;
    end else begin
      if((en == 1'b1)) begin
        if((skip == 1'b1)) begin
          increment = 2;
        end
        else begin
          increment = 1;
        end
        if((dir == 2'b00)) begin
          //move right: add 1
          pc_row <= (pc_row) + increment;
        end
        else if((dir == 2'b01)) begin
          //move up: subtract grid_width
          pc_col <= (pc_col) - increment;
        end
        else if((dir == 2'b10)) begin
          //move left: subtract 1
          pc_row <= (pc_row) - increment;
        end
        else if((dir == 2'b11)) begin
          //move down: add grid_width
          pc_col <= (pc_col) + increment;
        end
        else begin
          //do nothing, laaaatchhh!!!!
        end
      end
    end
  end
endmodule

