module top_nto1_ddr_se_tx(
input wire reset,
input wire refclkin_p,
input wire refclkin_n,
output wire [7:0] dataout,
output wire clkout
);
// reset (active high)
// frequency generator clock input
// single ended data outputs
// single ended clock output
// Parameters for serdes factor and number of IO pins
parameter S = 8;  // Set the serdes factor
parameter D = 8;  // Set the number of inputs and outputs
parameter DS = (D * S) - 1;  // Used for bus widths = serdes factor * number of inputs - 1
wire rst;
reg [DS:0] txd;  // Registered Data to serdeses
wire txioclkp;
wire txioclkn;
wire tx_serdesstrobe;
wire tx_bufg_x1;
wire [0:0] clkoutb;  // Parameters for clock generation
parameter TX_CLK_GEN = 8'hAA;  // Transmit a constant to make a clock
  assign rst = reset;
  // active high reset pin
  // Reference Clock Input genertaes IO clocks via 2 x BUFIO2
  clock_generator_ddr_s8_diff #(
      .S(S))
  inst_clkgen(
      .clkin_p(refclkin_p),
    .clkin_n(refclkin_n),
    .ioclkap(txioclkp),
    .ioclkan(txioclkn),
    .serdesstrobea(tx_serdesstrobe),
    .ioclkbp(/* open */),
    .ioclkbn(/* open */),
    .serdesstrobeb(/* open */),
    .gclk(tx_bufg_x1));
  always @(posedge tx_bufg_x1, posedge rst) begin : P1
  // Generate some data to transmit
    if(rst == 1'b1) begin
      txd <= 64'h3000000000000001;
    end else begin
      txd <= {txd[63:60],txd[58:0],txd[59]};
    end
  end
  // Transmitter Logic - Instantiate serialiser to generate forwarded clock
  serdes_n_to_1_ddr_s8_se #(
      .S(S),
    .D(1))
  inst_clkout(
      .dataout(clkoutb),
    .txioclkp(txioclkp),
    .txioclkn(txioclkn),
    .txserdesstrobe(tx_serdesstrobe),
    .gclk(tx_bufg_x1),
    .reset(rst),
    .datain(TX_CLK_GEN));
  // Transmit a constant to make the clock
  assign clkout = clkoutb[0];
  // Instantiate Outputs and output serialisers for output data lines
  serdes_n_to_1_ddr_s8_se #(
      .S(S),
    .D(D))
  inst_dataout(
      .dataout(dataout),
    .txioclkp(txioclkp),
    .txioclkn(txioclkn),
    .txserdesstrobe(tx_serdesstrobe),
    .gclk(tx_bufg_x1),
    .reset(rst),
    .datain(txd));
endmodule

module vga_out(
input wire iCLK,
input wire [9:0] px,
input wire [9:0] py,
input wire [7:0] potX,
input wire [7:0] potY,
input wire [11:0] color,
output reg [3:0] red,
output reg [3:0] green,
output reg [3:0] blue,
output reg [16:0] ram_addr_output
);
wire [31:0] px_int = 0;
wire [31:0] py_int = 0;
  assign px_int = px;
  assign py_int = py;
  always @(posedge iCLK) begin
    if(((py >= 107) && (py <= 363))) begin
      if(((px >= 192) && (px <= 448))) begin
        ram_addr_output <= (px_int - 192) + ((py_int - 107) * 256);
        // FIX THIS
        red <= color[11:8];
        green <= color[7:4];
        blue <= color[3:0];
        //          if (((py - 107) = potY) and ((px - 192) = potX)) then
        //             red <= "0000";
        //             blue <= "0000";
        //             green <= "0000";
        //          else
        //             red <= "1111";
        //             blue <= "1111";
        //             green <= "1111";
        //          end if;
      end
      else begin
        red <= 4'b0000;
        blue <= 4'b0000;
        green <= 4'b0000;
      end
    end
    else if(((py >= 447) && (py <= 479))) begin
      if(((px >= 128) && (px <= 512))) begin
        ram_addr_output <= 65536 + (px_int - 128) + ((py_int - 447) * 384);
        red <= color[11:8];
        green <= color[7:4];
        blue <= color[3:0];
        //          red <= "0000";
        //          blue <= "0000";
        //          green <= "0000";
      end
      else begin
        red <= 4'b0000;
        blue <= 4'b0000;
        green <= 4'b0000;
      end
    end
  end
endmodule

