module vga_counter(
input wire clk,
output reg sync,
output wire [31:0] pix,
output reg en
);
parameter [31:0] disp;
parameter [31:0] fp;
parameter [31:0] pw;
parameter [31:0] bp;
reg [31:0] count_s;
  always @(posedge clk) begin
    if(count_s < (disp - 1)) begin
      sync <= 1'b1;
      en <= 1'b1;
      count_s <= count_s + 1;
    end
    else if(count_s < (disp + fp - 1)) begin
      sync <= 1'b1;
      en <= 1'b0;
      count_s <= count_s + 1;
    end
    else if(count_s < (disp + fp + pw - 1)) begin
      sync <= 1'b0;
      en <= 1'b0;
      count_s <= count_s + 1;
    end
    else if(count_s < (disp + fp + pw + bp - 1)) begin
      sync <= 1'b1;
      en <= 1'b0;
      count_s <= count_s + 1;
    end
    else begin
      sync <= 1'b1;
      en <= 1'b1;
      count_s <= 0;
    end
  end
  assign pix = count_s;
endmodule

