module dma_bus_controller(
input wire Clk,
input wire Reset,
inout reg [7:0] Databus,
output reg [7:0] Address,
output reg ChipSelect,
output reg WriteEnable,
output reg OutputEnable,
input wire Send,
output reg Ready,
output reg DMA_RQ,
input wire DMA_ACK,
input wire RX_empty,
output reg [31:0] BC_state_ns,
input wire [7:0] RX_Databus,
input wire [7:0] RX_Address,
input wire RX_ChipSelect,
input wire RX_WriteEnable,
input wire RX_OutputEnable,
output reg RX_start,
input wire RX_end,
output wire [7:0] TX_Databus,
input wire [7:0] TX_Address,
input wire TX_ChipSelect,
input wire TX_WriteEnable,
input wire TX_OutputEnable,
output reg TX_start,
input wire TX_ready,
input wire TX_end
);
// Señales procedentes del bus del uP.
// Señales de handshake entre uP y DMA.
// Señales de handshake entre RS232 y DMA.
// pragma synthesis off
// pragma synthesis on
// Señales procedentes del Receptor para el control de los buses de 
// datos y direcciones, y las señales de control.
// Señales de control utilizadas por la máquina de estados del 
// Controlador de Bus para comunicarse con el Receptor.		 
// Señales procedentes del Transmisor.
// Señales de control utilizadas por la máquina de estados del 
// Controlador de Bus para comunicarse con el Transmisor.		
// Definición de los posibles estados de la FSM del Controlador de Bus:
// + Idle: Los buses de datos y direcciones, y las señales de control están 
//		bajo el control del uP.
//		Las salidas del DMA se mantienen a alta impedancia.
// + RX_wait_bus: Los buses de datos y direcciones, y las señales de control 
// 	están bajo el control del uP. El DMA avisa al uP de que hay datos a la
//		espera de ser recibidos.
//		Las salidas del DMA se mantienen a alta impedancia.
// + RX_use_bus: El Controlador de Bus da el control de los buses de datos y
//		direcciones, y las señales de control, al Receptor.
//		Las salidas del DMA se correponden con las del Receptor.
// + RX_free_bus: El Receptor ha terminado de utilizar los buses de datos y
//		direcciones, y las señales de control. El Controlador de Bus mantiene
// 	excitadas dichas señales a la espera de que el uP vuelva a tomar su
//		control.
// + TX_use_bus: El Controlador de Bus da el control de los buses de datos y
//		direcciones, y las señales de control, al Transmisor.
//		Las salidas del DMA se correponden con las del Transmisor.
// + RX_free_bus: El Transmisor ha terminado de utilizar los buses de datos
//		y direcciones, y las señales de control. El Controlador de Bus 
// 	mantiene excitadas dichas señales a la espera de que el uP vuelva a 
//		tomar su control.
parameter [2:0]
  idle = 0,
  RX_wait_bus = 1,
  RX_use_bus = 2,
  RX_free_bus = 3,
  TX_use_bus = 4,
  TX_free_bus = 5;
reg [2:0] BC_now; reg [2:0] BC_next;
  // Proceso secuencial de la máquina de estados del Controlador de Bus. 
  // Dispone de una señal de Reset asíncrono activa a nivel bajo. Mientras que
  // esta señal se mantenga activa, la FSM se mantiene en el estado de 'Idle'.
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b0)) begin
      BC_now <= idle;
    end else begin
      BC_now <= BC_next;
    end
  end
  // Proceso combinacional de la máquina de estados.
  always @(BC_now, RX_empty, Send, DMA_ACK, RX_end, TX_ready, TX_end, RX_Databus, RX_Address, RX_ChipSelect, RX_WriteEnable, RX_OutputEnable, TX_Address, TX_ChipSelect, TX_WriteEnable, TX_OutputEnable) begin
    // Valores preasignados por defecto.
    Databus <= {8{1'bZ}};
    Address <= {8{1'bZ}};
    ChipSelect <= 1'bZ;
    WriteEnable <= 1'bZ;
    OutputEnable <= 1'bZ;
    DMA_RQ <= 1'b0;
    Ready <= 1'b0;
    RX_start <= 1'b0;
    TX_start <= 1'b0;
    case(BC_now)
    idle : begin
      Ready <= 1'b1;
      // Cuando el uP ordene envíar datos y el Transmisor del DMA este 
      // listo:
      if((Send == 1'b1 && TX_ready == 1'b1)) begin
        Ready <= 1'b0;
        TX_start <= 1'b1;
        BC_next <= TX_use_bus;
        // Si no, si el DMA recibe la señal de que hay datos preparados 
        // para leer desde el RS232...
      end
      else if((RX_empty == 1'b0)) begin
        DMA_RQ <= 1'b1;
        BC_next <= RX_wait_bus;
      end
      else begin
        BC_next <= idle;
      end
    end
    TX_use_bus : begin
      Address <= TX_Address;
      ChipSelect <= TX_ChipSelect;
      WriteEnable <= TX_WriteEnable;
      OutputEnable <= TX_OutputEnable;
      //	Si el Transmisor ha terminado de utilizar el bus...
      if(TX_end == 1'b1) begin
        BC_next <= TX_free_bus;
      end
      else begin
        BC_next <= TX_use_bus;
      end
    end
    TX_free_bus : begin
      Databus <= {8{1'b0}};
      Address <= {8{1'b0}};
      ChipSelect <= 1'b0;
      WriteEnable <= 1'b0;
      OutputEnable <= 1'b0;
      Ready <= 1'b1;
      // Si el uP vuelve a tomar el control del bus en el siguiente
      // ciclo de reloj...
      if(Send == 1'b0) begin
        BC_next <= idle;
      end
      else begin
        BC_next <= TX_free_bus;
      end
    end
    RX_wait_bus : begin
      DMA_RQ <= 1'b1;
      Ready <= 1'b1;
      // Si el uP cede el bus a partir del siguiente ciclo de reloj...
      if(DMA_ACK == 1'b1) begin
        RX_start <= 1'b1;
        BC_next <= RX_use_bus;
        // Si no, y el uP ordene envíar datos y el Transmisor del DMA este 
        // listo:
      end
      else if((Send == 1'b1 && TX_ready == 1'b1)) begin
        Ready <= 1'b0;
        TX_start <= 1'b1;
        BC_next <= TX_use_bus;
      end
      else begin
        BC_next <= RX_wait_bus;
      end
    end
    RX_use_bus : begin
      Databus <= RX_Databus;
      Address <= RX_Address;
      ChipSelect <= RX_ChipSelect;
      WriteEnable <= RX_WriteEnable;
      OutputEnable <= RX_OutputEnable;
      DMA_RQ <= 1'b1;
      //	Si el Receptor ha terminado de utilizar el bus...
      if(RX_end == 1'b1) begin
        BC_next <= RX_free_bus;
      end
      else begin
        BC_next <= RX_use_bus;
      end
    end
    RX_free_bus : begin
      Databus <= {8{1'b0}};
      Address <= {8{1'b0}};
      ChipSelect <= 1'b0;
      WriteEnable <= 1'b0;
      OutputEnable <= 1'b0;
      // Si el uP vuelve a tomar el control del bus en el siguiente
      // ciclo de reloj...
      if(DMA_ACK == 1'b0) begin
        BC_next <= idle;
      end
      else begin
        BC_next <= RX_free_bus;
      end
    end
    endcase
  end
  // El bus de datos siempre estará conectado a la entrada del bus de datos 
  // del subsistema receptor. 
  assign TX_Databus = Databus;
  // pragma synthesis off
  always @(BC_now) begin
    case(BC_now)
    idle : begin
      BC_state_ns <= 0;
    end
    TX_use_bus : begin
      BC_state_ns <= 1;
    end
    TX_free_bus : begin
      BC_state_ns <= 2;
    end
    RX_wait_bus : begin
      BC_state_ns <= 3;
    end
    RX_use_bus : begin
      BC_state_ns <= 4;
    end
    RX_free_bus : begin
      BC_state_ns <= 5;
    end
    endcase
  end
    // pragma synthesis on
endmodule

module vme_bustimer(
input wire clk,
input wire rst,
input wire startup_rst,
input wire prevent_sysrst,
output wire set_sysc,
input wire sysc_bit,
output reg clr_sysr,
input wire sysr_bit,
input wire dsain,
input wire dsbin,
output reg bgouten,
output wire sysfailn,
input wire sysrstn_in,
output wire sysrstn_out,
output wire v2p_rst,
input wire bg3n_in,
output wire slot01n,
output reg berrn_out
);
// global clock
// global reset
// powerup reset
// if "1", sysrst_n_out will not be activated after powerup,
// if "0", sysrst_n_out will be activated if in slot1 and system reset is active (sysc_bit or rst)
// if set sysc-bit will be set
// 1=slot1 0=slotx
// if set sysr-bit will be cleared
// 1=system reset
// connected with Slave Unit
// data strobe a in
// data strobe b in
// enables SGL and bg3out signal
// bus grant daisy chain is driven through requester in Access VME:
//---------------------------------------------------------------------
// PINs:
// indicates when A15 is not ready or in reset
// Reset between VMEbus and Host CPU
// bus grant signal in (if not connected => slot01)
// enables V_SYSCLK (16 MHz)
// bus error 
//
parameter CONST_10US = 10'b1010011011;  // =667 @ 66MHz => 10,005 us
parameter CONST_200MS = 15'b100111000010111;  // = 19991 @ 10,005us => 
// counter value for vme rstn => 250ms
wire btresn;  // bus timer reset
reg [12:0] cnt;  // approximately 60 us
reg sysrstn_out_int;
reg v2p_rst_int;
parameter [2:0]
  IDLE = 0,
  WAIT_ON_RST = 1,
  RST_VME = 2,
  RST_VME2 = 3,
  WAIT_ON_VME = 4,
  RST_CPU = 5,
  WAIT_ON_CPU = 6,
  STARTUP_END = 7;
reg [2:0] rst_state;
reg [9:0] pre_cnt;
reg pre_cnt_end;
reg rst_pre_cnt;
reg rst_main_cnt;
reg [14:0] main_cnt;
wire [14:0] main_cnt_max_sig;
reg main_cnt_end;
reg sysrstn_q;
reg sysrstn_qq;
reg sysrstn_qqq;
reg degl_sysrstn;
reg rst_q;
reg rst_qq;
reg rst_qqq;
reg degl_rst;
reg dsain_q;
reg dsbin_q;
reg bg3n_in_q;
reg bg3n_in_qq;
wire [9:0] pre_cnt_max_sig;
reg set_sysc_int;
  assign slot01n =  ~sysc_bit;
  assign sysrstn_out = sysrstn_out_int;
  assign set_sysc = set_sysc_int;
  assign sysfailn = startup_rst == 1'b1 ? 1'b0 : 1'b1;
  assign v2p_rst = v2p_rst_int;
  //-----------------------------------------------------------------------------
  // Bus Timer. Works only when sysc_bit is set. Generates a bus error after 62 us
  // During normal operation, reset is triggered each
  // time both VMEbus Datastrobes are high.
  //-----------------------------------------------------------------------------
  assign btresn = (dsain_q == 1'b1 && dsbin_q == 1'b1) ? 1'b1 : 1'b0;
  always @(posedge clk, posedge startup_rst) begin
    if(startup_rst == 1'b1) begin
      sysrstn_q <= 1'b1;
      sysrstn_qq <= 1'b1;
      sysrstn_qqq <= 1'b1;
      degl_sysrstn <= 1'b1;
      rst_q <= 1'b0;
      rst_qq <= 1'b0;
      rst_qqq <= 1'b0;
      degl_rst <= 1'b0;
      bg3n_in_q <= 1'b1;
      bg3n_in_qq <= 1'b1;
    end else begin
      bg3n_in_q <= bg3n_in;
      bg3n_in_qq <= bg3n_in_q;
      sysrstn_q <= sysrstn_in;
      sysrstn_qq <= sysrstn_q;
      sysrstn_qqq <= sysrstn_qq;
      if(sysrstn_q == 1'b0 && sysrstn_qq == 1'b0 && sysrstn_qqq == 1'b0) begin
        degl_sysrstn <= 1'b0;
      end
      else if(sysrstn_q == 1'b1 && sysrstn_qq == 1'b1 && sysrstn_qqq == 1'b1) begin
        degl_sysrstn <= 1'b1;
      end
      else begin
        degl_sysrstn <= degl_sysrstn;
      end
      rst_q <= rst;
      rst_qq <= rst_q;
      rst_qqq <= rst_qq;
      if(rst_q == 1'b1 && rst_qq == 1'b1 && rst_qqq == 1'b1) begin
        degl_rst <= 1'b1;
      end
      else if(rst_q == 1'b0 && rst_qq == 1'b0 && rst_qqq == 1'b0) begin
        degl_rst <= 1'b0;
      end
    end
  end
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      cnt <= {13{1'b0}};
      berrn_out <= 1'b1;
      dsain_q <= 1'b1;
      dsbin_q <= 1'b1;
    end else begin
      dsain_q <= dsain;
      dsbin_q <= dsbin;
      if((btresn == 1'b1)) begin
        cnt <= {13{1'b0}};
      end
      else if((dsain_q == 1'b0 || dsbin_q == 1'b0) && sysc_bit == 1'b1) begin
        // counter starts with DSA or DSB signal
        cnt <= cnt + 1;
      end
      if(cnt[12] == 1'b1) begin
        berrn_out <= 1'b0;
      end
      else if(btresn == 1'b1) begin
        berrn_out <= 1'b1;
      end
    end
  end
  assign pre_cnt_max_sig = CONST_10US;
  assign main_cnt_max_sig = CONST_200MS;
  always @(posedge clk, posedge startup_rst) begin
    if(startup_rst == 1'b1) begin
      main_cnt <= {15{1'b0}};
      pre_cnt <= {10{1'b0}};
      main_cnt_end <= 1'b0;
      pre_cnt_end <= 1'b0;
    end else begin
      // pre counter for counting up to 10 us
      if(rst_pre_cnt == 1'b1) begin
        pre_cnt <= {10{1'b0}};
        pre_cnt_end <= 1'b0;
      end
      else if(pre_cnt == pre_cnt_max_sig) begin
        pre_cnt <= {10{1'b0}};
        pre_cnt_end <= 1'b1;
      end
      else begin
        pre_cnt <= pre_cnt + 1;
        pre_cnt_end <= 1'b0;
      end
      // main counter with base of 10 us counts up to 200 ms reset time
      if(rst_main_cnt == 1'b1) begin
        main_cnt <= {15{1'b0}};
        main_cnt_end <= 1'b0;
      end
      else if(main_cnt == main_cnt_max_sig && pre_cnt_end == 1'b1) begin
        main_cnt <= {15{1'b0}};
        main_cnt_end <= 1'b1;
      end
      else if(pre_cnt_end == 1'b1) begin
        main_cnt <= main_cnt + 1;
        main_cnt_end <= 1'b0;
      end
    end
  end
  always @(posedge clk, posedge startup_rst) begin
    if(startup_rst == 1'b1) begin
      set_sysc_int <= 1'b0;
      bgouten <= 1'b0;
      sysrstn_out_int <= 1'b0;
      v2p_rst_int <= 1'b0;
      clr_sysr <= 1'b0;
      rst_state <= IDLE;
      rst_pre_cnt <= 1'b0;
      rst_main_cnt <= 1'b0;
    end else begin
      if(set_sysc_int == 1'b1 && sysc_bit == 1'b1) begin
        // if status reg has stored slot 1 location => clear request to set bit
        set_sysc_int <= 1'b0;
      end
      else if(bg3n_in_qq == 1'b0 && main_cnt_end == 1'b1 && rst_state == IDLE) begin
        // slot 1 was detected => keep in mind until stored in status reg
        set_sysc_int <= 1'b1;
      end
      case(rst_state)
            // wait until powerup reset time has elapsed (16383 * system_clock_period = 250 us @ 66MHz)
      IDLE : begin
        bgouten <= 1'b0;
        sysrstn_out_int <= 1'b0;
        // activate reset to vme-bus
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        clr_sysr <= 1'b0;
        if(main_cnt_end == 1'b1) begin
          rst_state <= STARTUP_END;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= IDLE;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // release vme reset and wait for deactivation of vme- and cpu-reset (minimum 16383 * system_clock_period = 250 us @ 66MHz)
      end
      STARTUP_END : begin
        bgouten <= 1'b0;
        sysrstn_out_int <= 1'b1;
        // no reset to vme-bus
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        clr_sysr <= 1'b0;
        if(main_cnt_end == 1'b1 && degl_rst == 1'b0 && degl_sysrstn == 1'b1) begin
          // wait until cpu and vme does not deliver active reset
          rst_state <= WAIT_ON_RST;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= STARTUP_END;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // normal operation: wait until either cpu-reset or vme-reset is active
      end
      WAIT_ON_RST : begin
        bgouten <= 1'b1;
        sysrstn_out_int <= 1'b1;
        // no reset to vme-bus
        clr_sysr <= 1'b0;
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        if((degl_rst == 1'b1 || sysr_bit == 1'b1) && sysc_bit == 1'b1) begin
          // in slot 1 and cpu or bit has active reset
          rst_state <= RST_VME;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b1;
        end
        else if(degl_sysrstn == 1'b0) begin
          // not in slot 1 and vme-bus has active reset
          rst_state <= RST_CPU;
          rst_pre_cnt <= 1'b1;
          // clear counter in order to set cpu 10 us to reset
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= WAIT_ON_RST;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // set cpu reset active
      end
      RST_CPU : begin
        bgouten <= 1'b1;
        sysrstn_out_int <= 1'b1;
        // no reset to vme-bus
        v2p_rst_int <= 1'b1;
        // active reset to cpu 
        clr_sysr <= 1'b0;
        if(pre_cnt_end == 1'b1) begin
          // after 10 us, release cpu reset
          rst_state <= WAIT_ON_CPU;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= RST_CPU;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // wait until vme-reset has got deactivated
      end
      WAIT_ON_CPU : begin
        bgouten <= 1'b1;
        sysrstn_out_int <= 1'b1;
        // no reset to vme-bus
        v2p_rst_int <=  ~degl_sysrstn;
        clr_sysr <= 1'b0;
        if(degl_sysrstn == 1'b1 && degl_rst == 1'b0) begin
          // wait until vme-bus and cpu reset is inactive
          rst_state <= WAIT_ON_RST;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= WAIT_ON_CPU;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // activate vme reset for (16383 * system_clock_period = 250 us @ 66MHz)
      end
      RST_VME : begin
        bgouten <= 1'b1;
        if(prevent_sysrst == 1'b1) begin
          sysrstn_out_int <= 1'b1;
          // no reset
        end
        else begin
          sysrstn_out_int <= 1'b0;
          // active reset to vme-bus
        end
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        clr_sysr <= 1'b1;
        if(main_cnt_end == 1'b1) begin
          // keep vme-bus reset active for counter time
          rst_state <= RST_VME2;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= RST_VME;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // extend active vme reset time for (16383 * system_clock_period = 250 us @ 66MHz) till cpu reset has got deactivated
      end
      RST_VME2 : begin
        bgouten <= 1'b1;
        if(prevent_sysrst == 1'b1) begin
          sysrstn_out_int <= 1'b1;
          // no reset
        end
        else begin
          sysrstn_out_int <= 1'b0;
          // active reset to vme-bus
        end
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        clr_sysr <= 1'b1;
        if(main_cnt_end == 1'b1 && degl_rst == 1'b0) begin
          // wait until cpu-reset is inactive
          rst_state <= WAIT_ON_VME;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= RST_VME2;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        // wait until vme reset has got deactivated
      end
      WAIT_ON_VME : begin
        bgouten <= 1'b1;
        sysrstn_out_int <= 1'b1;
        // no reset to vme-bus
        v2p_rst_int <= 1'b0;
        // no reset to cpu
        clr_sysr <= 1'b0;
        if(degl_sysrstn == 1'b1) begin
          // wait until vme-bus reset is inactive
          rst_state <= WAIT_ON_RST;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
        else begin
          rst_state <= WAIT_ON_VME;
          rst_pre_cnt <= 1'b0;
          rst_main_cnt <= 1'b0;
        end
      end
      default : begin
        bgouten <= 1'b0;
        sysrstn_out_int <= 1'b1;
        v2p_rst_int <= 1'b0;
        clr_sysr <= 1'b0;
        rst_state <= WAIT_ON_RST;
        rst_pre_cnt <= 1'b0;
        rst_main_cnt <= 1'b0;
      end
      endcase
    end
  end
endmodule

module Volume_Pregain_Top_Module(
output wire [INTBIT_WIDTH - 1:0] OUT_VOLCTRL_L,
output wire [INTBIT_WIDTH - 1:0] OUT_VOLCTRL_R,
output wire OUT_RDY,
input wire [INTBIT_WIDTH - 1:0] IN_SIG_L,
input wire [INTBIT_WIDTH - 1:0] IN_SIG_R,
input wire [(INTBIT_WIDTH + FRACBIT_WIDTH) - 1:0] IN_COEF_L,
input wire [(INTBIT_WIDTH + FRACBIT_WIDTH) - 1:0] IN_COEF_R,
input wire CLK_100mhz,
input wire RESET
);
parameter [31:0] INTBIT_WIDTH;
parameter [31:0] FRACBIT_WIDTH;
// 24 bit signed output
// 24 bit signed output
//amplifier input signal 24-bit
//amplifier input signal 24-bit
// 32 bit COEF from a register. Last 8 bits are fractional for volume control 0<-->1
// 32 bit COEF from a register. Last 8 bits are fractional for volume control 0<-->1
wire [INTBIT_WIDTH - 1:0] AMP_OUT_L = 1'b0; wire [INTBIT_WIDTH - 1:0] AMP_OUT_R = 1'b0;
reg [INTBIT_WIDTH - 1:0] VOLCTRL_L = 1'b0; reg [INTBIT_WIDTH - 1:0] VOLCTRL_R = 1'b0;
wire volctrl_ready_l = 1'b0;
wire volctrl_ready_r = 1'b0;
  AmplifierFP #(
      .INTBIT_WIDTH(INTBIT_WIDTH),
    .FRACBIT_WIDTH(FRACBIT_WIDTH))
  AmplifierFP_L(
      .CLK(CLK_100mhz),
    .RESET(RESET),
    .IN_SIG(IN_SIG_L),
    .IN_COEF(IN_COEF_L),
    .OUT_AMP(AMP_OUT_L),
    .OUT_RDY(volctrl_ready_l));
  AmplifierFP #(
      .INTBIT_WIDTH(INTBIT_WIDTH),
    .FRACBIT_WIDTH(FRACBIT_WIDTH))
  AmplifierFP_R(
      .CLK(CLK_100mhz),
    .RESET(RESET),
    .IN_SIG(IN_SIG_R),
    .IN_COEF(IN_COEF_R),
    .OUT_AMP(AMP_OUT_R),
    .OUT_RDY(volctrl_ready_r));
  always @(posedge CLK_100mhz) begin
    //  update the ready signal when new values gets written to the buffer
    if((volctrl_ready_l == 1'b1)) begin
      VOLCTRL_L <= AMP_OUT_L;
    end
    if((volctrl_ready_r == 1'b1)) begin
      VOLCTRL_R <= AMP_OUT_R;
    end
  end
  assign OUT_RDY = volctrl_ready_l | volctrl_ready_r;
  assign OUT_VOLCTRL_L = VOLCTRL_L;
  assign OUT_VOLCTRL_R = VOLCTRL_R;
endmodule

module c1541_timing(
input wire clock,
input wire reset,
input wire use_c64_reset,
input wire c64_reset_n,
input wire iec_reset_n,
output wire iec_reset_o,
input wire drive_stop,
output reg drv_clock_en,
output wire cpu_clock_en
);
// 1/12.5 (4 MHz)
// 1/50   (1 MHz)
reg [3:0] div_cnt = 4'b0000;
reg [1:0] pre_cnt = 2'b00;
reg cpu_clock_en_i = 1'b0;
reg toggle = 1'b0;
reg [0:2] iec_reset_sh = 3'b000;
reg [0:2] c64_reset_sh = 3'b000;
  always @(posedge clock) begin
    drv_clock_en <= 1'b0;
    cpu_clock_en_i <= 1'b0;
    if(drive_stop == 1'b0) begin
      if((div_cnt == 4'hB && toggle == 1'b0) || (div_cnt == 4'hC && toggle == 1'b1)) begin
        div_cnt <= 4'h0;
        drv_clock_en <= 1'b1;
        toggle <=  ~toggle;
        pre_cnt <= pre_cnt + 1;
        if(pre_cnt == 2'b11) begin
          cpu_clock_en_i <= 1'b1;
        end
      end
      else begin
        div_cnt <= div_cnt + 1;
      end
    end
    if(cpu_clock_en_i == 1'b1) begin
      iec_reset_sh[0] <=  ~iec_reset_n;
      iec_reset_sh[1:2] <= iec_reset_sh[0:1];
      c64_reset_sh[0] <= use_c64_reset &  ~c64_reset_n;
      c64_reset_sh[1:2] <= c64_reset_sh[0:1];
    end
    if(reset == 1'b1) begin
      toggle <= 1'b0;
      pre_cnt <= {2{1'b0}};
      div_cnt <= {4{1'b0}};
    end
  end
  assign cpu_clock_en = cpu_clock_en_i;
  assign iec_reset_o = (iec_reset_sh == 3'b111) || (c64_reset_sh == 3'b111) ? 1'b1 : 1'b0;
endmodule

