module bridge_to_mem_ctrl(
input wire ulpi_clock,
input wire ulpi_reset,
input wire [7:0] nano_addr,
input wire nano_write,
input wire [15:0] nano_wdata,
input wire sys_clock,
input wire sys_reset,
output wire [3:0] cmd_addr,
output wire cmd_valid,
output wire cmd_write,
output wire [15:0] cmd_wdata,
input wire cmd_ack
);
// cmd interface
wire [19:0] fifo_data_in;
wire [19:0] fifo_data_out;
wire fifo_get;
wire fifo_empty;
wire fifo_write;
wire [19:0] cmd_data_out;
  assign fifo_data_in = {nano_addr[3:0],nano_wdata};
  assign fifo_write = (nano_addr[7:4] == 4'h7 && nano_write == 1'b1) ? 1'b1 : 1'b0;
  async_fifo #(
      .g_data_width(20),
    .g_depth_bits(3),
    .g_count_bits(3),
    .g_threshold(3),
    .g_storage(11'bdistributed))
  i_cmd_fifo(
      // write port signals (synchronized to write clock)
    .wr_clock(ulpi_clock),
    .wr_reset(ulpi_reset),
    .wr_en(fifo_write),
    .wr_din(fifo_data_in),
    .wr_flush(1'b0),
    .wr_count(/* open */),
    .wr_full(/* open */),
    .wr_almost_full(/* open */),
    .wr_error(/* open */),
    .wr_inhibit(/* open */),
    // read port signals (synchronized to read clock)
    .rd_clock(sys_clock),
    .rd_reset(sys_reset),
    .rd_en(fifo_get),
    .rd_dout(fifo_data_out),
    .rd_count(/* open */),
    .rd_empty(fifo_empty),
    .rd_almost_empty(/* open */),
    .rd_error(/* open */));
  fall_through_add_on #(
      .g_data_width(20))
  i_ft(
      .clock(sys_clock),
    .reset(sys_reset),
    // fifo side
    .rd_dout(fifo_data_out),
    .rd_empty(fifo_empty),
    .rd_en(fifo_get),
    // consumer side
    .data_out(cmd_data_out),
    .data_valid(cmd_valid),
    .data_next(cmd_ack));
  assign cmd_addr = cmd_data_out[19:16];
  assign cmd_wdata = cmd_data_out[15:0];
  assign cmd_write = 1'b1;
    // we don't support reads yet
endmodule

