module Contatore_finale(
input wire CLK100M,
input wire [7:0] SW,
output wire [0:6] SEG,
output wire [3:0] AN,
output wire [7:0] Led
);
wire [1:0] fsel;  //signal x:std_logic_vector(1 downto 0);
reg [1:0] x;
reg [15:0] limite;
reg [15:0] CC;
reg [15:0] C;
reg clock_1khz;
wire clock_timer;
reg clock_t;
wire [3:0] N0_g; wire [3:0] N1_g; wire [3:0] N2_g; wire [3:0] N3_g; wire [3:0] N0_preset; wire [3:0] N1_preset; wire [3:0] N2_preset; wire [3:0] N3_preset;
reg [3:0] N;
  assign Led[0] = SW[0];
  assign Led[1] = SW[1];
  assign Led[2] = SW[2];
  assign Led[3] = SW[3];
  assign Led[4] = SW[4];
  assign Led[5] = SW[5];
  assign Led[6] = SW[6];
  assign Led[7] = SW[7];
  assign fsel = SW[7:6];
  assign N0_preset = 4'b0000;
  assign N1_preset = 4'b0000;
  assign N2_preset = 4'b0000;
  assign N3_preset = 4'b0001;
  Contatore_4_cifre CONT_4_CFR(
      .Clock_in(clock_t),
    .Enable(SW[0]),
    .Reset(SW[1]),
    .Preset(SW[2]),
    .UpDown(SW[3]),
    .N0_preset(N0_preset),
    .N1_preset(N1_preset),
    .N2_preset(N2_preset),
    .N3_preset(N3_preset),
    .N0(N0_g),
    .N1(N1_g),
    .N2(N2_g),
    .N3(N3_g));
  always @(posedge CLK100M) begin
    if(CC == 49999) begin
      CC <= {16{1'b0}};
      clock_1khz <=  ~clock_1khz;
    end
    else begin
      CC <= CC + 1;
    end
  end
  assign AN[0] = x == 2'b00 ? 1'b0 : 1'b1;
  assign AN[1] = x == 2'b01 ? 1'b0 : 1'b1;
  assign AN[2] = x == 2'b10 ? 1'b0 : 1'b1;
  assign AN[3] = x == 2'b11 ? 1'b0 : 1'b1;
  always @(*) begin
    case(fsel)
      2'b00 : limite <= 1;
      2'b01 : limite <= 4;
      2'b10 : limite <= 49;
      default : limite <= 499;
    endcase
  end
  always @(posedge clock_1khz) begin
    if(C >= limite) begin
      C <= {16{1'b0}};
      clock_t <=  ~clock_t;
    end
    else begin
      C <= C + 1;
    end
  end
  assign clock_timer = fsel == 2'b00 ? clock_1khz : clock_t;
  always @(posedge clock_1khz) begin
    x <= x + 1;
  end
  always @(*) begin
    case(x)
      2'b00 : N <= N0_g;
      2'b01 : N <= N1_g;
      2'b10 : N <= N2_g;
      default : N <= N3_g;
    endcase
  end
  Decoder_7_segmenti DECODER(
      .U_NUMBER(N),
    .SEGMENTS(SEG[0:6]));
endmodule

