module UART_TX(
input wire i_Clk,
input wire i_TX_DV,
input wire [7:0] i_TX_Byte,
output reg o_TX_Active,
output reg o_TX_Serial,
output wire o_TX_Done
);
parameter [31:0] g_CLKS_PER_BIT=5208;
// Needs to be set correctly
parameter [2:0]
  s_Idle = 0,
  s_TX_Start_Bit = 1,
  s_TX_Data_Bits = 2,
  s_TX_Stop_Bit = 3,
  s_Cleanup = 4;
reg [2:0] r_SM_Main = s_Idle;
reg [31:0] r_Clk_Count = 0;
reg [31:0] r_Bit_Index = 0;  // 8 Bits Total
reg [7:0] r_TX_Data = 1'b0;
reg r_TX_Done = 1'b0;
  always @(posedge i_Clk) begin
    case(r_SM_Main)
    s_Idle : begin
      o_TX_Active <= 1'b0;
      o_TX_Serial <= 1'b1;
      // Drive Line High for Idle
      r_TX_Done <= 1'b0;
      r_Clk_Count <= 0;
      r_Bit_Index <= 0;
      if(i_TX_DV == 1'b1) begin
        r_TX_Data <= i_TX_Byte;
        r_SM_Main <= s_TX_Start_Bit;
      end
      else begin
        r_SM_Main <= s_Idle;
      end
      // Send out Start Bit. Start bit = 0
    end
    s_TX_Start_Bit : begin
      o_TX_Active <= 1'b1;
      o_TX_Serial <= 1'b0;
      // Wait g_CLKS_PER_BIT-1 clock cycles for start bit to finish
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Start_Bit;
      end
      else begin
        r_Clk_Count <= 0;
        r_SM_Main <= s_TX_Data_Bits;
      end
      // Wait g_CLKS_PER_BIT-1 clock cycles for data bits to finish          
    end
    s_TX_Data_Bits : begin
      o_TX_Serial <= r_TX_Data[r_Bit_Index];
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Data_Bits;
      end
      else begin
        r_Clk_Count <= 0;
        // Check if we have sent out all bits
        if(r_Bit_Index < 7) begin
          r_Bit_Index <= r_Bit_Index + 1;
          r_SM_Main <= s_TX_Data_Bits;
        end
        else begin
          r_Bit_Index <= 0;
          r_SM_Main <= s_TX_Stop_Bit;
        end
      end
      // Send out Stop bit.  Stop bit = 1
    end
    s_TX_Stop_Bit : begin
      o_TX_Serial <= 1'b1;
      // Wait g_CLKS_PER_BIT-1 clock cycles for Stop bit to finish
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Stop_Bit;
      end
      else begin
        r_TX_Done <= 1'b1;
        r_Clk_Count <= 0;
        r_SM_Main <= s_Cleanup;
      end
      // Stay here 1 clock
    end
    s_Cleanup : begin
      o_TX_Active <= 1'b0;
      r_TX_Done <= 1'b1;
      r_SM_Main <= s_Idle;
    end
    default : begin
      r_SM_Main <= s_Idle;
    end
    endcase
  end
  assign o_TX_Done = r_TX_Done;
endmodule

module Arbiter_out_one_hot_pseudo_checkers(
input wire [1:0] credit,
input wire req_X_N,
input wire req_X_E,
input wire req_X_W,
input wire req_X_S,
input wire req_X_L,
input wire [5:0] state,
input wire grant_Y_N,
input wire grant_Y_E,
input wire grant_Y_W,
input wire grant_Y_S,
input wire grant_Y_L,
input wire [5:0] state_in,
output reg err_Requests_state_in_state_not_equal,
output reg err_IDLE_req_X_N,
output reg err_North_req_X_N,
output reg err_North_credit_not_zero_req_X_N_grant_N,
output reg err_North_credit_zero_or_not_req_X_N_not_grant_N,
output reg err_East_req_X_E,
output reg err_East_credit_not_zero_req_X_E_grant_E,
output reg err_East_credit_zero_or_not_req_X_E_not_grant_E,
output reg err_West_req_X_W,
output reg err_West_credit_not_zero_req_X_W_grant_W,
output reg err_West_credit_zero_or_not_req_X_W_not_grant_W,
output reg err_South_req_X_S,
output reg err_South_credit_not_zero_req_X_S_grant_S,
output reg err_South_credit_zero_or_not_req_X_S_not_grant_S,
output reg err_Local_req_X_L,
output reg err_Local_credit_not_zero_req_X_L_grant_L,
output reg err_Local_credit_zero_or_not_req_X_L_not_grant_L,
output reg err_IDLE_req_X_E,
output reg err_North_req_X_E,
output reg err_East_req_X_W,
output reg err_West_req_X_S,
output reg err_South_req_X_L,
output reg err_Local_req_X_N,
output reg err_IDLE_req_X_W,
output reg err_North_req_X_W,
output reg err_East_req_X_S,
output reg err_West_req_X_L,
output reg err_South_req_X_N,
output reg err_Local_req_X_E,
output reg err_IDLE_req_X_S,
output reg err_North_req_X_S,
output reg err_East_req_X_L,
output reg err_West_req_X_N,
output reg err_South_req_X_E,
output reg err_Local_req_X_W,
output reg err_IDLE_req_X_L,
output reg err_North_req_X_L,
output reg err_East_req_X_N,
output reg err_West_req_X_E,
output reg err_South_req_X_W,
output reg err_Local_req_X_S,
output reg err_state_in_onehot,
output reg err_no_request_grants,
output reg err_request_IDLE_state,
output reg err_request_IDLE_not_Grants,
output reg err_state_North_Invalid_Grant,
output reg err_state_East_Invalid_Grant,
output reg err_state_West_Invalid_Grant,
output reg err_state_South_Invalid_Grant,
output reg err_state_Local_Invalid_Grant,
output reg err_Grants_onehot_or_all_zero
);
// From LBDR modules
// 6 states for Arbiter_out's FSM
// Grants given to LBDR requests (encoded as one-hot)
// 6 states for Arbiter's FSM
// Checker outputs
wire [4:0] Requests;
wire [4:0] Grants;
  assign Requests = {req_X_N,req_X_E,req_X_W,req_X_S,req_X_L};
  assign Grants = {grant_Y_N,grant_Y_E,grant_Y_W,grant_Y_S,grant_Y_L};
  // Checkers
  always @(Requests, state_in) begin
    err_Requests_state_in_state_not_equal <= 1'b0;
    if((Requests == 5'b00000 && state_in != IDLE)) begin
      err_Requests_state_in_state_not_equal <= 1'b1;
    end
  end
  //---------------------------------------------------------------------------------------------------------------------
  //---------------------------------------------------------------------------------------------------------------------
  //---------------------------------------------------------------------------------------------------------------------
  //---------------------------------------------------------------------------------------------------------------------
  //---------------------------------------------------------------------------------------------------------------------
  // Round 1
  // N has highest priority, then E, W, S and L (and then again N). 
  always @(state, req_X_N, state_in) begin
    err_IDLE_req_X_N <= 1'b0;
    if((state == IDLE && req_X_N == 1'b1 && state_in != North)) begin
      err_IDLE_req_X_N <= 1'b1;
    end
