module ledblinker(
input wire rst,
input wire clk,
input wire [2:0] freq,
output wire led
);
parameter RSTDEF=1'b1;
// reset, RSTDEF active
// clock, rising edge
// blinking frequency, 000 = stop, 111 = fast
// LED status, active high
// define length of counter
parameter CNTLEN = 26;  // counter that is incremented on each clk
reg [CNTLEN - 1:0] cnt = 1'b0;  // counter plus zero bit (freq = 0)
wire [CNTLEN:0] cnt_tmp = 1'b0;
  always @(posedge rst, posedge clk) begin
    if(rst == RSTDEF) begin
      cnt <= {((CNTLEN - 1)-(0)+1){1'b0}};
    end else begin
      // increment cnt, carry bit defines LED status
      cnt <= cnt + 1;
    end
  end
  // always keep a leading 0 for freq = 0
  assign cnt_tmp = {1'b0,cnt};
  // led status is defined by carry bit
  // position of carry bit is defined by freq
  assign led = cnt_tmp[CNTLEN - (freq)];
endmodule

module UART_TX(
input wire i_Clk,
input wire i_TX_DV,
input wire [7:0] i_TX_Byte,
output reg o_TX_Active,
output reg o_TX_Serial,
output wire o_TX_Done
);
parameter [31:0] g_CLKS_PER_BIT=115;
// Needs to be set correctly
parameter [2:0]
  s_Idle = 0,
  s_TX_Start_Bit = 1,
  s_TX_Data_Bits = 2,
  s_TX_Stop_Bit = 3,
  s_Cleanup = 4;
reg [2:0] r_SM_Main = s_Idle;
reg [31:0] r_Clk_Count = 0;
reg [31:0] r_Bit_Index = 0;  // 8 Bits Total
reg [7:0] r_TX_Data = 1'b0;
reg r_TX_Done = 1'b0;
  always @(posedge i_Clk) begin
    case(r_SM_Main)
    s_Idle : begin
      o_TX_Active <= 1'b0;
      o_TX_Serial <= 1'b1;
      // Drive Line High for Idle
      r_TX_Done <= 1'b0;
      r_Clk_Count <= 0;
      r_Bit_Index <= 0;
      if(i_TX_DV == 1'b1) begin
        r_TX_Data <= i_TX_Byte;
        r_SM_Main <= s_TX_Start_Bit;
        o_TX_Active <= 1'b1;
      end
      else begin
        r_SM_Main <= s_Idle;
      end
      // Send out Start Bit. Start bit = 0
    end
    s_TX_Start_Bit : begin
      o_TX_Serial <= 1'b0;
      // Wait g_CLKS_PER_BIT-1 clock cycles for start bit to finish
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Start_Bit;
      end
      else begin
        r_Clk_Count <= 0;
        r_SM_Main <= s_TX_Data_Bits;
      end
      // Wait g_CLKS_PER_BIT-1 clock cycles for data bits to finish          
    end
    s_TX_Data_Bits : begin
      o_TX_Serial <= r_TX_Data[r_Bit_Index];
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Data_Bits;
      end
      else begin
        r_Clk_Count <= 0;
        // Check if we have sent out all bits
        if(r_Bit_Index < 7) begin
          r_Bit_Index <= r_Bit_Index + 1;
          r_SM_Main <= s_TX_Data_Bits;
        end
        else begin
          r_Bit_Index <= 0;
          r_SM_Main <= s_TX_Stop_Bit;
        end
      end
      // Send out Stop bit.  Stop bit = 1
    end
    s_TX_Stop_Bit : begin
      o_TX_Serial <= 1'b1;
      // Wait g_CLKS_PER_BIT-1 clock cycles for Stop bit to finish
      if(r_Clk_Count < (g_CLKS_PER_BIT - 1)) begin
        r_Clk_Count <= r_Clk_Count + 1;
        r_SM_Main <= s_TX_Stop_Bit;
      end
      else begin
        r_TX_Done <= 1'b1;
        r_Clk_Count <= 0;
        r_SM_Main <= s_Cleanup;
      end
      // Stay here 1 clock
    end
    s_Cleanup : begin
      o_TX_Active <= 1'b0;
      r_TX_Done <= 1'b1;
      r_SM_Main <= s_Idle;
    end
    default : begin
      r_SM_Main <= s_Idle;
    end
    endcase
  end
  assign o_TX_Done = r_TX_Done;
endmodule

module AAI(
input wire rst,
input wire CS,
input wire [3:0] addr,
input wire [CPUDBwidth - 1:0] Din,
input wire cpuClk,
output wire [width - 1:0] Q
);
parameter [31:0] width=32;
parameter [31:0] CPUDBwidth=8;
parameter [3:0] Baddr=4'b0000;
// system signal
// CPU bus
reg [31:0] start;
reg [CPUDBwidth * 32:0] D;
  always @(posedge cpuClk, posedge rst) begin
    if(rst == 1'b1) begin
      D <= {((CPUDBwidth * 32)-(0)+1){1'b0}};
      start <= 0;
    end else begin
      if(CS == 1'b1) begin
        if(addr == reg_RESET && Din[0] == 1'b1) begin
          start <= 0;
        end
        else if(addr == Baddr) begin
          D[start + CPUDBwidth - 1 -: CPUDBwidth - 1 + 1] <= Din;
          start <= start + CPUDBwidth;
        end
      end
    end
  end
  assign Q = D[width - 1:0];
endmodule

module opc_fetch(
input wire I_CLK,
input wire I_CLR,
input wire [5:0] I_INTVEC,
input wire I_LOAD_PC,
input wire [15:0] I_NEW_PC,
input wire [15:0] I_PM_ADR,
input wire I_SKIP,
output wire [31:0] Q_OPC,
output wire [15:0] Q_PC,
output wire [7:0] Q_PM_DOUT,
output wire Q_T0
);
wire [31:0] P_OPC;
wire [15:0] P_PC;
wire L_INVALIDATE;
wire L_LONG_OP;
wire [15:0] L_NEXT_PC;
wire L_OPC_1_0123;
wire L_OPC_8A_014589CD;
wire L_OPC_9_01;
wire L_OPC_9_5_01_8;
wire L_OPC_9_5_CD_8;
wire L_OPC_9_9B;
wire L_OPC_F_CDEF;
reg [15:0] L_PC;
reg L_T0;
wire L_WAIT;
  prog_mem pmem(
      .I_CLK(I_CLK),
    .I_WAIT(L_WAIT),
    .I_PC(L_NEXT_PC),
    .I_PM_ADR(I_PM_ADR),
    .Q_OPC(P_OPC),
    .Q_PC(P_PC),
    .Q_PM_DOUT(Q_PM_DOUT));
  always @(posedge I_CLK) begin
    L_PC <= L_NEXT_PC;
    L_T0 <=  ~L_WAIT;
  end
  assign L_NEXT_PC = (I_CLR == 1'b1) ? 16'h0000 : (L_WAIT == 1'b1) ? L_PC : (I_LOAD_PC == 1'b1) ? I_NEW_PC : (L_LONG_OP == 1'b1) ? L_PC + 16'h0002 : L_PC + 16'h0001;
  // Two word opcodes:
  //
  //        9       3210
  // 1001 000d dddd 0000 kkkk kkkk kkkk kkkk - LDS
  // 1001 001d dddd 0000 kkkk kkkk kkkk kkkk - SDS
  // 1001 010k kkkk 110k kkkk kkkk kkkk kkkk - JMP
  // 1001 010k kkkk 111k kkkk kkkk kkkk kkkk - CALL
  //
  assign L_LONG_OP = (((P_OPC[15:9] == 7'b1001010) && (P_OPC[3:2] == 2'b11)) || ((P_OPC[15:10] == 6'b100100) && (P_OPC[3:0] == 4'b0000))) ? 1'b1 : 1'b0;
  //--------------------------------
  // Two cycle opcodes...         --
  //--------------------------------
  //-----------------------------------------------
  // 0001 00rd dddd rrrr - CPSE
  //
  assign L_OPC_1_0123 = (P_OPC[15:10] == 6'b000100) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 10q0 qq0d dddd 1qqq - LDD (Y + q)
  // 10q0 qq0d dddd 0qqq - LDD (Z + q)
  //
  assign L_OPC_8A_014589CD = ((P_OPC[15:14] == 2'b10) && (P_OPC[12] == 1'b0) && (P_OPC[9] == 1'b0)) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 1001 000d dddd .... - LDS, LD, LPM (ii/iii), ELPM, POP
  //
  assign L_OPC_9_01 = (P_OPC[15:9] == 7'b1001000) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 1001 0101 0000 1000 - RET
  // 1001 0101 0001 1000 - RETI
  //
  assign L_OPC_9_5_01_8 = ((P_OPC[15:5] == 11'b10010101000) && (P_OPC[3:0] == 4'b1000)) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 1001 0101 1100 1000 - LPM (i)
  // 1001 0101 1101 1000 - ELPM
  //
  assign L_OPC_9_5_CD_8 = ((P_OPC[15:5] == 11'b10010101110) && (P_OPC[3:0] == 4'b1000)) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 1001 1001 AAAA Abbb - SBIC
  // 1001 1011 AAAA Abbb - SBIS
  //
  assign L_OPC_9_9B = ((P_OPC[15:10] == 6'b100110) && (P_OPC[8] == 1'b1)) ? 1'b1 : 1'b0;
  //-----------------------------------------------
  // 1111 110r rrrr 0bbb - SBRC
  // 1111 111r rrrr 0bbb - SBRS
  //
  assign L_OPC_F_CDEF = (P_OPC[15:10] == 6'b111111) ? 1'b1 : 1'b0;
  assign L_WAIT = L_T0 & ( ~L_INVALIDATE) & ( ~I_INTVEC[5]) & (L_OPC_1_0123 | L_OPC_8A_014589CD | L_OPC_9_01 | L_OPC_9_5_01_8 | L_OPC_9_5_CD_8 | L_OPC_9_9B | L_OPC_F_CDEF);
  // SBRC, SBRS
  assign L_INVALIDATE = I_CLR | I_SKIP;
  assign Q_OPC = (L_INVALIDATE == 1'b1) ? 32'h00000000 : (I_INTVEC[5] == 1'b0) ? P_OPC : {24'h000000,2'b00,I_INTVEC};
  // "interrupt opcode"
  assign Q_PC = P_PC;
  assign Q_T0 = L_T0;
endmodule

