module BSA32bits(
input wire [31:0] val1,
input wire [31:0] val2,
output wire [31:0] SomaResult,
input wire clk,
input wire rst,
output wire CarryOut
);
reg Cin_temp; wire Cout_temp; wire Cout_sig; wire done;
wire [31:0] A_sig; wire [31:0] B_sig; reg [31:0] Out_sig;
  Reg32Bit Reg_A(
      .valIn(val1),
    .clk(clk),
    .rst(rst),
    .valOut(A_sig));
  Reg32Bit Reg_B(
      .valIn(val2),
    .clk(clk),
    .rst(rst),
    .valOut(B_sig));
  Reg1Bit Reg_CarryOut(
      .valIn(Cin_temp),
    .clk(clk),
    .rst(rst),
    .valOut(CarryOut));
  Reg32Bit Reg_Ssoma(
      .valIn(Out_sig),
    .clk(clk),
    .rst(rst),
    .valOut(SomaResult));
  always @(posedge clk, posedge rst, posedge done) begin : P1
    reg [31:0] counter = 0;
    if(rst == 1'b1) begin
      Cin_temp <= 1'b0;
    end else begin
      Out_sig[counter] <= (A_sig[counter] ^ B_sig[counter]) ^ Cin_temp;
      Cin_temp <= (A_sig[counter] & B_sig[counter]) | (Cin_temp & A_sig[counter]) | (Cin_temp & B_sig[counter]);
      counter = counter + 1;
    end
  end
endmodule

module uart_receive(
input wire rst_i,
input wire clk_i,
input wire Top16_i,
input wire TopRx_i,
output reg [7:0] Dout_o,
output wire ClrDiv_o,
output reg Recvd,
input wire Rx_i
);
parameter [2:0]
  idle = 0,
  start_rx = 1,
  edge_rx = 2,
  shift_rx = 3,
  stop_rx = 4,
  rxovf = 5;
  //constant NDbits : std_logic_vector(2 downto 0) :=8;
reg [2:0] RxFSM;
reg [7:0] Rx_Reg;
reg [31:0] RxBitCnt;
wire RxRdyi;
wire ClrDiv;
wire RxErr;
  // ------------------------
  // RECEIVE State Machine
  // ------------------------
  always @(posedge rst_i, posedge clk_i) begin
    if(rst_i == 1'b1) begin
      Rx_Reg <= {8{1'b0}};
      Dout_o <= {8{1'b0}};
      RxBitCnt <= 0;
      Recvd <= 1'b0;
      RxFSM <= Idle;
    end else begin
      case(RxFSM)
      Idle : begin
        Recvd <= 1'b0;
        if(Top16_i == 1'b1 && Rx_i == 1'b0) begin
          RxFSM <= Start_Rx;
          RxBitCnt <= 0;
        end
      end
      Start_Rx : begin
        if(TopRx_i == 1'b1) begin
          if(Rx_i == 1'b1) begin
            RxFSM <= RxOVF;
          end
          else begin
            RxFSM <= Edge_Rx;
          end
        end
      end
      Edge_Rx : begin
        if(TopRx_i == 1'b1) begin
          if(RxBitCnt == 8) begin
            RxFSM <= Stop_Rx;
          end
          else begin
            RxFSM <= Shift_Rx;
          end
        end
      end
      Shift_Rx : begin
        if(TopRx_i == 1'b1) begin
          RxFSM <= Edge_Rx;
          Rx_Reg[RxBitCnt] <= Rx_i;
          RxBitCnt <= RxBitCnt + 1;
        end
      end
      Stop_Rx : begin
        if(TopRx_i == 1'b1) begin
          RxFSM <= Idle;
          Dout_o <= Rx_Reg;
          Recvd <= 1'b1;
        end
      end
      RxOVF : begin
        if(Rx_i == 1'b1) begin
          RxFSM <= Idle;
        end
      end
      endcase
    end
  end
  assign ClrDiv_o = ClrDiv;
  assign RxRdyi = RxFSM == Idle ? 1'b1 : 1'b0;
  assign RxErr = RxFSM == RxOVF ? 1'b1 : 1'b0;
