module CNE_01600_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Raz,
input wire i_Enable,
input wire [pkg_Width:0] i_Length,
output wire o_Done
);
// Global clock signal
// Global reset signal
// Reset counting and load length
// Enable the counter
// How much the module should count (Value expected - 1)
// Counter output
reg [pkg_Width:0] Count;  // Counting signal
reg [pkg_Width:0] Length;  // How much the module should count
reg Done;  // Counter output
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      Count <= {((pkg_Width)-(0)+1){1'b0}};
      Length <= {((pkg_Width)-(0)+1){1'b0}};
      Done <= 1'b0;
    end else begin
      if((i_Raz == 1'b1)) begin
        // Reset the counting
        Length <= i_Length;
        Count <= {((pkg_Width)-(0)+1){1'b0}};
      end
      else if((i_Enable == 1'b1 && Done == 1'b0)) begin
        // Counter activated and not finished
        Count <= Count + 1;
      end
      if((Count >= Length)) begin
        // Compared elements are of the same type and dimension
        // Counter finished
        Done <= 1'b1;
      end
      else begin
        Done <= 1'b0;
      end
    end
  end
  assign o_Done = Done;
endmodule

module graycode_dist(
input wire [width - 1:0] inpt0,
input wire [width - 1:0] inpt1,
output wire [width - 1:0] outp
);
parameter [31:0] width;
wire [width - 1:0] aux0;
wire [width - 1:0] aux1;
wire [width - 1:0] zero;
wire [width - 1:0] max;
  assign zero = {((width - 1)-(0)+1){1'b0}};
  assign max = {((width - 1)-(0)+1){1'b1}};
  assign aux0[width - 1] = inpt0[width - 1];
  genvar i;
  generate for (i=width - 2; i >= 0; i = i - 1) begin: gtb0
    assign aux0[i] = inpt0[i] ^ aux0[i + 1];
  end
  endgenerate
  assign aux1[width - 1] = inpt1[width - 1];
  genvar i;
  generate for (i=width - 2; i >= 0; i = i - 1) begin: gbt1
    assign aux1[i] = inpt1[i] ^ aux1[i + 1];
  end
  endgenerate
  assign outp = aux0 > aux1 ? (aux0) - (aux1) : aux0 < aux1 ? (aux1) - (aux0) : zero;
endmodule

