module timer(
input wire clk,
input wire clock_50,
input wire rst,
input wire [31:0] tin,
output wire [31:0] tout,
input wire wr,
output wire INT,
input wire IACK
);
parameter [31:0] speed=500;
//Use 50MHz for time keeping standard
reg [31:0] data_reg;
reg done;
  assign tout[0] = done;
  //-------------------------------------------------------
  //Generating internal clock according to speed parameter
  //Must run on the 50MHz clock so the time is correct
  //-------------------------------------------------------
  always @(posedge clock_50, posedge data_reg[0]) begin : P1
    reg [31:0] loopcount;
    if((data_reg[0] == 1'b0)) begin
      loopcount = 0;
      done <= 1'b0;
    end else begin
      if((loopcount == 49999999)) begin
        //50,000,000 cycles of 50MHz clock = 1 second
        done <= 1'b1;
      end
      else begin
        loopcount = loopcount + 1;
      end
    end
  end
  //----------------------------------------------
  //CPU write 32-bit unsigned to data register
  //This number will not be destroyed for
  //repeating time keeping function
  //Timer stops counting when data_reg=0
  //Write 0 to data_reg to stop timer
  //----------------------------------------------
  always @(posedge rst, posedge clk) begin
    if((rst == 1'b1)) begin
      data_reg <= 32'h00000000;
    end else begin
      if((wr == 1'b1)) begin
        data_reg <= tin;
      end
      //CPU write handle
    end
  end
  //---------------------------------------------
  // INT Handshaking signal handling;
  // When count is DONE, set INT 
  // When IACK is received, reset INT
  //---------------------------------------------
  always @(posedge rst, posedge iack, posedge done) begin
    if((rst == 1'b1 || iack == 1'b1)) begin
      int <= 1'b0;
    end else begin
      int <= 1'b1;
    end
  end
endmodule

module TIMER(
input wire CS,
input wire WE,
input wire [15:0] WR_DATA,
output wire [15:0] RD_DATA,
output wire IRQ,
input wire SEL_IC,
input wire RESET,
input wire FCLK
);
// chip select
// write enable
// write data
// read  data
// Timer Interrupt
// select initial count
// system reset
// fast clock
//=================================================================
// Signal definitions
//=================================================================
// Registers
reg [15:0] IC_REG;  // initial count
// Counters
reg [14:0] PRE;  // prescaler
reg [15:0] CTR;  // timer count
// Counter Control
reg PEN;  // Prescaler count enable
reg CEN;  // Timer count enable
reg DBG;  // Debug mode (no prescaler)
reg TRQ;  // Timer interrupt
reg LOAD;  // load counter
// Terminal Counts
reg TC;  // Timer terminal count
// Terminal Count Constant
parameter PRE_TC = 15'b100101011100000;
parameter DBG_TC = 15'b000010101010101;
  //=============================================
  // Register Writes
  //=============================================
  always @(negedge FCLK) begin
    LOAD <= 1'b0;
    if((CS == 1'b1 && WE == 1'b1)) begin
      if((SEL_IC == 1'b1)) begin
        IC_REG <= WR_DATA;
        LOAD <= 1'b1;
      end
      else begin
        TRQ <= 1'b0;
        DBG <= WR_DATA[1];
        CEN <= WR_DATA[0];
      end
    end
    // set timer interrupt
    if((TC == 1'b1)) begin
      TRQ <= 1'b1;
    end
    if((RESET == 1'b1)) begin
      TRQ <= 1'b0;
      DBG <= 1'b0;
      CEN <= 1'b0;
      IC_REG <= {16{1'b0}};
    end
  end
  assign IRQ = TRQ;
  assign RD_DATA = {15'b000000000000000,TRQ};
  //==================================================
  // Prescaler (divide by 16000)
  //==================================================
  always @(negedge FCLK) begin
    PEN <= 1'b0;
    // If the counter is enabled then count
    if((CEN == 1'b1)) begin
      // linear-feedback counter
      PRE[0] <=  ~(PRE[14] ^ PRE[0]);
      PRE[14:1] <= PRE[13:0];
      // use PRE_TC terminal count for 1-msec
      // use DBG_TC terminal count for debug
      if((((DBG == 1'b0) && (PRE == PRE_TC)) || ((DBG == 1'b1) && (PRE == DBG_TC)))) begin
        PRE <= {15{1'b0}};
        PEN <= 1'b1;
      end
    end
    // reset state
    if((RESET == 1'b1)) begin
      PRE <= {15{1'b0}};
      PEN <= 1'b0;
    end
  end
  //==================================================
  // Timer
  //==================================================
  always @(negedge FCLK) begin
    TC <= 1'b0;
    // count at each prescaler terminal count
    if((PEN == 1'b1)) begin
      CTR <= CTR - 1;
    end
    // terminal count
    if(((PEN == 1'b1) && (CTR == 16'b0000000000000001))) begin
      TC <= 1'b1;
      // Reload the counter when the
      // terminal count is reached
      CTR <= IC_REG;
    end
    // load the counter on uP write
    if((LOAD == 1'b1)) begin
      CTR <= IC_REG;
    end
    // reset state
    if((RESET == 1'b1)) begin
      CTR <= {16{1'b1}};
      TC <= 1'b0;
    end
  end
endmodule

