module xorshift8(
input wire clk,
input wire kick_n,
output reg d_en_n,
output wire [7:0] data
);
reg [7:0] y = 8'ha2;
reg [1:0] state = 2'b00;
  assign data = y[7:0];
  always @(posedge clk) begin
    case(state)
    2'b00 : begin
      d_en_n <= 1'b1;
      if(kick_n == 1'b0) begin
        y <= y ^ ({y[7 - 3:0],3'b000});
        state <= 2'b01;
      end
    end
    2'b01 : begin
      y <= y ^ ({5'b00000,y[7:5]});
      state <= 2'b11;
    end
    2'b11 : begin
      y <= y ^ ({y[7 - 1:0],1'b0});
      state <= 2'b10;
    end
    2'b10 : begin
      state <= 2'b00;
      d_en_n <= 1'b0;
    end
    default : begin
    end
    endcase
  end
endmodule

module zcpsm2dma(
input wire clk,
input wire reset,
input wire zcpsm_clk,
input wire zcpsm_ce,
input wire [3:0] zcpsm_port_id,
input wire zcpsm_write_strobe,
input wire [7:0] zcpsm_out_port,
input wire zcpsm_read_strobe,
output wire [7:0] zcpsm_in_port,
output wire lastframe_flag,
output wire start,
output reg [15:0] length,
output reg [RAM_AWIDTH - 1:0] start_waddr,
output reg [RAM_AWIDTH - 1:0] start_raddr,
output reg [7:0] wstep,
output reg [7:0] rstep,
input wire busy
);
parameter [31:0] RAM_AWIDTH;
parameter PORT_DMA_START = 4'h0;
parameter PORT_DMA_LENGTH_0 = 4'h1;
parameter PORT_DMA_LENGTH_1 = 4'h2;
parameter PORT_DMA_RADDR_0 = 4'h3;
parameter PORT_DMA_RADDR_1 = 4'h4;
parameter PORT_DMA_RADDR_2 = 4'h5;
parameter PORT_DMA_RADDR_3 = 4'h6;
parameter PORT_DMA_WADDR_0 = 4'h7;
parameter PORT_DMA_WADDR_1 = 4'h8;
parameter PORT_DMA_WADDR_2 = 4'h9;
parameter PORT_DMA_WADDR_3 = 4'hA;
parameter PORT_DMA_RSTEP = 4'hB;
parameter PORT_DMA_WSTEP = 4'hC;
parameter PORT_DMA_BUSY = 4'hD;
parameter PORT_RX_LAST_FRAME = 4'hE;
wire zcpsm_we;
wire zcpsm_re;
wire [3:0] zcpsm_addr;
wire start_en;
  assign zcpsm_we = zcpsm_ce & zcpsm_write_strobe;
  assign zcpsm_re = zcpsm_ce & zcpsm_read_strobe;
  assign zcpsm_addr = zcpsm_port_id[3:0];
  assign zcpsm_in_port = zcpsm_ce == 1'b1 && zcpsm_addr == PORT_DMA_BUSY ? {7'b0000000,busy} : {8{1'bZ}};
  always @(posedge zcpsm_clk, posedge reset) begin
    if(reset == 1'b1) begin
      wstep <= 8'h01;
      rstep <= 8'h01;
      length <= {16{1'b0}};
      start_raddr <= {((RAM_AWIDTH - 1)-(0)+1){1'b0}};
      start_waddr <= {((RAM_AWIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if(zcpsm_we == 1'b1) begin
        case(zcpsm_addr)
        PORT_DMA_LENGTH_0 : begin
          length[7:0] <= zcpsm_out_port;
        end
        PORT_DMA_LENGTH_1 : begin
          length[15:8] <= zcpsm_out_port;
        end
        PORT_DMA_RADDR_0 : begin
          start_raddr[7:0] <= zcpsm_out_port;
        end
        PORT_DMA_RADDR_1 : begin
          start_raddr[15:8] <= zcpsm_out_port;
        end
        PORT_DMA_RADDR_2 : begin
          start_raddr[23:16] <= zcpsm_out_port;
        end
        PORT_DMA_RADDR_3 : begin
          start_raddr[31:24] <= zcpsm_out_port;
        end
        PORT_DMA_WADDR_0 : begin
          start_waddr[7:0] <= zcpsm_out_port;
        end
        PORT_DMA_WADDR_1 : begin
          start_waddr[15:8] <= zcpsm_out_port;
        end
        PORT_DMA_WADDR_2 : begin
          start_waddr[23:16] <= zcpsm_out_port;
        end
        PORT_DMA_WADDR_3 : begin
          start_waddr[31:24] <= zcpsm_out_port;
        end
        PORT_DMA_RSTEP : begin
          rstep <= zcpsm_out_port;
        end
        PORT_DMA_WSTEP : begin
          wstep <= zcpsm_out_port;
        end
        default : begin
        end
        endcase
      end
    end
  end
  asyncwrite u_start(
      .reset(reset),
    .async_clk(zcpsm_clk),
    .sync_clk(clk),
    .async_wren(start_en),
    .trigger(1'b1),
    .sync_wren(start),
    .over(/* open */),
    .flag(/* open */));
  assign start_en = zcpsm_we == 1'b1 && zcpsm_addr == PORT_DMA_START ? 1'b1 : 1'b0;
  assign lastframe_flag = zcpsm_we == 1'b1 && zcpsm_addr == PORT_RX_LAST_FRAME ? 1'b1 : 1'b0;
endmodule

