module conv_72to8(
input wire clk_in,
input wire reset_in,
input wire [71:0] data72_in,
input wire valid72_in,
output reg ready72_out,
output reg [7:0] data8_out,
output reg valid8_out,
input wire ready8_in
);
// System clock & reset
// 72-bit data coming in
// 8-bit data going out
parameter [3:0]
  S_WRITE0 = 0,
  S_WRITE1 = 1,
  S_WRITE2 = 2,
  S_WRITE3 = 3,
  S_WRITE4 = 4,
  S_WRITE5 = 5,
  S_WRITE6 = 6,
  S_WRITE7 = 7,
  S_WRITE8 = 8;
reg [3:0] state = S_WRITE0;
reg [3:0] state_next;
reg [63:0] wip = 1'b0;
reg [63:0] wip_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_WRITE0;
      wip <= {64{1'b0}};
    end
    else begin
      state <= state_next;
      wip <= wip_next;
    end
  end
  // Next state logic
  always @(state, wip, data72_in, valid72_in, ready8_in) begin
    state_next <= state;
    valid8_out <= 1'b0;
    wip_next <= wip;
    case(state)
        // Write byte 1
    S_WRITE1 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[63:56];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE2;
      end
      // Write byte 2
    end
    S_WRITE2 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[55:48];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE3;
      end
      // Write byte 3
    end
    S_WRITE3 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[47:40];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE4;
      end
      // Write byte 4
    end
    S_WRITE4 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[39:32];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE5;
      end
      // Write byte 5
    end
    S_WRITE5 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[31:24];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE6;
      end
      // Write byte 6
    end
    S_WRITE6 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[23:16];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE7;
      end
      // Write byte 7
    end
    S_WRITE7 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[15:8];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE8;
      end
      // Write byte 8 (LSB)
    end
    S_WRITE8 : begin
      ready72_out <= 1'b0;
      // not ready for data from 72-bit side
      data8_out <= wip[7:0];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE0;
      end
      // When a word arrives, write byte 0 (MSB)
    end
    default : begin
      ready72_out <= ready8_in;
      // ready for data from 72-bit side
      data8_out <= data72_in[71:64];
      valid8_out <= valid72_in;
      if((valid72_in == 1'b1 && ready8_in == 1'b1)) begin
        wip_next <= data72_in[63:0];
        state_next <= S_WRITE1;
      end
    end
    endcase
  end
endmodule

