  // copy pasted from grain128.c from Hell	
  assign func_h = nfsr[2] ^ nfsr[15] ^ nfsr[36] ^ nfsr[45] ^ nfsr[64] ^ nfsr[73] ^ nfsr[89] ^ lfsr[93] ^ (nfsr[12] & lfsr[8]) ^ (lfsr[13] & lfsr[20]) ^ (nfsr[95] & lfsr[42]) ^ (lfsr[60] & lfsr[79]) ^ (nfsr[12] & nfsr[95] & lfsr[95]);
