module resonant_pfd(
input wire clk,
input wire reset,
input wire sig_in,
input wire ref_in,
output reg up_out,
output reg down_out
);
// Inputs
// Outputs
reg ff;
  // D-type flip-flop
  always @(posedge clk, posedge reset) begin : P2
    reg last_sig;
    if(reset == 1'b1) begin
      ff <= 1'b0;
      last_sig = 1'b0;
      // FF is synchronous so we do not have to synchronize the output after
    end else begin
      if(( ~sig_in) == last_sig && sig_in == 1'b1) begin
        ff <= ref_in;
      end
      last_sig = sig_in;
    end
  end
  // Actual phase-frequency detector
  always @(posedge clk, posedge reset) begin : P1
    reg sig_ref_xor;
    if(reset == 1'b1) begin
      up_out <= 1'b0;
      down_out <= 1'b0;
      sig_ref_xor = 1'b0;
    end else begin
      sig_ref_xor = sig_in ^ ref_in;
      up_out <= sig_ref_xor & ff;
      down_out <= sig_ref_xor &  ~ff;
    end
  end
endmodule

