module bcd_1_adder(
input wire [3:0] A,
input wire [3:0] B,
input wire C_IN,
output reg [3:0] SUM,
output reg C_OUT
);
//algorithm 
// If A + B <= 9 then -- assume both A and B are valid BCD numbers 
// RESULT = A + B ; 
// CARRY = 0 ; 
// else 
// RESULT = A + B + 6 ; 
// CARRY = 1; 
// end if ; 
  //BCD adder logic
  always @(A, B, C_IN) begin
    if(((({1'b0,A}) + ({1'b0,B}) + C_IN) <= 9)) begin
      SUM <= A + B + C_IN;
      C_OUT <= 1'b0;
    end
    else begin
      SUM <= A + B + C_IN + 6;
      C_OUT <= 1'b1;
    end
  end
endmodule

