module interrupt_control(
input wire clock_i,
input wire reset_i,
input wire enable_i,
input wire event_i,
input wire acknowledge_i,
output wire interrupt_o
);
reg interrupt;
  assign interrupt_o = interrupt;
  always @(posedge clock_i) begin
    if((reset_i == 1'b1)) begin
      interrupt <= 1'b0;
    end
    else begin
      interrupt <= interrupt;
      if((enable_i == 1'b0 || acknowledge_i == 1'b1)) begin
        interrupt <= 1'b0;
      end
      else if((event_i == 1'b1)) begin
        interrupt <= 1'b1;
      end
    end
  end
endmodule

module PWMGenerator(
