reg [9:0] PWMCounter_D = 1'b0;
  always @(posedge Clk_CI) begin
      // process outreg
    // rising clock edge
    if(Reset_SI == 1'b1) begin
      // synchronous reset (active high)
      DutyCycle_D <= {10{1'b0}};
      PWMCounter_D <= {10{1'b0}};
      PulseOut_DO <= 1'b0;
    end
    else begin
      DutyCycle_D <= DutyCycle_DI;
      PWMCounter_D <= PWMCounter_D + 1;
      if(PWMCounter_D < DutyCycle_D) begin
        PulseOut_DO <= 1'b1;
      end
      else begin
        PulseOut_DO <= 1'b0;
      end
    end
  end
endmodule

