module sigma_delta_adc(
input wire clk,
input wire reset,
input wire din,
output reg dout,
output reg feedback
);
wire clk_i;
reg dout_i;
wire feedback_i;
  //Sample the output of the LVDS comparator
  always @(posedge reset, posedge clk, posedge din, posedge dout_i) begin
    if(reset == 1'b1) begin
      dout <= 1'b0;
    end else begin
      dout <= din;
      dout_i <= din;
    end
  end
  //Sample the output of the one_bit ADC for input feedback loop
  always @(posedge reset, posedge clk, posedge dout_i) begin
    if(reset == 1'b1) begin
      feedback <= 1'b0;
    end else begin
      feedback <= dout_i;
    end
  end
endmodule

