module FSM(
input wire Clk,
input wire Rst,
input wire Enter,
input wire [1:0] Operacao,
output reg [1:0] Sel,
output reg Enable_1,
output reg Enable_2
);
parameter [2:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3,
  S4 = 4,
  S5 = 5,
  S6 = 6,
  S7 = 7;
reg [2:0] EA;
reg [1:0] last_sel; wire [1:0] last_EN;
  always @(posedge Clk, posedge Rst, posedge Enter, posedge Operacao) begin
      // não esquecer do end if;
    if(Rst == 1'b0) begin
      EA <= S0;
    end else begin
      case(EA)
      S0 : begin
        if(Enter == 1'b0) begin
          EA <= S1;
        end
        else begin
          EA <= S0;
        end
      end
      S1 : begin
        if(Enter == 1'b0) begin
          EA <= S1;
        end
        else begin
          EA <= S2;
        end
      end
      S2 : begin
        if(Operacao == 2'b00) begin
          EA <= S3;
          // Fazer SOMA 
        end
        else if(Operacao == 2'b01) begin
          EA <= S4;
          // Fazer SUB 
        end
        else if(Operacao == 2'b10) begin
          EA <= S5;
          // Fazer /2
        end
        else begin
          EA <= S6;
          // Fazer *2
        end
      end
      S3 : begin
        //SOMA
        if(Enter == 1'b1) begin
          EA <= S3;
        end
        else begin
          EA <= S7;
        end
      end
      S4 : begin
        //SUB
        if(Enter == 1'b1) begin
          EA <= S4;
        end
        else begin
          EA <= S7;
        end
      end
      S5 : begin
        ///2
        EA <= S0;
      end
      S6 : begin
        //*2
        EA <= S0;
      end
      S7 : begin
        if(Enter == 1'b0) begin
          EA <= S7;
        end
        else begin
          EA <= S0;
        end
      end
      endcase
    end
  end
  always @(EA) begin
    case(EA)
    S0 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
    end
    S1 : begin
      Enable_1 <= 1'b1;
      Enable_2 <= 1'b0;
    end
    S2 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
      last_sel <= Operacao;
    end
    S3 : begin
      //SOMA
      //Enable_1 <= '0';
      //Enable_2 <= '0';
      Sel <= last_sel;
    end
    S4 : begin
      //SUB
      //Enable_1 <= '0';
      //Enable_2 <= '0';
      Sel <= last_sel;
    end
    S5 : begin
      ///2
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      Sel <= last_sel;
    end
    S6 : begin
      //*2
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      Sel <= last_sel;
    end
    S7 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      Sel <= last_sel;
    end
    endcase
  end
endmodule

