module desloc_1_bit_esq(
input wire CLK,
input wire ENABLE,
input wire RST,
input wire [7:0] sr_in,
output wire [7:0] sr_out
);
reg [7:0] sr;  // Registrador de N bits
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b0)) begin
      // Reset assíncrono do registrador
      sr <= {8{1'b0}};
    end else begin
      // Sinal de clock do registrador (subida)
      if((ENABLE == 1'b1)) begin
        // Sinal de enable do registrador
        sr[7:1] <= sr_in[6:0];
        // Desloca 1 bit para a esquerda. Bit mais significativo é perdido.
        sr[0] <= 1'b0;
      end
    end
  end
  assign sr_out = sr;
endmodule

module tickgen(
input wire CLK,
input wire RESET,
output wire TICK,
output reg TICK1CLK
);
// tick repetition frequency is (input freq) / (2**COUNTER_WIDTH / DIVISOR)
parameter [31:0] COUNTER_WIDTH=16;
parameter [31:0] DIVISOR=1208;
// output tick of width half repetition period
// output tick of width one CLK period
reg [COUNTER_WIDTH - 1:0] counter = 1'b0;
wire tick_i = 1'b0;
reg tick_prev = 1'b0;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      counter <= {((COUNTER_WIDTH - 1)-(0)+1){1'b0}};
      tick_prev <= 1'b0;
    end else begin
      counter <= counter + DIVISOR;
      tick_prev <= tick_i;
      TICK1CLK <= ( ~tick_prev) & tick_i;
    end
  end
  assign tick_i = counter[COUNTER_WIDTH - 1];
  assign TICK = tick_i;
endmodule

module vga_640x480(
input wire clk,
input wire clr,
output wire hsync,
output wire vsync,
output wire [9:0] hc,
output wire [9:0] vc,
output wire vidon
);
parameter hpixels = 10'b1100100000;  //Pixels in a horizontal line = 800
parameter vlines = 10'b1000001001;  //Lines in the image = 521
parameter hbp = 10'b0010010000;  //Horizontal back porch = 144
parameter hfp = 10'b1100010000;  //Horiztonal front porch = 748
parameter vbp = 10'b0000011111;  //Vertical back porch = 31
parameter vfp = 10'b0111111111;  //Vertical front porch = 511
reg [9:0] hcs; reg [9:0] vcs;  //Horiztonal and vertical counters
reg vsenable;  //Enable for the vertical counter
wire hsync_s; wire vsync_s;
  //Counter for the horizontal sync signal
  always @(posedge clk, posedge clr) begin
    if(clr == 1'b1) begin
      hcs <= 10'b0000000000;
    end else begin
      if(hcs == (hpixels - 1)) begin
        //The counter has reached the end of pixel count, reset
        hcs <= 10'b0000000000;
        //Enable the vertical counter
        vsenable <= 1'b1;
      end
      else begin
        //Increment the horizontal counter
        hcs <= hcs + 1;
        //Leave vsenable off
        vsenable <= 1'b0;
      end
    end
  end
  //Horizontal sync pulse is low when hc is 0-127
  assign hsync_s = hcs < 128 ? 1'b0 : 1'b1;
  //Counter for the vertical sync signal
  always @(posedge clk, posedge clr) begin
    if(clr == 1'b1) begin
      vcs <= 10'b0000000000;
    end else begin
      //Increment when enabled
      if(vcs == (vlines - 1)) begin
        //Reset when the number of lines is reached
        vcs <= 10'b0000000000;
      end
      else begin
        //Increment vertical counter
        vcs <= vcs + 1;
      end
    end
  end
  //Vertical sync pulse is low when vc is 0 or 1
  assign vsync_s = vcs < 2 ? 1'b0 : 1'b1;
  //Enable video out when within the porches
  //vidon <= '1' when (((hcs < hfp) and (hcs >= hbp)) and ((vcs < vfp) and (vcs >= vbp))) else '0';
  assign vidon = vsync_s & hsync_s;
  //Output horizontal and vertical counters
  assign hc = hcs;
  assign vc = vcs;
  assign hsync = hsync_s;
  assign vsync = vsync_s;
endmodule

