module Q16_8_RAM_288s(
input wire RESET,
input wire CLOCK,
input wire HOLDN,
input wire WRITE_EN,
input wire READ_EN,
input wire [31:0] INPUT_1,
output reg [31:0] OUTPUT_1
);
reg [15:0] RAM[0:288 - 1];
reg [8:0] READ_C;
reg [8:0] WRITE_C;
  //
  //
  //
  always @(posedge clock, posedge reset) begin : P3
    reg [8:0] TEMP;
    if(reset == 1'b0) begin
      WRITE_C <= 0;
    end else begin
      if(write_en == 1'b1) begin
        TEMP = WRITE_C + (1);
        if(TEMP == 288) begin
          TEMP = 0;
        end
        WRITE_C <= TEMP;
      end
      else begin
        WRITE_C <= WRITE_C;
      end
    end
  end
  //
  //
  //
  always @(posedge clock, posedge reset) begin : P2
    reg [8:0] TEMP;
    if(reset == 1'b0) begin
      READ_C <= 0;
    end else begin
      if(read_en == 1'b1) begin
        TEMP = READ_C + (1);
        if(TEMP == 288) begin
          TEMP = 0;
        end
        READ_C <= TEMP;
      end
      else begin
        READ_C <= READ_C;
      end
    end
  end
  //
  //
  //
  always @(posedge clock) begin : P1
    reg [31:0] AR;
    reg [31:0] AW;
    AR = READ_C;
    AW = WRITE_C;
    if(WRITE_EN == 1'b1) begin
      RAM[AW] <= INPUT_1[15:0];
    end
    OUTPUT_1[15:0] <= RAM[AR];
  end
  assign OUTPUT_1[31:16] = 16'b0000000000000000;
endmodule

module exceptions(
input wire [31:0] in1,
input wire [31:0] in2,
input wire [31:0] int_mul,
input wire enable,
input wire m_in47,
output reg [31:0] exp_out
);
wire [8:0] expa;
wire [8:0] expb;
wire [8:0] summ;
wire [8:0] m;
  assign expa = {1'b0,in1[30:23]};
  assign expb = {1'b0,in2[30:23]};
  assign m = {8'b00000000,m_in47};
  assign summ = (expa) + (expb) + (m);
  always @(enable, in1, in2, int_mul, summ) begin
    if((enable == 1'b1)) begin
      // not anumber 
      if((in1[30:23] == 8'b11111111 && in1[22:0] != 23'b00000000000000000000000)) begin
        exp_out <= 32'b11111111111111111111111111111111;
        // NaN
      end
      else if((in2[30:23] == 8'b11111111 && in2[22:0] != 23'b00000000000000000000000)) begin
        exp_out <= 32'b11111111111111111111111111111111;
        // NaN
      end
      else if((in1 == 32'h00000000)) begin
        // zero by infinity or negative infinity  = NaN
        if((in2[30:0] == 31'b1111111100000000000000000000000)) begin
          exp_out <= 32'b11111111111111111111111111111111;
          //NaN
          // zero by any number = 0 
        end
        else begin
          exp_out <= {32{1'b0}};
        end
      end
      else if((in2 == 32'h00000000)) begin
        if((in1[30:0] == 31'b1111111100000000000000000000000)) begin
          exp_out <= 32'b11111111111111111111111111111111;
          // NaN
        end
        else begin
          exp_out <= {32{1'b0}};
        end
      end
      else if((in1[30:0] == 31'b1111111100000000000000000000000)) begin
        exp_out <= {int_mul[31],in1[30:0]};
      end
      else if((in2[30:0] == 31'b1111111100000000000000000000000)) begin
        exp_out <= {int_mul[31],in2[30:0]};
        //-overflow detector \\\ ----
      end
      else if((summ >= 9'b111111100)) begin
        exp_out <= {int_mul[31],31'b1111111100000000000000000000000};
        // underflow detector
      end
      else if((summ <= 9'b001111111)) begin
        exp_out <= 32'b00000000000000000000000000000000;
      end
      else begin
        exp_out <= int_mul;
      end
    end
  end
endmodule

