output reg [RegCnt - 1:0] data_out_write,
input wire [7:0] avl_mm_address,
input wire [3:0] avl_mm_writebyteenable,
input wire [31:0] avl_mm_writedata,
input wire avl_mm_chipselect,
output reg [31:0] avl_mm_readdata,
input wire avl_mm_read
);
parameter [31:0] RegCnt=256;
parameter ByteEnable=false;
//    clk.clk
//  reset.reset
//   data.data_in_value
//       .data_in_read
//       .data_out_value
//       .data_out_write
// avl_mm.address
//  .writebyteenable
//       .writedata
//       .chipselect
//       .readdata
//       .read
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      avl_mm_readdata <= {32{1'b0}};
      data_in_read <= {((RegCnt - 1)-(0)+1){1'b0}};
    end else begin
      data_in_read <= {((RegCnt - 1)-(0)+1){1'b0}};
      for (i=0; i <= RegCnt - 1; i = i + 1) begin
        if(i == (avl_mm_address)) begin
          avl_mm_readdata <= data_in_value[(i + 1) * 32 - 1:i * 32];
          if(avl_mm_chipselect == 1'b1 && avl_mm_read == 1'b1) begin
            data_in_read[i] <= 1'b1;
          end
        end
      end
    end
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      data_out_value <= {((RegCnt * 32 - 1)-(0)+1){1'b0}};
      data_out_write <= {((RegCnt - 1)-(0)+1){1'b0}};
    end else begin
      data_out_write <= {((RegCnt - 1)-(0)+1){1'b0}};
      for (i=0; i <= RegCnt - 1; i = i + 1) begin
        if(i == (avl_mm_address) && avl_mm_chipselect == 1'b1) begin
          //and avl_mm_writebyteenable /= "0000" then
          for (b=0; b <= 4 - 1; b = b + 1) begin
            if(avl_mm_writebyteenable[b] == 1'b1) begin
              data_out_value[(i) * 32 + (b + 1) * 8 - 1:b * 8 + i * 32] <= avl_mm_writedata[(b + 1) * 8 - 1:b * 8];
              data_out_write[i] <= 1'b1;
            end
          end
        end
      end
    end
  end
// of new_component
