module Stopwatch(
input wire clk,
input wire stamp_and_reset,
output reg [7:0] time_stamp
);
reg [11:0] counter = 1'b0;
parameter [1:0]
  idle = 0,
  should_stamp = 1,
  should_reset = 2,
  counting = 3;
reg [1:0] state = idle;
  always @(posedge clk, posedge state, posedge counter, posedge stamp_and_reset) begin
    if((stamp_and_reset == 1'b1)) begin
      state <= should_stamp;
      // pXª§¿ºªèAÌNbNÅ^CX^vAXÉÌNbNÅZbg
    end else begin
      if((state == should_stamp)) begin
        time_stamp <= counter[11:4];
        state <= should_reset;
      end
      else if((state == should_reset)) begin
        counter <= {12{1'b0}};
        state <= counting;
      end
      else if((counter == 12'b111111111111)) begin
        counter <= {12{1'b0}};
        time_stamp <= {8{1'b0}};
        state <= idle;
      end
      else if((state == counting)) begin
        counter <= counter + 1;
      end
      else begin
        counter <= counter;
      end
    end
  end
endmodule

