module clockman(
input wire clkin,
output wire clk0
);
// clock input
// double clock rate output
wire clkfb; wire clkfbbuf; wire realclk0;
  // DCM: Digital Clock Manager Circuit for Virtex-II/II-Pro and Spartan-3/3E
  // Xilinx HDL Language Template version 8.1i
  DCM #(
      .CLKDV_DIVIDE(2.0),
    //  Divide by: 1.5,2.0,2.5,3.0,3.5,4.0,4.5,5.0,5.5,6.0,6.5
    //     7.0,7.5,8.0,9.0,10.0,11.0,12.0,13.0,14.0,15.0 or 16.0
    .CLKFX_DIVIDE(1),
    //  Can be any interger from 1 to 32
    .CLKFX_MULTIPLY(2),
    //  Can be any integer from 1 to 32
    .CLKIN_DIVIDE_BY_2(FALSE),
    //  TRUE/FALSE to enable CLKIN divide by two feature
    .CLKIN_PERIOD(20.0),
    //  Specify period of input clock
    .CLKOUT_PHASE_SHIFT(4'bNONE),
    //  Specify phase shift of NONE, FIXED or VARIABLE
    .CLK_FEEDBACK(2'b1X),
    //  Specify clock feedback of NONE, 1X or 2X
    .DESKEW_ADJUST(18'bSYSTEM_SYNCHRONOUS),
    //  SOURCE_SYNCHRONOUS, SYSTEM_SYNCHRONOUS or
    //     an integer from 0 to 15
    .DFS_FREQUENCY_MODE(3'bLOW),
    //  HIGH or LOW frequency mode for frequency synthesis
    .DLL_FREQUENCY_MODE(3'bLOW),
    //  HIGH or LOW frequency mode for DLL
    .DUTY_CYCLE_CORRECTION(FALSE),
    //  Duty cycle correction, TRUE or FALSE
    .FACTORY_JF(16'hC080),
    //  FACTORY JF Values
    .PHASE_SHIFT(0),
    //  Amount of fixed phase shift from -255 to 255
    .STARTUP_WAIT(TRUE))
  DCM_baseClock(
      .CLKIN(clkin),
    // Clock input (from IBUFG, BUFG or DCM)
    .PSCLK(1'b0),
    // Dynamic phase adjust clock input
    .PSEN(1'b0),
    // Dynamic phase adjust enable input
    .PSINCDEC(1'b0),
    // Dynamic phase adjust increment/decrement
    .RST(1'b0),
    // DCM asynchronous reset input
    .CLK2X(realclk0),
    .CLK0(clkfb),
    .CLKFB(clkfbbuf));
  // clkfb is run through a BUFG only to shut up ISE 8.1
  BUFG BUFG_clkfb(
      .O(clkfbbuf),
    // Clock buffer output
    .I(clkfb));
  assign clk0 = realclk0;
endmodule

