module control(
input wire clk,
input wire rst,
input wire en,
input wire done_m,
output reg done,
output reg [1:0] en_mul
);
parameter [1:0]
  idle = 0,
  load = 1,
  multiply = 2,
  deploy = 3;
reg [1:0] State; reg [1:0] NextState;
  always @(State) begin
    NextState <= idle;
    done <= 1'b0;
    en_mul <= 2'b00;
    case(State)
    idle : begin
      done <= 1'b0;
      en_mul <= 2'b00;
      if((en == 1'b1)) begin
        NextState <= load;
      end
      else begin
        NextState <= idle;
      end
    end
    load : begin
      NextState <= multiply;
      done <= 1'b0;
      en_mul <= 2'b01;
    end
    multiply : begin
      done <= 1'b0;
      en_mul <= 2'b11;
      if((done_m == 1'b1)) begin
        NextState <= deploy;
      end
      else begin
        NextState <= multiply;
      end
    end
    deploy : begin
      done <= 1'b1;
      en_mul <= 2'b11;
      NextState <= idle;
    end
    endcase
  end
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b0) begin
      State <= idle;
    end else begin
      State <= NextState;
    end
  end
endmodule

module dp_lsft64x6(
input wire [64:1] inbus,
input wire [6:1] shift,
output wire [64:1] outbus
);
wire [64:1] leftone; wire [64:1] lefttwo; wire [64:1] leftthr;
  assign leftone[1] = inbus[1] &  ~(shift[2]) &  ~(shift[1]);
  assign leftone[2] = (inbus[2] &  ~(shift[2]) &  ~(shift[1])) | (inbus[1] &  ~(shift[2]) & shift[1]);
  assign leftone[3] = (inbus[3] &  ~(shift[2]) &  ~(shift[1])) | (inbus[2] &  ~(shift[2]) & shift[1]) | (inbus[1] & shift[2] &  ~(shift[1]));
  genvar k;
  generate for (k=4; k <= 64; k = k + 1) begin: gla
      assign leftone[k] = (inbus[k] &  ~(shift[2]) &  ~(shift[1])) | (inbus[k - 1] &  ~(shift[2]) & shift[1]) | (inbus[k - 2] & shift[2] &  ~(shift[1])) | (inbus[k - 3] & shift[2] & shift[1]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 4; k = k + 1) begin: glb
      assign lefttwo[k] = leftone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=5; k <= 8; k = k + 1) begin: glc
      assign lefttwo[k] = (leftone[k] &  ~(shift[4]) &  ~(shift[3])) | (leftone[k - 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=9; k <= 12; k = k + 1) begin: gld
      assign lefttwo[k] = (leftone[k] &  ~(shift[4]) &  ~(shift[3])) | (leftone[k - 4] &  ~(shift[4]) & shift[3]) | (leftone[k - 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=13; k <= 64; k = k + 1) begin: gle
      assign lefttwo[k] = (leftone[k] &  ~(shift[4]) &  ~(shift[3])) | (leftone[k - 4] &  ~(shift[4]) & shift[3]) | (leftone[k - 8] & shift[4] &  ~(shift[3])) | (leftone[k - 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 16; k = k + 1) begin: glf
      assign leftthr[k] = lefttwo[k] &  ~(shift[6]) &  ~(shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=17; k <= 32; k = k + 1) begin: glg
      assign leftthr[k] = (lefttwo[k] &  ~(shift[6]) &  ~(shift[5])) | (lefttwo[k - 16] &  ~(shift[6]) & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=33; k <= 48; k = k + 1) begin: glh
      assign leftthr[k] = (lefttwo[k] &  ~(shift[6]) &  ~(shift[5])) | (lefttwo[k - 16] &  ~(shift[6]) & shift[5]) | (lefttwo[k - 32] & shift[6] &  ~(shift[5]));
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: gli
      assign leftthr[k] = (lefttwo[k] &  ~(shift[6]) &  ~(shift[5])) | (lefttwo[k - 16] &  ~(shift[6]) & shift[5]) | (lefttwo[k - 32] & shift[6] &  ~(shift[5])) | (lefttwo[k - 48] & shift[6] & shift[5]);
  end
  endgenerate
  assign outbus = leftthr;
endmodule

