module PS2_driver(
input wire clk,
input wire clk_slow,
output reg [7:0] data_out,
input wire PS2C,
input wire PS2D
);
// klok
// vertraagde klok
// PS2 data output
// PS2_clk pin
// PS2_data pin
reg [31:0] count = 0;  // counter voor inkomende data
reg [10:0] data_driver;  // vector om inkomende bits in te bewaren
reg [7:0] data_in;  // vector om nutige data
reg pulse = 1'b0;  // hulp var
reg pulsemem = 1'b0;  // hulp var
reg ipulse = 1'b0;  // hulp var
reg ipulsemem = 1'b0;  // hulp var
  // Input van PS2 interface binnen halen
  always @(negedge PS2C) begin
    count <= count + 1;
    data_driver[count] <= PS2D;
    if(count == 10) begin
      count <= 0;
      data_in <= data_driver[8:1];
      ipulse <=  ~ipulse;
    end
  end
  // Input vertraging
  always @(posedge clk_slow) begin
    // verandering (input) controleren
    if(!(ipulsemem == ipulse)) begin
      pulse <=  ~pulse;
      ipulsemem <= ipulse;
      // detectie doorgeven aan volgende stap
    end
  end
  // Output timem met interne werking van de andere componenten
  always @(posedge clk) begin
    // als input binnen gekomen is input naar buiten sturen, anders uitgang resetten
    if(pulse == pulsemem) begin
      data_out <= 8'b00000000;
    end
    else begin
      data_out <= data_in;
      pulsemem <= pulse;
    end
  end
endmodule

module ALU(
input wire [31:0] Oper1,
input wire [31:0] Oper2,
input wire [5:0] ALUOP,
input wire carry,
output reg [31:0] Salida
);
  always @(ALUOP, Oper1, Oper2) begin
    case(ALUOP)
    6'b000000 : begin
      //ADD
      Salida <= Oper1 + Oper2;
    end
    6'b000001 : begin
      //SUB
      Salida <= Oper1 - Oper2;
    end
    6'b000010 : begin
      //AND
      Salida <= Oper1 & Oper2;
    end
    6'b000011 : begin
      //ANDN
      Salida <= Oper1 &  ~Oper2;
    end
    6'b000100 : begin
      //OR
      Salida <= Oper1 | Oper2;
    end
    6'b000101 : begin
      //ORN
      Salida <= Oper1 |  ~Oper2;
    end
    6'b000110 : begin
      //XOR
      Salida <= Oper1 ^ Oper2;
    end
    6'b000111 : begin
      //XNOR
      Salida <=  ~(Oper1 ^ Oper2);
    end
    6'b001000 : begin
      //SUBcc
      Salida <= Oper1 - Oper2;
    end
    6'b001001 : begin
      // SUBx
      Salida <= Oper1 - Oper2 - Carry;
    end
    6'b001010 : begin
      //SUBxcc
      Salida <= Oper1 - Oper2 - Carry;
    end
    6'b001011 : begin
      //ANDcc
      Salida <= Oper1 & Oper2;
    end
    6'b001100 : begin
      //ANDNcc
      Salida <= Oper1 &  ~Oper2;
    end
    6'b001101 : begin
      //ORcc
      Salida <= Oper1 | Oper2;
    end
    6'b001110 : begin
      //ORNcc
      Salida <= Oper1 |  ~Oper2;
    end
    6'b001111 : begin
      //XORcc
      Salida <= Oper1 ^ Oper2;
    end
    6'b010000 : begin
      //XNORcc
      Salida <=  ~(Oper1 ^ Oper2);
    end
    6'b010001 : begin
      //ADDx
      Salida <= Oper1 + Oper2 + Carry;
    end
    6'b010010 : begin
      //ADDxcc
      Salida <= Oper1 + Oper2 + Carry;
    end
    6'b010011 : begin
      //ADDcc
      Salida <= Oper1 + Oper2;
    end
    6'b100101 : begin
      //sll
      Salida <= (Oper1) << (Oper2);
    end
    6'b100110 : begin
      //srl
      Salida <= (Oper1) >> (Oper2);
      //SAVE 57
    end
    6'b111001 : begin
      Salida <= Oper1 + Oper2;
      //RESTORE 58
    end
    6'b111101 : begin
      Salida <= Oper1 + Oper2;
    end
    default : begin
      Salida <= {32{1'b1}};
      //error
    end
    endcase
  end
endmodule

