module unidade_controle_logica_jogo(
input wire clock,
input wire reset,
input wire start,
input wire fim_recepcao,
input wire jogada_ok,
input wire fim_jogo,
output reg recebe_dado,
output reg insere_dado,
output reg jogo_acabado,
output reg pronto,
output reg [2:0] estados
);
// indica que um caractere terminou de ser recebido
// indica que o caractere recebido é valido
// indica que o jogo acabou
// habilita a recepção de um dado
// habilita a inserção do dado na memoria
// indica que o jogo acabou
// indica que a jogada terminou de ser processada
parameter [2:0]
  inicial = 0,
  recebe = 1,
  valida_jogada = 2,
  guarda = 3,
  valida_tabuleiro = 4,
  aguarda = 5,
  final = 6;
reg [2:0] estado;
  always @(posedge clock, posedge estado, posedge reset) begin
    if(reset == 1'b1) begin
      estado <= inicial;
    end else begin
      case(estado)
      inicial : begin
        // Aguarda sinal de start
        if(start == 1'b1) begin
          estado <= recebe;
        end
        else begin
          estado <= inicial;
        end
      end
      recebe : begin
        // Espera o dado ser recebido
        if(fim_recepcao == 1'b1) begin
          estado <= valida_jogada;
        end
        else begin
          estado <= recebe;
        end
      end
      valida_jogada : begin
        // Verifica se o caractere é valido
        if(jogada_ok == 1'b0) begin
          estado <= recebe;
        end
        else begin
          estado <= guarda;
        end
      end
      guarda : begin
        // Guarda o dado no tabuleiro
        estado <= valida_tabuleiro;
      end
      valida_tabuleiro : begin
        // Verifica se o jogo acabou
        if(fim_jogo == 1'b1) begin
          estado <= final;
        end
        else begin
          estado <= aguarda;
        end
      end
      aguarda : begin
        // Prepara a interface do jogo
        estado <= inicial;
      end
      final : begin
        // Fim do jogo
        estado <= final;
      end
      default : begin
        // Default
        estado <= inicial;
      end
      endcase
    end
  end
  // logica de saída
  always @(*) begin
    case(estado)
      recebe : recebe_dado <= 1'b1;
      default : recebe_dado <= 1'b0;
    endcase
  end
  always @(*) begin
    case(estado)
      guarda : insere_dado <= 1'b1;
      default : insere_dado <= 1'b0;
    endcase
  end
  always @(*) begin
    case(estado)
      final : jogo_acabado <= 1'b1;
      default : jogo_acabado <= 1'b0;
    endcase
  end
  always @(*) begin
    case(estado)
      aguarda : pronto <= 1'b1;
      default : pronto <= 1'b0;
    endcase
  end
  always @(estado) begin
    case(estado)
    inicial : begin
      estados <= 3'b000;
    end
    recebe : begin
      estados <= 3'b001;
    end
    valida_jogada : begin
      estados <= 3'b010;
    end
    guarda : begin
      estados <= 3'b011;
    end
    valida_tabuleiro : begin
      estados <= 3'b100;
    end
    aguarda : begin
      estados <= 3'b101;
    end
    final : begin
      estados <= 3'b110;
    end
    default : begin
    end
    endcase
  end
endmodule

