module single_cycle(
input wire [7:0] A,
input wire [7:0] B,
input wire clk,
input wire [2:0] op,
input wire reset_n,
input wire start,
output wire done_aax,
output reg [15:0] result_aax
);
// Declarations
//
wire [7:0] a_int; wire [7:0] b_int;
wire [15:0] mul_int1; wire [15:0] mul_int2;
reg done_aax_int;  // VHDL can't read an output  -- Doh!
  //---------------------------------------------------------------
  always @(posedge clk) begin : P1
  //---------------------------------------------------------------
    // Synchronous Reset
    if((reset_n == 1'b0)) begin
      // Reset Actions
      result_aax <= 16'b0000000000000000;
    end
    else begin
      if(START == 1'b1) begin
        case(op)
        3'b001 : begin
          result_aax <= ({8'b00000000,A}) + ({8'b00000000,B});
        end
        3'b010 : begin
          result_aax <= ({8'b00000000,A}) & ({8'b00000000,B});
        end
        3'b011 : begin
          result_aax <= ({8'b00000000,A}) ^ ({8'b00000000,B});
        end
        default : begin
        end
        endcase
      end
    end
  end
  // purpose: This block sets the done signal. This is set on the clock edge if the start signal is high.
  // type : sequential
  // inputs : clk, reset_n, start,op
  // outputs: done_aax_int
  always @(posedge clk, posedge reset_n) begin
      // process set_done_sig
    if(reset_n == 1'b0) begin
      // asynchronous reset (active low)
      done_aax_int <= 1'b0;
    end else begin
      // rising clock edge
      if(((start == 1'b1) && (op != 3'b000) && (done_aax_int == 1'b0) && (reset_n == 1'b1))) begin
        done_aax_int <= 1'b1;
      end
      else begin
        done_aax_int <= 1'b0;
      end
    end
  end
  assign done_aax = done_aax_int;
endmodule

