module MIPS_ALU_ctrl(
input wire [5:0] funct_code,
input wire [1:0] ALU_op,
output reg [3:0] ALU_ctrl
);
  always @(funct_code, ALU_op) begin : P1
    reg [3:0] alu_ctrl_tmp;
    //
    alu_ctrl_tmp = {1{1'bX}};
    //
    if(ALU_op == 2'b00) begin
      // LW/SW
      alu_ctrl_tmp = 4'b0010;
    end
    else if(ALU_op[0] == 1'b1) begin
      // BEQ
      alu_ctrl_tmp = 4'b0110;
    end
    else if(ALU_op[1] == 1'b1) begin
      // R type
      if(funct_code[3:0] == 4'b0000) begin
        // add  
        alu_ctrl_tmp = 4'b0010;
      end
      else if(funct_code[3:0] == 4'b0010) begin
        // sub
        alu_ctrl_tmp = 4'b0110;
      end
      else if(funct_code[3:0] == 4'b0100) begin
        // and  
        alu_ctrl_tmp = 4'b0000;
      end
      else if(funct_code[3:0] == 4'b0101) begin
        // or  
        alu_ctrl_tmp = 4'b0001;
      end
      else if(funct_code[3:0] == 4'b1010) begin
        // slt
        alu_ctrl_tmp = 4'b0111;
        //
      end
    end
    else begin
      alu_ctrl_tmp = {1{1'bX}};
    end
    ALU_ctrl <= alu_ctrl_tmp;
  end
endmodule

module my_fpga(
input wire clk,
input wire n_rst,
input wire up,
input wire dn,
output reg [31:0] cnt,
output reg [3:0] cnt_1k,
input wire in1,
input wire in2,
output wire out1,
output wire out2
);
reg rst;
  or_gate u1_or_gate(
      .a(in1),
    .b(in2),
    .c(out1));
  and_gate u1_and_gate(
      .a(in1),
    .b(in2),
    .c(out2));
  always @(posedge clk, posedge rst) begin : P3
    reg [31:0] count;
    if(rst == 1'b1) begin
      count = 32'h00000000;
      cnt <= 32'h00000000;
    end else begin
      if(up == 1'b1) begin
        count = count + 1;
      end
      else if(dn == 1'b1) begin
        count = count - 1;
      end
      cnt <= count;
    end
  end
  always @(posedge clk, posedge rst) begin : P2
    reg [16:0] div_count;
    reg [3:0] count;
    if(rst == 1'b1) begin
      div_count = {1{1'b0}};
      count = 4'h0;
      cnt_1k <= 4'h0;
    end else begin
      if(div_count == 99999) begin
        div_count = {1{1'b0}};
        if(up == 1'b1) begin
          count = count + 1;
        end
        else if(dn == 1'b1) begin
          count = count - 1;
        end
      end
      else begin
        div_count = div_count + 1;
      end
      cnt_1k <= count;
    end
  end
  always @(posedge clk, posedge n_rst) begin : P1
    reg [1:0] rst_sr;
    if(n_rst == 1'b0) begin
      rst_sr = 2'b11;
      rst <= 1'b1;
    end else begin
      rst <= rst_sr[1];
      rst_sr[1] = rst_sr[0];
      rst_sr[0] =  ~n_rst;
    end
  end
endmodule

