module edgedetector(
input wire iArst,
input wire iClk,
input wire iEnable,
input wire iData,
output reg oRising,
output reg oFalling,
output reg oAny
);
//! Asynchronous reset
//! Clock
//! Enable detection
//! Data to be sampled
//! Rising edge detected (unregistered)
//! Falling edge detected (unregistered)
//! Any edge detected (unregistered)
//! Register to delay input by one clock cycle
reg reg;  //! Register next
wire reg_next;  //! Second register
reg reg_l;  //! Second register next
wire reg_l_next;
  // assign input data to register
  assign reg_next = iData;
  //! Detection
  always @(iEnable, reg, reg_l) begin
    // default
    oRising <= cInactivated;
    oFalling <= cInactivated;
    oAny <= cInactivated;
    if(iEnable == cActivated) begin
      // rising edge
      if(reg_l == cInactivated && reg == cActivated) begin
        oRising <= cActivated;
        oAny <= cActivated;
      end
      // falling edge
      if(reg_l == cActivated && reg == cInactivated) begin
        oFalling <= cActivated;
        oAny <= cActivated;
      end
    end
  end
  assign reg_l_next = reg;
  //! Clock process
  always @(posedge iArst, posedge iClk) begin
    if(iArst == cActivated) begin
      reg <= cInactivated;
      reg_l <= cInactivated;
    end else begin
      reg <= reg_next;
      reg_l <= reg_l_next;
    end
  end
endmodule

module generic_hdl_fifo(
input wire clk,
input wire rst_n,
input wire [G_WIDTH - 1:0] data_wr,
input wire wr_en,
input wire rd_en,
output wire [G_WIDTH - 1:0] data_rd,
output wire rd_valid,
output wire [G_DEPTH_LOG2:0] nb_data,
output wire empty,
output wire full
);
parameter [31:0] G_DEPTH_LOG2=4;
parameter [31:0] G_WIDTH=8;
// Data
// Status
wire [G_DEPTH_LOG2:0] c_one_loop;  //:= (G_DEPTH_LOG2 => '1', others => '0');
reg [G_WIDTH - 1:0] RAM[2 ** G_DEPTH_LOG2 - 1:0] = 1'b0;
reg [G_DEPTH_LOG2:0] cur_ptr_wr = 1'b0;
wire [G_DEPTH_LOG2 - 1:0] cur_ptr_wr_lsb = 1'b0;
wire s_full = 1'b0;
reg [G_DEPTH_LOG2:0] cur_ptr_rd = 1'b0;
wire [G_DEPTH_LOG2 - 1:0] cur_ptr_rd_lsb = 1'b0;
wire s_empty = 1'b0;
reg [G_WIDTH - 1:0] r_data_rd = 1'b0;
reg r_rd_valid = 1'b0;
wire [G_DEPTH_LOG2:0] s_nb_data = 1'b0;
  assign c_one_loop[G_DEPTH_LOG2] = 1'b1;
  assign c_one_loop[G_DEPTH_LOG2 - 1:0] = {((G_DEPTH_LOG2 - 1)-(0)+1){1'b0}};
  assign cur_ptr_wr_lsb = cur_ptr_wr[G_DEPTH_LOG2 - 1:0];
  assign cur_ptr_rd_lsb = cur_ptr_rd[G_DEPTH_LOG2 - 1:0];
  // Write process
  always @(posedge clk) begin
    if(rst_n == 1'b0) begin
      cur_ptr_wr <= {((G_DEPTH_LOG2)-(0)+1){1'b0}};
    end
    else begin
      if(wr_en == 1'b1 && s_full == 1'b0) begin
        cur_ptr_wr <= cur_ptr_wr + 1;
        RAM[cur_ptr_wr_lsb] <= data_wr;
      end
    end
  end
  // Read process
  always @(posedge clk) begin
    if(rst_n == 1'b0) begin
      r_rd_valid <= 1'b0;
      cur_ptr_rd <= {((G_DEPTH_LOG2)-(0)+1){1'b0}};
      r_data_rd <= {((G_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      r_rd_valid <= 1'b0;
      if(rd_en == 1'b1 && s_empty == 1'b0) begin
        cur_ptr_rd <= cur_ptr_rd + 1;
        r_data_rd <= RAM[cur_ptr_rd_lsb];
        r_rd_valid <= 1'b1;
      end
    end
  end
  // Status
  assign s_full = cur_ptr_wr == (cur_ptr_rd + c_one_loop) ? 1'b1 : rst_n == 1'b0 ? 1'b1 : 1'b0;
  assign s_empty = cur_ptr_wr == cur_ptr_rd ? 1'b1 : 1'b0;
  assign s_nb_data = (cur_ptr_wr) - (cur_ptr_rd);
  // Mapping output
  assign full = s_full;
  assign empty = s_empty;
  assign nb_data = s_nb_data;
  assign data_rd = r_data_rd;
  assign rd_valid = r_rd_valid;
endmodule

