module VGA_sync_gen(
input wire clk,
input wire rst,
output wire [COUNT_WIDTH - 1:0] Hcount,
output wire [COUNT_WIDTH - 1:0] Vcount,
output reg Horiz_Sync,
output reg Vert_Sync,
output reg Video_on
);
reg [COUNT_WIDTH - 1:0] Hcount_temp; reg [COUNT_WIDTH - 1:0] Vcount_temp;
  assign Hcount = Hcount_temp;
  assign Vcount = Vcount_temp;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      Hcount_temp <= {((COUNT_WIDTH - 1)-(0)+1){1'b0}};
      Vcount_temp <= {((COUNT_WIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if((Hcount_temp == H_MAX)) begin
        Hcount_temp <= {((COUNT_WIDTH - 1)-(0)+1){1'b0}};
      end
      else begin
        Hcount_temp <= Hcount_temp + 1;
      end
      if((Vcount_temp == V_MAX)) begin
        Vcount_temp <= {((COUNT_WIDTH - 1)-(0)+1){1'b0}};
      end
      else if((Hcount_temp == H_VERT_INC)) begin
        Vcount_temp <= Vcount_temp + 1;
      end
    end
  end
  always @(Hcount_temp, Vcount_temp) begin
    if((Hcount_temp >= HSYNC_BEGIN && Hcount_temp <= HSYNC_END)) begin
      Horiz_Sync <= 1'b0;
      //active low
    end
    else begin
      Horiz_Sync <= 1'b1;
    end
    if((Vcount_temp >= VSYNC_BEGIN && Vcount_temp <= VSYNC_END)) begin
      Vert_Sync <= 1'b0;
    end
    else begin
      Vert_Sync <= 1'b1;
    end
    if(((Hcount_temp >= 0 && Hcount_temp <= H_DISPLAY_END) && (Vcount_temp >= 0 && Vcount_temp <= V_DISPLAY_END))) begin
      Video_on <= 1'b1;
      //this one is active high
    end
    else begin
      Video_on <= 1'b0;
    end
  end
endmodule

