module pwm(
input wire clk,
input wire reset_n,
input wire ena,
input wire [bits_resolution - 1:0] duty,
output reg [phases - 1:0] pwm_out,
output reg [phases - 1:0] pwm_n_out
);
parameter [31:0] sys_clk=50000000;
parameter [31:0] pwm_freq=100000;
parameter [31:0] bits_resolution=8;
parameter [31:0] phases=1;
//number of output pwms and phases
//system clock
//asynchronous reset
//latches in new duty cycle
//duty cycle
//pwm outputs
//pwm inverse outputs
parameter period = sys_clk / pwm_freq;  //number of clocks in one pwm period
  //data type for array of period counters
reg [31:0] count[0:phases - 1] = 0;  //array of period counters
reg [31:0] half_duty_new = 0;  //number of clocks in 1/2 duty cycle
  //data type for array of half duty values
reg [31:0] half_duty[0:phases - 1] = 0;  //array of half duty values (for each phase)
  always @(posedge clk, posedge reset_n) begin : P1
    reg [bits_resolution + 24 - 1:0] v_compute;
    if((reset_n == 1'b0)) begin
      //asynchronous reset
      count <= {1{0}};
      //clear counter
      pwm_out <= {((phases - 1)-(0)+1){1'b0}};
      //clear pwm outputs
      pwm_n_out <= {((phases - 1)-(0)+1){1'b0}};
      //clear pwm inverse outputs
    end else begin
      //rising system clock edge
      if((ena == 1'b1)) begin
        //latch in new duty cycle
        v_compute = (duty) * (period) / (2 ** (bits_resolution + 1));
        half_duty_new <= v_compute[31 - 1:0];
        //(unsigned(duty)*period/(2**(bits_resolution))/2));--conv_integer(duty)*period/(2**bits_resolution)/2;   --determine clocks in 1/2 duty cycle
      end
      for (i=0; i <= phases - 1; i = i + 1) begin
        //create a counter for each phase
        if((count[0] == (period - 1 - i * period / phases))) begin
          //end of period reached
          count[i] <= 0;
          //reset counter
          half_duty[i] <= half_duty_new;
          //set most recent duty cycle value
        end
        else begin
          //end of period not reached
          count[i] <= count[i] + 1;
          //increment counter
        end
      end
      for (i=0; i <= phases - 1; i = i + 1) begin
        //control outputs for each phase
        if((count[i] == half_duty[i])) begin
          //phase's falling edge reached
          pwm_out[i] <= 1'b0;
          //deassert the pwm output
          pwm_n_out[i] <= 1'b1;
          //assert the pwm inverse output
        end
        else if((count[i] == (period - half_duty[i]))) begin
          //phase's rising edge reached
          pwm_out[i] <= 1'b1;
          //assert the pwm output
          pwm_n_out[i] <= 1'b0;
          //deassert the pwm inverse output
        end
      end
    end
  end
endmodule

module clockDivider(
