  always @(posedge CLOCKIN) begin : P1
    reg [31:0] counter = 0;
    if(counter < COUNT_MAX) begin
      counter = counter + 1;
    end
    else begin
      counter = 0;
      clock <=  ~clock;
    end
  end
  assign CLOCKOUT = clock;
endmodule

