module led8_sseg(
input wire clk,
input wire reset,
input wire [7:0] led,
output wire [4:0] an,
output reg [7:0] sseg_out
);
parameter [31:0] clock_freq_hz=50000000;
parameter [31:0] refresh_rate_hz=800;
parameter clk_divider = clock_freq_hz / (refresh_rate_hz * 5);
reg [7:0] sseg0; reg [7:0] sseg1; reg [7:0] sseg2; reg [7:0] sseg3; wire [7:0] sseg_clk;
reg [31:0] divider_counter;
wire divider_end;
reg [4:0] an_r = 5'b00001;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      divider_counter <= clk_divider;
    end else begin
      if(divider_counter == 0) begin
        divider_counter <= clk_divider;
      end
      else begin
        divider_counter <= divider_counter - 1;
      end
    end
  end
  assign divider_end = divider_counter == 0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      an_r[4:1] <= {4{1'b0}};
    end else begin
      if(divider_end == 1'b1) begin
        an_r[4:1] <= an_r[3:0];
        an_r[0] <= an_r[4];
      end
    end
  end
  always @(*) begin
    case(an_r)
      5'b00001 : sseg_out <= sseg0;
      5'b00010 : sseg_out <= sseg1;
      5'b00100 : sseg_out <= sseg2;
      5'b01000 : sseg_out <= sseg3;
      5'b10000 : sseg_out <= sseg_clk;
      default : sseg_out <= {8{1'b0}};
    endcase
  end
  assign an = an_r;
  // --CONVERT THE LEDS TO THE 4X SEVEN SEGMENTS LED segements
  always @(*) begin
    case(led[1:0])
      2'b01 : sseg0 <= 8'b00000100;
      2'b10 : sseg0 <= 8'b00010000;
      2'b11 : sseg0 <= 8'b00010100;
      2'b00 : sseg0 <= 8'b00000000;
    endcase
  end
  always @(*) begin
    case(led[3:2])
      2'b01 : sseg1 <= 8'b00000100;
      2'b10 : sseg1 <= 8'b00010000;
      2'b11 : sseg1 <= 8'b00010100;
      2'b00 : sseg1 <= 8'b00000000;
    endcase
  end
  always @(*) begin
    case(led[5:4])
      2'b01 : sseg2 <= 8'b00000100;
      2'b10 : sseg2 <= 8'b00010000;
      2'b11 : sseg2 <= 8'b00010100;
      2'b00 : sseg2 <= 8'b00000000;
    endcase
  end
  always @(*) begin
    case(led[7:6])
      2'b01 : sseg3 <= 8'b00000100;
      2'b10 : sseg3 <= 8'b00010000;
      2'b11 : sseg3 <= 8'b00010100;
      2'b00 : sseg3 <= 8'b00000000;
    endcase
  end
endmodule

module GuessGame(
input wire [7:0] inputs,
input wire set,
input wire show,
input wire try,
output wire [6:0] hex1,
output wire [6:0] hex10
);
