// Show predefined value
// Evaluate guess
// 7seg ones
// 7seg tens
// declare signals, components here...
reg [7:0] setValue = 8'b00000000; reg [7:0] dispValue = 8'b00000000;
  DecimalSeg ones(
      .bin(dispValue[3:0]),
    .seg(hex1));
  DecimalSeg tens(
      .bin(dispValue[7:4]),
    .seg(hex10));
  // architecture body...
  always @(show, set, try) begin
    if(set == 1'b0) begin
      setValue <= inputs;
      dispValue <= setValue;
      // to avoid inferred latch for dispValue
    end
    else if(show == 1'b0) begin
      dispValue <= setValue;
    end
    else if(try == 1'b0) begin
      if(inputs < setValue) begin
        dispValue <= 8'b10101011;
      end
      else if(inputs > setValue) begin
        dispValue <= 8'b11001101;
      end
      else begin
        dispValue <= 8'b11101110;
      end
    end
    else begin
      dispValue <= inputs;
    end
  end
