output wire wbm_clk,
output wire wbm_rst,
output wire [12:0] wbm_address,
input wire [15:0] wbm_readdata,
output wire [15:0] wbm_writedata,
output wire wbm_strobe,
output wire wbm_write,
input wire wbm_ack,
output wire wbm_cycle,
input wire gls_clk,
input wire gls_reset
);
// i.MX Signals
// Wishbone interface signals
// Address bus
// Data bus for read access
// Data bus for write access
// Data Strobe
// Write access
// acknowledge
// bus cycle in progress
// clock and reset inputs 
reg write;
reg read;
reg strobe;
reg [15:0] writedata;
reg [12:0] address;
  assign wbm_clk = gls_clk;
  assign wbm_rst = gls_reset;
  //  External signals synchronization process
  always @(posedge gls_clk, posedge gls_reset) begin
    if((gls_reset == 1'b1)) begin
      write <= 1'b0;
      read <= 1'b0;
      strobe <= 1'b0;
      writedata <= {16{1'b0}};
      address <= {13{1'b0}};
    end else begin
      strobe <=  ~(imx_cs_n) &  ~(imx_oe_n & imx_eb0_n);
      write <=  ~(imx_cs_n | imx_eb0_n);
      read <=  ~(imx_cs_n | imx_oe_n);
      address <= {imx_address,1'b0};
      writedata <= imx_data;
    end
  end
  assign wbm_address = (strobe == 1'b1) ? address : {13{1'b0}};
  assign wbm_writedata = (write == 1'b1) ? writedata : {16{1'b0}};
  assign wbm_strobe = strobe;
  assign wbm_write = write;
  assign wbm_cycle = strobe;
  assign imx_data = (read == 1'b1) ? wbm_readdata : {16{1'bZ}};
endmodule

