input wire Clk,
output wire RingFlag
);
//switches
//switches
reg [3:0] alarm_hour_dec;
reg [3:0] alarm_hour_uni;
reg [3:0] alarm_min_dec;
reg [3:0] alarm_min_uni;
reg flag;
  always @(posedge Clk, posedge Rst, posedge LoadMin, posedge LoadHor, posedge DecEnt, posedge UniEnt, posedge alarm_hour_dec, posedge alarm_hour_uni, posedge alarm_min_dec, posedge alarm_min_uni, posedge DecHor, posedge UniHor, posedge DecMin, posedge UniMin) begin
    if((Rst == 1'b1)) begin
      alarm_hour_dec <= {4{1'b0}};
      alarm_hour_uni <= {4{1'b0}};
      alarm_min_dec <= {4{1'b0}};
      alarm_min_uni <= {4{1'b0}};
    end else begin
      if((LoadHor == 1'b1)) begin
        alarm_hour_dec <= DecEnt[3:0];
        alarm_hour_uni <= UniEnt[3:0];
      end
      else if((LoadMin == 1'b1)) begin
        alarm_min_dec <= DecEnt[3:0];
        alarm_min_uni <= UniEnt[3:0];
      end
      else if((alarm_hour_dec == DecHor && alarm_hour_uni == UniHor && alarm_min_dec == DecMin && alarm_min_uni == UniMin)) begin
        flag <= 1'b1;
      end
      else begin
        flag <= 1'b0;
      end
    end
