module mdio_set_100Full(
input wire clk,
input wire rst,
output reg mdio_op,
output reg [4:0] mdio_addr,
input wire [15:0] data_i,
output reg [15:0] data_o,
input wire mdio_busy,
output reg mdio_kick,
input wire [4:0] mnl_addr,
input wire mnl_trgr,
output wire cfg_busy
);
parameter [2:0]
  wait_rdy = 0,
  write_caps = 1,
  read_status = 2,
  check_status = 3,
  retry = 4,
  done = 5;
  // wait rdy
// write abilities
// loop reading autoneg done
// restart autoneg, go back one
// Initial setting to kick off state machine
reg [2:0] state = wait_rdy;
reg [2:0] trgt = write_caps;
reg [2:0] NEXT_state; reg [2:0] NEXT_trgt;
  assign cfg_busy = state == done ? 1'b0 : 1'b1;
  always @(state, mdio_busy, data_i, trgt, mnl_addr, mnl_trgr) begin
    NEXT_state <= state;
    NEXT_trgt <= trgt;
    mdio_op <= 1'b0;
    mdio_addr <= {5{1'b0}};
    mdio_kick <= 1'b0;
    data_o <= {16{1'b0}};
    case(state)
    wait_rdy : begin
      if(mdio_busy == 1'b0) begin
        NEXT_state <= trgt;
      end
    end
    write_caps : begin
      NEXT_state <= wait_rdy;
      NEXT_trgt <= read_status;
      mdio_op <= 1'b1;
      mdio_addr <= 5'b00100;
      data_o <= 16'h0181;
      mdio_kick <= 1'b1;
    end
    read_status : begin
      NEXT_state <= wait_rdy;
      NEXT_trgt <= check_status;
      mdio_op <= 1'b0;
      mdio_addr <= 5'b11111;
      mdio_kick <= 1'b1;
    end
    check_status : begin
      if(data_i[12] == 1'b0) begin
        // autoneg not done
        NEXT_state <= read_status;
      end
      else begin
        if(data_i[4:2] == 3'b110) begin
          NEXT_state <= done;
        end
        else begin
          NEXT_state <= retry;
        end
      end
    end
    retry : begin
      NEXT_state <= wait_rdy;
      NEXT_trgt <= read_status;
      mdio_op <= 1'b1;
      mdio_addr <= 5'b00000;
      data_o <= 16'h8000;
      mdio_kick <= 1'b1;
    end
    done : begin
      mdio_addr <= mnl_addr;
      mdio_kick <= mnl_trgr;
    end
    endcase
  end
  always @(posedge clk) begin
    state <= NEXT_state;
    trgt <= NEXT_trgt;
    if(rst == 1'b1) begin
      state <= wait_rdy;
      trgt <= write_caps;
    end
  end
endmodule

module variable_prescaler(
input wire clk_in,
input wire [1:0] control,
input wire reset,
output wire clk_out
);
reg [31:0] limit = 0;
reg temporal;
reg [31:0] counter = 0;
  always @(control) begin
    case(control)
    2'b00 : begin
      limit <= 25000000;
    end
    2'b01 : begin
      limit <= 12500000;
    end
    2'b10 : begin
      limit <= 6250000;
    end
    2'b11 : begin
      limit <= 3125000;
    end
    default : begin
      limit <= 0;
    end
    endcase
  end
  always @(posedge reset, posedge clk_in, posedge limit) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      counter <= 0;
    end else begin
      if((counter == limit)) begin
        temporal <=  ~(temporal);
        counter <= 0;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  assign clk_out = temporal;
endmodule

