module decode4(
input wire [3:0] d,
input wire enable,
output reg q8,
output reg q9,
output reg q11
);
  always @(enable, d) begin
    if(enable == 1'b1) begin
      case(d)
      4'b1000 : begin
        q8 <= 1'b0;
        q9 <= 1'b1;
        q11 <= 1'b1;
      end
      4'b1001 : begin
        q8 <= 1'b1;
        q9 <= 1'b0;
        q11 <= 1'b1;
      end
      4'b1011 : begin
        q8 <= 1'b1;
        q9 <= 1'b1;
        q11 <= 1'b0;
      end
      default : begin
        q8 <= 1'b1;
        q9 <= 1'b1;
        q11 <= 1'b1;
      end
      endcase
    end
    else begin
      q8 <= 1'b1;
      q9 <= 1'b1;
      q11 <= 1'b1;
    end
  end
endmodule

module projeto2(
input wire [3:0] a,
input wire [3:0] b,
input wire sel,
input wire clk,
output reg [6:0] display1,
output reg [6:0] display2
);
// Entrada A.
// Entrada B.
// Seletora de displays.
// Clock.
reg [3:0] saida_mux;
reg [6:0] bcd;  // BCD.
  // Mux 8->4.
  always @(a, b, clk) begin
    if((clk == 1'b0)) begin
      saida_mux <= a;
    end
    else begin
      saida_mux <= b;
    end
  end
  // BCD.
  always @(a, b, clk, saida_mux, bcd) begin
    if((saida_mux == 4'b0000)) begin
      // 0
      bcd <= 7'b1111110;
    end
    else if((saida_mux == 4'b0001)) begin
      // 1
      bcd <= 7'b0110000;
    end
    else if((saida_mux == 4'b0010)) begin
      // 2
      bcd <= 7'b1101101;
    end
    else if((saida_mux == 4'b0011)) begin
      // 3
      bcd <= 7'b1111001;
    end
    else if((saida_mux == 4'b0100)) begin
      // 4
      bcd <= 7'b0110010;
    end
    else if((saida_mux == 4'b0101)) begin
      // 5
      bcd <= 7'b1011010;
    end
    else if((saida_mux == 4'b0110)) begin
      // 6
      bcd <= 7'b1011111;
    end
    else if((saida_mux == 4'b0111)) begin
      // 7
      bcd <= 7'b1110000;
    end
    else if((saida_mux == 4'b1000)) begin
      // 8
      bcd <= 7'b1111111;
    end
    else if((saida_mux == 4'b1001)) begin
      // 9
      bcd <= 7'b1111011;
    end
    else if((saida_mux == 4'b1010)) begin
      // A
      bcd <= 7'b1110111;
    end
    else if((saida_mux == 4'b1011)) begin
      // B
      bcd <= 7'b0011111;
    end
    else if((saida_mux == 4'b1100)) begin
      // C
      bcd <= 7'b1001110;
    end
    else if((saida_mux == 4'b1101)) begin
      // D
      bcd <= 7'b0111101;
    end
    else if((saida_mux == 4'b1110)) begin
      // E
      bcd <= 7'b1001111;
    end
    else begin
      bcd <= 7'b1000111;
      // Caso defaul -> 'F'
    end
  end
  // Mux 1->2.
  always @(bcd, clk, sel) begin
    if((clk == 1'b0 && sel == 1'b0)) begin
      // Se sel = 0 então mostra B.
      display2 <= bcd;
      // Mostra B no display.
      display1 <= 8'b00000000;
      // Desliga A.
    end
    else if((clk == 1'b1 && sel == 1'b1)) begin
      // Se sel = 1 então mostra A.
      display1 <= bcd;
      // Mostra A no display.
      display2 <= 8'b00000000;
      // Desliga B.
    end
    else begin
      // Caso inesperado.
      display1 <= 8'b00000000;
      // Desliga A.
      display2 <= 8'b00000000;
      // Desliga B.
    end
  end
endmodule

