    4'b1111 : begin
      if((sdiv > 12'b010000000000)) begin
        outdiv <=  ~(outdiv);
        sdiv <= {12{1'b0}};
      end
      else begin
        sdiv <= sdiv + 1;
      end
    end
    4'b1110 : begin
      if((sdiv > 12'b100000000000)) begin
        outdiv <=  ~(outdiv);
        sdiv <= {12{1'b0}};
      end
      else begin
        sdiv <= sdiv + 1;
      end
    end
    default : begin
    end
    endcase
  end
