module TX(
input wire CLK,
input wire START,
output reg BUSY,
input wire [7:0] DATA,
output reg TX_LINE
);
reg [31:0] PRSCL = 0;
reg [31:0] INDEX = 0;
reg [9:0] DATAFLL;
reg TX_FLG = 1'b0;
  always @(posedge CLK) begin
    if((TX_FLG == 1'b0 && START == 1'b1)) begin
      TX_FLG <= 1'b1;
      BUSY <= 1'b1;
      DATAFLL[0] <= 1'b0;
      DATAFLL[9] <= 1'b1;
      DATAFLL[8:1] <= DATA;
    end
    if((TX_FLG == 1'b1)) begin
      if((PRSCL < 5207)) begin
        PRSCL <= PRSCL + 1;
      end
      else begin
        PRSCL <= 0;
      end
      if((PRSCL == 2607)) begin
        TX_LINE <= DATAFLL[INDEX];
        if((INDEX < 9)) begin
          INDEX <= INDEX + 1;
        end
        else begin
          TX_FLG <= 1'b0;
          BUSY <= 1'b0;
          INDEX <= 0;
        end
      end
    end
  end
endmodule

