module STD_04000_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Start,
input wire i_Stop
);
// Clock input
// Reset input
// Start counter signal
// Stop counter signal
//CODE
parameter c_Length = 1'b1;  // How long we should count
parameter [1:0]
  init = 0,
  loading = 1,
  enabled = 2,
  finished = 3;
  // Enumerated type for state encoding
reg [1:0] sm_State;  // State signal
reg Raz;  // Load the length value and initialize the counter
reg Enable;  // Counter enable signal
reg [3:0] Count_Length;  // Counter length for counting
wire End_Count;  // End signal of counter
  // A simple counter with loading length and enable signal
  Counter Counter(
      .i_Clock(i_Clock),
    .i_Reset_n(i_Reset_n),
    .i_Raz(Raz),
    .i_Enable(Enable),
    .i_Length(Count_Length),
    .o_Done(End_Count));
  // FSM process controlling the counter. Start or stop it in function of the input (i_Start & i_Stop),
  // load the length value, and wait for it to finish
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      sm_State <= init;
      Raz <= 1'b0;
      Enable <= 1'b0;
      Count_Length <= {4{1'b0}};
    end else begin
      case(sm_State)
      init : begin
        // Set the length value
        Count_Length <= c_Length;
        sm_State <= loading;
      end
      loading : begin
        // Load the counter and initialize it
        Raz <= 1'b1;
        sm_State <= enabled;
      end
      enabled : begin
        // Start or stop counting depending on inputs until it finishes
        Raz <= 1'b0;
        if((End_Count == 1'b0)) begin
          // The counter has not finished, wait
          Enable <= i_Start ^  ~i_Stop;
          sm_State <= Enabled;
        end
        else begin
          // The counter has finished, nothing else to do
          Enable <= 1'b0;
          sm_State <= finished;
        end
      end
      default : begin
        sm_State <= init;
      end
      endcase
    end
  end
//CODE
endmodule

module BranchSelector(
input wire [4:0] Op,
input wire [15:0] RegInput,
input wire T,
output reg [1:0] Branch
);
  always @(Op, RegInput, T) begin
    Branch <= 2'b00;
    case(Op)
    5'b11000 : begin
      // B
      Branch <= 2'b01;
    end
    5'b11001 : begin
      // BTEQZ
      if(T == 1'b0) begin
        Branch <= 2'b01;
      end
    end
    5'b11010 : begin
      // BEQZ
      if(RegInput == Int16_zero) begin
        Branch <= 2'b01;
      end
    end
    5'b11011 : begin
      //BNEZ
      if(RegInput != Int16_zero) begin
        Branch <= 2'b01;
      end
    end
    5'b11101 : begin
      //JR
      Branch <= 2'b10;
    end
    5'b11100 : begin
      //JRRA*
      Branch <= 2'b10;
    end
    default : begin
    end
    endcase
  end
endmodule

