module envelope(
input wire clk,
input wire reset,
input wire note_on,
input wire [3:0] attack_rate,
input wire [3:0] release_rate,
output reg [5:0] gain,
output reg [1:0] phase
);
parameter [1:0]
  wait_phase = 0,
  attack_phase = 1,
  sustain_phase = 2,
  release_phase = 3;
reg [1:0] current_phase = wait_phase;
reg [25:0] current_gain;  // current_gain(25) is carry
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      current_phase <= wait_phase;
      current_gain <= 0;
    end else begin
      gain <= current_gain[24:19];
      case(current_phase)
      wait_phase : begin
        phase <= 2'b00;
        if((note_on == 1'b1)) begin
          current_phase <= attack_phase;
        end
      end
      attack_phase : begin
        phase <= 2'b01;
        if((note_on == 1'b1)) begin
          if((current_gain[25] == 1'b1)) begin
            current_gain <= 33554431;
            current_phase <= sustain_phase;
          end
          else begin
            current_gain <= current_gain + attack_rate;
          end
        end
        else begin
          current_phase <= release_phase;
        end
      end
      sustain_phase : begin
        phase <= 2'b10;
        if((note_on == 1'b0)) begin
          current_phase <= release_phase;
        end
      end
      release_phase : begin
        phase <= 2'b11;
        // release
        if((note_on == 1'b1)) begin
          // We have a note on during release phase
          // Start a new attack phase
          current_gain <= 0;
          current_phase <= attack_phase;
        end
        else begin
          if((current_gain[25] == 1'b1)) begin
            current_gain <= 0;
            current_phase <= wait_phase;
          end
          else begin
            current_gain <= current_gain - release_rate;
          end
        end
      end
      endcase
    end
  end
endmodule

