module alu(
input wire [7:0] A,
input wire [7:0] B,
input wire C_IN,
input wire [3:0] Sel,
output wire [7:0] SUM,
output wire C_FLAG,
output wire Z_FLAG
);
reg [8:0] temp_s;
  always @(A, B, C_IN, SEL) begin
    case(SEL)
    4'b0000 : begin
      temp_s <= ({1'b0,A}) + B;
      // add
    end
    4'b0001 : begin
      temp_s <= ({1'b0,A}) + B + C_IN;
      // addc
    end
    4'b0010 : begin
      temp_s <= ({1'b0,A}) - B;
      // sub
    end
    4'b0011 : begin
      temp_s <= ({1'b0,A}) - B - C_IN;
      // subc
    end
    4'b0100 : begin
      temp_s <= ({1'b0,A}) - B;
      // cmp
    end
    4'b0101 : begin
      temp_s <= ({1'b0,A}) & ({1'b0,B});
      // and
    end
    4'b0110 : begin
      temp_s <= ({1'b0,A}) | ({1'b0,B});
      // or
    end
    4'b0111 : begin
      temp_s <= ({1'b0,A}) ^ ({1'b0,B});
      // exor
    end
    4'b1000 : begin
      temp_s <= ({1'b0,A}) & ({1'b0,B});
      // test
    end
    4'b1001 : begin
      temp_s <= {A,C_IN};
      // lsl
    end
    4'b1010 : begin
      temp_s <= {A[0],C_IN,A[7:1]};
      // lsr
    end
    4'b1011 : begin
      temp_s <= {A[7:0],A[7]};
      // rol
    end
    4'b1100 : begin
      temp_s <= {A[0],A[0],A[7:1]};
      // ror
    end
    4'b1101 : begin
      temp_s <= {A[0],A[7],A[7:1]};
      // asr
    end
    4'b1110 : begin
      temp_s <= {1'b0,B};
      // mov
    end
    4'b1111 : begin
      temp_s <= 9'b000000000;
      // unused
    end
    default : begin
      temp_s <= 9'b000000000;
    end
    endcase
  end
  // account for overflow during subtraction
  assign SUM = ((SEL == 4'b0010 || SEL == 4'b0011) && temp_s[8] == 1'b1) ?  ~(temp_s[7:0]) + 1 : temp_s[7:0];
  assign Z_FLAG = (temp_s == 9'b000000000 || temp_s == 9'b100000000) ? 1'b1 : 1'b0;
  assign C_FLAG = temp_s[8];
endmodule

