);
parameter [31:0] bits_per_ch=24;
// signal clkb:  std_logic;
//signal dclkb:  std_logic := '0';
wire mclkb = 1'b0;
wire bclkb = 1'b0;
wire lrclkb = 1'b0;
wire adc_sdatab = 1'b0;
reg dac_sdatab = 1'b0;
