  //clk  <= clkb;
  assign mclk = mclkb;
  assign bclk = bclkb;
  assign lrclk = lrclkb;
  assign adc_sdatab = adc_sdata;
  assign dac_sdata = dac_sdatab;
  //dclk_div: clk_div generic map(	div=>3 ) port map( input=> clk, output=> dclkb);
  clk_div #(
      .div(8 * 2))
  mclk_div(
      .input(clk),
    .output(mclkb),
    .state(/* open */));
  clk_div #(
      .div(8 * 2))
  bclk_div(
      .input(mclkb),
    .output(bclkb),
    .state(/* open */));
  clk_div #(
      .div(32 * 2))
  lrclk_div(
      .input(bclkb),
    .output(lrclkb),
    .state(index));
  always @(negedge bclkb) begin
    if((index == 31)) begin
      data[31:31 - bits_per_ch + 1] <= input;
      data[31 - bits_per_ch:0] <= {((31 - bits_per_ch)-(0)+1){1'b0}};
    end
    else begin
      dac_sdatab <= data[31];
      data <= {data[30:0],1'b0};
      //shift 
    end
  end
endmodule

