module pulse_stretch(
input wire clock,
input wire reset,
input wire pulse_in,
output reg pulse_out
);
parameter [31:0] g_duration=200;
reg [31:0] count;
  always @(posedge clock) begin
    if(reset == 1'b1) begin
      pulse_out <= 1'b0;
      count <= 0;
    end
    else if(pulse_in == 1'b1) begin
      pulse_out <= 1'b1;
      count <= g_duration - 1;
    end
    else if(count == 0) begin
      pulse_out <= 1'b0;
    end
    else begin
      count <= count - 1;
    end
  end
endmodule

