module spi_send_recv(
input wire Clk,
input wire Rst,
output reg cs_o,
output reg sck_o,
output reg mosi_o,
input wire miso_i,
input wire send_req_i,
input wire [SPI_SIZE - 1:0] data_i,
output reg [SPI_SIZE - 1:0] data_o,
input wire tick_i
);
parameter CPOL=1'b0;
parameter CPHA=1'b0;
parameter [31:0] SPI_SIZE=8;
// AXI
// SPI 
//-CPU To Slave
//- Slave To CPU
// BAUD RATE
parameter [1:0]
  spi_idle = 0,
  write = 1,
  read = 2,
  cs_high = 3;
reg [1:0] state_reg; reg [1:0] state_next;
reg [4:0] n_reg; reg [4:0] n_next;
reg cs_reg; reg cs_next;
reg sck_reg; reg sck_next;
reg mosi_reg; reg mosi_next;
reg [SPI_SIZE - 1:0] r_data_reg; reg [SPI_SIZE - 1:0] r_data_next;
reg [SPI_SIZE - 1:0] t_data_reg; reg [SPI_SIZE - 1:0] t_data_next;
wire led_reg; wire led_next;
  // change state
  always @(posedge Clk, posedge Rst) begin
    if(Rst == 1'b1) begin
      state_reg <= spi_idle;
      n_reg <= {5{1'b0}};
      r_data_reg <= {((SPI_SIZE - 1)-(0)+1){1'b0}};
      t_data_reg <= {((SPI_SIZE - 1)-(0)+1){1'b0}};
      cs_reg <= 1'b1;
      sck_reg <= CPOL;
      mosi_reg <= 1'b0;
    end else begin
      state_reg <= state_next;
      sck_reg <= sck_next;
      mosi_reg <= mosi_next;
      r_data_reg <= r_data_next;
      t_data_reg <= t_data_next;
      n_reg <= n_next;
      cs_reg <= cs_next;
    end
  end
  // next state logic & data path functional units/routing
  always @(state_reg, n_reg, tick_i, sck_reg, mosi_reg, data_i, send_req_i, miso_i, cs_reg, r_data_reg, t_data_reg) begin
    cs_next <= cs_reg;
    cs_next <= cs_reg;
    state_next <= state_reg;
    sck_next <= sck_reg;
    mosi_next <= mosi_reg;
    r_data_next <= r_data_reg;
    t_data_next <= t_data_reg;
    n_next <= n_reg;
    case(state_reg)
    spi_idle : begin
      if(send_req_i == 1'b1) begin
        cs_next <= 1'b0;
        state_next <= write;
        r_data_next <= {((SPI_SIZE - 1)-(0)+1){1'b0}};
        t_data_next <= data_i;
        n_next <= {5{1'b0}};
      end
      else begin
        cs_next <= 1'b1;
        sck_next <= CPOL;
      end
    end
    write : begin
      if((tick_i == 1'b1)) begin
        mosi_next <= t_data_reg[SPI_SIZE - 1];
        t_data_next <= {t_data_reg[SPI_SIZE - 2:0],1'b0};
        state_next <= read;
        if(CPHA == 1'b0) begin
          sck_next <= CPOL;
        end
        else begin
          sck_next <=  ~(sck_reg);
        end
      end
    end
    read : begin
      if((tick_i == 1'b1)) begin
        sck_next <=  ~(sck_reg);
        r_data_next <= {r_data_reg[SPI_SIZE - 2:0],miso_i};
        if((n_reg == (SPI_SIZE - 1))) begin
          n_next <= {5{1'b0}};
          state_next <= cs_high;
        end
        else begin
          state_next <= write;
          n_next <= n_reg + 1;
        end
      end
    end
    cs_high : begin
      if((tick_i == 1'b1)) begin
        cs_next <= 1'b1;
        state_next <= spi_idle;
      end
    end
    endcase
    mosi_o <= mosi_reg;
