module Program_Counter(
input wire clk,
input wire reset,
input wire enb,
input wire [1:0] func,
input wire [7:0] addr_in,
output wire [7:0] addr_out
);
// ufix2
// uint8
// uint8
// Signals
wire [1:0] func_unsigned;  // ufix2
wire [7:0] addr_in_unsigned;  // uint8
reg [7:0] addr_out_tmp;  // uint8
reg [7:0] PC_value;  // ufix8
reg [7:0] PC_value_next;  // ufix8
  assign func_unsigned = func;
  assign addr_in_unsigned = addr_in;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      PC_value <= 0;
    end else begin
      if(enb == 1'b1) begin
        PC_value <= PC_value_next;
      end
    end
  end
  always @(func_unsigned, addr_in_unsigned, PC_value) begin
    PC_value_next <= PC_value;
    //MATLAB Function 'CPU_Subsystem_8_bit/Program Counter': '<S10>:1'
    // Program Counter
    // func = 0 => reset PC
    // func = 1 => load PC
    // func = 2 => increment PC
    // HDL specific fimath
    //'<S10>:1:20'
    addr_out_tmp <= PC_value;
    case(func_unsigned)
    2'b00 : begin
      // reset
      //'<S10>:1:25'
      PC_value_next <= 0;
    end
    2'b01 : begin
      // store into PC
      //'<S10>:1:28'
      PC_value_next <= addr_in_unsigned;
    end
    2'b10 : begin
      // increment PC
      //'<S10>:1:31'
      PC_value_next <= PC_value + 1;
    end
    default : begin
    end
    endcase
  end
  assign addr_out = addr_out_tmp;
endmodule

module PSRModifier(
input wire [5:0] ALUOP,
input wire [31:0] Oper2,
input wire [31:0] Oper1,
input wire [31:0] ALURESULT,
output reg [3:0] NZVC
);
  always @(ALUOP, Oper2, Oper1, ALURESULT) begin
    if((ALUOP == 6'b010100 || ALUOP == 6'b001011 || ALUOP == 6'b001100 || ALUOP == 6'b001101 || ALUOP == 6'b001110 || ALUOP == 6'b001111 || ALUOP == 6'b010000 || ALUOP == 6'b010001 || ALUOP == 6'b010011 || ALUOP == 6'b010110 || ALUOP == 6'b010100)) begin
      //ANDcc,ANDNcc,ORcc,ORNcc,XORcc,XNORcc,ADDcc,ADDXcc,SUBcc,SUBXcc
      if((ALURESULT == 32'b00000000000000000000000000000000)) begin
        NZVC[2] <= 1'b1;
      end
      else begin
        NZVC[2] <= 1'b0;
      end
      NZVC[3] <= ALURESULT[31];
      if((ALUOP == 6'b001011 || ALUOP == 6'b001100 || ALUOP == 6'b001101 || ALUOP == 6'b001110 || ALUOP == 6'b001111 || ALUOP == 6'b010000)) begin
        //ANDcc,ANDNcc,ORcc,ORNcc,XORcc,XNORcc
        NZVC[1:0] <= 2'b00;
      end
      else if((ALUOP == 6'b010001 || ALUOP == 6'b010011)) begin
        //ADDcc, ADDXcc
        NZVC[1] <= (Oper1[31] & Oper2[31] & ( ~ALURESULT[31])) | (( ~Oper1[31]) & ( ~Oper2[31]) & ALURESULT[31]);
        NZVC[0] <= (Oper1[31] & Oper2[31]) | (( ~ALURESULT[31]) & (Oper1[31] | Oper2[31]));
      end
      else begin
        //(ALUOP="010100" or ALUOP="010110") SUBcc, SUBXcc
        NZVC[1] <= (Oper1[31] & ( ~Oper2[31]) & ( ~ALURESULT[31])) | (( ~Oper1[31]) & Oper2[31] & ALURESULT[31]);
        NZVC[0] <= (( ~Oper1[31]) & Oper2[31]) | (ALURESULT[31] & (( ~Oper1[31]) | Oper2[31]));
      end
      //else
      //	NZVC<="1111";
    end
  end
endmodule

module led_controller(
input wire clk,
input wire reset,
input wire [reg_width - 1:0] rf_data,
output wire [rf_addr_w - 1:0] rf_addr,
output wire [3:0] led
);
parameter [31:0] rf_addr_w=5;
parameter [31:0] reg_width=32;
parameter [1:0]
  read1 = 0,
  read2 = 1,
  read3 = 2,
  idle = 3;
reg [1:0] state; reg [1:0] state_next;
reg [31:0] delay; reg [31:0] delay_next;
reg [rf_addr_w - 1:0] addr; reg [rf_addr_w - 1:0] addr_next;
reg [reg_width - 1:0] sum; reg [reg_width - 1:0] sum_next;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      state <= idle;
      delay <= 0;
      addr <= {((rf_addr_w - 1)-(0)+1){1'b0}};
      sum <= {((reg_width - 1)-(0)+1){1'b0}};
    end
    else begin
      state <= state_next;
      delay <= delay_next;
      addr <= addr_next;
      sum <= sum_next;
    end
  end
  //reg 5 & 17 or 0
  always @(state, delay, rf_data, addr, sum) begin
    state_next <= state;
    delay_next <= delay;
    addr_next <= addr;
    sum_next <= sum;
    case(state)
    read1 : begin
      sum_next <= rf_data;
      addr_next <= 5'b10001;
      state_next <= read2;
    end
    read2 : begin
      sum_next <= sum & rf_data;
      addr_next <= 5'b00000;
      state_next <= read3;
    end
    read3 : begin
      sum_next <= sum | rf_data;
      state_next <= idle;
    end
    idle : begin
      if(delay == 100) begin
        delay_next <= 0;
        state_next <= read1;
        addr_next <= 5'b00101;
      end
      else begin
        delay_next <= delay + 1;
      end
    end
    endcase
  end
  assign led = sum[3:0];
  assign rf_addr = addr;
endmodule

