module SerialPollCoordinator(
input wire clk,
input wire reset,
input wire DAC,
input wire rec_stb,
input wire ATN_in,
output wire ATN_out,
input wire output_valid_in,
output wire output_valid_out,
output wire stb_received
);
// clock
// reset
// data accepted
// receive status byte
// attention in
// attention out
// output valid in
// output valid out
// stb received
// serial poll coordinator states
parameter [1:0]
  ST_IDLE = 0,
  ST_WAIT_DAC = 1,
  ST_WAIT_REC_STB_0 = 2;
reg [1:0] current_state;
  assign ATN_out = current_state == ST_WAIT_DAC ? 1'b0 : ATN_in;
  assign output_valid_out = current_state == ST_WAIT_DAC ? 1'b0 : output_valid_in;
  assign stb_received = current_state == ST_WAIT_REC_STB_0 ? 1'b1 : 1'b0;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      current_state <= ST_IDLE;
    end else begin
      case(current_state)
      ST_IDLE : begin
        if(rec_stb == 1'b1) begin
          current_state <= ST_WAIT_DAC;
        end
      end
      ST_WAIT_DAC : begin
        if(DAC == 1'b1) begin
          current_state <= ST_WAIT_REC_STB_0;
        end
        else if(rec_stb == 1'b0) begin
          current_state <= ST_IDLE;
        end
      end
      ST_WAIT_REC_STB_0 : begin
        if(rec_stb == 1'b0) begin
          current_state <= ST_IDLE;
        end
      end
      default : begin
        current_state <= ST_IDLE;
      end
      endcase
    end
  end
endmodule

