module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
// The default values are for 640x480
parameter [31:0] H_SIZE=640;
parameter [31:0] H_FRONT_DELAY=16;
parameter [31:0] H_BACK_DELAY=48;
parameter [31:0] H_RETRACE_DELAY=96;
parameter [31:0] V_SIZE=480;
parameter [31:0] V_FRONT_DELAY=10;
parameter [31:0] V_BACK_DELAY=33;
parameter [31:0] V_RETRACE_DELAY=2;
// sync counters
reg [9:0] v_count_reg;
reg [9:0] h_count_reg;
  // registers
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b0) begin
      v_count_reg <= {10{1'b0}};
      h_count_reg <= {10{1'b0}};
      vsync <= 1'b1;
      hsync <= 1'b1;
      active <= 1'b0;
    end else begin
      // Count the lines and rows      
      if(h_count_reg == (H_SIZE + H_FRONT_DELAY + H_BACK_DELAY + H_RETRACE_DELAY - 1)) begin
        h_count_reg <= {10{1'b0}};
        if(v_count_reg == (V_SIZE + V_FRONT_DELAY + V_BACK_DELAY + V_RETRACE_DELAY - 1)) begin
          v_count_reg <= {10{1'b0}};
        end
        else begin
          v_count_reg <= v_count_reg + 1;
        end
      end
      else begin
        h_count_reg <= h_count_reg + 1;
      end
      if(v_count_reg < V_SIZE && h_count_reg < H_SIZE) begin
        active <= 1'b1;
      end
      else begin
        active <= 1'b0;
      end
      if(h_count_reg > (H_SIZE + H_FRONT_DELAY) && h_count_reg <= (H_SIZE + H_FRONT_DELAY + H_RETRACE_DELAY)) begin
        hsync <= 1'b0;
      end
      else begin
        hsync <= 1'b1;
      end
      if(v_count_reg >= (V_SIZE + V_FRONT_DELAY) && v_count_reg < (V_SIZE + V_FRONT_DELAY + V_RETRACE_DELAY)) begin
        vsync <= 1'b0;
      end
      else begin
        vsync <= 1'b1;
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

