module serializer_generic(
input wire [C_channel_bits * C_channels - 1:0] tx_in,
input wire tx_inclock,
input wire tx_syncclock,
output wire [(C_channels + 1) * C_output_bits - 1:0] tx_out
);
parameter [31:0] C_channel_bits=10;
parameter [31:0] C_output_bits=1;
parameter [31:0] C_channels=3;
// number of channels to serialize
// 10x tx_syncclock
// one more channel for clock
reg [C_channel_bits * C_channels - 1:0] R_tx_latch;
wire [C_channel_bits - 1:0] S_tx_clock;
  // -- one channel more for clock
wire [C_channel_bits - 1:0] S_channel_latch[0:C_channels]; reg [C_channel_bits - 1:0] R_channel_shift[0:C_channels];
reg R_pixel_clock_toggle; reg R_prev_pixel_clock_toggle;
reg R_clock_edge;
parameter C_shift_pad = 1'b0;
  always @(posedge tx_syncclock) begin : P3
  // pixel clock
    R_tx_latch <= tx_in;
    // add the clock to be shifted to the channels
  end
  // rename - separate to shifted 4 channels
  genvar i;
  generate for (i=0; i <= C_channels - 1; i = i + 1) begin: separate_channels
      genvar j;
    generate for (j=0; j <= C_channel_bits - 1; j = j + 1) begin: reverse_bits
          assign S_channel_latch[i][j] = R_tx_latch[C_channel_bits * (i + 1) - j - 1];
    end
    endgenerate
  end
  endgenerate
  assign S_channel_latch[3] = 10'b1111100000;
  // the clock pattern
  always @(posedge tx_syncclock) begin
    R_pixel_clock_toggle <=  ~R_pixel_clock_toggle;
  end
  // shift-synchronous pixel clock edge detection
  always @(posedge tx_inclock) begin : P2
  // pixel shift clock (250 MHz)
    // pixel clock (25 MHz)
    R_prev_pixel_clock_toggle <= R_pixel_clock_toggle;
    R_clock_edge <= R_pixel_clock_toggle ^ R_prev_pixel_clock_toggle;
  end
  // fixme: initial state issue (clock shifting?)
  always @(posedge tx_inclock) begin : P1
  // pixel shift clock
    if(R_clock_edge == 1'b1) begin
      // rising edge detection
      R_channel_shift[0] <= S_channel_latch[0];
      R_channel_shift[1] <= S_channel_latch[1];
      R_channel_shift[2] <= S_channel_latch[2];
      R_channel_shift[3] <= S_channel_latch[3];
    end
    else begin
      R_channel_shift[0] <= {C_shift_pad,R_channel_shift[0][C_channel_bits - 1:C_output_bits]};
      R_channel_shift[1] <= {C_shift_pad,R_channel_shift[1][C_channel_bits - 1:C_output_bits]};
      R_channel_shift[2] <= {C_shift_pad,R_channel_shift[2][C_channel_bits - 1:C_output_bits]};
      R_channel_shift[3] <= {C_shift_pad,R_channel_shift[3][C_channel_bits - 1:C_output_bits]};
    end
  end
  assign tx_out = {R_channel_shift[3][C_output_bits - 1:0],R_channel_shift[2][C_output_bits - 1:0],R_channel_shift[1][C_output_bits - 1:0],R_channel_shift[0][C_output_bits - 1:0]};
endmodule

module alu(
input wire [data_width - 1:0] A,
input wire [data_width - 1:0] B,
input wire C_IN,
input wire [sel_width - 1:0] Sel,
output wire [data_width - 1:0] SUM,
output wire C_FLAG,
output wire Z_FLAG
);
parameter [31:0] data_width=8;
parameter [31:0] sel_width=4;
reg [8:0] temp_s;
  always @(A, B, C_IN, SEL) begin
    case(SEL)
    4'b0000 : begin
      temp_s <= ({1'b0,A}) + B;
      // add
    end
    4'b0001 : begin
      temp_s <= ({1'b0,A}) + B + C_IN;
      // addc
    end
    4'b0010 : begin
      temp_s <= ({1'b0,A}) - B;
      // sub
    end
    4'b0011 : begin
      temp_s <= ({1'b0,A}) - B - C_IN;
      // subc
    end
    4'b0100 : begin
      temp_s <= ({1'b0,A}) - B;
      // cmp
    end
    4'b0101 : begin
      temp_s <= ({1'b0,A}) & ({1'b0,B});
      // and
    end
    4'b0110 : begin
      temp_s <= ({1'b0,A}) | ({1'b0,B});
      // or
    end
    4'b0111 : begin
      temp_s <= ({1'b0,A}) ^ ({1'b0,B});
      // exor
    end
    4'b1000 : begin
      temp_s <= ({1'b0,A}) & ({1'b0,B});
      // test
    end
    4'b1001 : begin
      temp_s <= {A,C_IN};
      // lsl
    end
    4'b1010 : begin
      temp_s <= {A[0],C_IN,A[7:1]};
      // lsr
    end
    4'b1011 : begin
      temp_s <= {A[7:0],A[7]};
      // rol
    end
    4'b1100 : begin
      temp_s <= {A[0],A[0],A[7:1]};
      // ror
    end
    4'b1101 : begin
      temp_s <= {A[0],A[7],A[7:1]};
      // asr
    end
    4'b1110 : begin
      temp_s <= {1'b0,B};
      // mov
    end
    4'b1111 : begin
      temp_s <= 9'b000000000;
      // unused
    end
    default : begin
      temp_s <= 9'b000000000;
    end
    endcase
  end
  // account for overflow during subtraction
  assign SUM = ((SEL == 4'b0010 || SEL == 4'b0011) && temp_s[data_width] == 1'b1) ?  ~(temp_s[data_width - 1:0]) + 1 : temp_s[data_width - 1:0];
  assign Z_FLAG = (temp_s == 9'b000000000 || temp_s == 9'b100000000) ? 1'b1 : 1'b0;
  assign C_FLAG = temp_s[8];
endmodule

module pulse_synchronizer(
input wire clk_in_i,
input wire clk_out_i,
input wire pulse_i,
output wire done_o,
output wire pulse_o
);
//! Input pulse clock domain
//! Output pulse clock domain
//! One clk_in_i tick input pulse
//! Input pulse is synchronized (1 clk_in_i tick)
//! One clk_out_i tick output pulse
//=============================================================================
//! Architecture declaration Pulse synchronizer
//=============================================================================
reg s_input_toggle = 1'b0;
reg [6:0] s_input_sync;
reg s_gotit_toggle = 1'b0;
reg [2:0] s_gotit_sync;
wire s_output_pulse;  //=============================================================================
//! Architecture begin
//=============================================================================
  //*****************************************************************************
  // Begin of p_input_pulse_to_toggle
  //! Process: Toggles FF output on every input pulse
  //*****************************************************************************
  always @(posedge clk_in_i) begin
    if(pulse_i == 1'b1) begin
      s_input_toggle <=  ~(s_input_toggle);
    end
  end
  //*****************************************************************************
  // Begin of p_input_sync
  //! Process: Synchronizes input toggle to output clock domain
  //*****************************************************************************
  always @(posedge clk_out_i) begin
    s_input_sync[0] <= s_input_toggle;
    s_input_sync[1] <= s_input_sync[0];
    s_input_sync[2] <= s_input_sync[1];
    s_input_sync[3] <= s_input_sync[2];
    s_input_sync[4] <= s_input_sync[3];
    s_input_sync[5] <= s_input_sync[4];
    s_input_sync[6] <= s_input_sync[5];
  end
  // generates 1 tick pulse when s_input_toggle changes
  assign s_output_pulse = s_input_sync[1] ^ s_input_sync[6];
  // assign pulse output port
  assign pulse_o = s_output_pulse;
  //*****************************************************************************
  // Begin of p_output_pulse_to_toggle
  //! Process: Toggles FF output on every output pulse
  //*****************************************************************************
  always @(posedge clk_out_i) begin
    if(s_output_pulse == 1'b1) begin
      s_gotit_toggle <=  ~(s_gotit_toggle);
    end
  end
  //*****************************************************************************
  // Begin of p_gotit_sync
  //! Process: Synchronizes gotit toggle to input clock domain
  //*****************************************************************************
  always @(posedge clk_in_i) begin
    s_gotit_sync[0] <= s_gotit_toggle;
    s_gotit_sync[1] <= s_gotit_sync[0];
    s_gotit_sync[2] <= s_gotit_sync[1];
  end
  // generates 1 tick pulse when s_gotit_toggle changes
  assign done_o = s_gotit_sync[1] ^ s_gotit_sync[2];
//=============================================================================
//! Architecture end
//=============================================================================
endmodule

module shift_register_serial_in(
input wire clk,
input wire reset,
input wire shift,
input wire data_in_serial,
output wire [REG_WIDTH - 1:0] data_out_parallel,
output wire data_out_serial
);
parameter [31:0] REG_WIDTH=8;
reg [REG_WIDTH - 1:0] shift_register_mem_out;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      shift_register_mem_out <= {((REG_WIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if(shift == 1'b1) begin
        shift_register_mem_out <= {shift_register_mem_out[REG_WIDTH - 2:0],data_in_serial};
      end
    end
  end
  assign data_out_parallel = shift_register_mem_out;
  assign data_out_serial = shift_register_mem_out[REG_WIDTH - 2];
endmodule

module EPROC_OUT2_direct(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
output wire getDataTrig,
input wire [9:0] edataIN,
input wire edataINrdy,
output wire [1:0] EdataOUT
);
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
parameter zeros2bit = 1'b0;
reg [7:0] byte_r;
reg [1:0] request_cycle_cnt = 1'b0; reg [1:0] send_count = 1'b0;
reg send_out_trig = 1'b0;
wire inp_request_trig; wire inp_request_trig_out;
  //-----------------------------------------------------------------------------------------
  // input handshaking, request cycle 4 CLKs
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(rst == 1'b1) begin
      request_cycle_cnt <= {2{1'b0}};
    end
    else begin
      if(inp_request_trig == 1'b1) begin
        request_cycle_cnt <= {2{1'b0}};
      end
      else begin
        request_cycle_cnt <= request_cycle_cnt + 1;
      end
    end
  end
  //
  assign inp_request_trig = (request_cycle_cnt == 2'b11) ? 1'b1 : 1'b0;
  //
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  inp_reques1clk(
      bitCLKx4,
    inp_request_trig,
    inp_request_trig_out);
  assign getDataTrig = inp_request_trig_out;
  //
  always @(posedge bitCLK) begin
    send_out_trig <= inp_request_trig;
  end
  //
  //-----------------------------------------------------------------------------------------
  // sending out 2 bits @ bitCLK
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      byte_r <= edataIN[7:0];
    end
  end
  //
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      send_count <= {2{1'b0}};
    end
    else begin
      send_count <= send_count + 1;
    end
  end
  //
  MUX4_Nbit #(
      .N(2))
  outmux(
      .data0(byte_r[1:0]),
    .data1(byte_r[3:2]),
    .data2(byte_r[5:4]),
    .data3(byte_r[7:6]),
    .sel(send_count),
    .data_out(EdataOUT));
    //
endmodule

module SpiXmitSR(
input wire clk,
input wire resetN,
input wire tsrEnable,
input wire tsrLoad,
input wire [srWidth - 1:0] tsrData,
output wire dataOut
);
parameter [31:0] srWidth=8;
reg [srWidth - 1:0] tsrDummyReg; wire [srWidth - 1:0] nextTsrDummyReg; reg [srWidth - 1:0] tsrDataReg; wire [srWidth - 1:0] nextTsrDataReg;
reg load1; reg load2; reg load;
  always @(posedge clk, posedge resetN) begin
    if(resetN == 1'b0) begin
      tsrDataReg <= {((srWidth - 1)-(0)+1){1'b1}};
      tsrDummyReg <= {((srWidth - 1)-(0)+1){1'b1}};
      load2 <= 1'b0;
      load1 <= 1'b0;
      load <= 1'b0;
    end else begin
      tsrDataReg <= nextTsrDataReg;
      // shifts SR 
      tsrDummyReg <= nextTsrDummyReg;
      if((load2 == 1'b0 && load1 == 1'b1)) begin
        load <= 1'b1;
      end
      else begin
        load <= 1'b0;
      end
      load2 <= load1;
      load1 <= tsrLoad;
    end
  end
  // Next State Logic
  assign nextTsrDataReg = tsrEnable == 1'b1 ? {tsrDataReg[srWidth - 2:0],tsrDummyReg[0]} : load == 1'b1 ? tsrData : tsrDataReg;
  assign nextTsrDummyReg = load == 1'b1 ? tsrData : tsrDummyReg;
  // Output Logic
  assign dataOut = tsrDataReg[7];
endmodule

