module simon(
input wire clk,
input wire rst,
input wire enc,
input wire [127:0] key,
input wire [63:0] block_in,
output wire [63:0] block_out
);
// state indicator (1 = init, 0 = run)
// (0 = enc, 1 = dec)
reg [7:0] r_s;  // round index
reg [31:0] key_s[0:3];  // intermediate key (in words)
wire [31:0] subkey_out_s;  // round key
reg [63:0] v_in_s;  // intermediate 'plaintext'
wire [63:0] v_out_s;  // intermediate 'ciphertext'
reg ram_rw;
wire [31:0] ram_data_out;
  key_schedule KEY_SCHEDULE_0(
      r_s,
    key_s[0],
    key_s[1],
    key_s[3],
    subkey_out_s);
  round_f ROUND_F_0(
      v_in_s,
    key_s[0],
    v_out_s);
  ram RAM_0(
      key_s[0],
    ram_rw,
    clk,
    r_s,
    ram_data_out);
  // SIMON round index regulation
  always @(posedge clk, posedge rst) begin
    // initialization clock
    if(rst == 1'b1) begin
      if(enc == 1'b0) begin
        if(r_s == 8'h00) begin
          r_s <= 8'h01;
        end
        else begin
          r_s <= {8{1'b0}};
        end
      end
      else begin
        r_s <= (r_s) - 1;
      end
      // running clock
    end
    else begin
      if(enc == 1'b0) begin
        if(r_s != 8'h2B) begin
          r_s <= (r_s) + 1;
        end
        else begin
          // in preparation for subsequent decryption
          r_s <= (r_s) - 1;
        end
      end
      else begin
        if(r_s != 8'h00) begin
          r_s <= (r_s) - 1;
        end
      end
    end
  end
  // SIMON key cache rotation
  always @(posedge clk, posedge rst, posedge key_s, posedge key, posedge ram_data_out, posedge subkey_out_s) begin
    if(enc == 1'b0) begin
      if(rst == 1'b1) begin
        key_s[0] <= key[31:0];
        key_s[1] <= key[63:32];
        key_s[2] <= key[95:64];
        key_s[3] <= key[127:96];
      end
      else begin
        // final iteration is just to write final round key to ram
        if((r_s != 8'h2B)) begin
          key_s[0] <= key_s[1];
          key_s[1] <= key_s[2];
          key_s[2] <= key_s[3];
          key_s[3] <= subkey_out_s;
        end
      end
    end
    else begin
      key_s[0] <= ram_data_out;
    end
  end
  // SIMON Core
  always @(posedge clk, posedge rst, posedge enc, posedge r_s, posedge block_in, posedge v_in_s, posedge v_out_s, posedge ram_rw) begin
    // initalize
    if(rst == 1'b1) begin
      if(enc == 1'b0) begin
        v_in_s <= block_in;
        // write every round key to RAM during encryption
        // so that encryption also functions as pre-expansion for decryption
        ram_rw <= 1'b1;
      end
      else begin
        // swap blocks for decryption
        v_in_s <= {block_in[31:0],block_in[63:32]};
        ram_rw <= 1'b0;
      end
      // run
    end
    else begin
      if(enc == 1'b0) begin
        // final iteration is just to write final round key to ram
        if((r_s != 8'h2B)) begin
          v_in_s <= v_out_s;
        end
        else begin
          ram_rw <= 1'b0;
        end
      end
      else begin
        v_in_s <= v_out_s;
      end
    end
  end
  assign block_out = (enc == 1'b0) ? v_out_s : {v_out_s[31:0],v_out_s[63:32]};
endmodule

module i2s_interface(
input wire clk,
input wire reset,
input wire bclk,
input wire lrclk,
output wire [DATA_WIDTH - 1:0] sample_out,
input wire [DATA_WIDTH - 1:0] sample_in,
output reg dac_data,
input wire adc_data,
output reg valid,
output reg ready
);
parameter [31:0] DATA_WIDTH;
parameter [31:0] BITPERFRAME;
reg [DATA_WIDTH - 1:0] sr_in;
reg neg_edge; reg pos_edge;
reg lr_edge;
reg new_sample;
reg zbclk; reg zzbclk; reg zzzbclk;
reg zlrclk; reg zzlrclk; reg zzzlrclk;
reg [31:0] cnt = 0;  // signal bits_to_rx				: integer := DATA_WIDTH - 1;
reg [DATA_WIDTH - 1:0] sr_out;
  always @(posedge clk) begin
    zbclk <= bclk;
    zzbclk <= zbclk;
    zzzbclk <= zzbclk;
    if(zzbclk == 1'b1 && zzzbclk == 1'b0) begin
      pos_edge <= 1'b1;
    end
    else if(zzbclk == 1'b0 && zzzbclk == 1'b1) begin
      neg_edge <= 1'b1;
    end
    else begin
      pos_edge <= 1'b0;
      neg_edge <= 1'b0;
    end
  end
  always @(posedge clk) begin
    zlrclk <= lrclk;
    zzlrclk <= zlrclk;
    zzzlrclk <= zzlrclk;
    if(zzlrclk != zzzlrclk) begin
      lr_edge <= 1'b1;
    end
    else begin
      lr_edge <= 1'b0;
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      cnt <= 0;
      valid <= 1'b0;
    end
    else begin
      if(lr_edge == 1'b1) begin
        cnt <= 0;
      end
      if(pos_edge == 1'b1) begin
        if(cnt < (BITPERFRAME / 2 - 1)) begin
          cnt <= cnt + 1;
        end
      end
      if(neg_edge == 1'b1) begin
        if(cnt == 1) begin
          new_sample <= 1'b1;
        end
        else if(cnt >= (DATA_WIDTH + 1) && cnt < (BITPERFRAME / 2 - 1)) begin
          new_sample <= 1'b0;
        end
      end
      if(cnt == (DATA_WIDTH + 1) && neg_edge == 1'b1) begin
        valid <= 1'b1;
      end
      else begin
        valid <= 1'b0;
      end
    end
  end
  assign sample_out = sr_in;
  always @(posedge clk) begin
    if(pos_edge == 1'b1 && new_sample == 1'b1) begin
      // receive
      sr_in <= {sr_in[(DATA_WIDTH - 1) - 1:0],adc_data};
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      ready <= 1'b0;
    end
    else begin
      if(new_sample == 1'b0) begin
        // get data during delay period
        if(pos_edge == 1'b1) begin
          sr_out <= sample_in;
          ready <= 1'b1;
        end
      end
      else begin
        if(cnt == 0 || cnt > DATA_WIDTH) begin
          dac_data <= 1'bX;
        end
        else begin
          dac_data <= sr_out[DATA_WIDTH - cnt];
        end
        ready <= 1'b0;
      end
    end
  end
endmodule

module UART_LIMITER(
input wire CLOCK,
input wire RESET,
input wire WR_REQ,
output reg INHIBIT
);
reg [31:0] packet_time;
reg [31:0] byte_time;
reg [31:0] byte_count;
wire [31:0] last_count;
reg running;
wire inhibit_int;
reg inhibit_bt;
reg inhibit_bc;
parameter limit_ot = 4900;  // repeat rate of packets
parameter limit_bt = 2;  // all bytes within this time of eachother
parameter limit_bc = 33;  // limit of number of bytes
  // If the byte count or timing is exceeded, the
  // inhibit signal will precent further bytes from
  // being sent through the UART.
  assign inhibit_int = inhibit_bt | inhibit_bc;
  always @(posedge inhibit_int, posedge running) begin
    if(running == 1'b0) begin
      INHIBIT <= 1'b0;
    end else begin
      INHIBIT <= 1'b1;
    end
  end
  // Start tracking information on first write.
  always @(posedge RESET, posedge WR_REQ, posedge packet_time) begin
    if((RESET == 1'b1) || (packet_time > limit_ot)) begin
      running <= 1'b0;
    end else begin
      running <= 1'b1;
    end
  end
  // Time entire packet.
  // Once started, this timer will not reset until it reaches the
  // allowed re-send time.  The other parameters are tracked only
  // while this timer is running.
  always @(posedge CLOCK, posedge RESET, posedge running) begin
    if((RESET == 1'b1) || (running == 1'b0)) begin
      packet_time <= 0;
    end else begin
      packet_time <= packet_time + 1;
    end
  end
  // Time each byte.
  // Each byte must be received within a certain time in order for the
  // serial module to include them all in the same packet.
  always @(posedge RESET, posedge CLOCK, posedge running, posedge WR_REQ) begin
    if((RESET == 1'b1) || (running == 1'b0) || (WR_REQ == 1'b1)) begin
      byte_time <= 0;
      inhibit_bt <= 1'b0;
    end else begin
      byte_time <= byte_time + 1;
      if(byte_time >= limit_bt) begin
        inhibit_bt <= 1'b1;
      end
    end
  end
  // Count the number of bytes written.
  // Only a certain number of bytes can be sent in order
  // to keep packet size down.
  always @(negedge running, negedge WR_REQ) begin
    if(running == 1'b0) begin
      byte_count <= 0;
      inhibit_bc <= 1'b0;
    end else begin
      byte_count <= byte_count + 1;
      if(byte_count > limit_bc) begin
        inhibit_bc <= 1'b1;
      end
    end
  end
endmodule

module udp_add_udp_header(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out,
input wire [31:0] ip_src_ip,
input wire [31:0] ip_dst_ip,
input wire [15:0] udp_src_port,
input wire [15:0] udp_dst_port,
input wire [15:0] data_length,
input wire [15:0] data_checksum
);
reg [8:0] data_delay[0:8] = 1'b0;  //--------------------------------------------------------------
// Note: Set the initial state to pass the data striaght through
//--------------------------------------------------------------
reg [3:0] count = 1'b1;
reg data_valid_in_last = 1'b0;
wire [15:0] udp_length;
reg [19:0] udp_checksum_u1a;
reg [19:0] udp_checksum_u1b;
reg [16:0] udp_checksum_u2;
reg [15:0] udp_checksum_u3;
reg [15:0] udp_checksum;  //------------------------------------------------------------------
// UDP checksum is calculated based on a pseudo header that includes
// the source and destination IP addresses
//------------------------------------------------------------------
wire [15:0] pseudohdr_0 = 1'b0;
wire [15:0] pseudohdr_1 = 1'b0;
wire [15:0] pseudohdr_2 = 1'b0;
wire [15:0] pseudohdr_3 = 1'b0;
wire [15:0] pseudohdr_4 = 1'b0;
wire [15:0] pseudohdr_5 = 1'b0;
wire [15:0] pseudohdr_6 = 1'b0;
wire [15:0] pseudohdr_7 = 1'b0;
wire [15:0] pseudohdr_8 = 1'b0;
wire [15:0] pseudohdr_9 = 1'b0;
  assign udp_length = (data_length) + 8;
  assign pseudohdr_0 = {ip_src_ip[7:0],ip_src_ip[15:8]};
  assign pseudohdr_1 = {ip_src_ip[23:16],ip_src_ip[31:24]};
  assign pseudohdr_2 = {ip_dst_ip[7:0],ip_dst_ip[15:8]};
  assign pseudohdr_3 = {ip_dst_ip[23:16],ip_dst_ip[31:24]};
  assign pseudohdr_4 = 16'h0011;
  // UDP Protocol
  assign pseudohdr_5 = udp_length;
  assign pseudohdr_6 = udp_src_port;
  assign pseudohdr_7 = udp_dst_port;
  assign pseudohdr_8 = udp_length;
  assign pseudohdr_9 = udp_checksum;
  always @(posedge clk) begin
    case(count)
    4'b0000 : begin
      data_out <= udp_src_port[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0001 : begin
      data_out <= udp_src_port[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0010 : begin
      data_out <= udp_dst_port[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0011 : begin
      data_out <= udp_dst_port[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0100 : begin
      data_out <= udp_length[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0101 : begin
      data_out <= udp_length[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0110 : begin
      data_out <= udp_checksum[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0111 : begin
      data_out <= udp_checksum[7:0];
      data_valid_out <= 1'b1;
    end
    default : begin
      data_out <= data_delay[0][7:0];
      data_valid_out <= data_delay[0][8];
    end
    endcase
    data_delay[0:(8) - 1] <= data_delay[1:(8)];
    if(data_valid_in == 1'b1) begin
      data_delay[(8)] <= {1'b1,data_in};
      if(data_valid_in_last == 1'b0) begin
        count <= {4{1'b0}};
      end
      else if(count != 4'b1111) begin
        count <= count + 1;
      end
    end
    else begin
      data_delay[(8)] <= {1{1'b0}};
      if(count != 4'b1111) begin
        count <= count + 1;
      end
    end
    data_valid_in_last <= data_valid_in;
    // Pipelined checksum calculation    
    udp_checksum_u1a <= (0) + (pseudohdr_0) + (pseudohdr_1) + (pseudohdr_2) + (pseudohdr_3) + (pseudohdr_4);
    udp_checksum_u1b <= (0) + (pseudohdr_5) + (pseudohdr_6) + (pseudohdr_7) + (pseudohdr_8) + (data_checksum);
    udp_checksum_u2 <= (0) + udp_checksum_u1a[15:0] + udp_checksum_u1a[19:16] + udp_checksum_u1b[15:0] + udp_checksum_u1b[19:16];
    udp_checksum_u3 <= udp_checksum_u2[15:0] + udp_checksum_u2[16:16];
    udp_checksum <=  ~(udp_checksum_u3);
  end
endmodule
